def section_title(name):
    """BLOCK N: Название -> 'Название'. HOOK/FINAL/безымянные BLOCK — без титра."""
    m = re.match(r'BLOCK\s+\d+\s*:\s*(.+)', name, re.I)
    return m.group(1).strip() if m else None


def escape_drawtext(s):
    # % не экранировался — ffmpeg drawtext трактует его как начало strftime/
    # expansion-токена и роняет "Stray %" предупреждение (проверено вживую).
    return (s.replace("\\", "\\\\").replace(":", "\\:")
             .replace("%", "%%").replace("'", "\u2019"))


def pick_no_repeat(history, candidate, options, max_repeat):
    """Хэш даёт разнообразие "в среднем", но не мешает 3-4 одинаковым подряд
    случайным совпадением. Если последние max_repeat решений совпадают с
    кандидатом — детерминированно берём следующий вариант по кругу вместо
    него. history мутируется на месте (список последних решений)."""
    if len(history) >= max_repeat and all(x == candidate for x in history[-max_repeat:]):
        idx = options.index(candidate) if candidate in options else 0
        candidate = options[(idx + 1) % len(options)]
    history.append(candidate)
    del history[:-(max_repeat + 2)]
    return candidate


def audio_energy_curve(audio_path, window_sec=1.0):
    """RMS-громкость аудио по окнам — без Whisper/librosa, чистый PCM+numpy.
    Возвращает (rms_array, window_sec) или None, если numpy недоступен/что-то
    пошло не так (фича опциональная, пайплайн не должен падать без неё)."""
    if np is None:
        return None
    sr = 8000   # нужна только огибающая громкости, не звук — низкий sr достаточно и быстро
    try:
        r = subprocess.run(["ffmpeg", "-v", "quiet", "-i", audio_path, "-f", "s16le",
                            "-ac", "1", "-ar", str(sr), "-"], capture_output=True, timeout=120)
        if r.returncode != 0 or not r.stdout:
            return None
        raw = r.stdout[:len(r.stdout) - len(r.stdout) % 2]
        samples = np.frombuffer(raw, dtype=np.int16).astype(np.float64)
        if len(samples) < sr:
            return None
        win = max(1, int(sr * window_sec))
        n_win = max(1, len(samples) // win)
        trimmed = samples[:n_win * win].reshape(n_win, win)
        rms = np.sqrt(np.mean(trimmed ** 2, axis=1))
        return rms, window_sec
    except Exception as e:
        print(f"  Анализ громкости не удался (пропускаю): {e}")
        return None


def energy_pace_multipliers(curve, starts, durs, lo=0.8, hi=1.25):
    """Громче участок — короче кадры (множитель <1), тише — длиннее (>1).
    Множитель считается от отношения к МЕДИАНЕ громкости всей дорожки,
    чтобы тихий ролик целиком не растягивал все кадры одинаково."""
    if curve is None:
        return [1.0] * len(durs)
    rms, window_sec = curve
    med = float(np.median(rms))
    if med <= 0:
        return [1.0] * len(durs)
    mults = []
    for t0, d in zip(starts, durs):
        i0 = max(0, int(t0 / window_sec))
        i1 = min(len(rms), max(i0 + 1, int((t0 + d) / window_sec)))
        seg = rms[i0:i1] if i0 < len(rms) else rms[-1:]
        e = float(seg.mean()) if len(seg) else med
        ratio = max(0.5, min(2.0, e / med))
        mults.append(max(lo, min(hi, 1.0 / ratio)))
    return mults


def energy_levels(curve, starts, durs):
    """То же окно сэмплинга, что energy_pace_multipliers(), но возвращает
    СЫРОЕ отношение к медиане (0.5..2.0, 1.0 = обычная громкость), не
    инвертированный множитель темпа. Используется для лёгкой визуальной
    пульсации грейда в такт эмоциональным пикам речи (см. main()) —
    отдельная кривая от таймингов, чтобы не путать две разные вещи под
    одной переменной."""
    if curve is None:
        return [1.0] * len(durs)
    rms, window_sec = curve
    med = float(np.median(rms))
    if med <= 0:
        return [1.0] * len(durs)
    levels = []
    for t0, d in zip(starts, durs):
        i0 = max(0, int(t0 / window_sec))
        i1 = min(len(rms), max(i0 + 1, int((t0 + d) / window_sec)))
        seg = rms[i0:i1] if i0 < len(rms) else rms[-1:]
        e = float(seg.mean()) if len(seg) else med
        levels.append(max(0.5, min(2.0, e / med)))
    return levels


HOOK_ENERGY_SNAP_WINDOW = 0.35   # A8: макс. сдвиг границы реза в поиске локального пика, сек


def snap_hook_cuts_to_energy(blocks, durs, real_starts, audio_path):
    """A8: резы ВНУТРИ хука слегка "прилипают" к локальным пикам энергии
    ГОЛОСА (ударный слог/акцент) — тот же эффект "монтаж режется в такт",
    что в трейлерах режут под бит музыки, но синхронизировано с речью, а
    не с музыкой: наша подложка (generate_music_asset.py) намеренно без
    ритмического бита — дрон/пэд, чтобы не спорить с закадром документалки
    (см. A1/A2) — вводить бит в музыку ради этого сломало бы уже
    проверенное решение, поэтому синхронизация идёт по тому, что реально
    отбивает акценты в этой подаче: по голосу.

    Только границы МЕЖДУ соседними HOOK-клипами (не самая первая точка
    хука и не граница хук->тело — те определяются структурой сценария, не
    тайминг-эстетикой). Сдвиг ищется в мелком (80мс) окне энергии вокруг
    текущей границы, симметрично перекладывается между двумя соседними
    клипами — суммарная длительность хука не меняется НИ НА МИЛЛИСЕКУНДУ
    (бюджет xfade/точное совпадение с аудио не трогается), только реальные
    клипы i/j локально короче/длиннее друг друга. Каждый сдвиг ищется от
    ОРИГИНАЛЬНОЙ (досдвиговой) позиции границы — соседние сдвиги не
    накапливают дрейф друг от друга. Пол безопасности — hook_floor_for(),
    та же per-позиция функция, что уже держит открывающие резы хука ещё
    короче остального хука (не плоский порог — плоский тихо утаскивал бы
    уже нарочно короткие открывающие кадры обратно к общему полу, тот же
    класс бага, что hook_floor_for() уже один раз чинила для jitter/сдвига
    границы секции)."""
    curve = audio_energy_curve(audio_path, window_sec=0.08)
    if curve is None:
        return durs
    rms, win_sec = curve
    hook_idx = [i for i, b in enumerate(blocks) if b["section"].startswith("HOOK")]
    if len(hook_idx) < 3:
        return durs
    new_durs = list(durs)
    for k in range(len(hook_idx) - 1):
        i, j = hook_idx[k], hook_idx[k + 1]
        boundary_t = real_starts[j]
        lo = max(0, int((boundary_t - HOOK_ENERGY_SNAP_WINDOW) / win_sec))
        hi = min(len(rms), int((boundary_t + HOOK_ENERGY_SNAP_WINDOW) / win_sec) + 1)
        if hi <= lo:
            continue
        peak_i = lo + int(np.argmax(rms[lo:hi]))
        delta = max(-HOOK_ENERGY_SNAP_WINDOW, min(HOOK_ENERGY_SNAP_WINDOW, peak_i * win_sec - boundary_t))
        if new_durs[i] + delta < hook_floor_for(blocks, i) or new_durs[j] - delta < hook_floor_for(blocks, j):
            continue
        new_durs[i] += delta
        new_durs[j] -= delta
    return new_durs


# Единый источник целевой громкости — ЕДИНСТВЕННОЕ место, которое трогать
# при смене цели. Раньше -14 (было -16) была рассыпана литералом по пяти
# местам вручную (дефолт measure_loudnorm_stats, два af= в финальном
# миксе, print_format=json первого прохода, sanity-проверка готового
# файла) — РЕАЛЬНЫЙ найденный баг (02.09): при переходе -16 -> -14 пятое
# место (sanity-проверка) осталось на старом значении, и честный рендер
# на -14.3 (в пределах цели) печатал ложную тревогу "разошлось с целью
# -16". Четыре места нашли и поправили сразу, пятое — нет, потому что
# ничего в коде не требовало держать их согласованными. Константа не
# устраняет риск рассинхрона полностью (использования всё ещё нужно
# найти и подставить руками), но делает следующую смену цели ОДНИМ
# изменением вместо пяти grep'ов по литералу.
LOUDNORM_TARGET_I = -14.0
LOUDNORM_TARGET_TP = -1.5
LOUDNORM_TARGET_LRA = 11


def measure_loudnorm_stats(audio_path, target_i=LOUDNORM_TARGET_I,
                            target_tp=LOUDNORM_TARGET_TP, target_lra=LOUDNORM_TARGET_LRA):
    """Первый проход двух-проходного loudnorm — только измерение, звук не
    трогаем. Однопроходный (динамический) режим подстраивает усиление на
    лету по ходу файла и даёт неровную громкость внутри ролика и неточный
    итоговый integrated — это ffmpeg-документация прямо называет compromise-
    режимом, не тем, что стоит использовать для финального мастеринга.
    None при любой ошибке — main() откатывается на старый однопроходный af."""
    try:
        r = subprocess.run(
            ["ffmpeg", "-i", audio_path, "-af",
             f"loudnorm=I={target_i}:TP={target_tp}:LRA={target_lra}:print_format=json",
             "-f", "null", "-"], capture_output=True, text=True, timeout=60)
        start, end = r.stderr.rindex("{"), r.stderr.rindex("}") + 1
        return json.loads(r.stderr[start:end])
    except Exception:
        return None


def process_voice(voice_path, out_path):
    """A6: обработка сырой TTS-дорожки перед миксом с музыкой — срез
    суб-баса, лёгкая тональная коррекция, деэссер, мягкая компрессия
    микро-динамики фраз. VOICE_PROCESS_ENABLED=False -> просто копия
    исходника (безопасный откат, тот же принцип, что MUSIC_ENABLED)."""
    if not VOICE_PROCESS_ENABLED:
        r = subprocess.run(["ffmpeg", "-y", "-i", voice_path, "-ar", "48000", "-ac", "2", out_path],
                            capture_output=True, text=True)
        return out_path if r.returncode == 0 else voice_path
    af = (
        f"highpass=f={VOICE_HIGHPASS_HZ},"
        f"equalizer=f={VOICE_EQ_WARMTH_HZ}:width_type=o:width=1.5:g={VOICE_EQ_WARMTH_GAIN},"
        f"equalizer=f={VOICE_EQ_PRESENCE_HZ}:width_type=o:width=1.2:g={VOICE_EQ_PRESENCE_GAIN},"
        f"deesser=i={VOICE_DEESS_INTENSITY}:m=0.4,"
        f"acompressor=threshold={VOICE_COMPRESS_THRESHOLD}:ratio={VOICE_COMPRESS_RATIO}:"
        f"attack=8:release=120:makeup=1.15"
    )
    r = subprocess.run(["ffmpeg", "-y", "-i", voice_path, "-af", af, "-ar", "48000", "-ac", "2", out_path],
                        capture_output=True, text=True)
    if r.returncode != 0:
        r2 = subprocess.run(["ffmpeg", "-y", "-i", voice_path, "-ar", "48000", "-ac", "2", out_path],
                             capture_output=True, text=True)
        return out_path if r2.returncode == 0 else voice_path
    return out_path


def add_typewriter_clicks(mix_path, click_times, total_dur, out_path):
    """D4: звук печатной машинки — щелчок на КАЖДЫЙ символ, ровно в момент,
    когда он появляется на экране (тот же TYPEWRITER_CHAR_DUR, что и в
    add_overlays() — визуал и звук считаются от одной и той же ставки).
    click_times — абсолютные секунды в ФИНАЛЬНОМ таймлайне ролика (см.
    main(): sub_starts + delay + k*char_dur).

    KEYBOARD_CLICK_PATHS — библиотека из НЕСКОЛЬКИХ разных реальных ударов
    (не один сэмпл клонштампом на каждый символ — по прямой обратной связи
    пользователя один и тот же щелчок на каждый символ звучал механически,
    "не как в живой записи"; round-robin по библиотеке даёт естественный
    разброс тембра/громкости между соседними символами, как при живой
    печати). Каждый входной файл asplit'ится РОВНО на то число раз, сколько
    он реально используется в этом ролике — не больше (лишние неиспользуемые
    выходы asplit — трата, ffmpeg отдельно предупреждает про unconnected
    output)."""
    if not click_times or not TYPEWRITER_CLICK_ENABLED:
        return mix_path
    n_files = len(KEYBOARD_CLICK_PATHS)
    assigned = [i % n_files for i in range(len(click_times))]
    usage = [assigned.count(f) for f in range(n_files)]
    cmd = ["ffmpeg", "-y", "-i", mix_path]
    for p in KEYBOARD_CLICK_PATHS:
        cmd += ["-i", p]
    parts = []
    for f in range(n_files):
        if usage[f] > 0:
            parts.append(f"[{f + 1}:a]asplit={usage[f]}" + "".join(f"[fs{f}_{k}]" for k in range(usage[f])))
    cursor = [0] * n_files
    mix_inputs = ["[0:a]"]
    for i, (t, f_idx) in enumerate(zip(click_times, assigned)):
        ms = max(0, int(t * 1000))
        k = cursor[f_idx]
        cursor[f_idx] += 1
        parts.append(f"[fs{f_idx}_{k}]adelay={ms}|{ms},volume={TYPEWRITER_CLICK_GAIN_DB}dB[cd{i}]")
        mix_inputs.append(f"[cd{i}]")
    parts.append("".join(mix_inputs) + f"amix=inputs={len(click_times) + 1}:duration=first:normalize=0[out]")
    fc = ";".join(parts)
    # Граф в ФАЙЛ, не в аргумент: щелчки набираются по одному на СИМВОЛ
    # раскрываемой цифры, и на ролике с десятком stat-плашек это сотни
    # adelay-фильтров + amix на столько же входов — десятки тысяч символов
    # в одном аргументе. Лимит командной строки Windows (32767 на всю
    # строку) отвергает такое молча-фатально: шаг просто не запускается.
    fc_path = os.path.join(TEMP_FOLDER, "typewriter_filter.txt")
    try:
        with open(fc_path, "w", encoding="utf-8") as f:
            f.write(fc)
        cmd += ["-filter_complex_script", fc_path, "-map", "[out]",
                "-t", f"{total_dur:.3f}", "-ar", "48000", "-ac", "2", out_path]
    except OSError:
        cmd += ["-filter_complex", fc, "-map", "[out]",
                "-t", f"{total_dur:.3f}", "-ar", "48000", "-ac", "2", out_path]
    r = subprocess.run(cmd, capture_output=True, text=True)
    return out_path if r.returncode == 0 else mix_path


def build_mood_timeline(hook_end, final_start, total_dur, out_path):
    """A2: единая дорожка подложки на весь ролик, склеенная из 3 настроений
    (HOOK/BODY/FINAL, см. MUSIC_BED_PATHS) через медленный кроссфейд
    (acrossfade), а не один и тот же луп на все 18 минут. Переходные точки
    сдвинуты РАНЬШЕ формальной границы секции на MUSIC_JCUT_LEAD секунд —
    звуковой J-cut: настроение подложки уже слегка меняется до того, как
    текст/картинка формально перешли в новый раздел.

    Математика длин сегментов для acrossfade с двумя переходами t1 (HOOK->
    BODY) и t2 (BODY->FINAL), d = MUSIC_MOOD_XFADE:
    L1 = t1+d, L2 = (t2-t1)+d, L3 = total_dur-t2 — тогда итоговая длина
    после двух acrossfade равна ровно total_dur (проверено расчётом и живым
    ffprobe на реальных цифрах), с чистыми "полными" участками настроения
    длиной t1 / (t2-t1-d) / (total_dur-t2-d) между кроссфейдами.

    Слишком короткий ролик/секция (t2-t1 меньше 2 кроссфейдов) -> тихий
    откат на одну BODY-петлю на всю длину, без попытки втиснуть переходы
    туда, где для них физически нет места."""
    d = MUSIC_MOOD_XFADE
    t1 = max(2.0, hook_end - MUSIC_JCUT_LEAD)
    t2 = min(total_dur - 2.0, max(t1 + 2 * d, final_start - MUSIC_JCUT_LEAD))
    if t2 - t1 < 2 * d or t1 >= total_dur - 2 * d:
        r = subprocess.run(["ffmpeg", "-y", "-stream_loop", "-1", "-i", MUSIC_BED_PATHS["BODY"],
                             "-t", f"{total_dur:.3f}", "-ar", "48000", "-ac", "2", out_path],
                            capture_output=True, text=True)
        return out_path if r.returncode == 0 else None
    L1, L2, L3 = t1 + d, (t2 - t1) + d, total_dur - t2
    fc = (
        f"[0:a]atrim=0:{L1:.3f}[s1];"
        f"[1:a]atrim=0:{L2:.3f}[s2];"
        f"[2:a]atrim=0:{L3:.3f}[s3];"
        f"[s1][s2]acrossfade=d={d}:c1=tri:c2=tri[r1];"
        f"[r1][s3]acrossfade=d={d}:c1=tri:c2=tri[mood_mix]"
    )
    r = subprocess.run(
        ["ffmpeg", "-y",
         "-stream_loop", "-1", "-i", MUSIC_BED_PATHS["HOOK"],
         "-stream_loop", "-1", "-i", MUSIC_BED_PATHS["BODY"],
         "-stream_loop", "-1", "-i", MUSIC_BED_PATHS["FINAL"],
         "-filter_complex", fc, "-map", "[mood_mix]",
         "-t", f"{total_dur:.3f}", "-ar", "48000", "-ac", "2", out_path],
        capture_output=True, text=True)
    if r.returncode != 0:
        r2 = subprocess.run(["ffmpeg", "-y", "-stream_loop", "-1", "-i", MUSIC_BED_PATHS["BODY"],
                              "-t", f"{total_dur:.3f}", "-ar", "48000", "-ac", "2", out_path],
                             capture_output=True, text=True)
        return out_path if r2.returncode == 0 else None
    return out_path


def _climax_dip_window(t_c):
    """(start, end) полного окна провала громкости для одного climax-момента
    (fade-out -> hold -> fade-in) — ЕДИНСТВЕННОЕ место, которое считает эти
    границы: _climax_dip_expr() строит по нему ffmpeg-выражение, а
    _exclude_climax_overlapping_windows() ниже использует ТЕ ЖЕ границы,
    чтобы не дать музыкальному 'вздоху' (swell) на длинной паузе
    накладываться на уже идущий климакс-провал (dip) — иначе два
    последовательных volume-фильтра на одном треке частично гасят друг
    друга (+3дБ поверх -22дБ), разбавляя ИМЕННО тот момент, где провал
    нужен максимально чистым. Раньше эти границы дублировались бы в двух
    местах порознь — реальный риск рассинхрона при следующей правке
    констант."""
    d1 = max(0.0, t_c - CLIMAX_DIP_LEAD_SEC)
    return d1, d1 + CLIMAX_DIP_FADE_SEC + CLIMAX_DIP_HOLD_SEC + CLIMAX_DIP_FADE_SEC


def _exclude_climax_overlapping_windows(pause_windows_real, climax_times):
    """P0 (нейрокогнитивная критика системы пауз): не менять несколько
    каналов одновременно на одном и том же участке — swell (+3дБ, "вдох"
    подложки на длинной паузе) и climax dip (-22дБ, провал перед
    разоблачением) физически МОГУТ попасть на один и тот же интервал:
    после защиты reveal_hold-паузы её реальная длительность (kept_sec из
    protected_windows) часто оказывается >= PAUSE_SWELL_MIN_KEEP_SEC —
    паузу ПЕРЕД климаксом теперь корректно не срезают слепой кривой, но
    это же делает её длинной ДОСТАТОЧНО, чтобы задеть порог swell'а,
    которого раньше эта пауза почти никогда не достигала (раньше её
    обрезала кривая до ~0.6-0.8с). Два последовательных volume-фильтра на
    одном треке (dip, потом swell) не отменяют друг друга целиком, а
    ЧАСТИЧНО гасят (-22дБ*+3дБ ≈ -19дБ) — разбавляют самый драматургически
    важный провал слышимым артефактом, которого не было бы, будь эта
    пауза короче порога. Исключаем swell на любом окне, физически
    пересекающемся с dip-окном того же climax-момента — dip сам по себе
    уже полноценный акцент на этом участке, второй эффект поверх не
    нужен, только мешает."""
    if not pause_windows_real or not climax_times:
        return pause_windows_real
    dip_windows = [_climax_dip_window(t_c) for t_c in climax_times]
    kept = []
    for start, dur in pause_windows_real:
        end = start + dur
        if any(start < d_end and end > d_start for d_start, d_end in dip_windows):
            continue
        kept.append((start, dur))
    return kept


def _climax_dip_expr(climax_times):
    """Покадровое ffmpeg-выражение громкости (1.0 = без изменений) с
    провалом до CLIMAX_DIP_DB перед каждым моментом климакса — см.
    константы выше. Собирается как цепочка вложенных if(between(...)),
    каждый следующий уровень — fallback предыдущего (окна климаксов не
    пересекаются в реальном сценарии — драматургических поворотов не
    бывает через 2 секунды друг после друга). Тот же стиль выражений, что
    уже используют drawtext alpha='if(...)' по всему файлу (add_overlays)."""
    if not climax_times:
        return None
    g = 10 ** (CLIMAX_DIP_DB / 20.0)
    f = CLIMAX_DIP_FADE_SEC
    h = CLIMAX_DIP_HOLD_SEC
    expr = "1"
    for t_c in sorted(climax_times):
        d1 = max(0.0, t_c - CLIMAX_DIP_LEAD_SEC)
        seg2_start, seg3_start, seg3_end = d1 + f, d1 + f + h, d1 + f + h + f
        expr = (
            f"if(between(t\\,{d1:.3f}\\,{seg2_start:.3f})\\,"
            f"1-{1 - g:.4f}*(t-{d1:.3f})/{f:.3f}\\,"
            f"if(between(t\\,{seg2_start:.3f}\\,{seg3_start:.3f})\\,{g:.4f}\\,"
            f"if(between(t\\,{seg3_start:.3f}\\,{seg3_end:.3f})\\,"
            f"{g:.4f}+{1 - g:.4f}*(t-{seg3_start:.3f})/{f:.3f}\\,{expr})))"
        )
    return expr


PAUSE_SWELL_MIN_KEEP_SEC = 1.0   # порог отбора: fix_pauses.py держит паузу в
                                  # диапазоне KEEP_MIN_SEC=0.42..KEEP_MAX_SEC=1.35
                                  # (гладкая кривая, не бинарная ступенька —
                                  # старые KEEP_SEC=0.6/LONG_HOLD_KEEP_SEC=1.3
                                  # тут раньше упоминались, но эти константы
                                  # больше не существуют в fix_pauses.py, комментарий
                                  # был устаревшим). 1.0 — примерно верхние ~30%
                                  # диапазона кривой (0.42+0.7*(1.35-0.42)≈1.07) —
                                  # берём только "осознанно длинные" паузы, не
                                  # обычные вдохи TTS (см. load_pause_windows).
                                  # НА РЕАЛЬНОМ эпизоде без Speech Director гладкая
                                  # кривая редко/никогда не заходит настолько высоко
                                  # (raw-пауза должна быть >=~2.15с — обычные вдохи
                                  # заметно короче) — swell почти никогда не
                                  # срабатывает НА ОБЫЧНЫХ пауз, но ЖИВ на
                                  # protected closing_hold (target до 1.1с, см.
                                  # speech_planner.RHETORICAL_RANGES) — reveal_hold
                                  # (до 1.2с, см. pause_intelligence.py — тот же
                                  # модуль ещё и не даёт двум таким паузам подряд
                                  # столкнуться, см. cooldown) намеренно исключён
                                  # рядом с climax dip отдельно (структурно, не по
                                  # порогу длительности), см.
                                  # _exclude_climax_overlapping_windows(). Не
                                  # понижаю порог "на глаз" — нет реального корпуса
                                  # эпизодов, чтобы понять, где кончаются обычные
                                  # вдохи и начинаются осознанные паузы (пониженный
                                  # порог рискует включить swell на КАЖДОМ вдохе —
                                  # хуже, чем редкое срабатывание).
PAUSE_SWELL_DB = 3.0             # заметно тише климакс-провала (22дБ) — это
                                  # не разоблачение, а мягкое "дыхание" подложки
PAUSE_SWELL_FADE_SEC = 0.3       # должно уместиться внутри keep-окна (~1.3с)


def _pause_swell_expr(pause_windows_real):
    """Как _climax_dip_expr, но наоборот: лёгкий ПОДЪЁМ громкости подложки
    внутри окна осознанно длинной паузы (P1-15) — та же механика вложенных
    if(between(...)), тот же принцип "каждый следующий уровень — fallback
    предыдущего", те же неперекрывающиеся окна на практике (длинные паузы
    не бывают через доли секунды друг после друга). pause_windows_real —
    [(реальный_старт, длительность_keep), ...] уже в реальном (после
    обрезки) времени — см. main()."""
    if not pause_windows_real:
        return None
    boost = 10 ** (PAUSE_SWELL_DB / 20.0)
    f = min(PAUSE_SWELL_FADE_SEC, min(dur for _, dur in pause_windows_real) / 2.5)
    expr = "1"
    for real_start, dur in sorted(pause_windows_real):
        seg2_start = real_start + f
        seg3_start = max(seg2_start, real_start + dur - f)
        seg3_end = real_start + dur
        expr = (
            f"if(between(t\\,{real_start:.3f}\\,{seg2_start:.3f})\\,"
            f"1+{boost - 1:.4f}*(t-{real_start:.3f})/{f:.3f}\\,"
            f"if(between(t\\,{seg2_start:.3f}\\,{seg3_start:.3f})\\,{boost:.4f}\\,"
            f"if(between(t\\,{seg3_start:.3f}\\,{seg3_end:.3f})\\,"
            f"{boost:.4f}-{boost - 1:.4f}*(t-{seg3_start:.3f})/{f:.3f}\\,{expr})))"
        )
    return expr


def build_music_mix(voice_path, total_dur, out_path, hook_end=0.0, final_start=None, climax_times=None,
                     pause_windows_real=None):
    """A1: атмосферная подложка под голосом, с сайдчейн-дакингом — громкость
    музыки автоматически прижимается, когда звучит речь, и отпускает в
    паузах (тот же приём, что в любом проф. документальном монтаже: подложка
    ощущается, но никогда не спорит со словами). A2: подложка меняет
    настроение по секциям (build_mood_timeline), не один луп на весь ролик.
    2.8: climax_times (абсолютные секунды из [climax] в script.txt) — доп.
    провал громкости ПЕРЕД моментом разоблачения, независимо от дакинга
    (см. _climax_dip_expr/CLIMAX_DIP_* констант) — сайдчейн реагирует
    только на текущую громкость голоса, разоблачение может звучать не
    громче обычного текста и не даст дакингу провалиться само.
    MUSIC_ENABLED=False (нет ассета или явно выключено) -> просто копируем
    голос как есть, без регрессии.

    Микс делается ОТДЕЛЬНЫМ шагом (не встроен прямо в финальный мультиплекс)
    — так итоговый loudnorm (A7) считается на ГОТОВОМ миксе голос+музыка,
    а не только на голосе, как было раньше: иначе музыка добавляла бы
    громкость ПОСЛЕ калибровки и сводила её к нулю."""
    if not MUSIC_ENABLED:
        r = subprocess.run(["ffmpeg", "-y", "-i", voice_path, "-t", f"{total_dur:.3f}",
                             "-ar", "48000", "-ac", "2", out_path], capture_output=True, text=True)
        return out_path if r.returncode == 0 else voice_path
    if final_start is None:
        final_start = total_dur
    timeline_path = out_path + ".mood_timeline.wav"
    timeline = build_mood_timeline(hook_end, final_start, total_dur, timeline_path)
    if timeline is None:
        r = subprocess.run(["ffmpeg", "-y", "-i", voice_path, "-t", f"{total_dur:.3f}",
                             "-ar", "48000", "-ac", "2", out_path], capture_output=True, text=True)
        return out_path if r.returncode == 0 else voice_path
    dip_expr = _climax_dip_expr(climax_times)
    dip_stage = f",volume=eval=frame:volume='{dip_expr}'" if dip_expr else ""
    swell_expr = _pause_swell_expr(pause_windows_real)
    swell_stage = f",volume=eval=frame:volume='{swell_expr}'" if swell_expr else ""
    filter_complex = (
        f"[1:a]volume={MUSIC_BED_GAIN_DB}dB{dip_stage}{swell_stage}[music_raw];"
        f"[0:a]asplit=2[voice_main][voice_sc];"
        f"[music_raw][voice_sc]sidechaincompress=threshold={MUSIC_DUCK_THRESHOLD}:"
        f"ratio={MUSIC_DUCK_RATIO}:attack={MUSIC_DUCK_ATTACK_MS}:release={MUSIC_DUCK_RELEASE_MS}[music_ducked];"
        f"[voice_main][music_ducked]amix=inputs=2:duration=first:weights=1 1:normalize=0[mix]"
    )
    r = subprocess.run(
        ["ffmpeg", "-y", "-i", voice_path, "-i", timeline,
         "-filter_complex", filter_complex, "-map", "[mix]",
         "-t", f"{total_dur:.3f}", "-ar", "48000", "-ac", "2", out_path],
        capture_output=True, text=True)
    if r.returncode != 0:
        # Микс не собрался — откат на голос без подложки, не срываем сборку
        # ролика ради необязательного улучшения.
        r2 = subprocess.run(["ffmpeg", "-y", "-i", voice_path, "-t", f"{total_dur:.3f}",
                              "-ar", "48000", "-ac", "2", out_path], capture_output=True, text=True)
        return out_path if r2.returncode == 0 else voice_path
    return out_path


_FRAME_MEASURE_CACHE = {}   # {(fn_name, path, size, mtime_ns, args, kwargs): результат} — см. memoize_by_frame


def _frame_cache_key(path):
    """(путь, размер, mtime в наносекундах) — НЕ голый путь. Файл под тем
    же именем реально перезаписывается в рамках одного прогона (см.
    pexels_photo/pexels_video: кандидат-победитель занимает имя `cf` через
    os.replace, кандидат-проигравший на том же логическом слоте следующего
    эпизода может унаследовать то же имя кэша при повторном запуске) — голый
    путь как ключ дал бы тихую порчу: устаревшее измерение осталось бы
    приклеено к новому файлу под старым именем. os.stat() не удался (файл
    исчез между вызовами, гонка с параллельным рендер-пулом) -> None —
    вызывающий код такой результат не кэширует вообще, честный отказ, не
    порча по несуществующему/неполному ключу."""
    try:
        st = os.stat(path)
    except OSError:
        return None
    return (path, st.st_size, st.st_mtime_ns)


def memoize_by_frame(fn):
    """Мемоизация для ЧИСТЫХ измерений кадра — функция читает файл(ы) с
    диска по пути (ПЕРВЫЙ позиционный аргумент) и не имеет побочных
    эффектов помимо своего возвращаемого значения; на одном и том же
    (путь, размер, mtime) результат гарантированно совпадёт.

    ЗАЧЕМ (реальное дублирование, не гипотеза): estimate_busyness(photo) и
    measure_levels(photo) в kenburns() считаются один раз для zoom-delta,
    а на stat-блоке — ЕЩЁ РАЗ на том же файле внутри
    add_overlays()->pick_stat_variant() тем же вызовом рендера. Кандидатов
    у pexels_photo() до 20 на блок, блоков — сотни: clip_relevance/
    aesthetic_score (CLIP-инференс на CPU) — самая дорогая часть подбора
    медиа, и часть вызовов на практике приходится на один и тот же файл
    более одного раза за прогон.

    Живёт только в рамках ОДНОГО процесса (module-level dict, не пишется на
    диск) — новый прогон эпизода стартует с чистого кэша сам по себе,
    инвалидировать вручную нечего. Остальные аргументы вызова участвуют в
    ключе как есть — два вызова с одним файлом, но разными доп.параметрами
    (например clip_relevance(img, "меч") vs clip_relevance(img, "доспех"))
    не путаются между собой."""
    @functools.wraps(fn)
    def wrapper(path, *args, **kwargs):
        base_key = _frame_cache_key(path)
        if base_key is None:
            return fn(path, *args, **kwargs)
        key = (fn.__name__, base_key, args, tuple(sorted(kwargs.items())))
        if key in _FRAME_MEASURE_CACHE:
            return _FRAME_MEASURE_CACHE[key]
        result = fn(path, *args, **kwargs)
        _FRAME_MEASURE_CACHE[key] = result
        return result
    return wrapper


@memoize_by_frame
def measure_levels(path, is_video=False, lo_pct=2, hi_pct=98, video_samples=4, video_span=3.5, want_wb=False):
    """Чёрная/белая точка кадра (0..1) по перцентилям гистограммы — для
    адаптивной ТЕХНИЧЕСКОЙ нормализации экспозиции ДО фиксированного
    творческого грейда (см. auto_levels_params()/film_look()). Перцентили,
    не голый min/max — иначе один яркий блик/пересвеченный пиксель срывает
    белую точку всего кадра.

    Для видео — НЕСКОЛЬКО кадров-пробников (video_samples, разнесённых по
    первым video_span секундам, тот же принцип, что уже использует
    measure_motion() для спид-рампа), не один: экспозиция может плыть
    внутри клипа (панорама между светлым/тёмным), один кадр — нерепрезен-
    тативная выборка. Перцентили считаются по ОБЪЕДИНЁННЫМ пикселям всех
    сэмплов — честная оценка разброса по всему просматриваемому диапазону,
    не по случайному одному моменту.

    want_wb=True — ДОПОЛНИТЕЛЬНО возвращает (r,g,b) средние по тем же
    сэмплам (без повторного извлечения кадров через ffmpeg) для gray-world
    баланса белого (см. auto_wb_params()/film_look()). Реальная, проверенная
    вживую прямым сравнением кадров проблема: auto_levels_params() выравнивает
    только ЯРКОСТЬ (percentile по L-каналу) — разные стоковые источники с
    разной цветовой температурой (холодный снежный кадр vs тёплый музейный
    интерьер) проходят через ОДИН и тот же фиксированный творческий грейд
    неровно: у одного клипа кадр читается холодным, у другого — тёплым,
    хотя творческий грейд один и тот же. Возврат (lo, hi) не меняется для
    существующих вызовов (want_wb=False по умолчанию — обратная совместимость
    с line ~1900, где used для выбора варианта плашки, к цвету отношения
    не имеет)."""
    try:
        if is_video:
            arrs_l, arrs_rgb = [], []
            for i in range(video_samples):
                # 0.5 старт, не 0 — реальный сток иногда начинается с чёрного
                # лидер-кадра/fade-in (поймано вживую: у одного клипа эпизода
                # кадр 0 был буквально чистым чёрным, min=max=0 — без сдвига
                # это заваливало бы коррекцию в вырожденный случай на КАЖДОМ
                # таком клипе).
                t = 0.5 + video_span * i / max(1, video_samples - 1)
                tmp = path + f"._levels_probe_{i}.jpg"
                r = subprocess.run(["ffmpeg", "-y", "-ss", f"{t:.2f}", "-i", path,
                                     "-frames:v", "1", "-q:v", "5", tmp],
                                    capture_output=True, timeout=20)
                if r.returncode == 0 and os.path.exists(tmp):
                    if np is not None:
                        img = PILImage.open(tmp)
                        arrs_l.append(np.asarray(img.convert("L"), dtype=np.float32) / 255.0)
                        if want_wb:
                            arrs_rgb.append(np.asarray(img.convert("RGB"), dtype=np.float32) / 255.0)
                    os.remove(tmp)
            if not arrs_l:
                return None
            arr = np.concatenate([a.ravel() for a in arrs_l])
            rgb_arr = np.concatenate([a.reshape(-1, 3) for a in arrs_rgb], axis=0) if want_wb else None
        else:
            if np is None:
                return None
            img = PILImage.open(path)
            arr = np.asarray(img.convert("L"), dtype=np.float32).ravel() / 255.0
            rgb_arr = np.asarray(img.convert("RGB"), dtype=np.float32).reshape(-1, 3) / 255.0 if want_wb else None
        lo = float(np.percentile(arr, lo_pct))
        hi = float(np.percentile(arr, hi_pct))
        if want_wb:
            if rgb_arr is None or rgb_arr.size == 0:
                return (lo, hi), None
            rgb_means = tuple(float(x) for x in rgb_arr.mean(axis=0))
            return (lo, hi), rgb_means
        return lo, hi
    except Exception:
        return (None, None) if want_wb else None


AUTO_LEVELS_TARGET_BLACK = 0.03
AUTO_LEVELS_TARGET_WHITE = 0.97
# Клэмп силы коррекции — НЕ полное выравнивание к цели (иначе кадр с
# осознанно низким контрастом/затемнением — музейный экспонат в полумраке —
# перекорректируется до нейтрального "мыла", тот же принцип, что уже держит
# в узде brightness_bias). 0.5 = на полпути между "как есть" и целью.
AUTO_LEVELS_MAX_STRENGTH = 0.5
AUTO_LEVELS_MIN_RANGE = 0.05   # чёрная/белая точка ближе этого — вырожденная гистограмма, не трогаем
# P2 форензик-аудита (реальный, подтверждённый эмпирически риск): AUTO_LEVELS_MIN_RANGE
# отсекает только СОВСЕМ вырожденную гистограмму, но НЕ ограничивает выход сверху —
# scale_full = (TARGET_WHITE-TARGET_BLACK)/(white_in-black_in) растёт без потолка при
# приближении range к самому порогу (0.05 сверху), а не только ниже него. На реальном
# полном прогоне это дало eq=contrast=4.2453:brightness=0.9180 на одном фикстур-кадре —
# не гипотеза, увидено вживую в логе ffmpeg. Бэкстоп ниже — не перекалибровка формулы
# (та остаётся как есть для нормальных фото), а страховка именно от этого крайнего
# случая около порога: щедрые границы, чтобы не задеть легитимную сильную коррекцию
# плоского фото (range~0.2 у обычного тускло снятого кадра даёт contrast_eff~2.85,
# внутри границ), но не пропустить кратный/почти-бесконечный скачок у самого порога.
AUTO_LEVELS_MAX_CONTRAST = 3.0
AUTO_LEVELS_MIN_CONTRAST = 0.3
AUTO_LEVELS_MAX_BRIGHTNESS_ABS = 0.5

# Баланс белого (gray-world) — та же логика клэмпа силы, что и у auto_levels
# выше, только по цвету, не по яркости. Реальный, пойманный вживую (прямое
# сравнение кадров) дефект: без этого шага разные стоковые источники с
# разной цветовой температурой проходят ОДИН и тот же творческий грейд с
# разным итоговым "теплом" — грейд не единая история, а фильтр поверх
# несогласованного исходника. 0.35, не 0.5 (как у auto_levels) — цветовая
# коррекция субъективно заметнее эквивалентной силы яркостной, перебор
# читается как "перекрашено", клэмп жёстче.
AUTO_WB_MAX_STRENGTH = 0.35
AUTO_WB_MIN_MEAN = 0.04   # почти чёрный кадр — среднее по каналам ненадёжно, не трогаем


def auto_wb_params(rgb_means):
    """(gain_r, gain_g, gain_b) для colorchannelmixer — gray-world баланс
    белого: цель — среднее R≈G≈B (нейтральный серый) по кадру, тот же
    принцип, на котором строятся авто-ББ в любой камере/редакторе. Частичная
    коррекция (AUTO_WB_MAX_STRENGTH), не полная — иначе кадр с осознанно
    выраженным цветом (закат, тёплый музейный свет) обесцвечивается до
    нейтрального "никакого", тот же компромисс, что уже держит в узде
    auto_levels. None/вырожденный (слишком тёмный кадр) -> (1,1,1) —
    нейтральный проход, эффекта нет."""
    if rgb_means is None:
        return 1.0, 1.0, 1.0
    r, g, b = rgb_means
    avg = (r + g + b) / 3.0
    if avg < AUTO_WB_MIN_MEAN:
        return 1.0, 1.0, 1.0
    s = AUTO_WB_MAX_STRENGTH

    def gain(c):
        full = avg / max(c, 1e-4)
        g = (1 - s) + s * full
        # Реальный, пойманный вживую (упавший рендер блока) баг: на кадре
        # с сильным цветовым перекосом (почти чистый канал, avg/c большое)
        # gain может вылезти за допустимый диапазон colorchannelmixer у
        # ffmpeg (rr/gg/bb: -2..2) — ffmpeg тихо отклоняет фильтр целиком
        # (без исключения в Python, кадр просто не рендерится). Клэмп к
        # [0.5, 1.8] — с запасом внутри допустимого диапазона ffmpeg И
        # предотвращает перебор коррекции на вырожденных кадрах (почти
        # монохромных, где gray-world и так ненадёжен).
        return max(0.5, min(1.8, g))
    return gain(r), gain(g), gain(b)


def auto_levels_params(levels):
    """(contrast, brightness) для eq() — линейная растяжка чёрной/белой
    точки К цели (не ДО цели — см. AUTO_LEVELS_MAX_STRENGTH), формула eq
    подтверждена вживую на синтетическом градиенте: output=(input-0.5)*
    contrast+0.5+brightness. None/вырожденная гистограмма -> (1.0, 0.0) —
    нейтральный проход, эффекта нет.

    Финальный клэмп (см. AUTO_LEVELS_MAX_CONTRAST и соседей) — бэкстоп от
    реального, эмпирически увиденного случая: у самого порога
    AUTO_LEVELS_MIN_RANGE (но ещё формально его прошедшего) scale_full
    делится на почти нулевой range и даёт контраст в разы сильнее любой
    легитимной коррекции. Не меняет поведение на нормальных фото — только
    отсекает этот один патологический хвост распределения."""
    if levels is None:
        return 1.0, 0.0
    black_in, white_in = levels
    if white_in - black_in < AUTO_LEVELS_MIN_RANGE:
        return 1.0, 0.0
    s = AUTO_LEVELS_MAX_STRENGTH
    # Блендим ЛИНЕЙНО две affine-трансформации — identity (as-is) и полную
    # коррекцию (black_in->TARGET_BLACK, white_in->TARGET_WHITE) — блендинг
    # двух affine-преобразований сам по себе affine, поэтому это по-прежнему
    # чистая (contrast, brightness) пара, не приближение.
    scale_full = (AUTO_LEVELS_TARGET_WHITE - AUTO_LEVELS_TARGET_BLACK) / (white_in - black_in)
    contrast_eff = (1 - s) + s * scale_full
    brightness_offset = s * (AUTO_LEVELS_TARGET_BLACK - black_in * scale_full)
    brightness = brightness_offset - 0.5 + 0.5 * contrast_eff
    contrast_eff = max(AUTO_LEVELS_MIN_CONTRAST, min(AUTO_LEVELS_MAX_CONTRAST, contrast_eff))
    brightness = max(-AUTO_LEVELS_MAX_BRIGHTNESS_ABS, min(AUTO_LEVELS_MAX_BRIGHTNESS_ABS, brightness))
    return contrast_eff, brightness


def _probe_frame_is_degenerate(gray_arr):
    """True для вырожденного (сплошного, однотонного) кадра — реальный
    контент практически никогда не имеет нулевой дисперсии по всему кадру,
    порог с запасом (0.5 из 0..255) отсекает именно "стену одного цвета",
    не просто тёмную/пересвеченную, но текстурную сцену."""
    return float(gray_arr.std()) < 0.5


def extract_video_probe_frame(path, base_at=0.5, retry_ats=(1.5, 3.0), timeout=20, q=5):
    """Кадр-пробник для видео, устойчивый к чёрному лидер-кадру/fade-in
    длиннее 0.5с — реальный, подтверждённый на живом кэше эпизода случай
    (см. измерение на 0008_f62be164.mp4: t=0.1 и t=0.5 оба чисто чёрные,
    std=0, реальный контент начинается только к t≈1.0). Пробует base_at
    (дешёвый общий случай), при вырожденном результате — по очереди
    retry_ats, пока не найдёт нетривиальный кадр. Возвращает
    (путь_к_temp_jpg, нужно_ли_удалить) или (None, False), если ни одна
    попытка не дала реального кадра.

    Только для ОДНОКАДРОВЫХ пробников (measure_luma(),
    visual_qc._extract_probe_frame()) — measure_levels() уже сэмплирует
    НЕСКОЛЬКО кадров по 3.5с диапазону, там один вырожденный сэмпл из
    четырёх и так растворяется в остальных, отдельный фикс не нужен."""
    if np is None:
        return None, False
    for at in (base_at,) + tuple(retry_ats):
        tmp = path + f"._probe_{at:.2f}.jpg"
        try:
            r = subprocess.run(["ffmpeg", "-y", "-ss", f"{at:.2f}", "-i", path,
                                 "-frames:v", "1", "-q:v", str(q), tmp],
                                capture_output=True, timeout=timeout)
        except Exception:
            continue
        if r.returncode != 0 or not os.path.exists(tmp):
            continue
        try:
            arr = np.asarray(PILImage.open(tmp).convert("L"), dtype=np.float32)
        except Exception:
            os.remove(tmp)
            continue
        if _probe_frame_is_degenerate(arr):
            os.remove(tmp)
            continue
        return tmp, True
    return None, False


@memoize_by_frame
def measure_luma(path, is_video=False):
    """Средняя яркость кадра (0..1) — для сглаживания скачков экспозиции
    между соседними склейками (см. main()): сток из разных источников
    скачет по яркости кадр-к-кадру, это частый "любительский" tell в
    компиляциях. Для видео берём один кадр в начале — грубой оценки
    достаточно, не нужен точный анализ всего клипа (устойчиво к чёрному
    лидер-кадру — см. extract_video_probe_frame())."""
    try:
        if is_video:
            tmp, cleanup = extract_video_probe_frame(path)
            if tmp is None:
                return None
            img = PILImage.open(tmp).convert("L").resize((64, 36))
            if cleanup:
                os.remove(tmp)
        else:
            img = PILImage.open(path).convert("L").resize((64, 36))
        arr = list(img.getdata())
        return sum(arr) / len(arr) / 255.0
    except Exception:
        return None


def _md5_file(path):
    h = hashlib.md5()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def _fixed_audio_is_current(fixed_path):
    """P0-1 форензик-аудита (реальный, подтверждённый риск): раньше
    find_audio() безусловно выбирал audio_fixed.flac, если он просто
    СУЩЕСТВОВАЛ на диске — единственная проверка (в load_pause_cuts())
    сверяла source_audio_md5 только для ТАЙМИНГА (cuts), не для самого
    аудиофайла, идущего в саундтрек. Сценарий поломки: переозвучили
    эпизод (заменили audio.mp3), забыли перезапустить fix_pauses.py —
    pipeline_smart.py тихо собрал бы ролик СО СТАРЫМ ГОЛОСОМ из
    audio_fixed.flac, но с НОВЫМИ alignment/субтитрами/таймингом (та же
    MD5-проверка raw в load_pause_cuts() к этому моменту уже откатилась
    бы на identity-маппинг — тайминг просто перестал бы быть точным,
    но голос всё равно звучал бы чужой). Тестов на этот сценарий не было.

    Проверка в 2 уровня — media_plan/pause_cuts.json теперь (см.
    fix_pauses.save_cuts) хранит И source_audio_md5 (сырой audio.mp3), И
    fixed_audio_md5 (сам готовый audio_fixed.flac этого прогона):
    - оба поля есть и совпадают с текущими файлами -> True (полная гарантия);
    - fixed_audio_md5 отсутствует (старый формат pause_cuts.json, эпизод
      обработан ДО этого фикса) -> откат на прежнюю проверку (только
      source_audio_md5) — не хуже статус-кво для уже работающих старых
      эпизодов, не новое ограничение "из ниоткуда";
    - файла pause_cuts.json нет вообще (fix_pauses.py ни разу не
      запускался) -> False, но это не регрессия: раньше в этом случае
      audio_fixed.flac физически не существовало бы (никто его не создал),
      этот код и не вызывался бы."""
    cuts_path = os.path.join(VIDEO_FOLDER, "media_plan", "pause_cuts.json")
    if not os.path.exists(cuts_path):
        return False
    try:
        data = json.load(open(cuts_path, encoding="utf-8"))
    except Exception:
        return False
    raw_path = os.path.join(VIDEO_FOLDER, "audio.mp3")
    expected_src = data.get("source_audio_md5")
    if not expected_src or not os.path.exists(raw_path):
        return False
    if _md5_file(raw_path) != expected_src:
        return False
    expected_fixed = data.get("fixed_audio_md5")
    if expected_fixed is None:
        return True   # старый формат pause_cuts.json — прежний уровень доверия
    return os.path.exists(fixed_path) and _md5_file(fixed_path) == expected_fixed


def find_audio():
    # audio_fixed.flac — текущий выход fix_pauses.py (P0-4: FLAC вместо
    # MP3, вторая lossy-перекодировка поверх TTS-исходника была слышна на
    # "с"/"ш"/"ч"). audio_fixed.mp3 оставлен в порядке поиска для старых
    # эпизодов, чья озвучка уже была прогнана через fix_pauses.py до этого
    # фикса — не задел бы их молча.
    for name in ("audio_fixed.flac", "audio_fixed.mp3"):
        p = os.path.join(VIDEO_FOLDER, name)
        if os.path.exists(p):
            if _fixed_audio_is_current(p):
                return p
            print(f"  ВНИМАНИЕ: {name} не соответствует текущему audio.mp3 или "
                  f"media_plan/pause_cuts.json (озвучку заменили без повторного "
                  f"fix_pauses.py?) — игнорирую устаревший файл, использую audio.mp3 "
                  f"НАПРЯМУЮ (без обрезки пауз/нормализации громкости). Перезапусти "
                  f"scripts/fix_pauses.py, чтобы получить их обратно на новой озвучке.")
            break
    p = os.path.join(VIDEO_FOLDER, "audio.mp3")
    if os.path.exists(p):
        return p
    # os.listdir по несуществующей папке — FileNotFoundError НА ИМПОРТЕ
    # модуля (find_audio зовётся на уровне модуля), то есть опечатка в пути к
    # эпизоду давала сырой трейсбек вместо понятного сообщения. Поймано
    # вживую: свежий клон без папки videos/ (git не хранит пустые каталоги) +
    # любой скрипт, который импортирует pipeline_smart с таким путём.
    if not os.path.isdir(VIDEO_FOLDER):
        return os.path.join(VIDEO_FOLDER, "audio.mp3")
    mp3s = [f for f in os.listdir(VIDEO_FOLDER) if f.lower().endswith(".mp3")]
    return os.path.join(VIDEO_FOLDER, mp3s[0]) if mp3s else os.path.join(VIDEO_FOLDER, "audio.mp3")


AUDIO_FILE = find_audio()


def load_json_dict(path):
    if os.path.exists(path):
        try:
            return json.load(open(path, encoding="utf-8"))
        except Exception as e:
            print(f"  Битый {path}, пропускаю: {e}")
    return {}


def load_themes():
    """Два уровня: канальный словарь (channel_themes.json в корне репо —
    общие для ниши слова вроде "меч"/"доспех"/"музей", не меняются от
    ролика к ролику) + эпизодный (media_plan/themes.json конкретного
    видео — только то, что специфично именно этой теме). Раньше весь
    словарь собирался заново руками под каждый новый сценарий; теперь
    новому эпизоду нужно всего несколько строк добавки поверх базы."""
    base_path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
                              "channel_themes.json")
    episode_path = os.path.join(VIDEO_FOLDER, "media_plan", "themes.json")
    merged = load_json_dict(base_path)
    merged.update(load_json_dict(episode_path))
    return merged


THEMES = load_themes()

# channel_profile.json (в корне репо, рядом с CHANNEL.md) — творческие
# характеристики КОНКРЕТНОГО канала (грейд/контент-блоклист/тюнинг голоса),
# вынесенные из кода в конфиг (см. docs/ROADMAP_CHANNEL_PROFILE.md, ЧАСТЬ 24
# CLAUDE.md). Файла нет/пуст -> ничего не меняется: MOOD_GRADE/
# CONTENT_ALT_BLOCKLIST/VOICE_* ниже уже определены как хардкод этого
# (военно-исторического) канала, override применяется ПОВЕРХ них по
# отдельности, там, где эти константы объявлены — сам этот файл нужен
# только затем, чтобы CHANNEL_PROFILE был готов до первого override. Клон
# репозитория под другую нишу (см. ЧАСТЬ 24) заводит СВОЙ
# channel_profile.json — код трогать не нужно.
CHANNEL_PROFILE = load_json_dict(os.path.join(
    os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "channel_profile.json"))

# Override зашитых творческих констант этого канала значениями из профиля,
# если он есть (см. комментарий выше) — MOOD_GRADE (грейд по секциям) и
# VOICE_* (тюнинг обработки голоса) уже определены выше как хардкод по
# умолчанию, здесь их значение переопределяется ЦЕЛИКОМ по ключу, если
# ключ есть в channel_profile.json, иначе остаются как были (сам вызов
# .get() со вторым аргументом = уже присвоенное значение — не дублирует
# дефолты второй раз). CONTENT_ALT_BLOCKLIST переопределяется так же, у
# своего определения ниже (объявлена позже в файле).
MOOD_GRADE = CHANNEL_PROFILE.get("mood_grade", _MOOD_GRADE_DEFAULT)
_voice_profile = CHANNEL_PROFILE.get("voice", {})
VOICE_HIGHPASS_HZ = _voice_profile.get("highpass_hz", VOICE_HIGHPASS_HZ)
VOICE_EQ_WARMTH_HZ = _voice_profile.get("eq_warmth_hz", VOICE_EQ_WARMTH_HZ)
VOICE_EQ_WARMTH_GAIN = _voice_profile.get("eq_warmth_gain", VOICE_EQ_WARMTH_GAIN)
VOICE_EQ_PRESENCE_HZ = _voice_profile.get("eq_presence_hz", VOICE_EQ_PRESENCE_HZ)
VOICE_EQ_PRESENCE_GAIN = _voice_profile.get("eq_presence_gain", VOICE_EQ_PRESENCE_GAIN)
VOICE_DEESS_INTENSITY = _voice_profile.get("deess_intensity", VOICE_DEESS_INTENSITY)
VOICE_COMPRESS_THRESHOLD = _voice_profile.get("compress_threshold", VOICE_COMPRESS_THRESHOLD)
VOICE_COMPRESS_RATIO = _voice_profile.get("compress_ratio", VOICE_COMPRESS_RATIO)

# Слова, по которым блок вероятно описывает физическое действие/движение —
# видео туда осмысленно (бой на стоке реально показывает бой), не просто
# механическая чётность i%2 (см. main() — та не различала "плита лежит на
# столе" от "штурм крепости", зритель подсознательно считывает периодичность
# чередования). Общая лексика военно-исторической ниши, не привязана к
# конкретному эпизоду — как THEMES, расширяется по мере надобности.
#
# РЕАЛЬНЫЙ, ИЗМЕРЕННЫЙ баг (прямая жалоба пользователя: "когда говорится, что
# герой заносит клинок, показывается просто фото меча вместо видео, где
# персонаж заносит меч"). Причина найдена и посчитана, не предположена:
# проверка шла ТОЧНЫМ совпадением словоформы со словарём, а русский язык
# склоняет и спрягает. В тексте "Герой на экране ЗАНОСИТ клинок, РЫЧИТ, враг
# ПАДАЕТ" нет ни одной словарной формы — блок уходил в фото. На реальном
# эпизоде videos/01_ves-mecha (91 блок) старая проверка срабатывала на 3
# блоках из 91 (3.3%), пропуская при этом блоки с очевидным действием. То
# есть заявленный в main() "content-aware выбор фото/видео" фактически не
# работал: в 97% случаев решение принимал h_text % 2 — ровно та механическая
# чередовка, которую этот код должен был заменить. Это тот же класс ошибки,
# что уже задокументирован в CLAUDE.md ЧАСТЬ 8 ("важно понимать" в словаре
# не ловит форму "важно понять").
#
# Теперь сравнение по ОСНОВЕ слова (startswith), а не по полной форме: на том
# же эпизоде 3 -> 14 блоков (3.3% -> 15.4%), включая тот самый блок из жалобы.
#
# Основы выверены на коллизии ВРУЧНУЮ по реальному тексту канала — наивный
# список основ давал ложные срабатывания, каждое ниже реально найдено, не
# гипотетическое: "метал" ловит "МЕТАЛЛ" (на оружейном канале — сплошь),
# "сеч" ловит "СЕЧЕНИЕ клинка" (прямой термин этой ниши), "руб" ловит
# "РУБЛЬ"/"РУБЕЖ", "сраз" ловит "СРАЗУ" (найдено прогоном по эпизоду),
# "боя"/"бои" ловят "БОЯТСЯ"/"БОИТСЯ" (тема страха в бою — постоянная у
# этого канала). Поэтому основы намеренно длиннее и конкретнее, чем
# "минимально достаточные", плюс явный стоп-список ACTION_STEM_EXCLUDE на
# слова-омонимы, которые основа всё же зацепила бы.
ACTION_STEMS = (
    "битв", "сражен", "сража", "штурм", "атак", "нападен", "напада",
    "поход", "маршир", "наступлен", "отступлен", "погоня", "погони", "погоню",
    "бегут", "бежал", "бежит", "бегом", "мчат", "мчал", "скакал", "скачет",
    "скачка", "удар", "рубил", "рубит", "рубят", "рубить", "рубк",
    "сеча", "сечи", "сечь", "фехт", "поедин", "дуэл", "разил", "разит",
    "пожар", "горит", "горят", "горел", "взрыв", "обстрел",
    "осада", "осади", "осажд", "прорыв", "рукопашн", "схватк", "резн",
    "занос", "занёс", "занес", "замахн", "замахив", "размах", "взмах",
    "махал", "махнул", "бьёт", "бьют", "колол", "колющ", "укол", "вонз",
    "пробив", "пробил", "ломал", "ломает", "ломают", "сломал",
    "драл", "драк", "дерут", "дерёт", "режет", "резал", "резать",
    "пада", "упал", "рычит", "рычал", "отбива", "отбил", "парир",
    "швыр", "метнул", "метание", "бой",
)
# Омонимы, которые основа выше всё-таки цепляет — проверяются ПЕРВЫМИ.
# Каждое слово здесь либо реально встретилось в тексте канала, либо
# заведомо частотно именно в этой нише (металл/сечение/клинок).
ACTION_STEM_EXCLUDE = frozenset((
    "сразу", "маршрут", "маршрута", "маршруты", "металл", "металла",
    "металлы", "металлург", "рубль", "рубля", "рублей", "рубеж", "рубежа",
    "сечение", "сечения", "осадок", "осадки", "боится", "боятся", "боязнь",
    "бойкий", "погоны", "погон", "билет", "походка", "походки", "скачать",
    "разительный", "падаль",
))


def has_action_word(text):
    """Описывает ли блок физическое действие/движение — критерий заказа
    ВИДЕО вместо фото (см. main()). Сравнение по основе слова, см. подробный
    разбор у ACTION_STEMS выше."""
    for w in text.split():
        w = re.sub(r'[^\w]', '', w.lower())
        if not w or w in ACTION_STEM_EXCLUDE:
            continue
        if any(w.startswith(s) for s in ACTION_STEMS):
            return True
    return False


# Вторая половина той же жалобы пользователя: мало ВЫБРАТЬ видео вместо фото —
# сам поисковый запрос тоже не несёт действия. На блоке "герой заносит клинок"
# запрос собирается словарём THEMES по КОРНЮ ПРЕДМЕТНОГО СЛОВА ("клинок" ->
# "medieval sword close up") и описывает предмет крупным планом, то есть
# заведомо статичный кадр — даже идеальный по этому запросу результат не
# покажет замах. Пользователь сформулировал это точно: подбор идёт "не по
# полному предложению, а только по слову".
#
# Уточнение движения добавляется ТОЛЬКО к строке видео-поиска и только когда
# в блоке реально есть глагол действия — тот же приём и та же дисциплина, что
# у disambiguate_search_query() (ключ кэша и relevance-скоринг остаются на
# исходном запросе, чтобы не сдвигать уже откалиброванные пороги
# CLIP_RELEVANCE_THRESHOLD/RISKY_QUERY_MARGIN).
#
# Формулировки ПРОВЕРЕНЫ на живом Pexels API (не подобраны по интуиции), и
# часть кандидатов отклонена по результату выдачи:
#  - "swinging" отвергнуто: тянет "woman sitting on swing" (качели) — реальный
#    мусор в выдаче на живом запросе; "wielding" на том же запросе дал ноль
#    мусора и поднял наверх бой/обнажение клинка.
#  - Группа "падает/ломается" ("falling") УБРАНА целиком: на живой проверке
#    дала слабую выдачу (абстрактный цветной паттерн среди первых пяти), а её
#    триггеры у этого канала чаще метафоричны ("спрос упал", "миф рухнул"),
#    чем физичны. Сами основы остаются в ACTION_STEMS (решение "видео вместо
#    фото" — отдельное и менее рискованное), но уточнять ими ЗАПРОС нечем:
#    честнее не уточнять, чем уточнять во вред.
ACTION_VIDEO_QUALIFIERS = (
    (("занос", "занёс", "занес", "замахн", "замахив", "размах", "взмах",
      "махал", "махнул"), "wielding"),
    (("рубил", "рубит", "рубят", "рубить", "рубк", "сеча", "сечи", "сечь"), "slashing"),
    (("колол", "колющ", "укол", "вонз"), "thrusting"),
    (("фехт", "поедин", "дуэл"), "fencing duel"),
    (("битв", "сражен", "сража", "схватк", "рукопашн", "драл", "драк", "бой",
      "резн"), "fighting"),
    (("атак", "штурм", "наступлен", "прорыв", "нападен", "напада", "осада",
      "осади", "осажд"), "charging attack"),
    (("скакал", "скачет", "скачка"), "galloping horse"),
    (("бегут", "бежал", "бежит", "бегом", "мчат", "мчал"), "running"),
    (("маршир", "поход"), "marching"),
    (("пожар", "горит", "горят", "горел", "взрыв", "обстрел"), "fire flames"),
)


def action_video_qualifier(text):
    """Английское слово-уточнение движения по тексту блока, или None.
    Первое совпавшее правило (порядок = приоритет: конкретный жест важнее
    общего "бой"). Тот же стоп-список омонимов, что у has_action_word()."""
    if not text:
        return None
    words = [re.sub(r'[^\w]', '', w.lower()) for w in text.split()]
    words = [w for w in words if w and w not in ACTION_STEM_EXCLUDE]
    for stems, qualifier in ACTION_VIDEO_QUALIFIERS:
        if any(w.startswith(s) for w in words for s in stems):
            return qualifier
    return None


def apply_action_qualifier(query, qualifier):
    """Уточнение движения перед запросом — только те СЛОВА, которых в запросе
    ещё нет (тот же приём против дублей, что в disambiguate_search_query:
    реальный баг первой версии там — "european medieval medieval armor")."""
    if not qualifier:
        return query
    ql = query.lower()
    missing = [w for w in qualifier.split() if w not in ql]
    if not missing:
        return query
    return f"{' '.join(missing)} {query}"


def get_audio_duration():
    r = subprocess.run(["ffprobe", "-v", "quiet", "-print_format", "json",
                        "-show_format", AUDIO_FILE], capture_output=True, text=True, check=True)
    return float(json.loads(r.stdout)["format"]["duration"])


ALIGNMENT_DIR = os.path.join(VIDEO_FOLDER, "media_plan", "alignment")
ALIGNMENT_TAG_RE = re.compile(r'\[short pause\]|\[pause\]')
ALIGNMENT_STRIP_TAGS = ("[energetic]", "[slowly]", "[emphasis]")
PAUSE_CUTS_PATH = os.path.join(VIDEO_FOLDER, "media_plan", "pause_cuts.json")
_PAUSE_CUTS_CACHE = None   # ленивый кэш на процесс — файл не меняется за время рендера


def load_pause_cuts():
    """[[вырезанный_старт, вырезанный_конец], ...] в СЫРОМ времени audio.mp3
    (см. fix_pauses.save_cuts) — реальные интервалы, которые
    silencedetect+atrim вычистили из аудио. Нет файла (старый эпизод, ещё
    не пересчитанный fix_pauses.py) -> [] (тихий откат на identity-маппинг,
    raw_to_real_time тогда просто возвращает t без изменений).

    Проверка отпечатка (source_audio_md5): pause_cuts.json описывает
    порезки КОНКРЕТНОГО audio.mp3 на момент запуска fix_pauses.py. Если
    audio.mp3 потом перезаписали (новая озвучка, правка) без повторного
    fix_pauses.py — порезки больше не соответствуют реальности, а
    raw_to_real_time() молча применил бы их к чужому аудио, воспроизводя
    ровно тот класс рассинхрона, который этот файл должен был исправить.
    Несовпадение -> предупреждение в консоль + откат на [] (честно "без
    точной подгонки", а не тихая порча по устаревшим данным)."""
    global _PAUSE_CUTS_CACHE
    if _PAUSE_CUTS_CACHE is not None:
        return _PAUSE_CUTS_CACHE
    try:
        with open(PAUSE_CUTS_PATH, encoding="utf-8") as f:
            data = json.load(f)
        raw_audio_path = os.path.join(VIDEO_FOLDER, "audio.mp3")
        expected_md5 = data.get("source_audio_md5")
        if expected_md5 and os.path.exists(raw_audio_path):
            h = hashlib.md5()
            with open(raw_audio_path, "rb") as af:
                for chunk in iter(lambda: af.read(1 << 20), b""):
                    h.update(chunk)
            if h.hexdigest() != expected_md5:
                print("  ВНИМАНИЕ: pause_cuts.json не соответствует текущему audio.mp3 "
                      "(перезаписали озвучку без повторного fix_pauses.py?) — "
                      "порезки игнорирую, подписи хука пересчитаются без точной подгонки паузы.")
                _PAUSE_CUTS_CACHE = []
                return _PAUSE_CUTS_CACHE
        _PAUSE_CUTS_CACHE = [(float(a), float(b)) for a, b in data.get("cuts", [])]
    except Exception:
        _PAUSE_CUTS_CACHE = []
    return _PAUSE_CUTS_CACHE


_PAUSE_WINDOWS_CACHE = None   # ленивый кэш на процесс, как и _PAUSE_CUTS_CACHE


def load_pause_windows():
    """[[сырой_старт_тишины, сколько_оставлено], ...] — см. fix_pauses.save_cuts
    (P1-15). Используется только для музыкального "вздоха" на осознанно
    длинных паузах (см. _pause_swell_expr), поэтому переиспользует тот же
    файл/отпечаток, что и load_pause_cuts(), но не трогает её кэш и формат
    (raw_to_real_time распаковывает cuts как строгие (a, b) пары повсюду в
    файле — здесь отдельный ключ, отдельная проверка). Нет файла/ключа или
    отпечаток не совпадает с текущим audio.mp3 -> [] (тихий откат, как и
    у load_pause_cuts)."""
    global _PAUSE_WINDOWS_CACHE
    if _PAUSE_WINDOWS_CACHE is not None:
        return _PAUSE_WINDOWS_CACHE
    try:
        with open(PAUSE_CUTS_PATH, encoding="utf-8") as f:
            data = json.load(f)
        raw_audio_path = os.path.join(VIDEO_FOLDER, "audio.mp3")
        expected_md5 = data.get("source_audio_md5")
        if expected_md5 and os.path.exists(raw_audio_path):
            h = hashlib.md5()
            with open(raw_audio_path, "rb") as af:
                for chunk in iter(lambda: af.read(1 << 20), b""):
                    h.update(chunk)
            if h.hexdigest() != expected_md5:
                _PAUSE_WINDOWS_CACHE = []
                return _PAUSE_WINDOWS_CACHE
        _PAUSE_WINDOWS_CACHE = [(float(a), float(b)) for a, b in data.get("pause_windows", [])]
    except Exception:
        _PAUSE_WINDOWS_CACHE = []
    return _PAUSE_WINDOWS_CACHE


def raw_to_real_time(t, cuts):
    """Точный (не приближённый по тегам) пересчёт сырого времени alignment.csv
    (до обрезки пауз в fix_pauses.py) в реальное время audio_fixed.mp3 —
    вычитает из t суммарно всё, что реально вырезано ДО t (частично, если t
    попадает внутрь самого вырезанного интервала). cuts — из load_pause_cuts(),
    отсортированы по возрастанию (естественный порядок silencedetect)."""
    removed = 0.0
    for a, b in cuts:
        if a >= t:
            break
        removed += min(t, b) - a
    return t - removed


_SECTION_OFFSETS_CACHE = None   # ленивый кэш на процесс, как и _PAUSE_CUTS_CACHE
SECTION_OFFSETS_PATH = os.path.join(VIDEO_FOLDER, "media_plan", "section_offsets.json")


def load_section_offsets():
    """{section_name: raw_global_offset_sec} из media_plan/section_offsets.json —
    пишет scripts/speech_generate.py Stage B (сам конкатенирует фрагменты,
    знает точно) ИЛИ scripts/section_sync.py (кросс-корреляция паттерна
    пауз против реального аудио — для эпизодов без Stage B, см. докстринг
    section_sync.py). Нет файла -> {} (тихий откат: offsets.get(name, 0.0)
    везде ниже даёт РОВНО прежнее поведение — локальное время секции
    трактуется как глобальное, корректно только для первой секции по
    определению, как и было до этой карты)."""
    global _SECTION_OFFSETS_CACHE
    if _SECTION_OFFSETS_CACHE is not None:
        return _SECTION_OFFSETS_CACHE
    try:
        with open(SECTION_OFFSETS_PATH, encoding="utf-8") as f:
            data = json.load(f)
        _SECTION_OFFSETS_CACHE = {str(k): float(v) for k, v in data.items()}
    except Exception:
        _SECTION_OFFSETS_CACHE = {}
    return _SECTION_OFFSETS_CACHE


def _clean_timed_chars(segment):
    """Только РЕАЛЬНО озвученные символы сегмента с их временами
    [(char, start, end), ...] — без пробелов, скобок и служебных тегов вроде
    [energetic]/[slowly] (они не читаются TTS вслух, но формально попадают в
    поток символов alignment.csv). Общая основа для _real_speech_bounds()
    (границы сегмента) и load_alignment_onsets() (посимвольная привязка
    ПОД-блоков внутри сегмента) — одна реализация фильтра на оба места,
    иначе они молча разошлись бы при следующей правке."""
    text = "".join(c for c, s, e in segment)
    excluded = set()
    for tag in ALIGNMENT_STRIP_TAGS:
        idx = text.find(tag)
        while idx != -1:
            for j in range(idx, idx + len(tag)):
                excluded.add(j)
            idx = text.find(tag, idx + 1)
    return [(c, s, e) for j, (c, s, e) in enumerate(segment)
            if j not in excluded and re.match(r'[^\s\[\]]', c or "")]


def speech_chars_of_text(text):
    """Та же нормализация, что _clean_timed_chars(), но для ТЕКСТА блока —
    строка из одних озвучиваемых символов. Позволяет сопоставить блок с его
    участком посимвольного alignment один-в-один: sub-cut'ы (см.
    split_long_blocks) делят слова исходного блока БЕЗ остатка, поэтому их
    очищенные тексты, склеенные подряд, посимвольно равны очищенному тексту
    сегмента — это и даёт точную, а не пропорциональную привязку под-кадра
    ко времени озвучки."""
    text = re.sub(r'\[[^\]]*\]', '', text or "")
    return re.sub(r'[\s\[\]]', '', text)


def _real_speech_bounds(segment):
    """(старт, конец) реально озвученного текста в сегменте символов
    (index,char,start,end) — по первому и последнему озвученному символу
    (см. _clean_timed_chars). None, если в сегменте нет ни одного реального
    символа."""
    clean = _clean_timed_chars(segment)
    if not clean:
        return None
    return clean[0][1], clean[-1][2]


def _real_speech_span(segment, section_offset=0.0):
    """РЕАЛЬНАЯ (после обрезки пауз fix_pauses.py, см. raw_to_real_time)
    длительность озвученного текста в сегменте — см. _real_speech_bounds
    (общая логика, тег-агностичная граница). Раньше возвращала СЫРУЮ
    длительность (до обрезки) — а именно эта величина кормит вес блока в
    load_alignment_weights()/block_durations(), то есть раньше ДЛИТЕЛЬНОСТЬ
    КАДРА блока могла быть завышена, если внутри блока TTS сделал
    незапланированную (не тегом [pause]) паузу/вдох длиннее секунды —
    silencedetect в fix_pauses.py режет ЛЮБУЮ такую тишину, независимо от
    тегов в тексте (пойман вживую: 41 реальная порезка на 90 тегов паузы в
    эпизоде — то есть часть порезок вообще не в тех местах, где текст
    формально ожидал паузу). Теперь вес блока — точно то время, что он
    реально звучит в audio_fixed.mp3, а не в сыром audio.mp3.

    section_offset — сдвиг ЛОКАЛЬНОГО времени сегмента (свой ноль на файл
    alignment/NN.csv) в ГЛОБАЛЬНОЕ (по всему audio.mp3, та же шкала, что и
    cuts из load_pause_cuts() — см. load_section_offsets()). Раньше bounds
    (локальные) подавались в raw_to_real_time() НАПРЯМУЮ, как будто уже
    глобальные — для первой секции (HOOK) это случайно верно (локальный
    ноль совпадает с глобальным), для всех следующих секций cuts из ДРУГИХ
    участков ролика применялись не туда, давая неверный вес блока —
    реальный, эмпирически подтверждённый баг (см. section_sync.py)."""
    bounds = _real_speech_bounds(segment)
    if not bounds:
        return 0.0
    cuts = load_pause_cuts()
    real_start = raw_to_real_time(bounds[0] + section_offset, cuts)
    real_end = raw_to_real_time(bounds[1] + section_offset, cuts)
    return real_end - real_start


def _alignment_section_segments(blocks):
    """{секция: [сегмент, ...]} — разборка media_plan/alignment/NN.csv на
    сегменты по тегам пауз. Общая основа для load_alignment_weights() (вес
    блока) и load_alignment_onsets() (момент НАЧАЛА блока) — одна реализация
    на оба места. None, если папки alignment нет вообще."""
    if not os.path.isdir(ALIGNMENT_DIR):
        return None
    section_order = []
    for b in blocks:
        if not section_order or section_order[-1] != b["section"]:
            section_order.append(b["section"])
    section_segments = {}
    for i, name in enumerate(section_order):
        path = os.path.join(ALIGNMENT_DIR, f"{i:02d}.csv")
        if not os.path.exists(path):
            continue
        try:
            rows = list(csv.DictReader(open(path, encoding="utf-8")))
            chars = [(r["char"], float(r["start"]), float(r["end"])) for r in rows]
        except Exception as e:
            print(f"  alignment {path} битый, пропускаю: {e}")
            continue
        text = "".join(c for c, s, e in chars)
        segs, pos = [], 0
        for m in ALIGNMENT_TAG_RE.finditer(text):
            segs.append(chars[pos:m.start()])
            pos = m.end()
        segs.append(chars[pos:])
        section_segments[name] = segs
    return section_segments


ONSET_TEXT_MATCH_MIN_RATIO = 0.9   # ниже — текст блока разошёлся с озвученным, привязке нельзя доверять


def load_alignment_onsets(blocks):
    """РЕАЛЬНЫЙ момент НАЧАЛА речи каждого блока (сек, в шкале финального
    audio_fixed — после обрезки пауз fix_pauses.py). Список длиной len(blocks)
    или None, если хотя бы для одного блока привязка не подтвердилась
    (fail-open целиком, а не частично: половина точных онсетов и половина
    угаданных дала бы рассинхрон хуже, чем честная старая оценка).

    ЗАЧЕМ ЭТО ЕСТЬ (реальная, измеренная причина — 28 августа, разбор жалобы
    «видео показывается позже, когда фраза уже сказана»): длительности кадров
    считались по load_alignment_weights() — то есть по ДЛИНЕ речи блока, а не
    по её ПОЛОЖЕНИЮ. Дальше эта оценка проходила через семь преобразований
    (floor/cap-клэмп и rescale в block_durations, energy_mults, apply_section_
    boundary_shift ±250-400мс, apply_within_cut_shift ±80-180мс,
    apply_human_jitter ±300мс, snap_hook_cuts_to_energy), каждое из которых
    двигает границу кадра ОТНОСИТЕЛЬНО фразы, а ошибки складываются по
    накоплению — к концу хука рез уезжает от своей фразы на доли секунды и
    больше. Зритель видит ровно то, на что жаловался пользователь: кадр
    «не под озвучку».

    Длина речи не даёт положения — его даёт только ОНСЕТ. Поэтому здесь
    возвращается именно момент начала, и по нему (см. phrase_locked_durations)
    рез ставится ТОЧНО на начало следующей фразы.

    ТОЧНОСТЬ ДЛЯ ПОД-КАДРОВ: sub-cut'ы (split_long_blocks) делят слова
    исходного блока без остатка, поэтому очищенные тексты под-блоков,
    склеенные подряд, посимвольно равны очищенному тексту сегмента —
    привязка идёт по РЕАЛЬНОМУ символу alignment, а не пропорционально
    числу слов (как считается вес в load_alignment_weights).

    БЕЗОПАСНОСТЬ: текст каждого блока сверяется с реально озвученными
    символами на его позиции (ONSET_TEXT_MATCH_MIN_RATIO). Сценарий,
    поправленный ПОСЛЕ записи озвучки, не получит чужой тайминг молча —
    вернётся None, и сборка честно откатится на прежнее поведение."""
    section_segments = _alignment_section_segments(blocks)
    if not section_segments:
        return None
    section_offsets = load_section_offsets()
    cuts = load_pause_cuts()
    onsets = []
    seg_idx, char_pos = {}, {}
    for b in blocks:
        section = b["section"]
        segs = section_segments.get(section)
        if segs is None:
            return None
        k = seg_idx.get(section, 0)
        if k >= len(segs):
            return None   # блоков больше, чем сегментов записи — доверять нечему
        clean = _clean_timed_chars(segs[k])
        pos = char_pos.get(section, 0)
        want = speech_chars_of_text(b["text"])
        if not want or pos + len(want) > len(clean):
            return None
        got = "".join(c for c, s, e in clean[pos:pos + len(want)])
        if difflib.SequenceMatcher(None, want.lower(), got.lower()).ratio() < ONSET_TEXT_MATCH_MIN_RATIO:
            return None
        offset = section_offsets.get(section, 0.0)
        onsets.append(raw_to_real_time(clean[pos][1] + offset, cuts))
        pos += len(want)
        if pos >= len(clean):
            seg_idx[section] = k + 1
            char_pos[section] = 0
        else:
            char_pos[section] = pos
    return onsets


PHRASE_LOCK = os.environ.get("PHRASE_LOCK", "1") != "0"


def _merge_two_blocks(pb, cb, prev_words):
    """Слить блок cb В предыдущий (уже накопленный) pb — общая часть между
    merge_short_phrase_locked_blocks() и её хвостовым случаем. prev_words —
    число слов pb ДО слияния (нужно для пересчёта позиции stat-плашки)."""
    nb = dict(pb)
    nb["text"] = (pb["text"].rstrip() + " " + cb["text"].lstrip()).strip()
    nb["words"] = pb["words"] + cb["words"]
    nb["pause_after"] = cb["pause_after"]
    if nb.get("stat") is None and cb.get("stat") is not None:
        sp = cb.get("stat_word_pos")
        nb["stat"] = cb["stat"]
        nb["stat_word_pos"] = (prev_words + sp) if sp is not None else None
    nb["is_climax"] = bool(pb.get("is_climax")) or bool(cb.get("is_climax"))
    return nb


def merge_short_phrase_locked_blocks(blocks, real_weights, total):
    """РЕАЛЬНЫЙ найденный вживую баг (29 августа, videos/_test20s, idx=4,
    1.33с) — HOOK_MIN_CLIP (см. её ревизию выше) клэмпит длительность только
    внутри block_durations()/hook_floor_for. Этот эпизод (как и любой с
    рабочим alignment.csv) идёт по PHRASE LOCK ветке (см. main(),
    phrase_locked_durations) — там длительность клипа считается СТРОГО как
    расстояние между реальными онсетами речи, без единого пола вообще:
    растянуть короткую фразу до пола означало бы, что рез уедет мимо начала
    следующей фразы — ровно тот рассинхрон, ради устранения которого PHRASE
    LOCK и был написан (см. её докстринг). Единственный способ дать
    гарантию пола БЕЗ рассинхрона — не резать на границе слишком короткой
    фразы вовсе: сливаем её текст с предыдущим блоком той же секции в один
    клип (та же идея, что уже мержит короткие sub-cut куски в
    split_long_blocks). Уцелевшие резы по-прежнему стоят РОВНО на реальном
    онсете — их просто меньше.

    БЕЗОПАСНОСТЬ СЛИЯНИЯ (реальный найденный вживую баг при первой версии
    этой функции): сливать можно ТОЛЬКО блок с is_subcut=True — то есть
    кусок, на который split_long_blocks() уже порезал ОДИН исходный
    [pause]-блок (его склеенный текст посимвольно принадлежит тому же
    сегменту alignment, см. docstring speech_chars_of_text). Слияние ДВУХ
    разных исходных [pause]-блоков (is_subcut отсутствует/False) рвёт
    привязку: посимвольный курсор load_alignment_onsets() идёт строго по
    сегментам записи, и склеенный текст двух разных сегментов не находит
    соответствия ни в одном из них — onsets на всём эпизоде становится
    None, то есть "починка" пола сломала бы ВЕСЬ phrase lock целиком
    (проверено вживую: первая версия без этой проверки именно так и
    сломала onsets на videos/_test20s). Итог: короткая фраза, стоящая
    ДЕЙСТВИТЕЛЬНО между двумя настоящими паузами (не sub-cut), пол может
    не выдержать — это честный, редкий остаточный случай (звучит короче
    пола ровно потому, что автор поставил паузы по обе стороны от неё),
    не маскируется молча.
    Никогда не сливает блоки РАЗНЫХ секций (та же граница, которую уважает
    apply_section_boundary_shift).
    Fail-open: без рабочего alignment (onsets is None) ничего не меняет —
    обычная ветка block_durations()/hook_floor_for уже даёт гарантию сама."""
    onsets = load_alignment_onsets(blocks)
    if not onsets or len(onsets) != len(blocks):
        return blocks, real_weights
    merged_blocks = [blocks[0]]
    merged_weights = [real_weights[0] if real_weights else None]
    merged_start = [onsets[0]]
    for i in range(1, len(blocks)):
        cb = blocks[i]
        pb = merged_blocks[-1]
        same_section = cb["section"] == pb["section"]
        floor = hook_floor_for(blocks, i - 1)
        gap = onsets[i] - merged_start[-1]
        if same_section and gap < floor and cb.get("is_subcut"):
            merged_blocks[-1] = _merge_two_blocks(pb, cb, pb["words"])
            pw = merged_weights[-1]
            cw = real_weights[i] if real_weights else None
            merged_weights[-1] = None if (pw is None and cw is None) else (pw or 0.0) + (cw or 0.0)
        else:
            merged_blocks.append(cb)
            merged_weights.append(real_weights[i] if real_weights else None)
            merged_start.append(onsets[i])
    # Хвост: последний клип держится от своего онсета до конца аудио — этот
    # интервал не участвовал в цикле выше (там сравнивались только соседние
    # онсеты между собой). Короче пола — сливаем с предыдущим клипом той же
    # секции (если он есть).
    if len(merged_blocks) > 1:
        tail_floor = hook_floor_for(blocks, len(blocks) - 1)
        tail_gap = total - merged_start[-1]
        if (tail_gap < tail_floor and merged_blocks[-1]["section"] == merged_blocks[-2]["section"]
                and merged_blocks[-1].get("is_subcut")):
            cb = merged_blocks.pop()
            merged_start.pop()
            cw = merged_weights.pop()
            pb = merged_blocks[-1]
            merged_blocks[-1] = _merge_two_blocks(pb, cb, pb["words"])
            pw = merged_weights[-1]
            merged_weights[-1] = None if (pw is None and cw is None) else (pw or 0.0) + (cw or 0.0)
    return merged_blocks, merged_weights


def phrase_locked_durations(onsets, total, trans_plan, fps=None):
    """Длительности клипов, при которых ВИДИМЫЙ рез приходится ТОЧНО на
    начало следующей фразы. None, если данных не хватает (fail-open).

    ДВЕ вещи, которые обязательно учесть, иначе точность теряется:

    1) КОМПЕНСАЦИЯ КРОССФЕЙДА. xfade_chain() физически СЖИМАЕТ смонтированный
       таймлайн на длительность каждого перехода (см. её же комментарий и
       hook_visual_starts): видимый старт клипа n равен cumsum(durs[:n])
       МИНУС сумма уже прошедших нахлёстов. Без поправки каждый следующий рез
       уезжает раньше своей фразы накопительно. Отсюда
       dur[i] = (онсет[i+1] - онсет[i]) + длительность_перехода[i] — при этом
       итоговая длина видео остаётся равна длине аудио (сумма поправок ровно
       компенсируется сжатием).

    2) КВАНТОВАНИЕ ПО ГРАНИЦАМ, А НЕ ПО ДЛИТЕЛЬНОСТЯМ. Клип не может быть
       дробным по кадрам. Если округлять каждую ДЛИТЕЛЬНОСТЬ отдельно (как
       делает quantize_durations_to_frames), ошибка округления складывается
       по всей цепочке. Здесь на кадровую сетку кладутся сами ГРАНИЦЫ, а
       длительности из них вычитаются — тогда каждый рез отстоит от своей
       фразы не более чем на полкадра (~21мс при 24 fps), и это НЕ копится."""
    if not onsets or total <= 0:
        return None
    fps = fps or FPS
    n = len(onsets)
    # Границы клипов на шкале РЕАЛЬНОГО аудио: клип i держится от начала своей
    # фразы до начала следующей (первый — от нуля, чтобы не было чёрного
    # экрана на ведущей тишине; последний — до конца аудио).
    bounds = [0.0] + [onsets[i] for i in range(1, n)] + [float(total)]
    if any(bounds[i + 1] <= bounds[i] for i in range(n)):
        return None   # непоследовательные онсеты — доверять нельзя
    cum = 0.0
    shifted = []
    for i, b in enumerate(bounds):
        shifted.append(b + cum)
        if i < len(trans_plan):
            cum += trans_plan[i][1]
    grid = [round(x * fps) / fps for x in shifted]
    durs = [grid[i + 1] - grid[i] for i in range(n)]
    if any(d < 1.0 / fps for d in durs):
        return None   # кадр короче одного кадра сетки физически не рендерится
    return durs


def load_alignment_weights(blocks):
    """Реальные веса длительности блоков из посимвольного alignment.csv
    (ElevenLabs/Lumean отдают его бесплатно вместе с каждым TTS-заказом —
    раньше просто не забирался). Раньше длительность блока считалась ЧИСТО
    по числу слов и общей скорости слов/сек — то есть каждое слово "весило"
    одинаково. На деле темп TTS живой: короткая ударная фраза читается
    быстрее длинной со сложными словами, [slowly]-блок — заметно медленнее.
    Реальный посимвольный тайминг ловит эту вариацию, а не усредняет её.

    Файлы лежат в media_plan/alignment/00.csv, 01.csv... — по одному на
    КАЖДУЮ секцию (HOOK, BLOCK 1, ..., FINAL) в порядке их первого появления
    в script.txt, разрезаны по буквальным вхождениям [pause]/[short pause]
    на сегменты 1:1 с под-блоками этой секции в том же порядке.

    Возвращает список той же длины, что blocks, — вес (сек) реальной речи
    на блок или None для блоков без данных (эпизод без сохранённого
    alignment, или новый блок, добавленный после записи — сборка тогда
    просто откатывается на word-count оценку для этих блоков, как раньше)."""
    section_segments = _alignment_section_segments(blocks)
    if section_segments is None:
        return None

    section_offsets = load_section_offsets()   # {} без Stage B/section_sync.py -> offset 0.0 для всех, как раньше
    weights = []
    seg_cursor = {}
    stale = 0
    for b in blocks:
        segs = section_segments.get(b["section"])
        if segs is None:
            weights.append(None)
            continue
        offset = section_offsets.get(b["section"], 0.0)
        k = seg_cursor.get(b["section"], 0)
        if k >= len(segs):
            # Число под-блоков в текущем script.txt разошлось с числом
            # сегментов в сохранённом alignment (текст правили после
            # записи) — честно откатываемся на word-count для остатка
            # секции, а не подставляем чужой сегмент не по месту.
            weights.append(None)
        else:
            # Число сегментов может совпасть, а ТЕКСТ — разойтись (слово-два
            # поправили в script.txt после записи озвучки, не тронув счётчик
            # [pause]) — тогда старый код молча применял чужой тайминг к
            # новому тексту. Fuzzy-сверка (difflib, без новых зависимостей)
            # блока против реально озвученного сегмента: разошлись сильнее
            # порога — честный откат на word-count вместо тихой подмены.
            seg_text = re.sub(r'\s+', ' ', "".join(c for c, s, e in segs[k])).strip().lower()
            block_text = re.sub(r'\s+', ' ', b["text"]).strip().lower()
            ratio = difflib.SequenceMatcher(None, block_text, seg_text).ratio() if (block_text and seg_text) else 0.0
            if ratio < 0.55:
                weights.append(None)
                stale += 1
            else:
                span = _real_speech_span(segs[k], offset)
                weights.append(span if span > 0.05 else None)
        seg_cursor[b["section"]] = k + 1
    if stale:
        print(f"  Alignment: {stale} блок(ов) текстом разошлись с сохранённым таймингом "
              f"(script.txt правили после записи?) — откат на word-count для них")
    return weights


def load_hook_word_timings(blocks=None, sub_starts=None, sub_baseline=None, real_weights=None):
    """D2: посимвольный alignment.csv хука (00.csv — хук всегда первая
    секция эпизода, см. load_alignment_weights) собран в СЛОВА.

    ИСТОРИЯ (три раунда одного и того же бага, каждый пойман вживую жалобой
    пользователя на рассинхрон подписей с голосом):
    1) слова раньше отдавались в СЫРОЙ абсолютной шкале 00.csv (до обрезки
       пауз) и напрямую сравнивались с уже обрезанной шкалой sub_starts.
    2) первый фикс приближал обрезку ПО ТЕГАМ [pause]/[short pause] в
       тексте — но fix_pauses.py режет ЛЮБУЮ акустическую тишину длиннее
       порога, включая нетегированные вдохи/микропаузы TTS (на реальном
       эпизоде — 41 реальная порезка на 90 тегов в тексте) — рассинхрон
       оставался внутри сегментов, где порезка пришлась не там, где текст
       её ожидал.
    3) raw_to_real_time() (см. fix_pauses.save_cuts/pause_cuts.json) даёт
       ТОЧНУЮ, не приближённую обрезку — но voed НАПРЯМУЮ давать точное
       "чистое" время слова оказалось МАЛО: sub_starts/sub_baseline сами
       считаются НЕ линейно от точного времени, а через block_durations() —
       там ОДИН глобальный коэффициент scale=total/sum(d) растягивает/жмёт
       ВСЕ блоки ролика разом, независимо от того, где реально резались
       паузы (в HOOK этого эпизода не отрезали ни секунды — а глобальный
       коэффициент всё равно сжимает и его, потому что пауз наотрезали в
       других секциях). Прямой точный маппинг слова уезжали в СОСЕДНИЙ блок.

    Правильная комбинация: слово сначала переводится в точное "чистое"
    время (raw_to_real_time, шаг 3), ЗАТЕМ его позиция ВНУТРИ своего
    досплитового сегмента (та же посегментная разбивка по тегам, что и в
    load_alignment_weights) пропорционально размещается в реальном окне
    блока [sub_starts[i], sub_starts[i]+sub_baseline[i]) — той же
    (глобально пересчитанной) шкале, что и картинки. real_weights (уже
    точные, см. _real_speech_span) — сколько "чистого" времени сегмента
    достаётся каждому под-блоку по порядку (sub-cuts режут один сегмент на
    несколько блоков), без остатка, раз сумма кусков точно равна точному
    спану сегмента. Без blocks/sub_starts/sub_baseline/real_weights —
    тихий откат на точное-но-не-выровненное-с-картинками время (лучше так,
    чем совсем без подписей).

    Нет alignment.csv -> [] (кинетика хука тихо не показывается, не
    регрессия — как и все alignment-based фичи в пайплайне)."""
    path = os.path.join(ALIGNMENT_DIR, "00.csv")
    if not os.path.exists(path):
        return []
    try:
        rows = list(csv.DictReader(open(path, encoding="utf-8")))
        chars = [(r["char"], float(r["start"]), float(r["end"])) for r in rows]
    except Exception:
        return []
    text = "".join(c for c, s, e in chars)
    cuts = load_pause_cuts()

    raw_segs, pos = [], 0
    for m in ALIGNMENT_TAG_RE.finditer(text):
        raw_segs.append(chars[pos:m.start()])
        pos = m.end()
    raw_segs.append(chars[pos:])

    remap = None
    if blocks and sub_starts is not None and sub_baseline is not None and real_weights is not None:
        hook_idxs = [i for i, b in enumerate(blocks) if b["section"].startswith("HOOK")]
        # Точные (после вычета реально вырезанных пауз) границы каждого
        # досплитового сегмента — та же raw_to_real_time, что уже даёт
        # real_weights через _real_speech_span, поэтому расход ниже сходится
        # без остатка (не приближение по сырому времени).
        seg_spans = []
        for seg in raw_segs:
            bounds = _real_speech_bounds(seg)
            seg_spans.append((raw_to_real_time(bounds[0], cuts), raw_to_real_time(bounds[1], cuts))
                              if bounds else None)

        remap = []
        seg_ptr = 0
        cursor = remaining = None

        def _advance_seg():
            nonlocal seg_ptr, cursor, remaining
            while seg_ptr < len(seg_spans) and seg_spans[seg_ptr] is None:
                seg_ptr += 1
            if seg_ptr < len(seg_spans):
                cursor = seg_spans[seg_ptr][0]
                remaining = seg_spans[seg_ptr][1] - seg_spans[seg_ptr][0]
            else:
                cursor, remaining = None, 0.0

        _advance_seg()
        for bi in hook_idxs:
            w = real_weights[bi] if (bi < len(real_weights) and real_weights[bi]) else 0.0
            if cursor is None or w <= 0:
                continue
            if remaining <= 1e-6:
                seg_ptr += 1
                _advance_seg()
                if cursor is None:
                    continue
            seg_start = cursor
            take = min(w, remaining)
            seg_end = seg_start + take
            if seg_end - seg_start > 1e-6:
                # sub_baseline[bi] — ПОЛНОЕ окно блока, включая хвостовую
                # паузу (block_durations() прибавляет b["pause_after"] к
                # "сырому" весу ДО floor/cap/глобального scale — см.
                # block_durations). Растягивать frac*sub_baseline напрямую
                # (было раньше) значит растягивать слово ВПЛОТЬ ДО КОНЦА
                # паузы — последнее слово блока держалось на экране почти
                # всю паузу целиком, реальная жалоба пользователя ("текста
                # не должно быть во время паузы"). Пауза — не постоянная
                # доля исходного сырого веса блока (real_weight + pause_after
                # -> sub_baseline через один и тот же floor/cap/scale), эта
                # ДОЛЯ инвариантна к равномерному масштабированию — берём её
                # и оставляем как подпись-свободный хвост окна.
                pause_after = blocks[bi].get("pause_after") or 0.0
                if pause_after > 0 and w > 0:
                    pause_frac = pause_after / (w + pause_after)
                    speech_dur = sub_baseline[bi] * (1.0 - pause_frac)
                else:
                    speech_dur = sub_baseline[bi]
                remap.append((seg_start, seg_end, sub_starts[bi], speech_dur))
            cursor = seg_end
            remaining -= take

    def rescale(t):
        real_t = raw_to_real_time(t, cuts)
        if not remap:
            return real_t
        for seg_start, seg_end, real_start, real_dur in remap:
            if seg_start - 1e-6 <= real_t <= seg_end + 1e-6:
                frac = (real_t - seg_start) / (seg_end - seg_start) if seg_end > seg_start else 0.0
                return real_start + frac * real_dur
        return real_t   # вне всех сегментов (хвостовой мусор) — не подменяем произвольно

    excluded = set()
    for tag in ALIGNMENT_STRIP_TAGS + ("[pause]", "[short pause]"):
        idx = text.find(tag)
        while idx != -1:
            for j in range(idx, idx + len(tag)):
                excluded.add(j)
            idx = text.find(tag, idx + 1)
    # Вырезанный тег ТОЖЕ обязан рвать слово, не только пробел — в сыром
    # тексте тег часто стоит БЕЗ пробела ("...убеждают.[short pause]Так
    # говорят" — точка сразу перед тегом, слово сразу после), простое
    # исключение символов тега без разрыва склеивало соседние слова в одно
    # ("килограммов.Так") — поймано вживую на реальном 00.csv эпизода.
    words, cur = [], []
    for j, (c, s, e) in enumerate(chars):
        if j in excluded or c.isspace() or c in "[]":
            if cur:
                words.append(("".join(ch for ch, _, _ in cur), cur[0][1], cur[-1][2]))
                cur = []
        else:
            cur.append((c, s, e))
    if cur:
        words.append(("".join(ch for ch, _, _ in cur), cur[0][1], cur[-1][2]))
    words = [(w, rescale(s), rescale(e)) for w, s, e in words]
    return [w for w in words if w[0]]


HOOK_CAPTION_MIN_DUR = 0.40   # 2.6: было 0.15 — реальная жалоба "слишком быстро исчезают"; короткие
# слова (особенно после вырезанной паузы) читались меньше половины секунды, почти нечитаемо на
# практике. 0.40с — всё ещё быстрый кинетический темп, но экранно различимо; растяжка по-прежнему
# не вылезает за начало следующего слова (см. hook_captions_for_block), так что подряд идущие
# короткие слова просто НЕМНОГО перекрывают друг друга по расписанию блока, а не показывают оба разом.


def hook_visual_starts(blocks, durs):
    """Реальные старты клипов НА ШКАЛЕ ФИНАЛЬНОГО СМОНТИРОВАННОГО видео —
    не наивный cumsum(durs) (P0-3 доп. находка, независимый форензик-разбор
    архитектуры: xfade-переход СЖИМАЕТ итоговый таймлайн на свою
    длительность, offset = cum - this_dur, см. xfade_chain() — cumsum без
    вычета нахлёста завышает старт каждого следующего клипа на сумму уже
    прошедших нахлёстов, накопительно).

    Для ХУКА (единственное место, где сегодня есть вшитые в кадр подписи,
    см. rescale_hook_words_to_visual_time) длительность перехода ПОЛНОСТЬЮ
    детерминирована на этом этапе, ещё до того как выбраны финальные
    файлы клипов: xfade_chain() всегда даёт HOOK-переходам XFADE_DUR_HARD,
    кроме перехода СРАЗУ ПОСЛЕ блока со stat-плашкой — там SNAP_CUT_DUR
    (то же условие и тот же порядок проверки, что в xfade_chain(); ветка
    "обычный переход" — единственная, зависящая от хэша путей ЕЩЁ НЕ
    выбранных файлов — HOOK её физически никогда не достигает, см. код
    xfade_chain()). Значения вне HOOK этой функцией не гарантированы
    точными (там нет burned-caption потребителя — учитывать не нужно)."""
    plan = plan_transitions([b["section"] for b in blocks], blocks)
    starts, cum = [], (durs[0] if durs else 0.0)
    for i, d in enumerate(durs):
        if i == 0:
            starts.append(0.0)
            continue
        # Тот же самый план, по которому реально режет xfade_chain() — не
        # копия его условий (раньше условия были продублированы здесь
        # вручную и могли разойтись при любой правке одной из двух копий).
        this_dur = plan[i - 1][1] if i - 1 < len(plan) else XFADE_DUR_HARD
        offset = max(0.0, cum - this_dur)
        starts.append(offset)
        cum = cum + d - this_dur
    return starts


def rescale_hook_words_to_visual_time(hook_words, blocks, sub_starts, sub_baseline, visual_starts, durs):
    """P0-3 форензик-аудита (реальный, подтверждённый эмпирически баг):
    load_hook_word_timings() кладёт слова на АУДИО-шкалу (sub_starts/
    sub_baseline — та же, что использует write_subtitles/write_chapters,
    честно синхронная с голосом). Но РЕАЛЬНО рендерящийся визуальный кадр
    хука после apply_section_boundary_shift/apply_within_cut_shift/
    apply_human_jitter/snap_hook_cuts_to_energy — все они сдвигают ИМЕННО
    durs, не sub_baseline, — может отличаться по длительности и старту от
    sub_baseline/sub_starts на десятки-сотни мс. Изолированный прогон
    apply_within_cut_shift() на 4 блоках хука дал накопленную ошибку
    локального тайминга подписи +0.098/+0.094/-0.093с — маленькую на
    глаз, но реальную и систематическую, не шум.

    Кусочно-линейный пересчёт: для каждого слова находим HOOK-блок, чьё
    АУДИО-окно [sub_starts[i], sub_starts[i]+sub_baseline[i]) его
    содержит, и переносим его долю позиции внутри этого окна в ту же
    долю ВИЗУАЛЬНОГО окна [visual_starts[i], visual_starts[i]+durs[i])
    того же блока — слово остаётся привязано к тому же фрагменту речи,
    просто рисуется на шкале реально показанного кадра, а не идеализиро-
    ванной аудио-шкале. Слово вне всех хук-окон (не должно случаться) —
    возвращается как есть, не подменяем произвольно."""
    hook_idxs = [i for i, b in enumerate(blocks) if b["section"].startswith("HOOK")]
    windows = [(sub_starts[i], sub_baseline[i], visual_starts[i], durs[i]) for i in hook_idxs]
    if not windows or not hook_words:
        return hook_words

    def _map(t):
        for a_start, a_dur, v_start, v_dur in windows:
            if a_dur > 1e-9 and a_start - 1e-6 <= t <= a_start + a_dur + 1e-6:
                frac = (t - a_start) / a_dur
                return v_start + frac * v_dur
        return t

    return [(w, _map(s), _map(e)) for w, s, e in hook_words]


def hook_captions_for_block(hook_words, block_start, block_dur):
    """Слова из load_hook_word_timings(), чьё время пересекается с окном
    [block_start, block_start+block_dur) конкретного HOOK-клипа — переведены
    в ЛОКАЛЬНОЕ время клипа (0 = начало клипа) и обрезаны по его границам,
    чтобы drawtext enable=between() не ссылался на моменты вне клипа.

    Минимальная длительность показа (HOOK_CAPTION_MIN_DUR) — короткие слова
    (особенно сразу после вырезанного тега паузы, см. load_hook_word_timings)
    иногда получают из alignment почти нулевую длительность и мелькают
    незаметно; растягиваем ВПЕРЁД, но не дальше начала следующего слова
    (иначе два слова читались бы на экране одновременно)."""
    caps = []
    for k, (word, s, e) in enumerate(hook_words):
        if e <= block_start or s >= block_start + block_dur:
            continue
        local_s = max(0.0, s - block_start)
        local_e = min(block_dur, e - block_start)
        if local_e - local_s < HOOK_CAPTION_MIN_DUR:
            next_start = (hook_words[k + 1][1] - block_start) if k + 1 < len(hook_words) else block_dur
            local_e = min(block_dur, next_start, local_s + HOOK_CAPTION_MIN_DUR)
        if local_e > local_s:
            caps.append((word, local_s, local_e))
    return caps


def hook_floor_for(blocks, i):
    """Пол длительности для блока i — единый HOOK_MIN_CLIP на весь хук (см.
    ревизию 29 августа у самой константы: раньше первые резы хука получали
    отдельный, более низкий пол — убран по требованию пользователя, ни один
    клип хука не должен быть короче HOOK_MIN_CLIP независимо от позиции).
    Единая функция для всех мест, что клэмпят длительность по этому полу
    (block_durations/apply_section_boundary_shift/apply_human_jitter)."""
    if not blocks[i]["section"].startswith("HOOK"):
        return MIN_CLIP
    return HOOK_MIN_CLIP


def block_durations(blocks, total, energy_mults=None, real_weights=None):
    tw = sum(b["words"] for b in blocks)
    tp = sum(b["pause_after"] for b in blocks)
    wps = tw / max(total - tp, 1)
    raw = []
    for i, b in enumerate(blocks):
        rw = real_weights[i] if real_weights else None
        base = rw if rw is not None else b["words"] / wps
        raw.append(base + b["pause_after"])
    if energy_mults:
        raw = [r * m for r, m in zip(raw, energy_mults)]
    d = []
    for i, (b, r) in enumerate(zip(blocks, raw)):
        # В хуке кадры короче и чаще — первые секунды решают, останется ли зритель.
        # Раньше пол был ОДИН на весь ролик (MIN_CLIP) — реальная короткая
        # фраза в хуке всё равно раздувалась до общего пола, и хук не
        # отличался по темпу от тела ролика. Свой, более низкий пол (ещё
        # ниже — для самых первых резов, см. hook_floor_for) — хук реально
        # может резать чаще, а не только "теоретически может".
        is_hook = b["section"].startswith("HOOK")
        cap = HOOK_MAX_CLIP if is_hook else MAX_CLIP
        floor = hook_floor_for(blocks, i)
        d.append(max(floor, min(cap, r)))
    scale = total / sum(d)
    return [x * scale for x in d]


PEXELS_BROKEN = False       # взводится только на реальном отказе API, не на пустой выдаче

# Реальный, найденный вживую баг (27 августа, videos/_test20s, слоты 0 и 3):
# is_relevant_candidate() — гейт, не жёсткий фильтр в _score_and_pick() (см.
# докстринг pexels_photo() про лексикографический кортеж) — если ВЕСЬ
# просмотренный пул кандидатов (до PHOTO_DEDUP_MAX_TRIES штук) провалил
# relevance-гейт, побеждает всё равно "лучший из плохих" (эстетика/luma
# решают дальше по кортежу), без единой пометки об этом. На готовом рендере
# это дало слот с запросом "heavy iron dumbbell weight plate", вернувший
# фото рыцаря с мечом (relevance=0.151, порог 0.19) — пользователь поймал
# на глаз ("фото мальчика вместо гантели"), не пайплайн. Тот же принцип
# честной пометки, что visual_qc.py уже применяет к "ниже порога" кандидатам
# на Шаге 5.5 (media_plan/visual_qc_report.json) — здесь для более раннего
# этапа (сам выбор кандидата, не пост-хок QC уже выбранного). Не меняет
# поведение отбора (слот по-прежнему не остаётся пустым, см. философию
# ЧАСТИ 13) — только делает промах ВИДИМЫМ вместо молчаливого приёма.
RELEVANCE_GATE_MISSES = []   # [{"index", "query", "relevance", "threshold", "kind"}, ...]
DIRECTOR_RELEVANCE_MISSES = []   # [{"index", "text", "photo", "relevance", "threshold"}, ...]
                                  # — см. её докстринг в main() у DIRECTOR_RELEVANCE_FLOOR

# РЕАЛЬНЫЙ, найденный вживую пробел в самом RELEVANCE_GATE_MISSES выше
# (deep-audit, videos/_test20s, слот 7 "warrior on horseback with sword",
# 28 августа) — комментарий у RELEVANCE_GATE_MISSES утверждает "ВЕСЬ
# просмотренный пул провалил гейт", но код проверяет только ПОБЕДИТЕЛЯ
# (`if winner is not None and not winner["is_relevant"]`). Лексикографический
# кортеж _score_and_pick() ставит is_dup_free ПЕРЕД is_relevant — то есть
# кандидат, который релевантен и резкий, но оказался near-duplicate уже
# использованного кадра, проигрывает нерелевантному, но уникальному кандидату,
# и тогда "победитель нерелевантен" НЕ означает "пул нечего предложить" —
# кандидат, реально подходящий по смыслу, в пуле БЫЛ, просто отсеян дедупом
# (у видео — то же самое: dup_fallback конкретно для этого и заведён, см.
# pexels_video()). STOCK_EXHAUSTED_MISSES проверяет РОВНО ту ось, которую
# RELEVANCE_GATE_MISSES по факту не проверяет — "нашёлся ли в ПОЛНОСТЬЮ
# просмотренном пуле хоть один кандидат, прошедший relevance И резкость",
# НЕЗАВИСИМО от дедупа. Это строго более редкий и более сильный сигнал:
# не "победитель не идеален", а "стоку буквально нечего предложить на эту
# фразу" — практический вывод из него другой (не "проверь глазами", а
# "сгенерируй AI-картинку на Шаге 5", см. media_plan/stock_exhausted_report.json
# и render_episode.py). Не меняет отбор победителя (тот же принцип "слот не
# должен остаться пустым", ЧАСТЬ 13) — только делает этот более редкий и
# более серьёзный случай видимым отдельно от обычного relevance-промаха.
STOCK_EXHAUSTED_MISSES = []   # [{"index", "kind", "query", "n_candidates_examined"}, ...]


# Отбор (2.5): фильтр по alt-тексту кандидата — тот же JSON от Pexels-поиска,
# ничего не стоит (не новый запрос, не новая скачка). Заведён после ДВУХ
# реальных вживую пойманных случаев на этом эпизоде: и-словая
# неоднозначность английского запроса надёжно тянула контент не той
# категории — "игр" (video game...) стабильно ловил косплей/аниме-персонажей
# с оружием вместо документальных кадров, "весы"/"весит" (scale weighing...)
# стабильно ловил бытовые весы для тела (голые ступни на весах, лента для
# талии) вместо предметных весов. CLIP-релевантность и эстетика НЕ ловят
# это — с точки зрения обеих метрик косплей-фото "релевантно" запросу про
# видеоигры и красиво снято, весы с ногами "релевантны" запросу про весы.
# Список — не исчерпывающий тег-детектор (невозможен без платного vision на
# каждую фотографию, а платить за это на каждый кадр — именно то, от чего
# ЧАСТЬ 13/Шаг 7.5 явно отказывается), а конкретный, растущий по опыту
# список слов, которые в alt-тексте Pexels НАДЁЖНО значат "не тот жанр" для
# документального канала про историю/вооружение. Кандидат с любым из этих
# слов в alt — просто исключается из перебора (не понижается, а убирается
# совсем); если после фильтра кандидатов не осталось — тихий откат на
# нефильтрованный список (лучше формально нерелевантный кадр, чем сорванная
# сборка блока).
# Отдельное имя дефолта — тот же принцип и та же причина, что у
# _MOOD_GRADE_DEFAULT выше: самоаудит 03.09 нашёл 15 терминов
# (katana/samurai/kimono/wuxia/...), добавленных в channel_profile.json
# при работе над анахронизмами, но никогда не синхронизированных сюда —
# расхождение молчало, потому что имя было одно и то же, и не с чем было
# сравнить. Починено (термины добавлены ниже), но имя разделено, чтобы
# тест мог реально проверить инвариант, а не поверить ему на слово.
_CONTENT_ALT_BLOCKLIST_DEFAULT = (
    "cosplay", "anime", "manga character", "video game character",
    "bathroom scale", "body scale", "weight loss", "weight management",
    "body fat", "diet plan", "measuring tape body", "barefoot", "bare feet",
    "feet on scale", "feet on a scale", "human foot", "obesity",
    # Найдено вживую (deep-audit, videos/_test20s, 29 августа): и фото, и
    # видео-кандидаты по queries вроде "knight armor holding sword two
    # hands"/"warrior on horseback with sword" на Pexels — это чаще всего
    # СОВРЕМЕННЫЕ buhurt/HEMA-турниры и историческая реконструкция (видимая
    # толпа зрителей в обычной одежде, телефоны, деревянные ограждения), а
    # не постановочный "кинематографичный" кадр — CLIP-релевантность это не
    # ловит (тема "меч"/"бой" совпадает), только текстовый alt отличает.
    "reenactment", "reenactor", "medieval festival", "renaissance faire",
    "buhurt", "hema tournament", "combat sport", "full contact fighting",
    "spectators watching", "crowd watching", "audience watching",
    # Культурно-исторические анахронизмы (см. CLAUDE.md ЧАСТЬ 13/14,
    # QUERY_DISAMBIGUATION_RULES/VISUAL_DOMAIN_GUARDS ниже — три независимых
    # слоя защиты): 15 терминов ниже были добавлены ТОЛЬКО в
    # channel_profile.json при работе над анахронизмами (катана в выдаче по
    # "sword"), в этот хардкод-дефолт — никогда. channel_profile.json
    # всегда побеждает при .get() ниже, поэтому расхождение не меняло
    # текущее поведение репозитория — но нарушало документированный
    # инвариант "1-в-1" (см. _comment в channel_profile.json) и тихо
    # теряло бы защиту от анахронизмов, если конфиг когда-нибудь окажется
    # отсутствующим/повреждённым. Найдено 03.09 самоаудитом на тот же
    # класс бага, что дал непримененную виньетку в этой же сессии.
    "katana", "samurai", "kimono", "chinese sword", "jian sword",
    "wuxia", "tai chi", "shogun", "ninja",
    "stormtrooper", "motorcycle helmet", "sci-fi costume", "tribal costume",
    "cultural festival", "video game icon",
)
# Override из channel_profile.json (см. CHANNEL_PROFILE выше) — тот же
# принцип, что MOOD_GRADE/VOICE_*: список выше — хардкод по умолчанию ЭТОГО
# (военно-исторического) канала, для другой ниши (например, игровой канал,
# где cosplay/anime — нужный контент, не мусор) заменяется целиком через
# профиль, не код.
CONTENT_ALT_BLOCKLIST = tuple(CHANNEL_PROFILE.get("content_alt_blocklist", _CONTENT_ALT_BLOCKLIST_DEFAULT))


def filter_alt_blocklist(photos):
    """photos — список объектов Pexels /v1/search (см. pexels_photo). Убирает
    кандидатов, чей alt однозначно сигналит не тот жанр (см.
    CONTENT_ALT_BLOCKLIST) — тихий no-op откат на исходный список, если
    после фильтра ничего не осталось."""
    filtered = [p for p in photos
                if not any(term in (p.get("alt") or "").lower() for term in CONTENT_ALT_BLOCKLIST)]
    return filtered or photos


# Реальный, подтверждённый случай (внешний аудит + прямая проверка на
# 01_ves-mecha/_test20s, см. коммит): голый запрос "sword" на Pexels
# ощутимо намешивает восточноазиатские клинки (катана/цзянь) в выдачу —
# прямое сравнение живых результатов поиска: "sword close up" — заметная
# доля контаминации на первых 15 результатах (кимоно+катана, самурай и
# т.п.), "medieval sword close up" — заметно меньше, "european longsword"
# — на том же сэмпле ни одного явного восточноазиатского результата.
# Простая и при этом САМАЯ эффективная защита — не постфактум-классификация
# уже скачанного кандидата (см. VISUAL_DOMAIN_GUARDS ниже, вторая линия),
# а уточнение САМОГО ЗАПРОСА, чтобы контаминация не попадала в пул
# кандидатов вообще.
#
# ПОСЛЕ первого фикса (только "sword") пользователь справедливо указал:
# один частный случай — не системный апгрейд. Проверил ту же контаминацию
# на ДРУГИХ частых для военно-исторической ниши терминах ТЕМ ЖЕ методом
# (живой Pexels-поиск, не гадание) — контаминация реальна и по другим
# категориям, причём РАЗНОГО типа: "helmet close up" — мотоциклетный/sci-fi
# шлем (2/15), "armor close up" — самурай/штурмовик/косплей (3/14), "spear
# close up" — африканская культурная/фестивальная одежда (5/15, другой тип
# анахронизма, не азиатский), "battle scene" — индийский/китайский храмовый
# рельеф (2/15). Уточнение запроса ("european"/"european medieval")
# каждый раз реально гасило контаминацию (проверено на том же сэмпле:
# helmet 2->0, armor 3->1, spear 5->1, battle 2->0) — тот же рычаг
# работает системно для всей категории "generic-запрос по историческому
# оружию/сцене", не только для мечей.
#
# unless — не добавлять уточнение, если запрос УЖЕ содержит явный
# культурный/жанровый маркер (легитимный запрос про катану/самурая для
# соответствующей темы не должен получать искажающую приставку — то же
# верно для будущего эпизода про африканские копья и т.п.). qualifier
# добавляется ТОЛЬКО в реальный вызов Pexels API — см.
# disambiguate_search_query()/pexels_photo()/pexels_video() — кэш-ключ и
# relevance-скоринг остаются на ИСХОДНОМ query, нулевой риск для уже
# откалиброванных порогов (CLIP_RELEVANCE_THRESHOLD и т.п.). Список — тот
# же паттерн override из channel_profile.json, что CONTENT_ALT_BLOCKLIST
# выше (для другой ниши/культурного контекста правила заменяются целиком
# через профиль, не код).
QUERY_DISAMBIGUATION_RULES = (
    {"term": "sword",
     "unless": ("katana", "samurai", "chinese", "japanese", "jian", "wuxia", "asian", "kimono"),
     "qualifier": "european"},
    {"term": "helmet",
     "unless": ("katana", "samurai", "chinese", "japanese", "asian", "sci-fi", "futuristic",
                "motorcycle", "bike", "football", "construction"),
     "qualifier": "european"},
    {"term": "armor",
     "unless": ("katana", "samurai", "chinese", "japanese", "asian", "sci-fi", "futuristic",
                "cosplay", "stormtrooper", "video game"),
     "qualifier": "european medieval"},
    {"term": "spear",
     "unless": ("african", "tribal", "zulu", "asian", "japanese", "chinese", "maori"),
     "qualifier": "european medieval"},
    {"term": "battle",
     "unless": ("modern", "sci-fi", "futuristic", "space", "video game", "wwii", "world war"),
     "qualifier": "european medieval"},
)
QUERY_DISAMBIGUATION_RULES = tuple(CHANNEL_PROFILE.get("query_disambiguation_rules", QUERY_DISAMBIGUATION_RULES))


def disambiguate_search_query(query):
    """Возвращает уточнённую строку запроса ТОЛЬКО для реального вызова
    Pexels API (см. QUERY_DISAMBIGUATION_RULES выше) — исходный query для
    кэш-ключа/relevance-скоринга не трогает. Нет совпавшего правила —
    строка возвращается без изменений. Составные qualifier ("european
    medieval") добавляют только те СЛОВА, которых в запросе ещё нет —
    иначе запрос вроде "medieval armor close up" получил бы дубль
    ("european medieval medieval armor close up", реальный найденный
    баг первой версии этой функции)."""
    ql = query.lower()
    for rule in QUERY_DISAMBIGUATION_RULES:
        if rule["term"] not in ql:
            continue
        if any(u in ql for u in rule.get("unless", ())):
            continue
        missing_words = [w for w in rule["qualifier"].split() if w not in ql]
        if not missing_words:
            continue
        return f"{' '.join(missing_words)} {query}"
    return query


PHOTO_DEDUP_HAMMING = 6   # тот же порог, что в qc_report() — "заметно похоже"
# Апгрейд пула кандидатов (по прямому запросу пользователя — пункт аудита
# "40-80 кандидатов на шот", ЧЕСТНО НЕ взят буквально). Раньше (6/3) было
# калибровано под ДЕШЁВЫЙ director_score_fn (sentence_relevance ->
# SigLIP2-base-256 solo, доли секунды на вызов). После апгрейда на
# so400m-384+Jina ensemble (см. scripts/visual_director.py,
# ENSEMBLE_WEIGHT_SIGLIP2) один вызов ~2.5-3с — _score_and_pick() вызывает
# director_score_fn на КАЖДОГО собранного кандидата, поэтому пул 20-30 из
# аудита означал бы ~1 минуту ТОЛЬКО на скоринг одного слота (буквальная
# цифра аудита писалась без учёта того, что скоринг сам станет тяжелее в
# этой же сессии) — на эпизоде с сотнями слотов это часы, не приемлемо.
# 20/8 — умеренный, обоснованный компромисс (не переиспользование числа
# аудита без проверки): ~8×3с=24с на слот на скоринг, вместо ~1 минуты.
PHOTO_DEDUP_MAX_TRIES = 20 # сколько кандидатов реально СКАЧАТЬ и захэшировать, прежде чем сдаться
# I/O-bound, не CPU-bound (download() — HTTP GET на images.pexels.com,
# ffmpeg/модели тут не участвуют) — безопасно распараллелить без риска для
# качества выбора: сама сортировка/скоринг кандидатов (см. цикл ниже)
# остаётся ПОСЛЕДОВАТЕЛЬНОЙ, в том же порядке, с тем же ранним break по
# good_needed — параллелится только сетевое ожидание. НЕ считается против
# квоты api.pexels.com/v1/search (200/час) — это ОДИН уже сделанный поиск,
# качаются только байты уже найденных кандидатов с CDN, отдельный лимит.
PHOTO_PREFETCH_WORKERS = int(os.environ.get("PHOTO_PREFETCH_WORKERS", "6"))
DIRECTOR_MIN_POOL = 8   # Semantic Visual Director (scripts/visual_director.py) —
                          # тот же смысл и то же значение, что visual_director.
                          # DIRECTOR_MIN_POOL: без расширения пула Директору в
                          # pexels_photo() часто буквально нечего ранжировать
                          # (см. good_needed ниже). Отдельная константа здесь, а
                          # не импорт из visual_director.py — тот модуль сам
                          # импортирует pipeline_smart.py, обратный импорт создал
                          # бы цикл.

# По прямому запросу пользователя (31.08, реальный долгий рендер
# videos/01_ves-mecha — SigLIP2-so400m ~2.5-3с/кандидат х до 8 кандидатов
# уже даёт ~5-6 мин/клип, на ~155 клипах тела эпизода это часы): первые
# FAST_MODE_START_INDEX клипов (хук + немного после — самый важный по
# удержанию участок) держат полный пул (DIRECTOR_MIN_POOL/
# PHOTO_DEDUP_MAX_TRIES выше), дальше пул сознательно уже — ЧЕСТНЫЙ
# компромисс скорость/точность подбора, не тихий даунгрейд: пользователь
# прямо предупреждён, что клипы 16+ сравнивают меньше кандидатов, чем
# было откалибровано в этой же сессии (3->8/6->20).
FAST_MODE_START_INDEX = 15         # 0-based индекс блока; блоки 0..14 — полный пул
FAST_DIRECTOR_MIN_POOL = 2
FAST_PHOTO_DEDUP_MAX_TRIES = 5
FAST_VIDEO_RELEVANCE_MAX_TRIES = 1
FAST_VIDEO_RELEVANCE_MAX_TRIES_HARD_CAP = 3


def _director_min_pool_for(index):
    return DIRECTOR_MIN_POOL if index < FAST_MODE_START_INDEX else FAST_DIRECTOR_MIN_POOL


def _photo_dedup_max_tries_for(index):
    return PHOTO_DEDUP_MAX_TRIES if index < FAST_MODE_START_INDEX else FAST_PHOTO_DEDUP_MAX_TRIES


def _pool_cleared_both_gates(candidates_info):
    """True, если хотя бы ОДИН кандидат из candidates_info прошёл И
    relevance, И резкость — НЕЗАВИСИМО от дедупа/размера/итогового
    победителя. Ось STOCK_EXHAUSTED_MISSES (см. её докстринг у объявления
    выше): строго более сильный сигнал, чем "победитель не идеален" —
    "стоку тут физически нечего предложить". Извлечена в отдельную функцию
    ради тестируемости, тот же принцип, что и _score_and_pick() (см.
    докстринг tests/test_pexels_scoring.py)."""
    return any(c["is_relevant"] and c["sharp_ok"] for c in candidates_info)


def _score_and_pick(candidates_info, director_score_fn=None):
    """Чистая функция без сети/диска — построение и сравнение кортежей
    ранжирования по УЖЕ ПОСЧИТАННЫМ метрикам кандидатов (см. цикл в
    pexels_photo() ниже, который эти метрики считает и вызывает эту
    функцию один раз после скачивания). Извлечена отдельно от pexels_photo()
    именно чтобы тестироваться на синтетическом списке кандидатов, без
    реальных файлов/сети — pexels_photo() до этого рефакторинга была
    единственной core-функцией отбора медиа вообще без тестового покрытия.

    candidates_info — список dict, каждый с готовыми числами:
    path, p (сырой Pexels-объект), is_dup_free, size_ok, is_relevant,
    sharp_ok (опционально, см. ниже), aesthetic_val, luma_score, min_d.

    Возвращает (base_winner, director_winner) — оба элемента
    candidates_info (или None на пустом списке/если ни один кандидат не
    улучшил стартовый счёт). base_winner — 7-элементный
    лексикографический кортеж (is_dup_free, size_ok, is_relevant, sharp_ok,
    aesthetic_val, luma_score, min_d), то же строгое ">" сравнение и тот же
    порядок кандидатов, что был инлайн в pexels_photo() до этого
    рефакторинга — при равенстве кортежей побеждает ПЕРВЫЙ встреченный
    кандидат, не последний (важно для байт-в-байт совместимости).

    director_winner считается, ТОЛЬКО если передан director_score_fn(path,
    candidate_query=None, aesthetic_val=None) -> float (scripts/
    visual_director.py) — candidate_query (см. SAME_QUERY_BONUS) и
    aesthetic_val (см. OPENING_AESTHETIC_WEIGHT) передаются всегда, как
    keyword; любой director_score_fn обязан их принимать (**kwargs или
    явные параметры) — см. тестовые lambda в tests/test_pexels_scoring.py.
    8-элементный кортеж с extra-
    осью СРАЗУ ПОСЛЕ sharp_ok, ДО aesthetic (см. докстринг
    scripts/visual_director.py: "подходит ли по роли/домену/повтору"
    важнее "красиво ли", но relevance/dedup/size остаются гейтами, не
    подвинуты). director_winner — None, если director_score_fn не
    передан — вызывающий код (pexels_photo) тогда просто не считает вторую
    ветвь вообще.

    sharp_ok (опционально, по умолчанию 1 через .get — старые вызовы/тесты
    без этого ключа получают байт-в-байт прежнее поведение) — гейт резкости
    (PHOTO_SHARPNESS_REJECT, см. её докстринг: реальный найденный случай,
    videos/_test20s слот 7 — размытый кандидат никогда не проверялся на
    этапе отбора). Стоит СРАЗУ после is_relevant, ДО aesthetic — та же
    логика приоритета, что и у extra Директора: "не размыто" важнее
    "красиво", но не важнее "по теме"/"не дубль"/"нужный размер"."""
    base_best, base_score = None, (-1, -1, -1, -1, -100.0, -1.0, -1)
    dir_best, dir_score = None, (-1, -1, -1, -1, -100.0, -100.0, -1.0, -1)
    for c in candidates_info:
        sharp_ok = c.get("sharp_ok", 1)
        score = (c["is_dup_free"], c["size_ok"], c["is_relevant"], sharp_ok,
                  c["aesthetic_val"], c["luma_score"], c["min_d"])
        if score > base_score:
            base_best, base_score = c, score
        if director_score_fn is not None:
            # candidate_query — из какого запроса пула пришёл ЭТОТ кандидат
            # (см. SAME_QUERY_BONUS в visual_director.py) — c["p"] всегда
            # словарь (см. candidates_info.append выше), _origin_query
            # проставляется в pexels_photo()/pexels_video() при сборе пула;
            # отсутствует -> None, старое поведение (ноль бонуса).
            # aesthetic_val — уже посчитан для base-тройки ниже, передаём
            # тот же (см. OPENING_AESTHETIC_WEIGHT в visual_director.py) —
            # используется, только если вызывающий partial связал is_opening=True.
            with stage_timer.stage("ensemble_score"):
                extra = director_score_fn(c["path"], candidate_query=c["p"].get("_origin_query"),
                                           aesthetic_val=c["aesthetic_val"])
            dscore = (c["is_dup_free"], c["size_ok"], c["is_relevant"], sharp_ok, extra,
                       c["aesthetic_val"], c["luma_score"], c["min_d"])
            if dscore > dir_score:
                dir_best, dir_score = c, dscore
    return base_best, dir_best


def _build_arbiter_shortlist(candidates_info, base_winner, director_winner, own_query, max_n=3):
    """Шорт-лист для VLM-арбитра (shot_director.arbitrate_hook_candidates,
    см. её блок-комментарий) — до max_n РАЗЛИЧНЫХ (по path) уже прошедших
    все гейты кандидатов из уже скачанного пула (ничего не докачивает):
    director_winner и base_winner (если это разные файлы — сама эта разница
    и есть неопределённость, которую арбитр разрешает), плюс лучший
    кандидат из СВОЕГО запроса слота (own_query), если он не совпал ни с
    одним из них — ровно тот кандидат, которого раньше мог "перетянуть"
    чужой запрос до появления SAME_QUERY_BONUS."""
    seen = set()
    shortlist = []
    for c in (director_winner, base_winner):
        if c is not None and c["path"] not in seen:
            shortlist.append(c)
            seen.add(c["path"])
    own_gated = [c for c in candidates_info
                 if c["p"].get("_origin_query") == own_query
                 and c["is_dup_free"] and c["size_ok"] and c["is_relevant"] and c.get("sharp_ok", 1)]
    if own_gated:
        best_own = max(own_gated, key=lambda c: (c["aesthetic_val"], c["luma_score"]))
        if best_own["path"] not in seen:
            shortlist.append(best_own)
            seen.add(best_own["path"])
    return shortlist[:max_n]


def _build_opening_shortlist(candidates_info, base_winner, director_winner, max_n=4):
    """Шорт-лист для САМОГО ПЕРВОГО кадра ролика (см. is_opening в
    shot_director.arbitrate_hook_candidates) — реальная жалоба пользователя
    (29 августа, /goal): _build_arbiter_shortlist() держится своего запроса
    слота — для открывающего кадра это неверный приоритет, зрителю нужна
    максимально эффектная картинка ради удержания (CLAUDE.md ЧАСТЬ 9), а не
    самая буквально точная. Кросс-опылённые кандидаты из ДРУГИХ запросов
    секции (section_query_pool, см. main()) уже в candidates_info — эта
    функция просто не отбрасывает их молча в пользу буквальной точности,
    а берёт лучших ПО ЭСТЕТИКЕ технически чистых кандидатов ИЗ ВСЕГО пула,
    не только своего запроса."""
    gated = [c for c in candidates_info
             if c["is_dup_free"] and c["size_ok"] and c["is_relevant"] and c.get("sharp_ok", 1)]
    if not gated:
        gated = candidates_info   # честная деградация — лучше нерелевантный шорт-лист, чем пустой
    by_aesthetic = sorted(gated, key=lambda c: c["aesthetic_val"], reverse=True)
    seen = set()
    shortlist = []
    for c in (director_winner, base_winner):
        if c is not None and c["path"] not in seen:
            shortlist.append(c)
            seen.add(c["path"])
    for c in by_aesthetic:
        if len(shortlist) >= max_n:
            break
        if c["path"] not in seen:
            shortlist.append(c)
            seen.add(c["path"])
    return shortlist[:max_n]


def _build_video_arbiter_shortlist(good, own_query, max_n=3):
    """Аналог _build_arbiter_shortlist() для видео-пути (pexels_video) —
    good уже отсортирован по (luma_ok, sent_score) убыванию, элементы —
    (sent_score, luma_ok, trial_path, id, hash, origin_query), все уже
    прошли гейты. Победитель (good[0]) + лучший кандидат СВОЕГО запроса
    слота, если не совпал (см. SAME_QUERY_BONUS), + второй по счёту
    (good[1]), если отличается от уже добавленных — та же неопределённость
    "какой сигнал прав", что у фото-версии, только без раздельных base/
    director победителей (видео-путь считает один общий sent_score)."""
    seen = set()
    shortlist = [good[0]]
    seen.add(good[0][2])
    own_matches = [g for g in good if g[5] == own_query]
    if own_matches and own_matches[0][2] not in seen:
        shortlist.append(own_matches[0])
        seen.add(own_matches[0][2])
    if len(good) > 1 and good[1][2] not in seen:
        shortlist.append(good[1])
        seen.add(good[1][2])
    return shortlist[:max_n]


def _build_opening_video_shortlist(good, max_n=4):
    """Видео-версия _build_opening_shortlist() — good уже отсортирован по
    (luma_ok, sent_score) и уже включает кросс-опылённых кандидатов всех
    запросов секции, не только своего слота (см. extra_queries в
    pexels_video()). В отличие от фото-версии здесь нет отдельной
    эстетической метрики на кандидата — берёт первые max_n РАЗЛИЧНЫХ (по
    trial_path) элементов уже отсортированного good без own_query-
    приоритета обычной видео-версии (_build_video_arbiter_shortlist),
    чтобы явно "эффектные" кросс-опылённые кандидаты не отсеивались молча
    в пользу буквальной точности своего запроса."""
    seen = set()
    shortlist = []
    for g in good:
        if g[2] not in seen:
            shortlist.append(g)
            seen.add(g[2])
        if len(shortlist) >= max_n:
            break
    return shortlist


SEMANTIC_CONTEXT_MIN_WORDS = 9   # короче — фраза сама себя не описывает
SEMANTIC_CONTEXT_MAX_WORDS = 40  # и не растворять смысл текущей фразы в соседях


def semantic_context_text(blocks, i):
    """Текст для СМЫСЛОВОГО подбора картинки к блоку i — сам блок, при
    необходимости дополненный соседними фразами ТОЙ ЖЕ секции.

    Реальный, увиденный на готовом кадре случай: блок "Не дрались. Несли."
    (3 слова) — в нём нет ни одного зрительного существительного, его смысл
    целиком в предыдущей фразе ("категория мечей, которые никогда не
    предназначались для боя"). Модель сопоставления фразы с картинкой на
    таком огрызке физически не может выбрать осмысленно — и раньше получала
    именно его, слово в слово. В реальном эпизоде таких блоков 7 из 91 ещё
    ДО sub-cut-разбивки (та дробит длинные блоки и добавляет коротких).

    Контекст берётся только внутри своей секции (через границу раздела тема
    меняется) и только пока не набрано SEMANTIC_CONTEXT_MIN_WORDS: сначала
    предыдущая фраза (она обычно и вводит предмет), затем следующая. Длинный
    блок не трогается вообще — байт-в-байт прежнее поведение.

    Влияет ТОЛЬКО на выбор картинки. Ни тайминг, ни резы, ни поисковый
    запрос, ни субтитры от этого не зависят."""
    cur = blocks[i]
    words = cur["text"].split()
    if len(words) >= SEMANTIC_CONTEXT_MIN_WORDS:
        return cur["text"]
    section = cur.get("section")
    before, after = "", ""
    if i > 0 and blocks[i - 1].get("section") == section:
        before = blocks[i - 1]["text"]
    if i + 1 < len(blocks) and blocks[i + 1].get("section") == section:
        after = blocks[i + 1]["text"]
    parts = [p for p in (before, cur["text"]) if p]
    if len(" ".join(parts).split()) < SEMANTIC_CONTEXT_MIN_WORDS and after:
        parts.append(after)
    out = " ".join(parts).split()
    # Обрезаем ВОКРУГ текущей фразы, а не с начала: она должна остаться в
    # окне даже когда соседи длинные.
    if len(out) > SEMANTIC_CONTEXT_MAX_WORDS:
        out = out[:SEMANTIC_CONTEXT_MAX_WORDS] if not before else out[-SEMANTIC_CONTEXT_MAX_WORDS:]
    return " ".join(out)


_PEXELS_SEARCH_CACHE = {}   # {api_query: [photo, ...]} — на процесс, см. ниже


def _pexels_search_photos(api_query):
    """Выдача Pexels по УЖЕ подготовленной строке запроса, с кэшем на процесс.

    Кэш здесь не оптимизация "на всякий случай", а условие работоспособности
    расширенного пула: один и тот же запрос повторяется у ДЕСЯТКОВ блоков
    (запрос берётся из словаря по корню слова либо из авторских запросов
    секции), и раньше каждый блок дёргал API заново — на эпизоде в 91 блок
    это десятки одинаковых запросов. Квота Pexels — 200/час (ЧАСТЬ 21), а
    сбор пула из всех запросов секции умножил бы число вызовов ещё в 3-4
    раза и гарантированно упёрся бы в лимит. С кэшем расход становится
    "по одному вызову на УНИКАЛЬНЫЙ запрос эпизода" (порядок 10-40), то есть
    расширение пула обходится дешевле, чем стоил прежний однозапросный путь.

    Выдача Pexels на один и тот же запрос стабильна в пределах прогона —
    кэшировать её безопасно; разные блоки всё равно получают РАЗНЫЕ картинки
    за счёт used_ids/used_hashes (анти-дубль), а не за счёт разной выдачи."""
    if api_query in _PEXELS_SEARCH_CACHE:
        return _PEXELS_SEARCH_CACHE[api_query]
    q = urllib.parse.quote(api_query)
    req = urllib.request.Request(
        f"https://api.pexels.com/v1/search?query={q}&per_page=80&orientation=landscape",
        headers={"Authorization": PEXELS_API_KEY, "User-Agent": UA})
    with urllib.request.urlopen(req, timeout=15) as r:
        data = json.load(r)
    photos = data.get("photos") or []
    _PEXELS_SEARCH_CACHE[api_query] = photos
    return photos


def pexels_photo(query, index, used_ids=None, used_hashes=None, recent_sizes=None, target_luma=None,
                  director_score_fn=None, director_assist=False, director_report=None,
                  extra_queries=None, text_key=None, arbiter_text=None, is_opening_shot=False):
    """used_ids — множество ID уже показанных в этом ролике фото (мутируется на
    месте). Разные блоки часто ловят один и тот же тематический запрос — без
    этого им всем доставался бы top-1 результат, то есть одна и та же картинка
    по нескольку раз за ролик. Перебираем выдачу (per_page=80 — Pexels-максимум,
    проверено вживую: возвращает 79; 40 всё ещё не хватало на узкой теме
    вроде "meч" при 150 sub-cut блоках на одну лексическую тему — used_ids
    общий на весь ролик, а не на запрос, так что разные запросы про мечи
    делят один и тот же небольшой пул различимых стоковых фото).

    used_hashes (опционально) — список aHash уже отобранных в ролик фото.
    Дедуп только по ID ловит лишь буквально тот же файл повторно — не ловит
    РАЗНЫЕ ID из одной фотосессии (тот же реквизит/ракурс, другой кадр серии),
    а именно так выглядели реальные дубли, найденные постфактум в qc_report()
    на готовом ролике. Теперь при наличии used_hashes каждый кандидат перед
    принятием СКАЧИВАЕТСЯ и хэшируется — если он визуально слишком похож
    (hamming <= 6) на уже выбранную картинку, пробуем следующего кандидата
    из уже полученного списка (без нового сетевого запроса на список, только
    докачка кандидата) — до PHOTO_DEDUP_MAX_TRIES попыток, чтобы не жечь
    время/трафик на исчерпание всей выдачи. Не нашли непохожего — берём
    наименее похожего из просмотренных (лучше редкий повтор, чем сорванная
    сборка).

    target_luma (опционально) — текущий luma_ema соседних кадров (см. main()).
    Самый младший критерий выбора (после anti-dup и size-variety): среди уже
    и так скачанных в рамках анти-дубль перебора кандидатов предпочитаем того,
    чья ЕСТЕСТВЕННАЯ яркость ближе к контексту — меньше нагрузки на синтетическую
    коррекцию film_look(brightness_bias), та зажата в ±0.035 и не всегда
    вытягивает разницу целиком. Не тратит дополнительные скачивания сверх уже
    идущего анти-дубль перебора.

    director_score_fn/director_assist/director_report (опционально, Semantic
    Visual Director — scripts/visual_director.py) — по умолчанию все None/
    False, поведение байт-в-байт как без этой фичи. Если director_score_fn
    задан, good_needed поднимается до DIRECTOR_MIN_POOL (Директору нужно
    реально из чего выбирать, не один первый прошедший гейты кандидат — см.
    докстринг visual_director.py про cost-tradeoff), а после скачивания пула
    (см. _score_and_pick) считаются ДВА победителя параллельно на одном и
    том же уже скачанном пуле — base (сегодняшний) и director (с extra-
    осью). director_assist=False (shadow) — реально используется base;
    True (assist) — director. director_report, если передан dict —
    заполняется {"base_winner"/"director_winner": Pexels-ID или None,
    "diverged": bool} для честного аудита независимо от director_assist.

    extra_queries (опционально) — ОСТАЛЬНЫЕ авторские запросы этой секции.
    Кандидаты собираются из всех них сразу (один вызов API на УНИКАЛЬНЫЙ
    запрос, см. _pexels_search_photos), а не только из `query`. Смысл: раньше
    блок видел ровно один запрос, доставшийся ему позиционно по кругу
    (pool[idx % len(pool)]), и выбирать было физически не из чего — на
    реальном эпизоде это давало совпадение по смыслу примерно у 1 блока из 3
    (фраза про заточку клинка получала запрос "medieval castle hall").
    Запрос блока (`query`) теперь назначается ПО СМЫСЛУ его фразы, а не
    позиционно (см. semantic_query_assignment()), поэтому гейт релевантности
    сверяет каждого кандидата ИМЕННО С НИМ — а не с тем запросом пула, из
    которого кандидат приплыл. Расширенный пул при этом сохраняется целиком
    (глубина выбора та же), но кандидат из соседнего запроса секции побеждает
    только если реально подходит и теме ЭТОГО блока — см. развёрнутый разбор
    у самого вызова is_relevant_candidate() ниже. None/[] -> прежнее
    поведение."""
    global PEXELS_BROKEN
    cache = os.path.join(TEMP_FOLDER, "pexels_cache")
    os.makedirs(cache, exist_ok=True)
    # Хэш запроса в имени файла — иначе смена themes.json без чистки temp_smart/
    # молча оставляет картинку под старый запрос (кэш бил только по номеру блока).
    # Хэш правил отбора (candidate_gate_signature()) в имени файла ТУДА ЖЕ —
    # иначе улучшение relevance/анахронизм-гварда молча не переоценивает уже
    # закэшированного кандидата, отобранного по старым, менее строгим правилам
    # (реальный найденный баг, см. докстринг candidate_gate_signature()).
    # В ключ входит ВЕСЬ набор запросов пула (не только основной): смена
    # состава пула меняет, из чего вообще выбирался кадр — переиспользовать
    # старый файл в этом случае значит молча остаться на прежнем, более
    # бедном выборе (тот же класс бага, что закрывает candidate_gate_signature).
    # text_key — РЕАЛЬНЫЙ пробел, найденный по прямому запросу пользователя
    # (не гипотеза): кэш до этого бил по (индекс слота, ЗАПРОС, версия
    # кода) — но ЗАПРОС для слота считает resolve_queries() либо по
    # словарю тем, либо циклическим курсором по авторскому пулу секции.
    # Правка текста в script.txt (перефразировка, добавленное/убранное
    # предложение) может ОСТАВИТЬ вычисленный запрос тем же самым (то же
    # слово темы) или же — из-за сдвига позиций при циклическом курсоре —
    # ПОЗИЦИОННО попасть на ту же самую строку запроса, что была у СОВСЕМ
    # ДРУГОГО предложения раньше. В обоих случаях кэш-файл на диске уже
    # существует под этим же именем и молча отдаётся — фото, подобранное
    # под старый текст, беззвучно остаётся стоять под новый. text_key
    # (semantic_context_text() того же блока — та же строка, что реально
    # идёт в сравнение по смыслу) — это то немногое, что ОДНОЗНАЧНО
    # привязывает кэш к КОНКРЕТНОЙ фразе, а не к производному от неё
    # запросу. None (вызов без блока сценария, напр. тесты) -> прежнее
    # поведение, ноль регрессии.
    #
    # arbiter_text — РЕАЛЬНЫЙ (не дополненный соседями) текст блока, только
    # для HOOK-слотов (см. вызов в main(), VLM_ARBITER_MODE) — включает
    # VLM-арбитра (shot_director.arbitrate_hook_candidates) поверх уже
    # решённого base/director победителя, см. её блок-комментарий в
    # shot_director.py. None -> арбитраж не запускается вообще, прежнее
    # поведение.
    qkey = "|".join([query] + sorted(q for q in (extra_queries or []) if q and q != query)
                     + ([text_key] if text_key else []))
    qhash = hashlib.md5(qkey.encode()).hexdigest()[:8]
    gate_sig = candidate_gate_signature().split(":", 1)[-1]
    cf = os.path.join(cache, f"{index:04d}_{qhash}_{gate_sig}.jpg")
    # size>0, не просто exists — см. atomic_url_download: старые (до этого
    # фикса) прерванные закачки могли уже оставить 0-байтный файл под этим
    # именем, и голый exists() принял бы его за валидный кэш.
    if os.path.exists(cf) and os.path.getsize(cf) > 0:
        if used_hashes is None:
            if recent_sizes is not None:
                try:
                    recent_sizes.append(estimate_shot_size(cf))
                except Exception:
                    pass
            return cf
        # Реальный баг, пойманный вживую: кэш-хит раньше отдавал файл СРАЗУ,
        # даже не проверяя его против used_hashes — анти-дубль код (ниже)
        # тогда никогда не успевал сработать на файлах, скачанных ЕЩЁ ДО
        # его появления (или на прошлом прогоне без анти-дубля). На готовом
        # ролике это дало 4 пары дублей — оба файла кэша существовали
        # заранее, каждый кэш-хит молча их одобрял. Теперь кэш-хит тоже
        # проверяется на похожесть — коллизия найдена, файл НЕ считается
        # валидным кэшем, код падает ниже в обычный путь скачивания и
        # перезаписывает cf нормальным анти-дубль перебором кандидатов.
        try:
            h = ahash(cf)
            if min((hamming(h, uh) for uh in used_hashes), default=99) > PHOTO_DEDUP_HAMMING:
                used_hashes.append(h)
                if recent_sizes is not None:
                    try:
                        recent_sizes.append(estimate_shot_size(cf))
                    except Exception:
                        pass
                return cf
        except Exception:
            return cf
    if not PEXELS_API_KEY:
        # Досюда доходим и в случае "кэш есть, но он визуальный дубль уже
        # показанного" (см. ветку used_hashes выше). Без ключа заменить
        # его нечем — вернуть дубль честнее, чем потерять кадр целиком:
        # пустой слот при RENDER_STRICT_GATE=1 останавливает всю сборку.
        if os.path.exists(cf) and os.path.getsize(cf) > 0:
            return cf
        return None
    try:
        # Пул кандидатов собирается из ВСЕХ запросов секции сразу, а не из
        # одного (см. extra_queries в докстринге) — победителя дальше выбирает
        # director_score_fn по ПОЛНОЙ фразе блока.
        pool_queries = [query] + [q for q in (extra_queries or []) if q and q != query]
        per_query = []
        for pq in pool_queries:
            lst = []
            for p in _pexels_search_photos(disambiguate_search_query(pq)):
                # Из какого запроса кандидат пришёл — гейт релевантности ниже
                # должен сверять его с ЕГО запросом, иначе кандидат из второго
                # запроса секции сравнивался бы с чужим текстом и честно
                # отбраковывался бы ни за что.
                p = dict(p)
                p["_origin_query"] = pq
                lst.append(p)
            per_query.append(lst)
        # ЧЕРЕДОВАНИЕ по запросам, а не подряд — реальный дефект первой
        # версии этого пула, найденный покадровым просмотром рендера: Pexels
        # отдаёт до 80 результатов на запрос, а перебирается лишь первые
        # PHOTO_DEDUP_MAX_TRIES кандидатов, поэтому при склейке "подряд" ВСЕ
        # они оказывались из первого (позиционно доставшегося) запроса, и до
        # остальных запросов секции дело не доходило вообще — расширение
        # пула существовало только на бумаге. При чередовании сравниваемая
        # выборка гарантированно охватывает все запросы секции.
        photos = []
        seen_ids = set()
        for row in itertools.zip_longest(*per_query):
            for p in row:
                if p is None:
                    continue
                pid = p.get("id")
                if pid in seen_ids:
                    continue
                seen_ids.add(pid)
                photos.append(p)
        if not photos:
            return None
        photos = filter_alt_blocklist(photos)
        candidates = [p for p in photos if used_ids is None or p.get("id") not in used_ids] or photos

        def download(p, dest):
            url = p["src"].get("large2x") or p["src"].get("large")
            req_img = urllib.request.Request(url, headers={"User-Agent": UA})
            atomic_url_download(req_img, dest, timeout=20)

        if used_hashes is None:
            pick = candidates[0]
            download(pick, cf)
        else:
            # score = (не дубль?, разнообразит масштаб плана?, релевантна
            # запросу по CLIP?, эстетическая оценка, ближе по яркости к
            # соседям?, дистанция по хэшу) — сравниваются как кортежи,
            # лексикографически: "не дубль" важнее "разнообразия", то
            # важнее релевантности, та важнее эстетики, та важнее яркостной
            # близости, та важнее точной дистанции (самый младший критерий —
            # просто добивает выбор среди и так уже равных по первым осям).
            # recent_sizes/luma/CLIP/эстетика — те же уже скачанные
            # кандидаты анти-дубля, никакого нового сетевого трафика ради
            # этой доп. проверки — переиспользуем то, что и так уже качаем.
            good_seen = 0
            # Без target_luma брейк на первом же "хорошем" кандидате, как раньше
            # (0 доп. скачиваний). С target_luma нужно сравнить МИНИМУМ 2 таких
            # кандидата, иначе яркостный критерий никогда не встретится с
            # реальной альтернативой и молча ничего не решает — брейк на первом
            # же успехе просто не даёт ему сработать. +1 скачивание в типичном
            # случае (не x6) — единственный способ сделать tie-breaker не
            # фиктивным, не разгоняя стоимость до полного перебора. CLIP-
            # релевантность НЕ добавляет к good_needed — она не tie-breaker,
            # а гейт (см. is_relevant ниже, часть условия break) — кандидат
            # без неё не считается "хорошим", даже если дубль-фри/размер ок.
            good_needed = 2 if target_luma is not None else 1
            if director_score_fn is not None:
                # Директору реально нужно из чего выбирать — иначе цикл
                # часто останавливался бы на первом же прошедшем кандидате
                # (good_needed=1) и extra-ось ни разу не встретила бы
                # альтернативу (см. докстринг scripts/visual_director.py про
                # честный cost-tradeoff расширения пула).
                good_needed = max(good_needed, _director_min_pool_for(index))
            candidates_info = []
            trial_slice = candidates[:_photo_dedup_max_tries_for(index)]
            # Скачивание кандидатов — сетевой I/O, не CPU (см. докстринг
            # PHOTO_PREFETCH_WORKERS выше) — заранее запускаем ВСЕ загрузки
            # этого слота параллельно, а обрабатываем/скорим строго
            # ПОСЛЕДОВАТЕЛЬНО в том же порядке и с тем же ранним break, что
            # и раньше: какой кандидат победит — не меняется ни на бит,
            # меняется только то, что к моменту очереди файл обычно уже
            # скачан (или качается параллельно с обработкой предыдущего),
            # а не ждёт своей синхронной очереди с нуля.
            trial_paths = {id(p): cf + f".trial_{p.get('id')}.jpg" for p in trial_slice}
            prefetch_pool = concurrent.futures.ThreadPoolExecutor(
                max_workers=max(1, min(PHOTO_PREFETCH_WORKERS, len(trial_slice) or 1)))
            prefetch_futures = {id(p): prefetch_pool.submit(download, p, trial_paths[id(p)])
                                 for p in trial_slice}
            for p in trial_slice:
                trial = trial_paths[id(p)]
                try:
                    with stage_timer.stage("cand_download_wait", clip_idx=index):
                        prefetch_futures[id(p)].result()
                    h = ahash(trial)
                except Exception:
                    continue
                min_d = min((hamming(h, uh) for uh in used_hashes), default=99)
                is_dup_free = 1 if min_d > PHOTO_DEDUP_HAMMING else 0
                size_ok = 1
                if recent_sizes is not None:
                    try:
                        size_ok = 0 if estimate_shot_size(trial) in recent_sizes[-2:] else 1
                    except Exception:
                        size_ok = 1
                # Гейт сверяет кандидата с запросом ЭТОГО БЛОКА (`query`), а не
                # с тем запросом пула, из которого кандидат приплыл
                # (`_origin_query`). РЕАЛЬНАЯ, измеренная причина смены (28
                # августа, videos/_test20s): пул расширен ВСЕМИ авторскими
                # запросами секции (extra_queries), и при проверке «по своему
                # запросу» кандидат-всадник из запроса про конницу честно
                # проходил гейт... и попадал в блок «Пятнадцать килограммов»,
                # потому что дальше его ранжировал image-text скор Директора,
                # ложащийся на абстрактных фразах в шум 0.03-0.11 (то есть
                # выбор был фактически случайным). Прежняя формулировка была
                # осмысленна ровно до тех пор, пока запрос блока раздавался
                # ПОЗИЦИОННО и сам ничего не значил (см. semantic_query_
                # assignment() — теперь значит). Расширенный пул при этом
                # сохраняется целиком: кандидат из соседнего запроса по-
                # прежнему может победить, но только если он РЕАЛЬНО подходит
                # и теме этого блока тоже — чистое ужесточение без потери
                # глубины выбора.
                with stage_timer.stage("cheap_gate_clip", clip_idx=index):
                    relevance = clip_relevance(trial, query)
                    # Порог + risky-margin гейт (museum/exhibition/collection/... —
                    # см. RISKY_GENERIC_TERMS) — см. is_relevant_candidate(), та же
                    # функция, что проверяет golden-тест media-selection.
                    is_relevant = 1 if is_relevant_candidate(trial, query, relevance=relevance) else 0
                # sharp_ok (PHOTO_SHARPNESS_REJECT) — см. её докстринг: реальный
                # найденный случай, ни один кандидат никогда не проверялся на
                # резкость на этапе отбора, только опциональный постфактум-
                # проход (visual_qc.py, часто не запускается). None (сбой
                # декода/недоступность numpy) -> не гейтит, тот же безопасный
                # откат, что у остальных опциональных осей.
                sharp = image_sharpness_score(trial)
                sharp_ok = 1 if (sharp is None or sharp >= PHOTO_SHARPNESS_REJECT) else 0
                # Эстетика — доп. измерение, НЕ повышает good_needed само по
                # себе (в отличие от target_luma) — иначе каждый выбор фото
                # тратил бы вдвое больше скачиваний/Pexels-трафика по
                # умолчанию, а не только когда это уже оправдано другой
                # причиной. В реальных вызовах из main() target_luma и так
                # почти всегда задан (сравниваются 2+ кандидата), так что
                # эстетика получает шанс сработать бесплатно; если нет —
                # просто тихо не участвует в выборе (как раньше).
                aesthetic = aesthetic_score(trial)
                aesthetic_val = aesthetic if aesthetic is not None else 0.0
                luma_score = 0.0
                if target_luma is not None:
                    try:
                        cand_luma = measure_luma(trial)
                        if cand_luma is not None:
                            luma_score = -abs(cand_luma - target_luma)
                    except Exception:
                        pass
                candidates_info.append({
                    "path": trial, "p": p, "is_dup_free": is_dup_free, "size_ok": size_ok,
                    "is_relevant": is_relevant, "sharp_ok": sharp_ok, "aesthetic_val": aesthetic_val,
                    "luma_score": luma_score, "min_d": min_d, "relevance": relevance,
                })
                if is_dup_free and size_ok and is_relevant and sharp_ok:
                    good_seen += 1
                    if good_seen >= good_needed:
                        break   # набрали, сколько нужно для честного сравнения — не жжём оставшиеся попытки
            # Ранний break (как и раньше) может оставить часть prefetch-загрузок
            # ещё не понадобившимися — они не попали в candidates_info, значит
            # не попадут и под обычную чистку файлов-неудачников ниже. Ещё не
            # стартовавшие потоки отменяются (cancel() — no-op, если уже
            # бегут); shutdown(wait=False) не блокирует хвост функции, уже
            # запущенные докачки долетают в фоне и просто остаются на диске в
            # temp_smart/pexels_cache — тот же порядок величины "несколько
            # лишних trial-файлов", что и раньше терпелся у обычных неудачников.
            _processed_ids = {id(c["p"]) for c in candidates_info}
            for p in trial_slice:
                if id(p) not in _processed_ids:
                    prefetch_futures[id(p)].cancel()
            prefetch_pool.shutdown(wait=False)
            # _score_and_pick (см. выше) — чистое сравнение по уже скачанному
            # пулу, вынесенное отдельно ради тестируемости. Файлы-неудачники
            # раньше удалялись СРАЗУ по ходу цикла (экономия диска) — теперь
            # удаляются один раз здесь, после того как известен и base-, и
            # (если считался) director-победитель; PHOTO_DEDUP_MAX_TRIES=6,
            # так что одновременно на диске лежит максимум 6 trial-файлов —
            # пренебрежимо. Порядок выбора победителя от этого не меняется.
            base_winner, director_winner = _score_and_pick(candidates_info, director_score_fn)
            if director_report is not None:
                director_report["base_winner"] = base_winner["p"].get("id") if base_winner else None
                director_report["director_winner"] = director_winner["p"].get("id") if director_winner else None
                director_report["diverged"] = bool(
                    base_winner and director_winner and base_winner["path"] != director_winner["path"])
            winner = director_winner if (director_assist and director_winner is not None) else base_winner
            # VLM-АРБИТР (см. shot_director.arbitrate_hook_candidates,
            # блок-комментарий там же) — только когда вызывающий код передал
            # arbiter_text (HOOK-слоты, VLM_ARBITER_MODE, см. main()). Гейт
            # по режиму ЗДЕСЬ же, до сборки шорт-листа/импорта модуля — не
            # тратим время впустую при off (тот же паттерн, что resolve_
            # queries() уже применяет к SHOT_DIRECTOR_MODE).
            if (arbiter_text is not None and winner is not None
                    and os.environ.get("VLM_ARBITER_MODE", "off").strip().lower() == "on"):
                # Открывающий кадр — отдельный, ШИРЕ, шорт-лист (см.
                # _build_opening_shortlist) и отдельный промпт (критерий
                # "эффектность", не "точность", см. is_opening в
                # arbitrate_hook_candidates) — реальная жалоба пользователя
                # (/goal, 29 августа): обычный критерий стабильно выбирал
                # технически точную, но невыразительную картинку (весы) для
                # самого решающего для удержания кадра всего ролика.
                if is_opening_shot:
                    shortlist = _build_opening_shortlist(candidates_info, base_winner, director_winner)
                else:
                    shortlist = _build_arbiter_shortlist(candidates_info, base_winner, director_winner, query)
                if len(shortlist) >= 2:
                    import shot_director
                    arbiter_pick = shot_director.arbitrate_hook_candidates(
                        arbiter_text, [c["path"] for c in shortlist],
                        [c["p"].get("id") for c in shortlist], VIDEO_FOLDER, is_opening=is_opening_shot)
                    if arbiter_pick is not None:
                        winner = next(c for c in shortlist if c["path"] == arbiter_pick)
            if winner is not None and not winner["is_relevant"]:
                # Весь просмотренный пул провалил relevance-гейт — см.
                # RELEVANCE_GATE_MISSES выше. Победитель всё равно есть
                # (слот не должен остаться пустым), но промах теперь
                # честно записан, а не молчит.
                RELEVANCE_GATE_MISSES.append({
                    "index": index, "query": query,
                    "relevance": winner.get("relevance"),
                    "threshold": CLIP_RELEVANCE_THRESHOLD, "kind": "photo",
                })
            # STOCK_EXHAUSTED_MISSES — см. её докстринг у объявления выше:
            # True-пул-вайд проверка (независимо от дедупа), а не только по
            # победителю, как RELEVANCE_GATE_MISSES. candidates_info уже
            # содержит relevance/sharp_ok на КАЖДОГО кандидата — переиспользуем
            # то, что и так посчитано, ни одного нового вызова.
            if candidates_info and not _pool_cleared_both_gates(candidates_info):
                STOCK_EXHAUSTED_MISSES.append({
                    "index": index, "kind": "photo", "query": query,
                    "n_candidates_examined": len(candidates_info),
                })
            for c in candidates_info:
                if winner is None or c["path"] != winner["path"]:
                    try:
                        os.remove(c["path"])
                    except OSError:
                        pass
            if winner is None:
                pick = candidates[0]
                download(pick, cf)
            else:
                pick = winner["p"]
                os.replace(winner["path"], cf)
        if used_ids is not None:
            used_ids.add(pick.get("id"))
        if used_hashes is not None:
            try:
                used_hashes.append(ahash(cf))
            except Exception:
                pass
        if recent_sizes is not None:
            try:
                recent_sizes.append(estimate_shot_size(cf))
            except Exception:
                pass
        return cf
    except Exception as e:
        PEXELS_BROKEN = True
        print(f"  Pexels [{query}]: {e}")
        return None


_LOCAL_PHOTOS_CACHE = None


def _local_photos():
    """Отсортированный список локальных фото media/ — один раз на процесс.
    Раньше os.listdir(media/) выполнялся на КАЖДЫЙ вызов local_photo(), то
    есть по разу на блок (сотни раз за прогон) на папке из сотен файлов."""
    global _LOCAL_PHOTOS_CACHE
    if _LOCAL_PHOTOS_CACHE is None:
        _LOCAL_PHOTOS_CACHE = sorted(
            [f for f in os.listdir(MEDIA_FOLDER)
             if f.lower().endswith((".jpg", ".jpeg", ".png"))],
            key=lambda x: int(re.findall(r'\d+', x)[0]) if re.findall(r'\d+', x) else 0
        ) if os.path.isdir(MEDIA_FOLDER) else []
    return _LOCAL_PHOTOS_CACHE


def local_photo(index, allow_cycle=False):
    """Локальное фото под блок index (0-based).

    Порядок поиска:
    1) точное совпадение по номеру слота ({index+1:03d}_*) — это конвенция
       имён, которой пишут и stock_fetch_multisource.py, и AI-картинки
       (001_flow.jpg / 007_stock.jpg, см. ЧАСТЬ 14 CLAUDE.md);
    2) позиционно (photos[index]) — документированное "media/ по порядку";
    3) allow_cycle=True -> по кругу (photos[index % len]).

    РЕАЛЬНЫЙ БАГ, который здесь жил: раньше единственным вариантом был
    пункт 3 — по кругу ВСЕГДА. А признак "использовать локальную папку"
    (use_local в main()) взводится, если в media/ есть ХОТЯ БЫ ОДНО фото.
    То есть штатный сценарий протокола (Шаг 5: положить AI-картинки под
    хук, остальное добрать стоком/Pexels) давал ролик, целиком собранный
    из этих нескольких картинок, повторённых по кругу десятки раз, а
    Pexels не опрашивался ни разу. Теперь исчерпание локального пула —
    это None, и вызывающий код идёт в Pexels, как и написано в докстринге
    модуля ("Медиа: локальная папка media/ по порядку, fallback — Pexels").
    Цикл остался ровно там, где он лучше пустого кадра: последняя попытка
    в main(), когда Pexels уже не дал ничего (allow_cycle=True)."""
    photos = _local_photos()
    if not photos:
        return None
    prefix = f"{index + 1:03d}_"
    for f in photos:
        if f.startswith(prefix):
            return os.path.join(MEDIA_FOLDER, f)
    if index < len(photos):
        return os.path.join(MEDIA_FOLDER, photos[index])
    if allow_cycle:
        return os.path.join(MEDIA_FOLDER, photos[index % len(photos)])
    return None


GENERIC_FALLBACKS = [
    "medieval sword still life", "knight armor moody light",
    "medieval castle atmosphere", "old manuscript parchment history",
    "cinematic dark fantasy weapon",
]


def query_for(text, keyword_counts=None):
    """keyword_counts (опционально, мутируется на месте) — значение THEMES
    может быть СПИСКОМ синонимичных запросов, не только строкой. Найден
    вживую реальный источник дублей на готовом ролике: "меч" — самое частое
    слово в видео буквально про вес меча, matches keyword напрямую (не
    через generic-заглушку с её собственной ротацией) — один и тот же
    запрос "medieval sword close up" уходил в Pexels 35 раз на 150 кадров
    эпизода. У Pexels физически нет 35 визуально различимых фото на один
    узкий запрос — сколько ни доверяй анти-дублю (pexels_photo), пул
    исчерпывается. Ротация по списку синонимов делит нагрузку на несколько
    независимых пулов вместо одного.

    Матч по ГРАНИЦЕ слова, не по голой подстроке — ключи THEMES это корни
    словоформ ("музе" -> музей/музейные/музея), поэтому конец матча
    намеренно открыт (\\w* добавляет любое окончание), а вот НАЧАЛО матча
    обязано быть началом слова (\\b). Раньше `kw in tl` совпадал и ВНУТРИ
    произвольного слова, где корень оказался подстрокой случайно — тихий
    риск ложного срабатывания на короткие 3-4-буквенные ключи (их в
    THEMES большинство)."""
    tl = text.lower()
    for kw, q in THEMES.items():
        if re.search(r'\b' + re.escape(kw), tl):
            if isinstance(q, list):
                idx = keyword_counts.get(kw, 0) if keyword_counts is not None else 0
                if keyword_counts is not None:
                    keyword_counts[kw] = idx + 1
                return q[idx % len(q)]
            return q
    return None


# Реальный, эмпирически найденный случай (жалоба пользователя "3 кадра
# подряд с кино", videos/_test_wide): даже ПОСЛЕ починки конкретной плохой
# темы ("кино"/"фильм"/"игр" -> буквальный, мимо смысла запрос — см.
# channel_themes.json) наследование запроса у соседа само по себе может
# дать ДЛИННУЮ цепочку блоков с ОДНОЙ и той же буквальной строкой запроса
# (на этом же эпизоде — 6 подряд "medieval sword close up" в самом начале
# хука, БЕЗ какой-либо ошибки в словаре тем — просто несколько
# нераспознанных фраз подряд унаследовали запрос у одного и того же
# первого совпадения). Семантическая проверка (мультиязычная CLIP против
# реального русского текста) для этого НЕ годится — проверено вживую на
# 3 калибровках подряд на реальных данных этого эпизода (полный текст
# блока, не обрезанный query-посредник): даже в лучшем случае 37%
# инверсий (картинка "по смыслу верно" сама себе проигрывала случайной
# фразе из другого домена) — слишком шумно для автоматического отказа
# кандидата, это утопило бы правильные совпадения чаще, чем спасло от
# неправильных. MAX_CONSECUTIVE_SAME_QUERY — детерминированная (без
# ML-шума) защита от ДРУГОЙ, но родственной причины той же жалобы:
# визуальной монотонности внутри одной темы, не только полного
# рассогласования по смыслу.
MAX_CONSECUTIVE_SAME_QUERY = 3


def _diversify_repeated_query_runs(resolved, blocks):
    """Меняет resolved НА МЕСТЕ: ни один буквально одинаковый запрос не
    идёт подряд дольше MAX_CONSECUTIVE_SAME_QUERY раз. Для блока сверх
    лимита ищем БЛИЖАЙШЕГО соседа той же секции с ДРУГИМ уже готовым
    запросом (тот же принцип границ секции, что и у наследования выше —
    тема раздела обычно единая, выходить за её пределы без нужды не
    хотим); если во всей секции все блоки схлопнулись в один и тот же
    запрос — берём по кругу из GENERIC_FALLBACKS (тот же, уже проверенный
    резерв, что и для полностью нераспознанных блоков).

    ОДНОГО прохода недостаточно (реальный случай, пойман на этом же
    эпизоде): несколько соседних блоков внутри одного слишком длинного
    прогона могут независимо "занять" ОДИН и тот же альтернативный
    запрос у одного и того же внешнего соседа — тогда прогон не исчезает,
    а просто сдвигается (был 6 подряд "medieval sword close up", стало
    3 + НОВЫЙ прогон из 4 "sword blade close up"). Поэтому — повторяем
    поиск-и-правку, пока новый проход не перестанет находить нарушения
    (fixed-point), с жёстким потолком итераций как страховкой от
    зацикливания на патологических входных данных."""
    fallback_cursor = 0
    for _pass in range(len(resolved) + 1):
        n = len(resolved)
        run_start = 0
        changed = False
        for i in range(1, n + 1):
            if i < n and resolved[i] == resolved[run_start]:
                continue
            run_len = i - run_start
            if run_len > MAX_CONSECUTIVE_SAME_QUERY:
                changed = True
                for k in range(run_start + MAX_CONSECUTIVE_SAME_QUERY, i):
                    current = resolved[k]
                    section = blocks[k]["section"]
                    alt = None
                    for j in range(k - 1, -1, -1):
                        if blocks[j]["section"] != section:
                            break
                        if resolved[j] != current:
                            alt = resolved[j]
                            break
                    if alt is None:
                        for j in range(k + 1, n):
                            if blocks[j]["section"] != section:
                                break
                            if resolved[j] != current:
                                alt = resolved[j]
                                break
                    if alt is None:
                        alt = GENERIC_FALLBACKS[fallback_cursor % len(GENERIC_FALLBACKS)]
                        fallback_cursor += 1
                    resolved[k] = alt
            run_start = i
        if not changed:
            break


SEMANTIC_QUERY_ASSIGNMENT = os.environ.get("SEMANTIC_QUERY_ASSIGNMENT", "1") != "0"


def semantic_query_assignment(block_texts, queries):
    """Кому какой АВТОРСКИЙ запрос — по СМЫСЛУ фразы, а не по позиции в списке.
    Возвращает список индексов queries (по одному на блок) или None (fail-open:
    вызывающий код тогда откатывается на прежнее позиционное поведение).

    РЕАЛЬНАЯ, измеренная причина (videos/_test20s, 28 августа — не гипотеза,
    прямой разбор готового ролика по жалобе пользователя): авторские запросы
    из `=== PEXELS QUERIES ===` раздавались блокам ПОЗИЦИОННО по кругу
    (`pool[cursor % len(pool)]`). Между ТЕКСТОМ запроса и ТЕКСТОМ блока не
    было вообще никакой связи — только порядковый номер. На реальном хуке из
    8 запросов и 8 блоков это дало 6 промахов из 8: фраза «Так говорят кино,
    видеоигры и школьные учебники» получала запрос про ВЕСЫ, фраза «сколько
    весил настоящий боевой меч» — запрос про КИНОЗАЛ, а самая визуальная
    фраза эпизода «Герой на экране заносит клинок... вместе с конём» —
    вообще чужой запрос по наследству от непредметной связки «Готов спорить,
    что да» (правило is_subcut-наследования). Зритель видит это ровно как
    «картинку поставили в рандом, а не под озвучку» — потому что связь с
    озвучкой физически отсутствовала.

    Никакой гейт качества/резкости/релевантности это НЕ ЛЕЧИТ: они проверяют
    «хорош ли кандидат для СВОЕГО запроса», а запрос с самого начала был не
    тот. Поэтому чинить надо здесь, в точке назначения, а не ниже по конвейеру.

    МЕТОД. visual_director.text_text_similarity() — мультиязычный текстовый
    энкодер (Jina CLIP v2): русская фраза сценария против английского
    авторского запроса, обе стороны ТЕКСТ (см. её докстринг с реальными
    замерами: правильный запрос выигрывает с заметным отрывом на каждом
    визуальном блоке). Это принципиально сильнее, чем image-text скоринг
    Директора, который на абстрактных фразах ложится в шум 0.03-0.11.

    Распределение — ЖАДНОЕ ГЛОБАЛЬНОЕ по всей матрице (самая уверенная пара
    «блок-запрос» забирается первой), с равномерным потолком повторов
    ceil(n_блоков / n_запросов). Почему не «каждому блоку его максимум
    независимо»: тогда несколько блоков забрали бы один и тот же самый
    «удобный» запрос, а остальные авторские запросы не использовались бы
    вообще — автор писал их как ПОСЛЕДОВАТЕЛЬНОСТЬ кадров, и терять часть
    ряда значит терять его замысел. Глобальная жадность детерминирована
    (сортировка со стабильным тай-брейком по индексам), поэтому один и тот
    же сценарий всегда даёт одно и то же распределение — важно для кэша.

    is_subcut-наследование здесь СОЗНАТЕЛЬНО не применяется: оно было
    компенсацией именно за то, что позиционный запрос всё равно ничего не
    значил. Теперь каждый под-кадр получает СВОЙ лучший по смыслу запрос —
    и это прямо чинит найденный случай (под-кадр «Герой... заносит клинок»
    больше не наследует запрос непредметного родителя)."""
    if not SEMANTIC_QUERY_ASSIGNMENT or not block_texts or not queries:
        return None
    try:
        import visual_director
        sim = visual_director.text_text_similarity(block_texts, queries)
    except Exception:
        return None
    if not sim:
        return None
    n_blocks, n_q = len(block_texts), len(queries)
    max_uses = -(-n_blocks // n_q)   # ceil — равномерный потолок повторов
    pairs = sorted(((-sim[b][q], b, q) for b in range(n_blocks) for q in range(n_q)))
    assigned, uses = [None] * n_blocks, [0] * n_q
    for _, b, q in pairs:
        if assigned[b] is None and uses[q] < max_uses:
            assigned[b] = q
            uses[q] += 1
    # Блок, которому не хватило квоты (возможно при неровном делении) —
    # берёт свой безусловный максимум, без потолка: пустой слот хуже повтора.
    for b in range(n_blocks):
        if assigned[b] is None:
            assigned[b] = max(range(n_q), key=lambda q: sim[b][q])
    return assigned


def _query_assignment_cache_dir():
    return os.path.join(VIDEO_FOLDER, "media_plan", "query_resolution_cache")


def _query_assignment_cache_path(block_texts, queries):
    key = hashlib.sha256(
        json.dumps({"block_texts": block_texts, "queries": queries},
                    ensure_ascii=False, sort_keys=False).encode("utf-8")
    ).hexdigest()
    return os.path.join(_query_assignment_cache_dir(), f"{key}.json")


def _cached_semantic_query_assignment(block_texts, queries):
    """Тонкая дисковая обёртка над semantic_query_assignment() — реальный
    измеренный вживую (01_ves-mecha, 31 авг) кейс: `resolve_queries()`
    считается ЗАНОВО при КАЖДОМ перезапуске процесса (эпизод перезапускался
    несколько раз за сессию из-за OOM, не по вине этой функции) — Jina
    text-text similarity по всем секциям с авторскими запросами занимала
    ориентировочно 10-15+ минут, притом что вход (тексты блоков + авторские
    запросы секции) между перезапусками ОДНОГО и того же эпизода не менялся
    вообще. Кэш на диске по хэшу точного содержимого (block_texts, queries)
    — тот же паттерн, что уже используют media_plan/shot_director_cache/.

    Кэшируется ТОЛЬКО успешный результат (assignment is not None) — fail-open
    "модель недоступна" не кэшируется (дёшево пересчитать, и это честный
    сигнал состояния окружения на конкретный момент, не вход).

    Отключено под pytest (PYTEST_CURRENT_TEST) — тесты этого модуля гоняют
    semantic_query_assignment()/resolve_queries() на подменённой (monkeypatch)
    text_text_similarity() с ОДИНАКОВЫМ текстовым входом, но РАЗНЫМИ
    матрицами по разным тестам (см. tests/test_parse.py::_fake_sim) — общий
    VIDEO_FOLDER=tempdir() на весь тестовый прогон сделал бы такой дисковый
    кэш общим между тестами и мог бы отдать результат ОДНОГО теста другому
    с тем же текстом. PYTEST_CURRENT_TEST — стандартная переменная, которую
    сам pytest выставляет на время каждого теста, надёжный сигнал "не прод"."""
    if os.environ.get("PYTEST_CURRENT_TEST"):
        return semantic_query_assignment(block_texts, queries)
    cache_path = None
    try:
        cache_path = _query_assignment_cache_path(block_texts, queries)
        if os.path.exists(cache_path):
            with open(cache_path, encoding="utf-8") as f:
                cached = json.load(f)
            if isinstance(cached, list) and len(cached) == len(block_texts):
                return cached
    except Exception:
        pass
    result = semantic_query_assignment(block_texts, queries)
    if result is not None and cache_path is not None:
        try:
            os.makedirs(os.path.dirname(cache_path), exist_ok=True)
            with open(cache_path + ".tmp", "w", encoding="utf-8") as f:
                json.dump(result, f, ensure_ascii=False)
            os.replace(cache_path + ".tmp", cache_path)
        except Exception:
            pass
    return result


def resolve_queries(blocks, authored_queries=None):
    """Прямой поиск по themes.json ловит не все блоки — короткие связки
    ("Не дрались. Несли.", "Береги себя.") и абстрактные куски без предметных
    слов улетают в generic-заглушку, которая никак не привязана к теме ролика.
    Вместо одной фиксированной строки на все такие блоки: сперва пробуем
    унаследовать запрос соседнего блока той же секции (тема раздела обычно
    не меняется от предложения к предложению), и только если во всей секции
    вообще ничего не нашлось — берём по кругу из GENERIC_FALLBACKS (не один
    и тот же текст на всё, иначе Pexels отдаёт одну и ту же жалкую пятёрку).

    authored_queries (опционально) — {normalized_section_key: [query, ...]}
    из === PEXELS QUERIES === (см. script_parser.parse_pexels_queries) —
    запросы, написанные вручную СО ЗНАНИЕМ КОНКРЕТНОГО МОМЕНТА сценария
    ("вспомни, сколько весит пакет молока" -> "milk bottle hand"), которые
    query_for()/THEMES физически не может воспроизвести (статический
    словарь корней, без понимания сцены целиком). Реальный, найденный по
    прямому запросу пользователя пробел: секция писалась по протоколу
    (CLAUDE.md ЧАСТЬ 13, Шаг 3), но НИКОГДА не читалась пайплайном —
    query_for() всегда молча пересчитывал заново, теряя весь авторский
    контекст. ПРИОРИТЕТ над query_for() там, где для секции есть
    авторские запросы: распределяются по ОРИГИНАЛЬНЫМ (до sub-cut split)
    блокам секции по порядку, sub-cut-продолжение (b["is_subcut"]) получает
    ТОТ ЖЕ запрос, что и его исходный блок (тот же принцип, что уже
    работает для query_for() — "под-кадры унаследуют запрос", см.
    split_long_blocks). None/{} -> прежнее поведение, ноль регрессии.

    Наследование само по себе может дать длинную цепочку блоков с ОДНИМ и
    тем же буквальным запросом (см. _diversify_repeated_query_runs) —
    финальный проход разбивает такие цепочки длиннее
    MAX_CONSECUTIVE_SAME_QUERY, даже если каждый отдельный запрос в ней
    формально верный по теме (в т.ч. авторские — те тоже могут повторяться
    по кругу, если исходных блоков в секции больше, чем написанных запросов)."""
    keyword_counts = {}
    raw = [query_for(b["text"], keyword_counts) for b in blocks]

    if authored_queries:
        # Индексы блоков каждой секции, у которой есть авторские запросы.
        by_section = {}
        for i, b in enumerate(blocks):
            key = _normalize_section_key(b["section"])
            if key and authored_queries.get(key):
                by_section.setdefault(key, []).append(i)
        for key, idxs in by_section.items():
            pool = authored_queries[key]
            assignment = _cached_semantic_query_assignment([blocks[i]["text"] for i in idxs], pool)
            if assignment is not None:
                for pos, i in enumerate(idxs):
                    raw[i] = pool[assignment[pos]]
                continue
            # Fail-open: смысловая модель недоступна -> ПРЕЖНЕЕ позиционное
            # поведение байт-в-байт (ноль регрессии на машине без Jina/onnx).
            cursor = 0
            for i in idxs:
                if blocks[i].get("is_subcut") and i > 0 and raw[i - 1] is not None:
                    raw[i] = raw[i - 1]
                    continue
                raw[i] = pool[cursor % len(pool)]
                cursor += 1

    # LLM-режиссёр (SHOT_DIRECTOR_MODE=on, дефолт off) — только для блоков,
    # оставшихся None ПОСЛЕ authored_queries и THEMES (см. shot_director.py
    # докстринг: идиомы/метафоры без предметных слов, реальный, эмпирически
    # найденный пробел неспособности neighbor-inherit/GENERIC_FALLBACKS
    # передать смысл именно ЭТОЙ фразы). Ленивый импорт по тому же паттерну,
    # что VISUAL_DIRECTOR_MODE/LOOK_MANAGEMENT_MODE ниже в этом файле — off
    # не тянет модуль и не трогает сеть вообще.
    if os.environ.get("SHOT_DIRECTOR_MODE", "off").strip().lower() == "on":
        import shot_director
        for i, q in enumerate(raw):
            if q is not None:
                continue
            directed = shot_director.direct_query(blocks[i]["text"], VIDEO_FOLDER)
            if directed is not None:
                raw[i] = directed

    resolved = list(raw)
    for i, q in enumerate(resolved):
        if q is not None:
            continue
        for j in range(i - 1, -1, -1):
            if blocks[j]["section"] != blocks[i]["section"]:
                break
            if raw[j] is not None:
                resolved[i] = raw[j]
                break
        if resolved[i] is not None:
            continue
        for j in range(i + 1, len(blocks)):
            if blocks[j]["section"] != blocks[i]["section"]:
                break
            if raw[j] is not None:
                resolved[i] = raw[j]
                break
    fallback_n = 0
    for i, q in enumerate(resolved):
        if q is None:
            resolved[i] = GENERIC_FALLBACKS[fallback_n % len(GENERIC_FALLBACKS)]
            fallback_n += 1
    _diversify_repeated_query_runs(resolved, blocks)
    return resolved


STAT_ACCENT = "0xC8102E"   # акцентный красный, CHANNEL.md house style
# D4: печатная машинка на 5-м варианте плашки (variant 4 из 5) — round-robin
# stat_variant % 5 уже даёт "не постоянно всегда" бесплатно (1 из 5 появлений
# цифры/даты в ролике), без отдельной классификации "это дата или нет" —
# [stat:...] и так по смыслу ВСЕГДА число/дата (см. ЧАСТЬ 9 script.txt),
# отдельный детектор не нужен. Тайминг посимвольного появления — константа,
# используется И в drawtext (визуал), И в main() при сборе таймкодов для
# звука печатной машинки (add_typewriter_clicks) — ОДНА и та же величина,
# иначе визуал и звук разъедутся по скорости печати.
TYPEWRITER_CHAR_DUR = 0.075
# Библиотека из 8 РЕАЛЬНЫХ отдельных ударов клавиш (не один клип, повторённый
# клонштампом на каждый символ — на реальной записи разные удары звучат чуть
# по-разному, один и тот же сэмпл на каждый символ читался механически,
# "не как в живой записи", по прямой обратной связи пользователя). Извлечены
# из присланной пользователем записи (scripts/generate — нет, это ручное
# разовое извлечение, см. коммит) — каждый нормализован к своему пику
# отдельно (не общий loudnorm), сохраняя естественный разброс громкости
# между разными ударами.
KEYBOARD_CLICKS_DIR = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
                                    "assets", "sfx", "keyboard_clicks")
KEYBOARD_CLICK_PATHS = sorted(glob.glob(os.path.join(KEYBOARD_CLICKS_DIR, "click_*.flac")))
TYPEWRITER_CLICK_ENABLED = os.environ.get("TYPEWRITER_CLICKS", "1") != "0" and bool(KEYBOARD_CLICK_PATHS)
TYPEWRITER_CLICK_GAIN_DB = -6.0


def typewriter_reveal_timing(n_chars, delay, dur, fin_dur=0.25, hold_margin=0.5):
    """Общая математика тайминга посимвольного появления — используется И в
    add_overlays() (визуал, локальное время клипа), И в main() при сборе
    таймкодов звука (реальное абсолютное время ролика) — ОДНА функция, чтобы
    визуал и звук печатной машинки не могли разъехаться по скорости из-за
    двух независимо подправленных копий одной и той же формулы клэмпа."""
    hold = max(delay + fin_dur, dur - hold_margin)
    cd = TYPEWRITER_CHAR_DUR
    if n_chars > 0 and delay + n_chars * cd > hold:
        cd = max(0.02, (hold - delay) / n_chars)
    return hold, cd


def pick_stat_variant(stat_variant, media_path=None):
    """D5: среди "статичных" оформлений плашки (0/1/2/3 — баннер-бокс/
    крупный центр без бокса/боковой акцент/мелкий угол) выбор не чисто по
    кругу, а с поправкой на РЕАЛЬНЫЙ контраст/плотность кадра под ней:
    - плотный кадр (busy>0.55, много локальных перепадов — макро/деталь) ->
      мелкий угловой (3), крупная плашка перекрыла бы сюжет;
    - малоконтрастный фон (узкий диапазон белая-чёрная точка) -> крупный
      центральный текст без бокса (1) читается безопасно, бокс тут не нужен;
    - просторный И контрастный кадр -> боковой акцент (2), есть настоящее
      негативное пространство под полосу+текст;
    - смешанный случай -> классический баннер с боксом (0), самый
      универсально безопасный (бокс сам создаёт контраст, не полагается на
      то, что уже есть в кадре).
    media_path=None (видео-клип или PIL/np недоступны) -> откат на прежний
    чистый round-robin (%4) — не регрессия, а прежнее поведение."""
    if media_path is None:
        return stat_variant % 4
    try:
        busy = estimate_busyness(media_path)
        levels = measure_levels(media_path)
        contrast = (levels[1] - levels[0]) if levels else 0.5
    except Exception:
        return stat_variant % 4
    if busy > 0.55:
        return 3
    if contrast < 0.35:
        return 1
    if busy < 0.25 and contrast > 0.55:
        return 2
    return 0


def add_overlays(vf_base, dur, title=None, stat=None, stat_variant=0, stat_delay=0.0, media_path=None):
    """Титр секции (низ кадра, слайд+fade первые ~2.5с, фирменный дисплейный
    шрифт) + цифровая плашка. Общий код для фото и видео-стока. Обычный
    fade раньше был самым узнаваемым штампом автослайдшоу — слайд добавляет
    "кто-то это анимировал руками".

    Плашка (2.2): раньше ОДИН и тот же красный баннер на каждую цифру за
    ролик — после 3-4 повторов за 16 минут читается как "шаблон программы",
    не дизайнерское решение. 4 варианта оформления, чередуются по позиции
    цифры в ролике (main() считает running-индекс): классический баннер /
    крупное число по центру без плашки / боковой акцент с полосой / мелкий
    текст в углу с подчёркиванием."""
    vf = vf_base
    # Титр раздела — вторичный уровень иерархии (Montserrat): это подпись,
    # не "геройский" факт-баннер — жирный, но не такой кричащий, как Benzin
    # на цифрах-доказательствах (stat ниже). Один и тот же шрифт на оба
    # уровня раньше читался как "программа так рисует", не решение монтажёра.
    if title and FONT_SECONDARY_PATH:
        hold = min(2.5, dur * 0.6)
        fin = max(0.3, hold * 0.3)
        text = title.upper() if FONT_IS_DISPLAY else title
        safe = escape_drawtext(text)
        fs = 46 if FONT_IS_DISPLAY else 54
        vf += (f",drawtext=fontfile='{FONT_SECONDARY_PATH}':text='{safe}':"
               f"fontcolor=white:fontsize={fs}:borderw=3:bordercolor=black@0.8:"
               f"x=(w-text_w)/2:"
               f"y='h-180+(1-min(t/{fin:.2f}\\,1))*36':"
               f"alpha='if(lt(t\\,{fin:.2f})\\,t/{fin:.2f}\\,"
               f"if(lt(t\\,{hold:.2f})\\,1\\,max(0\\,1-(t-{hold:.2f})/0.4)))'")
    if stat and FONT_PATH:
        fin_dur = 0.25
        # Плашка раньше ВСЕГДА стартовала от t=0 клипа — независимо от того,
        # где внутри фразы реально произносится число (см. stat_word_pos в
        # parse_blocks/split_long_blocks). Цифра появлялась на экране
        # заметно раньше, чем её произносили. delay — момент внутри клипа,
        # когда число уже озвучено; clamp оставляет минимум ~1.2с на сам
        # fade-in/hold/fade-out, даже если delay пришёлся почти на конец
        # клипа (не даём плашке исчезнуть, не успев появиться).
        delay = max(0.0, min(stat_delay, dur - 1.2))
        fin = delay + fin_dur
        hold = max(fin, dur - 0.5)
        text = stat.upper() if FONT_IS_DISPLAY else stat
        safe = escape_drawtext(text)
        alpha = (f"if(lt(t\\,{delay:.2f})\\,0\\,"
                 f"if(lt(t\\,{fin:.2f})\\,(t-{delay:.2f})/{fin_dur:.2f}\\,"
                 f"if(lt(t\\,{hold:.2f})\\,1\\,max(0\\,1-(t-{hold:.2f})/0.4))))")
        # D4: печатная машинка — фиксированный round-robin слот "не всегда"
        # (1 из 5 появлений цифры/даты), независимо от D5 ниже. D5: остальные
        # 4/5 появлений выбирают оформление по контрасту кадра, не по кругу.
        variant = 4 if stat_variant % 5 == 4 else pick_stat_variant(stat_variant, media_path)
        if variant == 0:
            # Классический баннер — верх кадра, слайд сверху.
            fs = 58 if FONT_IS_DISPLAY else 64
            vf += (f",drawtext=fontfile='{FONT_PATH}':text='{safe}':"
                   f"fontcolor=white:fontsize={fs}:"
                   f"box=1:boxcolor={STAT_ACCENT}@0.92:boxborderw=18:"
                   f"x=(w-text_w)/2:"
                   f"y='110-(1-max(0\\,min((t-{delay:.2f})/{fin_dur:.2f}\\,1)))*26':"
                   f"alpha='{alpha}'")
        elif variant == 1:
            # Крупное число по центру кадра — без плашки, тень вместо box.
            fs = 96 if FONT_IS_DISPLAY else 108
            vf += (f",drawtext=fontfile='{FONT_PATH}':text='{safe}':"
                   f"fontcolor=white:fontsize={fs}:"
                   f"shadowcolor=black@0.85:shadowx=4:shadowy=4:"
                   f"borderw=2:bordercolor=black@0.6:"
                   f"x=(w-text_w)/2:y=(h-text_h)/2:"
                   f"alpha='{alpha}'")
        elif variant == 2:
            # Боковой акцент — число слева, вертикальная полоса рядом.
            fs = 62 if FONT_IS_DISPLAY else 68
            # drawbox: w/h в x/y-выражениях ссылаются на СОБСТВЕННЫЕ параметры
            # бокса (w=8, h=160), не на кадр — иначе бы (h-160)/2 = 0
            # (самоссылка h=160-160=0), поймано на реальном рендере (полоса
            # уезжала в самый верх кадра). ih/iw — явно "кадр", не бокс.
            vf += (f",drawbox=x=100:y=(ih-160)/2:w=8:h=160:"
                   f"color={STAT_ACCENT}@0.92:t=fill:"
                   f"enable='between(t\\,{delay:.2f}\\,{hold:.2f})'"
                   f",drawtext=fontfile='{FONT_PATH}':text='{safe}':"
                   f"fontcolor=white:fontsize={fs}:"
                   f"shadowcolor=black@0.8:shadowx=3:shadowy=3:"
                   f"x=130:y=(h-text_h)/2:"
                   f"alpha='{alpha}'")
        elif variant == 3:
            # Минимальный — текст в нижнем правом углу, подчёркивание. По
            # смыслу подпись, не геройская цифра — вторичный шрифт, но
            # реальная жалоба (скриншот пользователя): на практике читалась
            # как "слишком мелкая и незаметная" на фоне живой картинки —
            # 34-38px терялись рядом с деталями кадра. Крупнее + тёмная
            # подложка под текст для контраста (не превращаем в баннер
            # variant 0 — подложка полупрозрачная и только под текстом, не
            # во весь угол), позиция и логика (right-aligned, подчёркивание)
            # не менялись — только заметность.
            fs = 46 if FONT_IS_DISPLAY else 52
            vf += (f",drawtext=fontfile='{FONT_SECONDARY_PATH}':text='{safe}':"
                   f"fontcolor=white:fontsize={fs}:"
                   f"box=1:boxcolor=black@0.5:boxborderw=12:"
                   f"borderw=2:bordercolor=black@0.7:"
                   f"x=w-text_w-70:y=h-140:"
                   f"alpha='{alpha}'"
                   f",drawbox=x=iw-300:y=ih-88:w=240:h=4:"
                   f"color={STAT_ACCENT}@0.92:t=fill:"
                   f"enable='between(t\\,{delay:.2f}\\,{hold:.2f})'")
        else:
            # D4: печатная машинка — сверено с референсом пользователя
            # (архивная аэросъёмка, дата "12.09.2020"): НЕ крупный "геройский"
            # центр кадра (как было раньше), а скромная подпись в нижней
            # трети — субтильный вес, тонкая тень вместо жирного борда, ближе
            # к "архивной датировке кадра", чем к рекламному баннеру. По X
            # оставлен центр (не копируем точный сдвиг референса влево — тот
            # кадр 9:16 с другим соотношением сторон, а текст variant 4 может
            # быть разной длины/языка, центр — единственное универсально
            # безопасное положение по горизонтали).
            # Символы появляются один за другим (та же ставка
            # TYPEWRITER_CHAR_DUR, что задаёт таймкоды звука в
            # main()/add_typewriter_clicks), после полного текста — обычная
            # задержка и fade-out, как у остальных вариантов. Цепочка
            # drawtext: filter k показывает text[:k+1] ТОЛЬКО в своём окне
            # [delay+k*cd, delay+(k+1)*cd) — сменяется следующим, длиннее на
            # один символ; последний остаётся до конца hold+fade-out.
            n_chars = len(text)
            _, cd = typewriter_reveal_timing(n_chars, delay, dur)
            fs = 56 if FONT_IS_DISPLAY else 62
            for k in range(n_chars):
                sub = escape_drawtext(text[:k + 1])
                seg_start = delay + k * cd
                seg_end = hold if k == n_chars - 1 else delay + (k + 1) * cd
                seg_alpha = alpha if k == n_chars - 1 else "1"
                vf += (f",drawtext=fontfile='{FONT_PATH}':text='{sub}':"
                       f"fontcolor=white:fontsize={fs}:"
                       f"shadowcolor=black@0.7:shadowx=1:shadowy=1:"
                       f"x=(w-text_w)/2:y=h*0.78-text_h/2:"
                       f"enable='between(t\\,{seg_start:.3f}\\,{seg_end:.3f})':"
                       f"alpha='{seg_alpha}'")
    return vf


CAPTION_FONT_SIZE = 76   # D2: крупные кинетические слова-акценты хука, Benzin-ExtraBold


def add_kinetic_captions(vf, captions):
    """D2: кинетические подписи хука — по одному слову крупным фирменным
    шрифтом (FONT_PATH), синхронно с РЕАЛЬНЫМ посимвольным таймингом
    произношения (см. load_hook_word_timings/hook_captions_for_block — тот
    же alignment.csv, что и везде в пайплайне, не оценка по words/wps).
    Только ХУК (main() зовёт это только для HOOK-блоков) — приём крупных
    слов-акцентов для самых первых секунд удержания, не постоянный субтитр
    на весь ролик (тот — write_subtitles(), полноразмерные описательные
    субтитры, другая задача).

    Позиция (2.6, было h*0.66 — реальная жалоба: слишком по центру кадра,
    мешает смотреть картинку): write_subtitles() пишет ТОЛЬКО отдельный
    subtitles.srt для загрузки на YouTube, в кадр НЕ вшивается — "дно кадра
    уже занято субтитрами" было неверно с самого начала, реального
    конкурента внизу нет. Единственные соседи внизу — плашка-цифра (2.2):
    variant 4 (typewriter, add_overlays) сидит на y=h*0.78 по центру,
    variant 3 — мелкая подпись в правом нижнем углу (y=h-110). Стандартная
    для горизонтального ролика зона субтитров — нижняя треть, ближе к низу,
    чем к центру, но с запасом НАД variant 4, чтобы два текстовых слоя не
    накладывались, если в одном клипе одновременно и цифра, и кинетическое
    слово хука."""
    if not captions or not FONT_PATH:
        return vf
    for word, start, end in captions:
        text = word.upper() if FONT_IS_DISPLAY else word
        safe = escape_drawtext(text)
        if not safe:
            continue
        vf += (f",drawtext=fontfile='{FONT_PATH}':text='{safe}':"
               f"fontcolor=white:fontsize={CAPTION_FONT_SIZE}:"
               f"shadowcolor=black@0.85:shadowx=3:shadowy=3:"
               f"borderw=2:bordercolor=black@0.6:"
               f"x=(w-text_w)/2:y=h*0.73-text_h/2:"
               f"enable='between(t\\,{start:.3f}\\,{end:.3f})'")
    return vf


def kb_hash_choices(photo):
    """Кандидаты зума/пана по хэшу файла — детерминированно, но БЕЗ памяти о
    соседних клипах (это даёт anti-repetition в main(), см. pick_no_repeat)."""
    h = int(hashlib.md5(photo.encode()).hexdigest()[:8], 16)
    zoom_in = bool(h & 1)
    pan_dir = PAN_DIRECTIONS[(h >> 1) % len(PAN_DIRECTIONS)]
    return h, zoom_in, pan_dir


@memoize_by_frame
def estimate_busyness(photo_path):
    """Грубая мера "тесноты" кадра без depth-модели — просто плотность
    перепадов яркости на уменьшенной копии. Не настоящая детекция крупности
    плана, но дешёвый прокси: у тесного/плотного кадра (уже крупный план)
    перепадов много на каждый пиксель, у просторного — мало. Используется
    только чтобы НЕ зумить ещё сильнее то, что и так уже крупный план."""
    try:
        img = PILImage.open(photo_path).convert("L").resize((160, 90))
        arr = np.asarray(img, dtype=np.float32) if np is not None else None
        if arr is None:
            return 0.5
        gx = np.abs(np.diff(arr, axis=1)).mean()
        gy = np.abs(np.diff(arr, axis=0)).mean()
        return float(min(1.0, (gx + gy) / 40.0))
    except Exception:
        return 0.5


_FACE_CASCADE = None
_EYE_CASCADE = None   # см. _face_region_plausible() — вторичная проверка найденного "лица"


FACE_SKIN_FRAC_MIN = 0.25   # доля YCrCb-кожи в найденном "лице" — калибровано вживую (см. ниже)
FACE_EYE_MIN_SIZE_FRAC = 0.10   # мин. размер глаза относительно найденного "лица"


def _face_region_plausible(img, gray, fx, fy, fw, fh):
    """Вторая, независимая проверка НАД результатом Haar-каскада лица —
    не меняет чувствительность самого каскада (см. detect_face_anchor,
    ЧАСТЬ 13 "меч всё ещё холодный"): реальный вживую замер на 125
    уникальных стоковых кандидатах этого канала (военные предметы, доспехи,
    архивные фото) дал 39 "лиц" от голого frontalface-каскада — из них
    ПРОВЕРЕНО глазами лишь единицы настоящие (навершие меча, кинозал,
    камуфляжный геймпад и т.п. регулярно ложно триггерят каскад). Два
    независимых, бесплатных, уже-в-OpenCV сигнала, оба должны пройти:
    1) skin-tone в YCrCb (Cr/Cb-диапазон — стандартная, документированная
       эвристика детекции кожи, не выдуманная) — доля пикселей найденной
       области в человеческом диапазоне тона;
    2) вложенный eye-каскад (haarcascade_eye.xml, тот же бесплатный набор
       OpenCV) — хотя бы один глаз внутри области лица.
    Комбинация на том же тестовом наборе: 39 -> 9 кандидатов (проверено
    вживую чтением кадров — среди 9 подтверждённых лиц оказалось
    большинство настоящих, включая случай, что фильтр НЕ идеален (один
    геймпад с камуфляжной раскраской всё ещё проходит) — честно, не
    гарантия нуля ошибок, только СИЛЬНОЕ сужение частоты false positive,
    та же дисциплина, что и у _warm_mult/DOMAIN_WARM_PUSH_SCALE выше:
    только сужение сигнала, никогда не расширение (ничего, что раньше не
    считалось лицом, теперь лицом не станет)."""
    global _EYE_CASCADE
    roi_color = img[fy:fy + fh, fx:fx + fw]
    roi_gray = gray[fy:fy + fh, fx:fx + fw]
    if roi_color.size == 0 or roi_gray.size == 0:
        return False
    ycrcb = cv2.cvtColor(roi_color, cv2.COLOR_BGR2YCrCb)
    cr, cb = ycrcb[:, :, 1], ycrcb[:, :, 2]
    skin_frac = float(((cr >= 133) & (cr <= 173) & (cb >= 77) & (cb <= 127)).mean())
    if skin_frac < FACE_SKIN_FRAC_MIN:
        return False
    if _EYE_CASCADE is None:
        _EYE_CASCADE = cv2.CascadeClassifier(cv2.data.haarcascades + "haarcascade_eye.xml")
    min_eye = max(8, int(min(fw, fh) * FACE_EYE_MIN_SIZE_FRAC))
    eyes = _EYE_CASCADE.detectMultiScale(roi_gray, scaleFactor=1.1, minNeighbors=4,
                                          minSize=(min_eye, min_eye))
    return len(eyes) >= 1


SKIN_STATS_MIN_FRAC = 0.04   # доля кадра — ниже считаем "кожи в кадре нет" (рука в углу и т.п. уже проходит)


def skin_tone_stats(photo_path):
    """(skin_fraction, mean_skin_rgb_0_1_or_None) — та же YCrCb skin-tone
    эвристика, что _face_region_plausible() (см. её докстринг), но по
    ВСЕМУ кадру, а не только внутри уже найденного каскадом "лица".

    Зачем отдельно от has_face: has_face=False (нет каскад-лица) СЕГОДНЯ
    означает "Look Management коррекция применяется без единой проверки
    кожи вообще" — рука, держащая меч, плечо, любой частичный человеческий
    силуэт без лица в кадре (в этой нише — редкий, но реальный случай)
    раньше был так же беззащитен, как сам клинок. Это отдельный, ДО этого
    непокрытый сигнал (см. look_reference._skin_gains_stay_in_corridor) —
    не замена has_face, а его дополнение для случая "кожа есть, лица нет".

    None/cv2 недоступен/сигнала недостаточно -> (frac, None) — честный
    откат, коррекция ведёт себя как раньше (сигнала кожи просто не видно)."""
    if not PARALLAX_LIBS:
        return 0.0, None
    try:
        img = cv2.imread(photo_path)
        if img is None:
            return 0.0, None
        ycrcb = cv2.cvtColor(img, cv2.COLOR_BGR2YCrCb)
        cr, cb = ycrcb[:, :, 1], ycrcb[:, :, 2]
        mask = (cr >= 133) & (cr <= 173) & (cb >= 77) & (cb <= 127)
        frac = float(mask.mean())
        if frac < SKIN_STATS_MIN_FRAC:
            return frac, None
        mean_bgr = img[mask].mean(axis=0)
        mean_rgb = (float(mean_bgr[2]) / 255.0, float(mean_bgr[1]) / 255.0, float(mean_bgr[0]) / 255.0)
        return frac, mean_rgb
    except Exception:
        return 0.0, None


def detect_face_anchor(photo_path):
    """Anchor-aware crop: раньше кроп под кадр 16:9 всегда бил ровно по
    центру исходного фото (increase+crop без смещения) — на портретных или
    непропорциональных стоковых кадрах это регулярно подрезало лицо/голову
    сверху или сбоку. Лёгкий локальный Haar-детектор (OpenCV, бесплатно,
    уже используется для параллакса — новых зависимостей и денег не стоит)
    ищет самое крупное лицо и возвращает точку привязки (fraction 0..1 по
    ширине/высоте ОРИГИНАЛА, чуть выше центра лица — глаза, не подбородок).
    Лицо не найдено/cv2 недоступен/фото не про людей (оружие, пейзаж) —
    возвращает None, и вызывающий код падает обратно на старый центр-кроп
    (то же поведение, что было всегда) — чистое дополнение без регрессии.

    Найденный каскадом регион ДОПОЛНИТЕЛЬНО проверяется _face_region_
    plausible() (skin-tone + вложенный eye-каскад) — см. её докстринг,
    реальный false-positive baг, пойманный на жалобе "меч всё ещё
    холодно выглядит"."""
    if not PARALLAX_LIBS:
        return None
    global _FACE_CASCADE
    try:
        if _FACE_CASCADE is None:
            _FACE_CASCADE = cv2.CascadeClassifier(
                cv2.data.haarcascades + "haarcascade_frontalface_default.xml")
        img = cv2.imread(photo_path)
        if img is None:
            return None
        gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
        h, w = gray.shape[:2]
        min_side = int(min(w, h) * 0.08)
        faces = _FACE_CASCADE.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5,
                                                minSize=(min_side, min_side))
        if len(faces) == 0:
            return None
        fx, fy, fw, fh = max(faces, key=lambda f: f[2] * f[3])
        if not _face_region_plausible(img, gray, fx, fy, fw, fh):
            return None
        return ((fx + fw / 2) / w, (fy + fh * 0.35) / h)
    except Exception:
        return None


def spectral_saliency_anchor(photo_path, confidence_z=2.2):
    """Anchor-кроп по лицу (detect_face_anchor) покрывает ~10% кадров этого
    канала — остальное оружие/доспехи/предметы без единого лица в кадре, для
    них anchor всегда был None (центр-кроп). Saliency (spectral residual,
    Hou & Zhang 2007) — общий детектор "главного объекта" без лиц.

    Взял именно spectral residual, а не сырую плотность градиента/контраста
    (как estimate_busyness) — по конкретной причине: у сырого градиента
    текстурный ФОН (шершавый камень, кольчуга) часто даёт БОЛЬШЕ локального
    контраста, чем гладкий клинок на переднем плане — anchor утянуло бы к
    фону, кроп стал бы ХУЖЕ центрального, не лучше. Spectral residual вместо
    этого ищет то, что СТАТИСТИЧЕСКИ необычно относительно частотного
    профиля всего кадра — повторяющаяся текстура (камень, кольчуга) даёт
    низкий остаток именно потому, что она регулярна, один явный объект на
    таком фоне даёт пик. Чистый numpy (FFT) — cv2.saliency живёт только в
    opencv-contrib, которого нет в запиненном пакете (тот же класс промаха,
    что уже был с CascadeClassifier в этой сессии — не повторяем).

    ПОРОГ УВЕРЕННОСТИ (confidence_z): возвращаем anchor, только если пик
    saliency-карты заметно (z-score >= confidence_z) выше среднего уровня
    шума карты — на плоских/симметричных кадрах (широкий пейзаж, ткань)
    saliency не выражена вообще, и НАВЯЗЫВАТЬ смещение кропа туда, где нет
    реального сигнала, опаснее, чем оставить центр (см. критика раньше в
    этой же сессии). Слабый/отсутствующий пик -> None, откат на центр —
    то же safety-поведение, что и у detect_face_anchor."""
    if np is None:
        return None
    try:
        H, W = 36, 64
        img = PILImage.open(photo_path).convert("L").resize((W, H), PILImage.LANCZOS)
        gray = np.asarray(img, dtype=np.float64)
        # FFT считает кадр периодическим "по кругу" — резкий разрыв между
        # правым/левым и верхним/нижним краем сам создаёт ложную высокочастотную
        # "границу", которую spectral residual принимает за объект. Поймано
        # вживую на реальных фото канала: пик СИСТЕМАТИЧЕСКИ садился в первую
        # строку кадра (0/36) почти на каждом кадре — не совпадение, артефакт.
        # Окно Ханна плавно гасит яркость к краям перед FFT — убирает разрыв.
        win = np.outer(np.hanning(H), np.hanning(W))
        fft = np.fft.fft2(gray * win)
        amp = np.abs(fft)
        log_amp = np.log(amp + 1e-8)
        phase = np.angle(fft)
        kernel = np.ones((3, 3)) / 9.0
        avg_log_amp = _convolve2d_same(log_amp, kernel)
        residual = log_amp - avg_log_amp
        sal = np.abs(np.fft.ifft2(np.exp(residual + 1j * phase))) ** 2
        sal = _convolve2d_same(sal, np.ones((3, 3)) / 9.0)   # лёгкое сглаживание карты
        # Даже с окном Ханна самый край карты остаётся наименее надёжным —
        # исключаем внешнюю кайму из поиска пика (реальный объект в кадре
        # у стокового фотографа почти никогда не приклеен к самому краю).
        my, mx = max(1, H // 8), max(1, W // 8)
        interior = sal[my:H - my, mx:W - mx]
        if interior.size == 0:
            return None
        mean, std = float(sal.mean()), float(sal.std())
        # Верхний потолок на mean — поймано вживую: на ПОЧТИ однородном кадре
        # (плоский цвет/градиент без реальной текстуры) окно Ханна само по
        # себе создаёт плавный "холм" яркости, который residual-математика
        # принимает за огромный ложный пик (mean взлетает на 2-3 порядка
        # выше любого реального фото — проверено на 12 реальных кадрах
        # канала: 0.0005-0.00065, и на синтетическом плоском/градиентном
        # тесте: 0.33-0.74). Порог 0.02 — с большим запасом выше реальных
        # фото и с большим запасом ниже вырожденного случая.
        if std < 1e-9 or mean > 0.02:
            return None
        peak_idx = np.unravel_index(np.argmax(interior), interior.shape)
        z = (interior[peak_idx] - mean) / std
        if z < confidence_z:
            return None
        py, px = peak_idx[0] + my, peak_idx[1] + mx
        return ((px + 0.5) / W, (py + 0.5) / H)
    except Exception:
        return None


def _convolve2d_same(arr, kernel):
    """Мини-свёртка без scipy (не тянуть отдельную зависимость ради одной
    функции) — 'same'-паддинг через edge-repeat, реализация в лоб на
    маленькой (64x36) карте, скорость тут не критична."""
    kh, kw = kernel.shape
    ph, pw = kh // 2, kw // 2
    padded = np.pad(arr, ((ph, ph), (pw, pw)), mode="edge")
    out = np.zeros_like(arr)
    for i in range(kh):
        for j in range(kw):
            out += kernel[i, j] * padded[i:i + arr.shape[0], j:j + arr.shape[1]]
    return out


def resolve_crop_anchor(photo_path):
    """Единая точка входа для anchor-кропа: лицо приоритетнее (выше точность,
    когда сработало), saliency — общий фоллбэк для кадров без лиц (оружие/
    доспехи/предметы, большинство кадров этого канала). Ни один сигнал не
    найден -> None, старый центр-кроп (ноль регрессии по построению)."""
    anchor = detect_face_anchor(photo_path)
    if anchor is not None:
        return anchor
    return spectral_saliency_anchor(photo_path)


def compute_crop_offset(iw, ih, cw, ch, anchor=None):
    """increase+crop геометрия (та же, что раньше делал ffmpeg force_original_
    aspect_ratio=increase сам, без смещения) — теперь считается в Python, чтобы
    можно было подставить anchor вместо жёсткого центра. anchor=None -> тот же
    центр-кроп, что был всегда (0 изменений в дефолтном поведении)."""
    scale = max(cw / iw, ch / ih)
    nw, nh = max(cw, round(iw * scale)), max(ch, round(ih * scale))
    if anchor:
        ax, ay = anchor
        cx, cy = ax * nw, ay * nh
        x0 = int(min(max(cx - cw / 2, 0), nw - cw))
        y0 = int(min(max(cy - ch / 2, 0), nh - ch))
    else:
        x0, y0 = (nw - cw) // 2, (nh - ch) // 2
    return nw, nh, x0, y0


SHOT_SIZES = ("wide", "medium", "close", "detail")


@memoize_by_frame
def estimate_shot_size(photo_path):
    """Четвёртая ось грамматики кадра (после функции блока) — масштаб
    плана: wide/medium/close/detail. Профессиональный монтаж постоянно
    МЕНЯЕТ масштаб визуальной информации между соседними кадрами; без
    этого сигнала пайплайн может случайно поставить подряд несколько
    общих или несколько крупных планов — по отдельности каждый кадр
    подобран хорошо, но подряд это читается как монотонность.

    Сигналы — все уже дешёвые и частично считаются в пайплайне для
    других целей, новой модели не тянем:
    1. Лицо и его относительный размер (Haar, уже есть для anchor-кропа)
       — самый надёжный сигнал, когда сработал.
    2. Плотность локального контраста (estimate_busyness) — тесный/
       текстурный кадр (макро металла, гравировка) даёт много перепадов
       на пиксель, просторный — мало.
    3. Уверенность spectral saliency — резкий узкий пик на спокойном
       фоне типичен для предметной съёмки крупным/средним планом
       (студийный сток), отсутствие пика — открытая сцена."""
    if PARALLAX_LIBS:
        try:
            global _FACE_CASCADE
            if _FACE_CASCADE is None:
                _FACE_CASCADE = cv2.CascadeClassifier(
                    cv2.data.haarcascades + "haarcascade_frontalface_default.xml")
            img = cv2.imread(photo_path)
            if img is not None:
                gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
                h, w = gray.shape[:2]
                min_side = int(min(w, h) * 0.08)
                faces = _FACE_CASCADE.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5,
                                                        minSize=(min_side, min_side))
                if len(faces) > 0:
                    fx, fy, fw, fh = max(faces, key=lambda f: f[2] * f[3])
                    face_frac = (fw * fh) / (w * h)
                    if face_frac > 0.06:
                        return "close"
                    if face_frac > 0.015:
                        return "medium"
                    return "wide"
        except Exception:
            pass
    busy = estimate_busyness(photo_path)
    if busy > 0.62:
        return "detail"
    if spectral_saliency_anchor(photo_path) is not None:
        return "medium"
    return "wide"


MOTION_MODES = ("classic_kb", "static_hold", "snap_push", "slow_pull",
                 "horizontal_pan", "micro_drift")


def choose_motion_mode(b, is_section_start, photo_hash, shot_size=None):
    """Все кадры "дышат" одним и тем же классом движения (smoothstep
    zoom+pan) — фирменный почерк автослайдшоу, даже с anti-repeat на
    выборе направления. Профессиональный монтаж чередует статику, быстрый
    push-in, медленный pull-out, чистую панораму, едва заметный дрифт.
    Выбор — по ФУНКЦИИ блока в первую очередь: цифра должна читаться (не
    ехать), reveal-кадр раздела — медленный отъезд, sub-cut деталь —
    почти неподвижна (не тянет внимание с главного кадра фразы).

    shot_size (см. estimate_shot_size) — вторая, более тонкая поправка
    ПОВЕРХ выбора по функции, не вместо него: широкий план (простор,
    открытая сцена) естественнее смотрится с панорамой/медленным отъездом,
    крупный/деталь — с едва заметным дрифтом или статикой (быстрый зум на
    и без того тесном кадре съедает сам объект). Дешёвая эвристика вместо
    отдельного классификатора "портрет/архитектура/пейзаж" — используем
    уже посчитанный сигнал, а не тянем новую модель ради категорий."""
    if b.get("stat"):
        return "static_hold"
    if is_section_start:
        return "slow_pull"
    if b["section"].startswith("HOOK"):
        return "snap_push" if (photo_hash & 2) else "classic_kb"
    if b.get("is_subcut"):
        if shot_size in ("close", "detail"):
            return "micro_drift"
        return "micro_drift" if (photo_hash & 4) else "static_hold"
    if shot_size == "wide":
        return "horizontal_pan" if (photo_hash & 1) else "slow_pull"
    if shot_size in ("close", "detail"):
        return "micro_drift" if (photo_hash & 1) else "static_hold"
    return "horizontal_pan" if (photo_hash % 7 == 0) else "classic_kb"


def classify_shot_function(b, is_section_start):
    """Грубая, но дешёвая категоризация "зачем этот кадр" — evidence (цифра-
    доказательство), context (reveal раздела), detail (sub-cut деталь одной
    фразы), hook (энергия хука), narrative (обычное повествование)."""
    if b.get("stat"):
        return "evidence"
    if b.get("is_subcut"):
        return "detail"
    if is_section_start:
        return "context"
    if b["section"].startswith("HOOK"):
        return "hook"
    return "narrative"


def is_parallax_highlight(b, is_section_start):
    """Заслуживает ли этот кадр дорогого 2.5D-параллакса (см. вызов в main()
    рядом с PARALLAX_ENABLED) — хук целиком, первый кадр раздела ("открывашка")
    или момент [climax] ("что-то важное" по прямому запросу пользователя,
    17-28-минутные ролики — параллакс на весь хронометраж был бы часами
    рендера, но точечно на разоблачение — та же цена, что уже платится за
    открывашки разделов). Не новый сигнал — та же разметка is_climax, что
    уже двигает reveal_hold в speech_planner.py и climax dip в музыке."""
    return (b["section"].startswith("HOOK") or is_section_start
            or b.get("is_climax", False))


def _srt_timestamp(t):
    t = max(0.0, t)
    ms_total = int(round(t * 1000))
    h, rem = divmod(ms_total, 3600000)
    m, rem = divmod(rem, 60000)
    s, ms = divmod(rem, 1000)
    return f"{h:02d}:{m:02d}:{s:02d},{ms:03d}"


SRT_MAX_LINE_CHARS = 42   # реальный, задокументированный стандарт индустрии субтитров
                           # (Netflix/BBC-класс гайдлайнов, ~40-42 символа/строка — читаемо
                           # без движения глаз поперёк всего экрана)
SRT_MAX_LINES = 2   # тот же стандарт — больше 2 строк одновременно закрывает кадр


def _wrap_caption_text(text, max_line_chars=SRT_MAX_LINE_CHARS, max_lines=SRT_MAX_LINES):
    """Перенос ОДНОГО SRT-cue на строки по РЕАЛЬНЫМ границам слов, не более
    max_lines строк — задокументированный стандарт субтитрирования (см.
    CLAUDE.md/коммит про GSA/CU Boulder captioning guidelines): короткие
    читаемые строки, разрыв по словам, никогда посередине слова.

    Не пытается влезть в max_lines любой ценой — блок, для которого даже
    после max_lines строк остаётся текст, честно дописывает остаток В
    ПОСЛЕДНЮЮ строку (длиннее стандарта, но ничего не обрезается и не
    теряется молча) — слишком длинный для 2 строк блок сценария сам по
    себе повод пересмотреть длину блока выше по пайплайну, не что чинить
    здесь угадыванием, где резать смысл."""
    words = text.split()
    if not words:
        return text
    lines, idx = [], 0
    while idx < len(words) and len(lines) < max_lines:
        cur = words[idx]
        idx += 1
        while idx < len(words):
            candidate = f"{cur} {words[idx]}"
            if len(candidate) > max_line_chars:
                break
            cur = candidate
            idx += 1
        lines.append(cur)
    if idx < len(words):
        lines[-1] = lines[-1] + " " + " ".join(words[idx:])
    return "\n".join(lines)


def write_subtitles(video_dir, blocks, starts, durs, real_weights=None):
    """SRT — бесплатный побочный продукт уже посчитанного тайминга: реальный
    посимвольный alignment.csv (см. load_alignment_weights) уже участвует в
    расчёте durs/starts, отдельно парсить CSV второй раз не нужно. starts —
    РЕАЛЬНОЕ аудио-время (block_durations по total, не по раздутой под xfade
    target — та же модель, что уже использует energy_pace_multipliers для
    сэмплинга кривой громкости, см. main()), иначе субтитры разъехались бы
    с озвучкой на сумму xfade-нахлёстов к концу ролика.

    Один блок = один субтитр-кадр: текст уже чистый (теги вырезаны в
    parse_blocks), деления и так на границах пауз/фраз — не нужно заново
    резать по 5-7 слов, разбивка уже смысловая.

    Видимое окно субтитра НЕ включает хвостовую паузу блока (2.7, тот же
    класс бага, что уже чинили в load_hook_word_timings): durs[i] —
    ПОЛНОЕ окно блока, block_durations() прибавляет b["pause_after"] к весу
    ДО floor/cap/глобального scale, так что субтитр держался бы на экране
    почти всю следующую паузу — визуально текст "отстаёт" от голоса на
    тишине. real_weights (если есть) даёт долю паузы в исходном сыром весе
    блока — она инвариантна к равномерному масштабированию, обрезаем ею
    durs[i] перед показом. Без real_weights (старый вызов/фоллбэк) — как
    раньше, полное окно."""
    path = os.path.join(video_dir, "subtitles.srt")
    lines = []
    n = 0
    for i, (b, s, d) in enumerate(zip(blocks, starts, durs)):
        text = b["text"].strip()
        if not text:
            continue
        text = _wrap_caption_text(text)
        pause_after = b.get("pause_after") or 0.0
        w = real_weights[i] if (real_weights and i < len(real_weights) and real_weights[i]) else None
        visible_d = d * (1.0 - pause_after / (w + pause_after)) if (pause_after > 0 and w) else d
        n += 1
        lines.append(str(n))
        lines.append(f"{_srt_timestamp(s)} --> {_srt_timestamp(s + max(visible_d, 0.3))}")
        lines.append(text)
        lines.append("")
    open(path, "w", encoding="utf-8").write("\n".join(lines))
    return path


def write_chapters(video_dir, blocks, starts):
    """Список глав для описания YouTube — из уже известных границ секций
    (section_title()) и их реального старта в аудио (starts, см.
    write_subtitles). YouTube требует первую главу строго с 00:00 и минимум
    3 главы от 10с каждая, иначе не активирует таймлайн — это проверяется
    руками при вставке в описание, здесь только честный расчёт таймингов."""
    path = os.path.join(video_dir, "chapters.txt")
    seen, lines = set(), []
    for b, s in zip(blocks, starts):
        if b["section"] in seen:
            continue
        seen.add(b["section"])
        label = section_title(b["section"])
        if label is None:
            label = "Хук" if b["section"].startswith("HOOK") else (
                "Итоги" if b["section"].startswith("FINAL") else b["section"])
        # Заголовки блоков в script.txt пишутся КАПСОМ для видимости внутри
        # сценария (не для показа зрителю) — в реальном описании YouTube это
        # читается как крик. Трогаем только то, что ЦЕЛИКОМ капс — намеренно
        # смешанный регистр не портим.
        if label.isupper():
            label = label[0] + label[1:].lower()
        t = max(0.0, s)
        h, rem = divmod(int(t), 3600)
        m, sec = divmod(rem, 60)
        ts = f"{h}:{m:02d}:{sec:02d}" if h else f"{m}:{sec:02d}"
        lines.append(f"{ts} {label}")
    open(path, "w", encoding="utf-8").write("\n".join(lines) + "\n")
    return path


def write_shot_manifest(video_dir, blocks, durs, queries):
    """3.4: JSON-манифест по клипу — что это за кадр (function/motion_mode/
    запрос), не только "какая картинка досталась по номеру". Раньше связь
    блок->медиа была неявной, проверить "не стоят ли 5 context-кадров
    подряд" можно было только глазами по всему готовому рендеру. Манифест —
    читаемая опора для Шага 7.5 визуальной QC-проверки (CLAUDE.md), не
    отдельная фича ради фичи — сразу печатает подсказку о длинных пробегах
    одной функции подряд, чтобы не читать весь JSON руками, если паттерн
    уже виден невооружённым глазом.

    motion_mode_estimate тут ПРИБЛИЗИТЕЛЬНЫЙ — по хэшу текста блока, не
    реального файла фото (тот известен только во время рендера, здесь мы
    ещё даже не знаем, какая картинка достанется). Для обзорной QC-опоры
    точность до бита не нужна — расхождение возможно только на редких
    hash-tie-break внутри HOOK/обычных блоков (snap_push/classic_kb,
    horizontal_pan/classic_kb)."""
    entries = []
    for i, (b, d) in enumerate(zip(blocks, durs)):
        is_section_start = i == 0 or blocks[i]["section"] != blocks[i - 1]["section"]
        h = int(hashlib.md5(b["text"][:40].encode()).hexdigest()[:8], 16)
        mode = choose_motion_mode(b, is_section_start, h)
        section_slug = re.sub(r'[^A-Za-z0-9]+', '_', b["section"])[:24].strip('_')
        entries.append({
            "shot_id": f"{i:03d}_{section_slug}",
            "index": i,
            "section": b["section"],
            "duration_sec": round(d, 2),
            "function": classify_shot_function(b, is_section_start),
            "motion_mode_estimate": mode,
            "is_subcut": bool(b.get("is_subcut")),
            "has_stat": bool(b.get("stat")),
            "query": queries[i],
            "text_preview": b["text"][:60],
        })
    path = os.path.join(video_dir, "media_plan", "shot_manifest.json")
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(entries, f, ensure_ascii=False, indent=1)
    run_func, run_len, warn = None, 0, []
    for e in entries:
        if e["function"] == run_func:
            run_len += 1
        else:
            run_func, run_len = e["function"], 1
        if run_len == 5:
            warn.append(f"{run_func}@{e['index']-4}-{e['index']}")
    if warn:
        print(f"  Shot manifest: пробеги одной функции подряд (>=5) — {warn}")
    return path


WOBBLE_AMP_CANVAS_PX = 6.0   # ~1.4px в итоговом 1920-кадре (канва 8000px) — см. kenburns()
FREEZE_HOLD_DUR = 0.35       # секунд остановки движения перед stat-плашкой — см. kenburns()
# Адаптивный холст для kenburns() (по умолчанию ВЫКЛЮЧЕН — байт-в-байт
# старое поведение с фиксированными 8000x4500). Реальный, измеренный вживую
# (01_ves-mecha, ночь 31 авг/1 сен) остаток времени клипа, не объяснённый
# ни одной ML-моделью — zoompan однопоточен, его стоимость на кадр растёт
# вместе с разрешением холста, а 8000x4500 (36 Мп) апскейлит ЛЮБОЕ фото
# (реальные Pexels large2x — ~1880px по длинной стороне, проверено ffprobe
# на 54 закэшированных файлах эпизода) в 4+ раза больше, чем нужно.
# KENBURNS_CANVAS_MARGIN выведен из уже существующих в kenburns() констант
# зума (не с потолка): максимально возможный zoom = ZOOM_FLOOR (1.04) +
# ZOOM_DELTA_MAX (0.22) = 1.26 — то есть холст шириной WIDTH*1.26 уже
# достаточен, чтобы на пике зума кроп-окно (canvas/zoom) не апскейлилось
# при финальном ресайзе в WIDTHxHEIGHT. 1.5 — тот же запас, что уже
# ПРОВЕРЕН В ПРОДЕ на самых заметных кадрах ролика (хук/climax/начало
# разделов) — см. PARALLAX_MARGIN/fill_crop_canvas() ниже, тот же принцип,
# независимо выведенное число оказалось близко (1.26 нужно, 1.5 даёт
# честный запас на панораму/округление/anchor-кроп).
KENBURNS_ADAPTIVE_CANVAS = os.environ.get("KENBURNS_ADAPTIVE_CANVAS", "0") != "0"
KENBURNS_CANVAS_MARGIN = 1.5


def _kenburns_canvas_size():
    """(ширина, высота) рабочего холста kenburns() ДО crop/zoompan. Вынесена
    отдельной чистой функцией ради юнит-теста — сама по себе ни на что не
    влияет, флаг читается в момент вызова (не на импорте), см. тесты
    monkeypatch KENBURNS_ADAPTIVE_CANVAS."""
    if not KENBURNS_ADAPTIVE_CANVAS:
        return 8000, 4500
    return round(WIDTH * KENBURNS_CANVAS_MARGIN), round(HEIGHT * KENBURNS_CANVAS_MARGIN)


def piecewise_ease_expr(t_expr, points):
    """Составная (multi-phase) траектория вместо одной гладкой кривой на
    весь клип — "push → micro-pan → settle" или "pull → reveal → hold"
    вместо равномерного smoothstep от начала до конца. points — контрольные
    точки [(0.0,0.0), ..., (1.0,1.0)] по возрастанию t; между соседними
    точками — НЕЗАВИСИМЫЙ smoothstep (гладкая скорость на стыке фаз, не
    рывок при переходе между ними, а не кусочно-линейная ломаная).
    Возвращает строку ffmpeg-eval выражения, t_expr — переменная времени
    0..1 (обычно on/frames)."""
    expr = f"{points[-1][1]:.4f}"
    for i in range(len(points) - 1, 0, -1):
        t0, v0 = points[i - 1]
        t1, v1 = points[i]
        local = f"(({t_expr}-{t0:.4f})/{(t1 - t0):.4f})"
        smooth = f"(3*pow({local},2)-2*pow({local},3))"
        seg_val = f"({v0:.4f}+{(v1 - v0):.4f}*{smooth})"
        expr = f"if(lt({t_expr}\\,{t1:.4f})\\,{seg_val}\\,{expr})"
    return expr


def render_tmp_path(out):
    """Промежуточный путь для АТОМАРНОЙ записи клипа — рендерим сюда, потом
    os.replace() в финальный `out` ТОЛЬКО при успехе (см. finalize_render()).
    Без этого убитый процесс (SIGKILL/OOM/обрыв контейнера — ровно так один
    раз уже падал многочасовой фоновый рендер без единой строчки трейсбека)
    посреди записи оставляет ОБРЕЗАННЫЙ mp4 ровно по пути, который кэш
    main() (простая проверка os.path.exists(out)) на следующем запуске
    молча считает валидным готовым клипом — порченый кадр всплыл бы только
    на сборке/просмотре готового ролика, не в момент самого рендера."""
    return out + ".partial.mp4"


def finalize_render(tmp, out, ok):
    """Переименовать tmp -> out атомарно при успехе; подчистить огрызок при
    провале — см. render_tmp_path(). os.replace — атомарная операция на
    одной файловой системе (tmp и out всегда в одной папке), не "скопировать
    и удалить" — на успешном пути либо всего файла целиком не существует,
    либо он полностью готов, никакого промежуточного полу-состояния."""
    if ok and os.path.exists(tmp):
        os.replace(tmp, out)
        return True
    if os.path.exists(tmp):
        try:
            os.remove(tmp)
        except OSError:
            pass
    return False


# --- Отказоустойчивый рендер клипа: код возврата ffmpeg сам по себе НЕ
# гарантирует, что записанный файл реально того же качества/длины, что
# заказано (редкий, но реальный класс сбоя — процесс отчитался успехом на
# усечённом/битом выводе). verify_clip() — независимая от кода возврата
# проверка через ffprobe; run_ffmpeg_with_retry() — несколько попыток одной
# и той же команды с верификацией после каждой, транзиентный сбой (диск,
# память, гонка) часто не повторяется на следующей попытке.
CLIP_VERIFY_TOLERANCE_SEC = 0.25   # допуск между заказанной и фактической длительностью клипа
RENDER_RETRY_ATTEMPTS = max(1, int(os.environ.get("RENDER_RETRY_ATTEMPTS", "3")))
RENDER_RETRY_BACKOFF_SEC = 1.5


def render_timeout_sec(dur):
    """Таймаут на ОДНУ попытку рендера клипа длительностью dur секунд.
    РЕАЛЬНЫЙ, пойманный вживую при разработке этого модуля случай: ffmpeg
    `-loop 1 -i <битый/усечённый файл>` не падает с ошибкой декода — он
    ВИСНЕТ БЕСКОНЕЧНО (проверено напрямую: процесс пришлось убивать по
    внешнему timeout, ни строчки вывода за 10+ секунд). Без явного таймаута
    ретрай вообще не срабатывает — первая же попытка никогда не возвращает
    управление, чтобы её можно было повторить.
    Плоский пол 30с ("15x реального времени клипа") оказался НЕВЕРНЫМ на
    практике: под реальной нагрузкой пула воркеров (RENDER_POOL_WORKERS,
    несколько ffmpeg с тяжёлым filter_complex — scale до 8000x4500, gblur,
    deband, unsharp — одновременно; -threads 1 ограничивает только
    энкодер, НЕ фильтр-граф — filter_complex_threads отдельный флаг, тоже
    не выставлен) короткие (~1-2с) под-катные клипы ловили ложный таймаут
    под реальным контеншном. Плоский подъём пола (проверено: 180с) чинил
    это, но ломал другую сторону — тест на реальное бесконечное
    зависание (битый файл, RENDER_PARALLEL=0, один воркер, contention=1)
    честно ждал все 180с на одну заведомо безнадёжную попытку вместо
    прежних быстрых 30с. Обе цифры были правильными каждая для своего
    сценария — но врозь, не как одна константа. Правильный сигнал уже
    существует в коде: RENDER_POOL_ENABLED/RENDER_POOL_WORKERS. Пол
    масштabируется контеншном пула, а не берётся с потолка одним числом
    для всех режимов: при выключенном пуле (RENDER_PARALLEL=0, как в
    последовательном рендере) contention=1 -> те же 30с, что и были
    (не трогаем то, что уже подтверждено рабочим); при N воркерах в
    пуле — 30с*N, тот же принцип, которым уже руководствуется
    _default_render_workers() (нагрузка растёт вместе с числом
    параллельных ffmpeg). Проверено вживую на 4-ядерной машине с
    RENDER_POOL_WORKERS=3 (90с пол) — реальный прогон 4 клипов проходит
    с первой попытки на каждый клип, суммарно на весь пул 73.8с.

    РЕАЛЬНЫЙ пойманный вживую пробел (не гипотеза): формула выше учитывает
    ТОЛЬКО contention от RENDER_POOL_WORKERS — но parallax_kenburns()
    (2.5D-параллакс на highlight-кадрах, см. is_parallax_highlight())
    всегда выполняется ПОСЛЕДОВАТЕЛЬНО в главном процессе, а не в пуле, и
    сам по себе тяжёлый ffmpeg-энкод (тот же дорогой film_look() с
    gblur=14 bloom-эффектом, что и у остальных клипов). Пока он идёт,
    реальное число одновременных тяжёлых ffmpeg-процессов на машине —
    RENDER_POOL_WORKERS ИЗ ПУЛА плюс ЕЩЁ ОДИН в главном процессе, а
    формула этого не считала. На 4-ядерной песочнице поймано вживую:
    изолированный (без конкуренции) прогон тяжёлого клипа — 112-224с,
    под реальной нагрузкой пула — таймаут на ровно той же цифре, что
    выдавала формула (contention=3 -> ~418-429с), 3 попытки подряд.
    +1 к contention — честный запас именно под эту, ранее не посчитанную
    добавку от параллакса, не гадание с потолка."""
    contention = (RENDER_POOL_WORKERS + 1) if RENDER_POOL_ENABLED else 1
    return max(30 * contention, dur * 15 * contention)


def verify_clip(path, expected_dur, tolerance=CLIP_VERIFY_TOLERANCE_SEC):
    """ffprobe-верификация уже отрендеренного клипа — единственный источник
    правды о том, что реально записано на диск, независимый от кода
    возврата ffmpeg. Возвращает (ok, reason, actual_dur|None)."""
    try:
        r = subprocess.run(["ffprobe", "-v", "quiet", "-print_format", "json",
                            "-show_format", "-show_streams", path],
                           capture_output=True, text=True, timeout=20)
        if r.returncode != 0:
            return False, "ffprobe не смог прочитать файл", None
        data = json.loads(r.stdout)
        if not any(s.get("codec_type") == "video" for s in data.get("streams", [])):
            return False, "в файле нет видеопотока", None
        actual_dur = float(data["format"]["duration"])
        if actual_dur < max(0.1, expected_dur - tolerance):
            return False, f"длительность {actual_dur:.2f}с короче заказанной {expected_dur:.2f}с", actual_dur
        return True, "ok", actual_dur
    except Exception as e:
        return False, f"{type(e).__name__}: {e}", None


def _looks_like_drawtext_failure(reason):
    """True — ТОЛЬКО если reason (см. run_ffmpeg_with_retry) реально
    указывает на недоступность drawtext/шрифта (некоторые сборки ffmpeg
    собраны без libfreetype/drawtext вообще — единственный случай, ради
    которого существует откат "рисую без них" у kenburns()/video_render()).

    РЕАЛЬНЫЙ БАГ, найден по жалобе пользователя ("субтитров нет вначале,
    потом резко появляются, рассинхрон") на реальном рендере: откат раньше
    срабатывал на ЛЮБОЙ reason, включая таймаут/OOM/гонку ресурсов —
    транзиентный сбой (в конкретном случае: CPU-контеншн от параллельного
    процесса) ронял ВСЕ попытки WITH-captions рендера по таймауту, код
    трактовал это как "drawtext не работает" и молча перерисовывал клип БЕЗ
    подписей — та версия проще/быстрее и укладывалась в лимит времени, где
    сложная (с подписями) не успевала. Итог на экране: подписи есть не на
    всех клипах хука, без единой строчки в логе, объясняющей почему именно
    эти. Теперь откат без подписей — только когда причина реально об этом
    (drawtext/шрифт), любой другой сбой после исчерпанных попыток — честный
    провал ВСЕГО клипа (тот же путь, что systematic ffmpeg-ошибка), не тихая
    потеря подписей."""
    r = (reason or "").lower()
    return any(sig in r for sig in
               ("drawtext", "fontfile", "font file", "no such filter", "unrecognized option",
                "unable to parse option value", "cannot load default config"))


def run_ffmpeg_with_retry(build_cmd, tmp_out, expected_dur, label=""):
    """Прогоняет build_cmd() (callable без аргументов — каждый вызов строит
    и исполняет НОВУЮ ffmpeg-команду в tmp_out, возвращает CompletedProcess)
    до RENDER_RETRY_ATTEMPTS раз. После КАЖДОГО ненулевого-кода-возврата
    успеха дополнительно проверяет реальный файл через verify_clip() —
    returncode==0 сам по себе недостаточен (см. комментарий у
    CLIP_VERIFY_TOLERANCE_SEC). Систематический сбой (битый вход, кодек)
    повторится тем же образом на всех попытках и честно вернёт (False,
    причина); транзиентный (гонка, нехватка ресурсов в моменте) часто
    лечится самим повтором. Возвращает (ok, reason)."""
    last_reason = "неизвестная ошибка"
    for attempt in range(1, RENDER_RETRY_ATTEMPTS + 1):
        if os.path.exists(tmp_out):
            try:
                os.remove(tmp_out)
            except OSError:
                pass
        try:
            r = build_cmd()
        except subprocess.TimeoutExpired:
            # РЕАЛЬНЫЙ случай, пойманный при разработке (см. render_timeout_sec):
            # ffmpeg на битом/усечённом входе не падает с ошибкой декода —
            # виснет БЕСКОНЕЧНО. Без этого перехвата TimeoutExpired улетел бы
            # наружу и уронил бы весь рендер (или воркер пула), а не дал
            # честное "не получилось, пробуем ещё раз/сдаёмся".
            last_reason = f"таймаут ({render_timeout_sec(expected_dur):.0f}с) — процесс завис"
            r = None
        except Exception as e:
            last_reason = f"{type(e).__name__}: {e}"
            r = None
        if r is None:
            pass   # уже записали last_reason выше
        elif r.returncode != 0:
            stderr_tail = (r.stderr or "")[-200:] if hasattr(r, "stderr") else ""
            last_reason = f"ffmpeg вышел с кодом {r.returncode}: {stderr_tail}"
        else:
            ok, reason, _ = verify_clip(tmp_out, expected_dur)
            if ok:
                if attempt > 1:
                    print(f"  [{label}] ok с {attempt}-й попытки")
                return True, "ok"
            last_reason = reason
        if attempt < RENDER_RETRY_ATTEMPTS:
            print(f"  [{label}] попытка {attempt}/{RENDER_RETRY_ATTEMPTS} не удалась ({last_reason}), повтор...")
            time.sleep(RENDER_RETRY_BACKOFF_SEC)
    return False, last_reason


def atomic_url_download(req, dest, timeout):
    """Тот же принцип, что render_tmp_path/finalize_render, но для скачки
    стокового медиа (pexels_photo/pexels_video) — реальный баг, пойманный
    вживую: обе функции раньше писали ПРЯМО в конечное имя кэша
    (open(cf,"wb").write(r.read())), а кэш-хит на следующий запуск проверял
    только os.path.exists(cf), ничего про размер/целостность. Прерванная
    закачка (обрыв сети/сигнал/OOM — тот же класс сбоя, что уже ловили на
    рендере клипов) оставляет 0-байтный или обрезанный файл ровно под
    "доверенным" именем — молча наступили на это вживую (0072_...mp4,
    0 байт, месяц пролежал в кэше, "непредвиденно" выкинул блок из ролика
    без единой строчки в логе, потому что скачка даже не запускалась
    заново — кэш-хит просто отдал битый файл). Качаем во временный файл,
    переименовываем атомарно только при успехе — как рендер клипов."""
    tmp = dest + ".download.part"
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            with open(tmp, "wb") as f:
                f.write(r.read())
        if os.path.getsize(tmp) == 0:
            raise IOError("скачан 0-байтный файл")
        os.replace(tmp, dest)
        return True
    except Exception:
        if os.path.exists(tmp):
            try:
                os.remove(tmp)
            except OSError:
                pass
        raise


def log_render_diagnostics(tag):
    """Лёгкий след памяти процесса в TEMP_FOLDER/render_diag.log — НЕ для
    рантайма (ни на что не влияет), а на случай СЛЕДУЮЩЕГО непонятного
    обрыва: ровно так уже падал многочасовой фоновый рендер один раз, без
    единой строчки трейсбека (см. render_tmp_path()) — если это снова
    SIGKILL/OOM, в diag-логе будет видно, росла ли память перед смертью,
    а не только "тихо умер, причина неизвестна" во второй раз подряд.
    resource — Linux/macOS; тихий no-op на всём остальном (Windows и т.п.,
    см. CLAUDE.md — пайплайн кросс-платформенный) — диагностика не ценой
    падения самого рендера."""
    try:
        import resource
        rss_mb = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss / 1024
        with open(os.path.join(TEMP_FOLDER, "render_diag.log"), "a", encoding="utf-8") as f:
            f.write(f"{time.strftime('%H:%M:%S')} {tag} peak_rss={rss_mb:.0f}MB\n")
    except Exception:
        pass


def kenburns(photo, out, dur, title=None, zoom_in=None, pan_dir=None, stat=None,
             section="", motion_mode="classic_kb", stat_variant=0,
             brightness_bias=0.0, energy_bias=0.0, stat_delay=0.0, levels=None, wb=None,
             grain_scale=1.0, captions=None, look_filter=None, ffmpeg_threads=None, domain=None):
    frames = max(1, round(dur * FPS))
    # KENBURNS_ADAPTIVE_CANVAS=0 (дефолт) -> ровно 8000x4500, как раньше,
    # байт-в-байт. См. докстринг константы у объявления выше.
    kb_cw, kb_ch = _kenburns_canvas_size()
    h, zoom_in_default, pan_dir_default = kb_hash_choices(photo)
    if zoom_in is None:
        zoom_in = zoom_in_default
    dx, dy = pan_dir if pan_dir is not None else pan_dir_default
    rate_jit = ((h >> 5) % 1000) / 1000.0
    pan_jit = ((h >> 15) % 1000) / 1000.0
    # C6: скорость зума в такт энергии голоса — на эмоциональных пиках речи
    # камера "подбирается" быстрее, на спокойных местах медленнее, тот же
    # energy_bias, что уже модулирует контраст/сатурацию в film_look().
    # Клэмп ZOOM_DELTA_MIN/MAX всё равно применяется ПОСЛЕ — энергия сдвигает
    # в пределах уже безопасного диапазона, не расширяет его.
    energy_zoom_mult = 1.0 + max(-0.5, min(0.5, energy_bias)) * 0.2
    delta = max(ZOOM_DELTA_MIN, min(ZOOM_DELTA_MAX,
                ZOOM_RATE_BASE * dur * (0.75 + rate_jit * 0.5) * energy_zoom_mult))
    # Уже тесный/плотный кадр (крупный план) не нуждается в таком же зуме,
    # как просторный — иначе на кадре и так крупного меча к концу клипа
    # остаётся одна текстура металла, некуда уже приближаться со смыслом.
    busy = estimate_busyness(photo)
    if busy > 0.6:
        delta *= 0.7
    # PAN_SAFETY * jitter всегда < 1.0 (проверено численно) — офсет остаётся
    # строго внутри геометрического запаса (1-1/zoom)/2 на любом кадре клипа.
    pan_amt = PAN_SAFETY * (PAN_JITTER_MIN + pan_jit * (PAN_JITTER_MAX - PAN_JITTER_MIN))
    on_expr = "on"
    # Freeze-hold: короткая остановка движения ПРЯМО ПЕРЕД тем, как
    # появляется stat-плашка (stat_delay — см. main()/add_overlays,
    # тот же момент, синхронизированный с реальной озвучкой числа).
    # Контраст "движение → пауза → цифра" — приём, отличающий монтаж
    # с намерением от бесшовной анимации без акцентов. Замораживаем
    # именно ПЕРЕМЕННУЮ ВРЕМЕНИ (виртуальный "on"), а не сами zoom/pan —
    # эффект автоматически подхватывается ЛЮБЫМ motion_mode без
    # дублирования логики в каждой ветке. Движение после паузы продолжает
    # с того же места, откуда остановилось (не теряет фазу), а не рестартует.
    if stat and stat_delay > 0.5:
        freeze_start_f = max(0, round((stat_delay - FREEZE_HOLD_DUR) * FPS))
        freeze_end_f = round(stat_delay * FPS)
        if freeze_end_f > freeze_start_f:
            on_expr = (f"if(lt(on\\,{freeze_start_f})\\,on\\,"
                       f"if(lt(on\\,{freeze_end_f})\\,{freeze_start_f}\\,"
                       f"on-{freeze_end_f - freeze_start_f}))")
    t = f"({on_expr}/{frames})"
    # smoothstep вместо линейного роста: старт/финиш без рывка — линейный зум
    # это самый узнаваемый штамп шаблонных слайд-шоу.
    eased = f"(3*pow({t},2)-2*pow({t},3))"

    if motion_mode == "static_hold":
        # Цифра должна читаться — кадр не едет вообще. Лёгкий "дышащий" зум
        # (не 1.0 буквально — совсем мёртвый стоп-кадр сам по себе штамп)
        # без пана.
        delta = min(delta, 0.02)
        pan_amt = 0.0
    elif motion_mode == "classic_kb":
        # Multi-phase вместо одной ровной кривой на весь клип: "push →
        # micro-pan → settle" — быстрый ход в первой половине, спокойное
        # продолжение, гладкая остановка перед резом. Одна гладкая кривая
        # от начала до конца — сама по себе узнаваемый штамп "программа
        # анимировала", реальная камера редко держит идеально постоянную
        # скорость до самого конца движения.
        eased = piecewise_ease_expr(t, [(0.0, 0.0), (0.5, 0.72), (0.85, 0.95), (1.0, 1.0)])
    elif motion_mode == "snap_push":
        # Быстрый punch-in за ~0.3с, дальше — hold на максимуме. eased
        # клампится к 1.0 рано (по доле кадров, не по общей длительности —
        # короткий hook-кадр и так короткий).
        snap_frac = min(0.95, max(0.05, 8 / frames))
        eased = f"min(1,{t}/{snap_frac})"
        eased = f"(3*pow({eased},2)-2*pow({eased},3))"
        zoom_in = True
        delta = max(delta, ZOOM_DELTA_MIN * 1.4)
        pan_amt *= 0.4   # пан почти не нужен — внимание на резкость punch-in
    elif motion_mode == "slow_pull":
        # Reveal кадр раздела: стартуем зумленными, спокойно отъезжаем.
        # Без пана — это медленный отъезд, а не комбинация приёмов.
        # Multi-phase: "pull → reveal → hold" — основной отъезд в первой
        # половине-двух третях клипа, дальше движение гасится к спокойному
        # hold перед резом (реальный оператор не продолжает тянуть камеру
        # рывками ровно до конца кадра).
        zoom_in = False
        delta = max(delta, ZOOM_DELTA_MIN * 1.6)
        pan_amt = 0.0
        eased = piecewise_ease_expr(t, [(0.0, 0.0), (0.55, 0.68), (0.85, 0.92), (1.0, 1.0)])
    elif motion_mode == "horizontal_pan":
        # Почти чистая панорама — для длинных объектов (клинки, карты,
        # гравюры). ВАЖНО: offset пана ниже завязан на (1-1/zoom) — растёт
        # ВМЕСТЕ с изменением зума, а не по отдельной шкале времени. При
        # delta=0 (зум строго константа) этот множитель тоже был бы
        # константой — пан физически не двигался бы кадр от кадра (поймано
        # при проверке формулы, не вживую). Держим delta малой, но не
        # нулевой — зум еле заметен, а пан (усиленный) реально едет.
        delta = min(delta, 0.06)
        pan_amt = PAN_SAFETY * 0.95
    elif motion_mode == "micro_drift":
        # Едва заметное движение — не тянет внимание с главного кадра
        # sub-cut-фразы.
        delta = min(delta, 0.03)
        pan_amt = 0.0
    max_zoom = ZOOM_FLOOR + delta
    z = (f"'{ZOOM_FLOOR}+{delta:.5f}*{eased}'" if zoom_in
         else f"'{max_zoom:.5f}-{delta:.5f}*{eased}'")
    # Film weave: математически идеальная smoothstep-кривая зума/пана — сама
    # по себе штамп "отрендерено алгоритмом", у настоящей камеры/плёнки
    # всегда есть микро-дрожь. Низкочастотный синус (не шум per-frame — это
    # выглядело бы как тряска, не имитация плёнки), амплитуда и фаза/период —
    # детерминированно по хэшу фото. Меньше цикла за весь клип (0.6-1.4) —
    # чтобы не читалось как заметное "покачивание туда-сюда".
    # Абсолютное значение в пикселях калибровано под холст 8000px (см.
    # докстринг константы) — масштабируем пропорционально РЕАЛЬНОМУ холсту
    # (kb_cw), иначе при меньшем холсте то же число пикселей — заметно
    # более сильное "дрожание плёнки" относительно кадра. При выключенном
    # KENBURNS_ADAPTIVE_CANVAS kb_cw==8000 -> множитель==1.0, ноль изменений.
    wob_amp = (WOBBLE_AMP_CANVAS_PX * (kb_cw / 8000.0)) * (0.5 if motion_mode == "static_hold" else 1.0)
    wob_px = f"{wob_amp:.2f}*sin(2*PI*(on/{frames})*{0.6 + ((h >> 19) % 100) / 125.0:.3f}+{((h >> 3) % 628) / 100.0:.3f})"
    wob_py = f"{wob_amp:.2f}*sin(2*PI*(on/{frames})*{0.6 + ((h >> 23) % 100) / 125.0:.3f}+{((h >> 11) % 628) / 100.0:.3f})"
    # margin = (1-1/zoom)/2 считается от РЕАЛЬНОГО zoom в текущем кадре (переменная
    # zoompan даёт его сама) — офсет безопасен на любом кадре клипа по построению,
    # а не только к концу движения, как раньше при завязке на delta.
    x = (f"'iw/2-(iw/zoom/2){dx * pan_amt:+.5f}*(1-1/zoom)/2*iw+{wob_px}'" if dx
         else f"'iw/2-(iw/zoom/2)+{wob_px}'")
    y = (f"'ih/2-(ih/zoom/2){dy * pan_amt:+.5f}*(1-1/zoom)/2*ih+{wob_py}'" if dy
         else f"'ih/2-(ih/zoom/2)+{wob_py}'")
    # increase+crop (не decrease+pad) — исходные фото редко ровно 16:9, "вписать
    # в рамку" оставляло чёрные поля по краям на большинстве кадров (проверено:
    # 3 из 8 тестовых кадров с полосами по обеим сторонам). Залить кадр целиком
    # и обрезать лишнее — тот же приём, что уже применялся к видео-стоку ниже.
    # Anchor-aware: кроп бьёт по центру, только если ни лицо, ни saliency
    # не нашли уверенного сигнала (см. resolve_crop_anchor) — иначе
    # смещается так, чтобы не резать голову/главный объект.
    try:
        iw, ih = PILImage.open(photo).size
    except Exception:
        iw, ih = kb_cw, kb_ch
    anchor = resolve_crop_anchor(photo)
    nw, nh, cx0, cy0 = compute_crop_offset(iw, ih, kb_cw, kb_ch, anchor)
    vf_base = (f"scale={nw}:{nh},"
               f"crop={kb_cw}:{kb_ch}:{cx0}:{cy0},setsar=1,"
               f"zoompan=z={z}:x={x}:y={y}:"
               f"d={frames}:s={WIDTH}x{HEIGHT}:fps={FPS},"
               f"{film_look(h, section, brightness_bias, energy_bias, levels, wb, domain)}"
               # Reference-Guided Look Management (см. scripts/look_reference.py) —
               # ДОБАВОЧНЫЙ фрагмент ПОСЛЕ уже готового film_look(), никогда не
               # заменяет его. look_filter=None (фича выключена/lookbook пуст/
               # низкая уверенность/лицо в кадре и т.д.) -> без изменений.
               + (f",{look_filter}" if look_filter else ""))
    vf_overlay = None
    if title or stat or captions:
        vf_overlay = add_overlays(vf_base, dur, title, stat, stat_variant, stat_delay, media_path=photo)
        vf_overlay = add_kinetic_captions(vf_overlay, captions)

    tmp_out = render_tmp_path(out)

    def render(vf):
        cmd = ["ffmpeg", "-y", "-loop", "1", "-i", photo]
        if GRAIN_ENABLED:
            # Зерно — отдельный вход (зацикленный grain_loop.mp4), не строка
            # фильтров — filter_complex вместо -vf, тот же приём, что уже
            # используется для speed ramp/halation embedding.
            cmd += ["-stream_loop", "-1", "-i", GRAIN_LOOP_PATH]
            fc = f"[0:v]{vf}[gr_in];{grain_blend_complex('gr_in', 1, 'vout', grain_scale)}"
            cmd += ["-filter_complex", fc, "-map", "[vout]"]
        else:
            cmd += ["-vf", vf]
        # -frames:v, а НЕ -t: заказ в кадрах — единственная точная единица
        # (столько же кадров, сколько заложено в zoompan d=frames и в
        # тайминг склейки). С -t граница "последний кадр влез/не влез"
        # решалась сравнением дробных секунд, и клип регулярно выходил на
        # один кадр длиннее заказанного — на сотнях клипов эпизода это
        # складывалось в секунды ухода видео от голоса (см.
        # quantize_durations_to_frames). Так же уже работает
        # parallax_kenburns(), путь просто приведён к одному виду.
        cmd += ["-frames:v", str(frames), "-c:v", "libx264", "-preset", RENDER_PRESET,
               "-crf", RENDER_CRF, "-r", str(FPS)] + CLIP_PIX_ARGS + COLOR_META_ARGS
        if ffmpeg_threads:
            cmd += ["-threads", str(ffmpeg_threads)]
        cmd += [tmp_out]
        return subprocess.run(cmd, capture_output=True, text=True, timeout=render_timeout_sec(dur))

    label = os.path.basename(out)
    if vf_overlay:
        ok, reason = run_ffmpeg_with_retry(lambda: render(vf_overlay), tmp_out, dur, label)
        if ok:
            return finalize_render(tmp_out, out, True)
        if not _looks_like_drawtext_failure(reason):
            # См. _looks_like_drawtext_failure — таймаут/OOM/др. транзиентный
            # сбой после исчерпанных попыток НЕ повод тихо терять подписи,
            # это честный провал клипа (main() отправит его в missing/повтор).
            print(f"  [{label}] рендер с подписями не удался ({reason}) — "
                  f"это не про drawtext, не откатываюсь на версию без них")
            return finalize_render(tmp_out, out, False)
        # Титр/плашка (drawtext/шрифт) реально недоступны — не повод терять
        # весь кадр. Откат на версию без них (тоже с ретраем/верификацией).
        print(f"  титр/плашка не встали ({label}): {reason} — рисую без них")
    ok, reason = run_ffmpeg_with_retry(lambda: render(vf_base), tmp_out, dur, label)
    if not ok:
        print(f"  [{label}] рендер не удался после {RENDER_RETRY_ATTEMPTS} попыток: {reason}")
    return finalize_render(tmp_out, out, ok)


# --- 2.5D-параллакс (опционально, нужны torch/transformers/opencv) ---
# Depth-Anything-V2-Small с Hugging Face: по одной фотке строит карту глубины
# (белое — близко, чёрное — далеко), дальше "ближние" пиксели двигаются
# сильнее "дальних" при панорамировании — настоящее ощущение объёма вместо
# плоского зума. GitHub codeload (откуда обычно тянут MiDaS) закрыт сетевой
# политикой (проверено: 403) — huggingface.co открыт, поэтому источник модели
# именно оттуда.
PARALLAX_MARGIN = 1.5     # рабочий холст на 50% больше кадра — запас под
                           # зум+пан+параллакс-смещение без чёрных дыр по краям
PARALLAX_PX_BASE = 55.0   # максимальный доп.разброс между ближним/дальним слоем, px

# ГЕОМЕТРИЧЕСКИЙ бюджет искажения параллакса — прямая, ИЗМЕРЕННАЯ (не на глаз)
# починка жалобы пользователя "артефакты от параллакса сильные, кадр уродуется".
#
# Что реально происходило (измерено, а не предположено). Смещение пикселя в
# parallax_kenburns() пропорционально глубине: extra = (d - 0.5)*parallax_px.
# Значит ЛОКАЛЬНОЕ РАСТЯЖЕНИЕ картинки = parallax_px * |grad d| — там, где
# карта глубины меняется быстро (силуэт предмета на фоне), соседние пиксели
# разъезжаются. На реальном кадре эпизода (щит с мечами на фоне решётки,
# videos/_test20s слот 2) при рабочих parallax_px=90.9 и |grad d| p99=0.0092
# это давало 84% расчётного растяжения, а прямое измерение якобиана поля
# смещения на последнем кадре — 172%. Видно глазом однозначно: прямой прут
# решётки становится изогнутым и раздваивается, гарда меча расплывается в
# мазок (сравнение первого и последнего кадра клипа).
#
# Почему НЕ лечится "просто уменьшить силу": растяжение сосредоточено на
# границах предметов, а глобальное снижение амплитуды убивает эффект на всём
# кадре ради нескольких краёв (пользователь уже жаловался на обратное — что
# параллакс неотличим от обычного Ken Burns, из-за чего нижняя граница
# strength_gain поднималась 0.4 -> 0.6).
#
# Что сделано вместо этого — две независимые ручки:
# 1) Карта глубины ДЛЯ ГЕОМЕТРИИ размывается сильно (PARALLAX_WARP_SIGMA_FRAC),
#    отдельно от карты для DOF/контраста. Резкая карта нужна боке (там край
#    предмета обязан быть чётким — это маска композитинга), геометрии же
#    резкий край вреден: он и есть источник разрыва. Размытие снижает |grad d|
#    примерно в 4-6 раз, НЕ уменьшая диапазон глубины — то есть эффект
#    остаётся, а рвущий градиент исчезает.
# 2) Амплитуда ограничивается ИЗМЕРЕННЫМ на этом конкретном фото градиентом:
#    parallax_px <= PARALLAX_MAX_STRETCH / p99(|grad d|). Это не единая
#    константа "на всех", а гарантия бюджета на каждом кадре.
#
# Калибровка (10 реальных фото двух эпизодов, не синтетика): при sigma_frac
# 0.10 потолок амплитуды выходит 49..128px при рабочих амплитудах 31..91px —
# то есть на большинстве фото ограничитель ВООБЩЕ не срабатывает (эффект в
# полную силу), и срезает только те кадры, которые реально рвались (слот 2:
# 90.9 -> 49.2). Измеренное искажение якобиана на том же кадре: 172% -> 12.9%,
# прутья решётки прямые, гарда целая (проверено просмотром кадров, не только
# числами). Бюджет 0.08 выбран как лучший из проверенных (0.05 — амплитуда
# схлопывается до ~5px, эффекта нет; 0.12 — искажение 19.4%, край уже заметно
# "дышит").
PARALLAX_WARP_SIGMA_FRAC = 0.10   # доля min(холста) — размытие карты глубины ДЛЯ ВАРПА
PARALLAX_MAX_STRETCH = 0.08       # потолок локального растяжения поля смещения (p99)

# Глубина резкости/боке (ЭТАП 1.3 внешнего аудита — реальный пробел, не
# гипотеза: параллакс уже считает depth-карту, но НЕ использует её для
# размытия фона, кадры технически объёмные по движению, но плоские по
# оптике). Дешёвая "poor man's DOF": одна размытая копия холста + линейный
# блендинг по уже посчитанной depth-карте (1=близко=резко, 0=далеко=
# максимальное размытие) — БЕЗ второй модели/скачивания, тот же canvas и
# depth, что уже посчитаны для параллакса. Считается ОДИН раз на холст (не
# на кадр) — размытие фона относительно СЦЕНЫ, не относительно текущего
# вида камеры, оптически корректно и дешевле по CPU.
DOF_ENABLED = os.environ.get("DOF_BLUR", "1") != "0"
DOF_SIGMA_FRAC = 0.014     # сигма размытия фона как доля min(cw, ch) —
                           # относительный, не абсолютный пиксельный размер
                           # (тот же принцип, что sigma в estimate_depth())
DOF_FOCUS_DEPTH = 0.55     # запасной порог на вырожденный случай (пустой
                           # центральный патч) — см. _dof_focus_depth() ниже,
                           # в норме порог адаптивный, не эта константа
DOF_FALLOFF_POWER = 1.4    # >1 — резкость держится дольше около порога,
                           # размытие быстро нарастает у самого дальнего плана
                           # (мягче "стены" на границе фокуса, чем линейный спад)
DOF_FOCUS_DEPTH_FLOOR = 0.05   # защита от деления на ноль в _dof_focus_depth()
                                # и от вырожденного "порог=0" на полностью
                                # плоском/дальнем кадре (см. тест all_far)
# Реальный, найденный вживую баг (27 августа, videos/_test20s, слот 3 —
# HOOK-фото рыцаря на фоне лестницы): DOF_FOCUS_DEPTH был АБСОЛЮТНОЙ
# константой на normalized(0..1) карте, что молча предполагает — главный
# объект кадра всегда лежит у самого ВЕРХА диапазона глубины (ближе всего
# к камере во всём кадре). На этом конкретном фото у главного объекта
# (рыцарь, центр кадра) реальная normalized-глубина оказалась 0.23-0.32 —
# из-за постороннего яркого/резкого элемента в кадре (силуэт слева),
# перетянувшего верх диапазона на себя при min-max нормализации. Порог
# 0.55 в итоге считал САМ ОБЪЕКТ "дальним планом" и размывал его наравне с
# фоном — на готовом рендере это выглядело как "фото ужасно размазано", не
# как боке. Измерено прямо (torso row): blur_weight 0.29-0.60 на пикселях
# главного объекта при фиксированном пороге — заведомо не то же самое, что
# лёгкая мягкость фона.
DOF_FOCUS_CENTER_Y = (0.25, 0.85)   # доля кадра по вертикали для патча "где обычно объект"
DOF_FOCUS_CENTER_X = (0.30, 0.70)   # (тот же композиционный принцип, что центр-кроп
                                     # по умолчанию в compute_crop_offset/detect_face_anchor)


def _dof_focus_depth(depth, h, w):
    """Адаптивный порог фокуса ДЛЯ ЭТОГО конкретного кадра — медиана глубины
    в центральном патче (там, где в этом пайплайне почти всегда находится
    объект интереса — тот же композиционный принцип, что центр-кроп по
    умолчанию). Заменяет фиксированный DOF_FOCUS_DEPTH: реальный главный
    объект кадра размывается по СВОЕЙ фактической глубине, а не по
    предположению "объект всегда у самого верха normalized-диапазона" (см.
    комментарий у DOF_FOCUS_DEPTH выше — это предположение подтверждённо
    ломается на реальных фото). DOF_FOCUS_DEPTH_FLOOR — пол на случай
    вырожденного патча (пустой срез/полностью плоская нулевая глубина, см.
    test_apply_depth_of_field_all_far_blurs_canvas) — без него деление в
    blur_weight ушло бы в 0/0."""
    cy0, cy1 = int(h * DOF_FOCUS_CENTER_Y[0]), int(h * DOF_FOCUS_CENTER_Y[1])
    cx0, cx1 = int(w * DOF_FOCUS_CENTER_X[0]), int(w * DOF_FOCUS_CENTER_X[1])
    patch = depth[cy0:cy1, cx0:cx1]
    focus = float(np.median(patch)) if patch.size else DOF_FOCUS_DEPTH
    return max(focus, DOF_FOCUS_DEPTH_FLOOR)
# --- CLIP-релевантность медиа (опционально, нужны torch/transformers) ---
# Главная реально подтверждённая на QC этого канала проблема: текстовый
# поиск Pexels иногда возвращает кандидата, который ПОХОЖ по ключевым
# словам, но по смыслу мимо (найдено вживую — клипы кино/танцевального боя
# проходили через запросы про мечи). CLIP умеет реально сравнить картинку
# с текстом ЗАПРОСА (не с русским текстом блока — CLIP англоязычный, а
# query уже на английском, см. THEMES/query_for) и дать число, а не
# доверять слепо тому, что поиск вернул top-N по ключевым словам.
CLIP_ENABLED = os.environ.get("CLIP_RELEVANCE", "1") != "0"
CLIP_BROKEN = False   # взводится только на системном сбое (модель/сеть), не на одной картинке
# Калибровано вживую на 01_ves-mecha: 20 верных пар (картинка, её реальный
# запрос) дали score 0.217-0.303 (среднее 0.262); 15 пар с заведомо
# посторонним запросом ("pizza restaurant", "office meeting" и т.п. — не
# просто другой вариант той же темы, а другая тема целиком) дали 0.118-0.201
# (среднее 0.164). Порог 0.19 — выше кластера настоящих непопаданий, ниже
# минимума верных пар с запасом, не режет близкие по смыслу варианты одной
# темы (те тоже пересекаются с верными по диапазону — это ОК, задача ловить
# явный промах, не выбирать идеальный вариант из синонимов).
CLIP_RELEVANCE_THRESHOLD = 0.19

# Реальный, найденный вживую пробел (27 августа, videos/_test20s, слот 7 —
# видео всадника с занесённым клинком): ни pexels_photo(), ни pexels_video()
# НИКОГДА не проверяли резкость кандидата НА ЭТАПЕ ОТБОРА — только
# отдельный, часто НЕ запускаемый scripts/visual_qc.py (Шаг 5.5, работает
# по media\, а этот эпизод тянул медиа НАПРЯМУЮ из Pexels, minuя media\
# вообще) умел это ловить. render_qc_report.json (см. RENDER_SHARPNESS_
# DROP_RATIO выше) сравнивает готовый рендер с ЕГО ЖЕ источником — но если
# ИСТОЧНИК сам по себе смазан (реальное motion-blur в самой стоковой
# съёмке, не наш рендер его испортил), эта проверка молчит: рендер честно
# не размытее источника, источник изначально плохой. PHOTO_SHARPNESS_REJECT
# переиспользует уже откалиброванный порог visual_qc.py (тот же Лапласиан
# на том же 720px-нормализованном кадре — see image_sharpness_score()) —
# теперь ту же проверку применяет и сам отбор кандидата, не только опциональный
# постфактум-проход.
PHOTO_SHARPNESS_REJECT = 25.0

# 2.5-3a: второй якорь для запросов с "собирательными" словами (museum,
# exhibition, collection, display, cabinet, case, gallery) — сами по себе
# они не гарантируют, что в кадре ДОМИНИРУЕТ предмет темы, а не архитектура
# зала/случайная утварь. Реальный пойманный случай: "sword museum display
# case" стабильно возвращал витражные окна музейного зала — по CLIP-скору
# против самого запроса это формально "релевантно" (слово museum в кадре
# есть), но карта не про то. Калибровано вживую (эпизод 01_ves-mecha, 10
# заведомо хороших кандидатов "весы"/"музе"-тем против 5 заведомо плохих
# "display case"/"glass cabinet" промахов): margin = релевантность(query) -
# релевантность(NEGATIVE_ANCHOR_PROMPT) у хороших — 0.050..0.138, у плохих —
# от -0.081 до 0.013. Порог 0.03 — с запасом ниже минимума хороших и выше
# максимума плохих на этой калибровке.
RISKY_GENERIC_TERMS = ("museum", "exhibition", "collection", "display",
                        "cabinet", "case", "gallery")
NEGATIVE_ANCHOR_PROMPT = "empty room interior architecture window"
RISKY_QUERY_MARGIN = 0.03


def is_risky_query(query):
    ql = query.lower()
    return any(term in ql for term in RISKY_GENERIC_TERMS)


# Вторая линия защиты от того же реального случая, что QUERY_DISAMBIGUATION_
# RULES выше (восточноазиатские клинки в выдаче по "sword") — та часть
# кандидатов, что просачивается мимо уточнённого запроса (Pexels — полнотек-
# стовый поиск, не гарантия), проверяется ВИЗУАЛЬНО. Калибровано вживую на
# 45 реальных Pexels-фото (tests/fixtures/golden_media/katana.jpg,
# euro_sword_2.jpg, уже существующий sword.jpg + 42 доп. фото — 23
# подтверждённых восточноазиатских клинка, включая 2 случая, найденных
# среди изначально "хороших" при прямой проверке кадра глазами, которые
# оказались катанами, а не отбраковкой метода; 22 подтверждённых европейских,
# включая sword.jpg — уже существующую эталонную фикстуру с рукоятью,
# обмотанной похоже на катана-цуку — самый жёсткий из проверенных случаев).
# margin = relevance(euro_prompt) - relevance(asian_prompt): подтверждённые
# восточноазиатские до +0.0187, подтверждённые европейские от -0.0139.
# Порог -0.03 — с запасом ниже минимума европейских (асимметричный риск:
# ложный reject кандидата просто пробует следующего в пуле, см.
# is_relevant_candidate() ниже — ложный accept пропускает анахронизм в
# кадр, дороже). ЧЕСТНО не ловит 100%: реальный найденный случай — крупный
# план ОДНОЙ рукояти без клинка/гарды в кадре (см. видео-кандидат в
# коммите) CLIP физически не может отличить по форме клинка, которой не
# видно — это первая, менее надёжная линия защиты (QUERY_DISAMBIGUATION_
# RULES) должна ловить такие случаи раньше, здесь — просто доп. слой,
# не единственная гарантия. Тот же паттерн override из channel_profile.json,
# что CONTENT_ALT_BLOCKLIST/QUERY_DISAMBIGUATION_RULES выше.
#
# ВТОРОЙ, независимо подтверждённый вживую случай ЭТОГО ЖЕ известного
# пробела (27 августа, videos/_test20s, слот 4, запрос "sword blade close
# up" — уже с дизамбигуацией "european"): реальное Pexels-видео катаны с
# ЯСНО видимой круглой цубой и ромбовидной цука-ито (не тесный кроп без
# гарды, как в исходном случае выше — здесь форма отчётливо видна и
# человеку, и, видимо, CLIP тоже, но недостаточно уверенно) — margin на
# 3 сэмплированных кадрах video_domain_guard_violation(): -0.0171/-0.0135/
# -0.0092, ВСЕ строго между порогом -0.03 и ближайшим подтверждённым
# европейским sword.jpg (-0.0139). Ни минимум, ни среднее по кадрам
# (-0.0133) не пересекают -0.03. Это НЕ новый баг и не повод молча
# подвинуть порог на этих 2-3 точках (тот же принцип, что уже применён к
# RISKY_QUERY_MARGIN ниже — TestRiskyQueryMargin.test_known_gap_exact_
# bug_query_still_accepts_stainedglass, xfail strict, НЕ автоматическое
# исправление без калибровки на большем наборе): доверительный интервал
# на n=2 подтверждённых европейских слишком мал, чтобы уверенно сузить
# зазор до -0.017 (где стоял бы порог, чтобы поймать этот конкретный
# случай) без риска начать резать легитимный европейский контент со
# похожей обмоткой рукояти. Отдельная задача — калибровка на большем
# наборе видео-кандидатов, не в этом заходе.
VISUAL_DOMAIN_GUARDS = (
    {
        "name": "east_asian_sword",
        "trigger_terms": ("sword", "blade", "katana", "longsword", "saber", "sabre"),
        "euro_prompt": "straight double-edged european longsword blade with cross-shaped hilt guard",
        "asian_prompt": ("curved single-edged katana blade with round tsuba guard, "
                          "or chinese jian sword with diamond pommel and tassel"),
        "margin_threshold": -0.03,
    },
)
VISUAL_DOMAIN_GUARDS = tuple(CHANNEL_PROFILE.get("visual_domain_guards", VISUAL_DOMAIN_GUARDS))


def visual_domain_guard_violation(image_path, query):
    """(нарушен_ли_анкер, имя_анкера) для ПЕРВОГО сработавшего правила из
    VISUAL_DOMAIN_GUARDS, чей trigger_terms совпал с query — см. калибровку
    выше. (False, None), если анкеры не применимы к этому запросу или CLIP
    недоступен (безопасный откат, тот же принцип, что is_risky_query)."""
    ql = query.lower()
    for guard in VISUAL_DOMAIN_GUARDS:
        if not any(t in ql for t in guard["trigger_terms"]):
            continue
        euro = clip_relevance(image_path, guard["euro_prompt"])
        asian = clip_relevance(image_path, guard["asian_prompt"])
        if euro is None or asian is None:
            continue
        if (euro - asian) < guard["margin_threshold"]:
            return True, guard["name"]
    return False, None


# Доли длительности ролика, где берутся дополнительные кадры-пробники для
# video_domain_guard_violation() ниже — не научный подбор, просто разброс
# "начало/середина/конец", чтобы не зависеть от одной случайной секунды.
VIDEO_DOMAIN_GUARD_SAMPLE_FRACS = (0.15, 0.5, 0.85)


def video_domain_guard_violation(video_path, query):
    """Тот же visual_domain_guard_violation(), но на НЕСКОЛЬКИХ кадрах видео,
    не на одном (см. pexels_video() — та проверяет relevance/risky-margin
    через ОДИН пробник extract_video_probe_frame(), обычно на 0.5с).
    Реальный, живьём найденный предел метода (не гипотеза): у видео по
    запросу "sword blade close up" кадр на 0.5с показывал ТОЛЬКО ромбовидную
    оплётку рукояти катаны — anchor-промпты домен-гварда описывают форму
    КЛИНКА/ГАРДЫ (см. VISUAL_DOMAIN_GUARDS), которых на этом кадре просто
    не видно, поэтому CLIP не мог сработать — а дальше по тому же ролику
    клинок/гарда уже попадали в кадр. Берём несколько точек по длительности
    (не только начало), нарушение НА ЛЮБОЙ из них — нарушение кандидата
    целиком (тот же принцип "не доверять одному сэмплу", что уже применяет
    measure_levels() против measure_luma() — см. её докстринг). Каждый
    сэмпл — свой независимый вызов extract_video_probe_frame() (с его же
    защитой от чёрного/вырожденного кадра). Дешёво в среднем: guard сам по
    себе не делает ни одного CLIP-вызова, если query не совпал ни с одним
    trigger_terms — эта функция вызывается ТОЛЬКО когда общий relevance-гейт
    уже прошёл на первом кадре, то есть на подавляющем большинстве обычных
    (не «оружейных») запросов не добавляет ни одного лишнего кадра/вызова."""
    try:
        duration = get_media_duration(video_path)
    except Exception:
        duration = None
    if duration and duration > 0.6:
        ats = [max(0.3, min(duration - 0.2, duration * f)) for f in VIDEO_DOMAIN_GUARD_SAMPLE_FRACS]
    else:
        ats = [0.5]
    seen = []
    for at in ats:
        if any(abs(at - s) < 0.2 for s in seen):
            continue   # слишком близко к уже проверенной точке — тот же кадр
        seen.append(at)
        probe, cleanup = extract_video_probe_frame(video_path, base_at=at, retry_ats=())
        if probe is None:
            continue
        try:
            violated, name = visual_domain_guard_violation(probe, query)
        finally:
            if cleanup and os.path.exists(probe):
                os.remove(probe)
        if violated:
            return True, name
    return False, None


# Реальный, найденный вживую случай (27 августа, videos/_test20s, слот 7):
# видео всадника с занесённым клинком — генуинное motion-blur самой
# стоковой съёмки (быстрая скачка/поворот камеры), не артефакт нашего
# рендера. Замерено на РЕАЛЬНЫХ кандидатах этого эпизода: заведомо ХОРОШЕЕ
# видео (батальная реконструкция, уже стоявшее в кадре) — резкость 1009-1952
# на 5 сэмплах по всей длительности; заведомо ПЛОХОЕ (этот всадник) —
# 92-270 на тех же 5 сэмплах, той же функцией image_sharpness_score(). Разрыв
# чистый и большой (минимум хорошего 1009 против максимума плохого 270) —
# порог 400 берётся с большим запасом в разрыв. Честно: n=2 видео, не
# статистика — тот же принцип малой калибровки, что уже применяет
# DIRECTOR_RELEVANCE_FLOOR/RISKY_QUERY_MARGIN в этом файле, не гадание с
# потолка.
VIDEO_SHARPNESS_REJECT = 400.0
VIDEO_SHARPNESS_SAMPLE_FRACS = (0.15, 0.5, 0.85)   # та же сетка, что у domain-гварда


def video_sharpness_ok(video_path):
    """Median резкости по нескольким сэмплам (не один кадр — транзиентное
    смазывание в один момент не должно топить весь клип, см. докстринг
    video_domain_guard_violation про "не доверять одному сэмплу"). None
    (не гейтит) при сбое длительности/декода — безопасный откат, как и у
    остальных опциональных проверок. РЕАЛЬНАЯ проверка на калибровочных
    видео этого эпизода (см. VIDEO_SHARPNESS_REJECT) — хорошее видео держит
    median далеко ВЫШЕ порога на всех сэмплах, плохое — далеко НИЖЕ."""
    try:
        duration = get_media_duration(video_path)
    except Exception:
        duration = None
    if not duration or duration <= 0.6:
        return None
    scores = []
    for frac in VIDEO_SHARPNESS_SAMPLE_FRACS:
        at = max(0.3, min(duration - 0.2, duration * frac))
        probe, cleanup = extract_video_probe_frame(video_path, base_at=at, retry_ats=())
        if probe is None:
            continue
        try:
            s = image_sharpness_score(probe)
        finally:
            if cleanup and os.path.exists(probe):
                os.remove(probe)
        if s is not None:
            scores.append(s)
    if not scores:
        return None
    scores.sort()
    median = scores[len(scores) // 2]
    return median >= VIDEO_SHARPNESS_REJECT


def is_relevant_candidate(image_path, query, relevance=None):
    """Итоговое решение "релевантен ли кандидат query" — тот же порог +
    risky-margin гейт, что раньше жил инлайном в цикле подбора фото (см.
    main()/pexels_photo(), вызов ниже). Вынесено в отдельную функцию, чтобы
    golden-тест (tests/test_media_selection_golden.py) гонял РЕАЛЬНУЮ
    логику принятия решения через реальный clip_relevance(), а не свою
    отдельную копию тех же трёх строк, которая могла бы молча разойтись
    с рабочим кодом при следующей правке. relevance можно передать уже
    посчитанным (вызывающий код часто уже считал его для других целей) —
    иначе считается здесь же."""
    if relevance is None:
        relevance = clip_relevance(image_path, query)
    is_relevant = relevance is None or relevance >= CLIP_RELEVANCE_THRESHOLD
    if is_relevant and relevance is not None and is_risky_query(query):
        anchor_relevance = clip_relevance(image_path, NEGATIVE_ANCHOR_PROMPT)
        if anchor_relevance is not None and (relevance - anchor_relevance) < RISKY_QUERY_MARGIN:
            is_relevant = False
    if is_relevant:
        violated, _ = visual_domain_guard_violation(image_path, query)
        if violated:
            is_relevant = False
    return is_relevant


# Версия ПРАВИЛ гейта, которые живут НЕ внутри перечисленных в
# candidate_gate_signature() функций, а в месте их ВЫЗОВА (pexels_photo/
# pexels_video) — inspect.getsource() таких изменений не видит, и без явного
# маркера правка правила молча не инвалидировала бы уже закэшированного
# кандидата, отобранного по старому правилу (ровно тот класс бага, который
# эта подпись и создавалась закрывать, см. её докстринг).
# 2 -> гейт релевантности сверяет кандидата с запросом ЕГО БЛОКА, а не с тем
#      запросом пула, из которого кандидат приплыл (28 августа, см. разбор у
#      вызова is_relevant_candidate() в pexels_photo()).
CANDIDATE_GATE_RULES_VERSION = 2

_CANDIDATE_GATE_SIG = None   # см. candidate_gate_signature(), считается лениво один раз


def candidate_gate_signature():
    """Отпечаток ПРАВИЛ ОТБОРА кандидата (relevance/анахронизм-гвард/
    дизамбигуация запроса) — входит в имя файла кэша temp_smart/pexels_cache
    и temp_smart/pexels_video_cache.

    РЕАЛЬНЫЙ, найденный вживую на Шаге 7.5 баг (QC теста videos/_test20s,
    27 августа): pexels_photo()/pexels_video() кэшируют скачанный файл по
    ключу "{индекс_слота}_{хэш_запроса}" и на кэш-хите отдают его СРАЗУ
    (см. комментарий "size>0, не просто exists" в обеих функциях) — ни
    is_relevant_candidate(), ни video_domain_guard_violation() на кэш-хите
    вообще не вызываются повторно. На практике: слот с запросом "sword
    blade close up" закэшировал кадр восточноазиатской катаны (видео
    0004_a29e160f.mp4, скачано 23 августа) ДО того, как в этот файл попал
    multi-frame video-domain-guard (более поздняя правка той же сессии) —
    и при каждом следующем прогоне ЭТОГО ЖЕ эпизода отдавался как есть,
    потому что улучшение проверки не меняло ключ кэша: анахронизм пережил
    свой собственный фикс. render_recipe_signature() уже решает ровно этот
    класс бага для temp_smart/clip_*.mp4 (визуальный РЕЦЕПТ рендера) — эта
    функция то же самое для temp_smart/pexels_cache и
    temp_smart/pexels_video_cache (правила ОТБОРА кандидата, другой этап
    пайплайна, другой кэш, тот же класс проблемы).

    Инвалидация грубая (правка любой из перечисленных функций/констант —
    даже строчки комментария внутри — считается сменой правил): та же
    осознанно консервативная сторона, что у render_recipe_signature() —
    лишняя перезакачка дешевле молча просроченного анахронизм-гварда.
    Сбой inspect -> стабильная заглушка, поведение как раньше, без падения."""
    global _CANDIDATE_GATE_SIG
    if _CANDIDATE_GATE_SIG is not None:
        return _CANDIDATE_GATE_SIG
    try:
        import inspect
        parts = [inspect.getsource(f) for f in (
            is_relevant_candidate, visual_domain_guard_violation,
            video_domain_guard_violation, disambiguate_search_query,
            is_risky_query,
            # image_sharpness_score/video_sharpness_ok — резкость кандидата
            # (PHOTO_SHARPNESS_REJECT/VIDEO_SHARPNESS_REJECT) — ТОЖЕ правило
            # отбора, хоть и не внутри is_relevant_candidate() самой (вызывается
            # отдельно в pexels_photo()/pexels_video()) — тот же класс пробела,
            # что уже описан в докстринге этой функции выше (анахронизм пережил
            # свой фикс) — без явного перечисления здесь правка порога/формулы
            # резкости молча не инвалидировала бы уже закэшированный размытый
            # кандидат, отобранный до этого фикса (реальный случай — слот 7,
            # videos/_test20s, 27 августа).
            image_sharpness_score, video_sharpness_ok,
            # Найдено самоаудитом 03.09 (тот же принцип, что уже применён к
            # image_sharpness_score/video_sharpness_ok выше): вызываются по
            # имени изнутри уже перечисленных функций, реально влияют на
            # решение гейта, @memoize_by_frame их не защищает МЕЖДУ
            # прогонами (та же оговорка, что у render_recipe_signature()).
            #
            # clip_relevance — САМА функция, дающая число: используется и в
            # is_relevant_candidate() (порог CLIP_RELEVANCE_THRESHOLD), и в
            # visual_domain_guard_violation() (euro/asian margin — то есть
            # сам анахронизм-гвард, ради которого эта сигнатура и была
            # создана изначально), и в NEGATIVE_ANCHOR_PROMPT-проверке.
            clip_relevance,
            # extract_video_probe_frame — из video_domain_guard_violation()/
            # video_sharpness_ok(): решает, КАКОЙ именно кадр видео (с
            # ретраями от вырожденного/чёрного) идёт на CLIP-проверку домена
            # и резкости — другой выбранный кадр даёт другой результат гейта.
            extract_video_probe_frame,
        )]
        parts.append(repr((
            CLIP_RELEVANCE_THRESHOLD, RISKY_QUERY_MARGIN, NEGATIVE_ANCHOR_PROMPT,
            RISKY_GENERIC_TERMS, VISUAL_DOMAIN_GUARDS, VIDEO_DOMAIN_GUARD_SAMPLE_FRACS,
            CONTENT_ALT_BLOCKLIST, QUERY_DISAMBIGUATION_RULES,
            PHOTO_SHARPNESS_REJECT, VIDEO_SHARPNESS_REJECT, VIDEO_SHARPNESS_SAMPLE_FRACS,
            SHARPNESS_PROBE_MAX_SIDE, CANDIDATE_GATE_RULES_VERSION,
        )))
    except Exception:
        _CANDIDATE_GATE_SIG = "gate:unknown"
        return _CANDIDATE_GATE_SIG
    _CANDIDATE_GATE_SIG = "gate:" + hashlib.md5("".join(parts).encode()).hexdigest()[:10]
    return _CANDIDATE_GATE_SIG


# P2 (аудит "зерно vs частицы в мире"): часть стокового контента УЖЕ несёт
# собственные визуальные частицы (падающий снег, пыль, капли дождя, боке) —
# найдено вживую прямым просмотром кадра (фото "EXCALIBUR" со снегом,
# см. коммит). Наше процедурное зерно (grain_blend_complex) кладётся ОДНИМ
# и тем же opacity на любой клип, независимо от того, есть ли у исходника
# уже своя текстура — на "частицастых" клипах зритель видит два разных по
# характеру источника мелких точек сразу.
#
# Калибровано вживую (НЕ на глаз): 10 подтверждённых прямым просмотром
# кандидатов — частицастые (реальный дождь/снег/пыль на кадре, включая
# "EXCALIBUR", реальные Pexels-фото по запросам "sword snow"/"medieval
# weapon dust particles"/"sword rain droplets") дают relevance против
# PARTICLE_PROMPT в диапазоне 0.208..0.287; чистые "по делу" кадры того же
# оружейного топика (рыцари/легионеры/косплей без частиц, включая один
# кадр с обычным несфокусированным зелёным фоном — НЕ частицы, просто
# боке) — 0.115..0.216. Порог 0.21 — выше единственного пограничного
# случая (0.2156, подтверждённое отсутствие частиц) и не выше самого
# слабого подтверждённого частицастого случая (0.2079). Точность неидеальна
# (граница узкая, ~0.006), но цена ошибки низкая: ложное срабатывание
# просто чуть снижает opacity зерна на обычном фото с боке — не искажает
# контент и не отбрасывает кандидата (кандидат остаётся выбранным, меняется
# только позже наложение зерна).
PARTICLE_PROMPT = "falling snow dust particles bokeh in frame"
PARTICLE_SCORE_THRESHOLD = 0.21
PARTICLE_GRAIN_SCALE = 0.5   # во сколько раз снижаем GRAIN_OPACITY на "частицастом" клипе


def measure_particle_score(path, is_video=False):
    """clip_relevance() кандидата против PARTICLE_PROMPT — см. калибровку
    выше. Для видео — один кадр-пробник (тот же приём, что measure_luma()
    уже использует для видео: -ss 0.5, не кадр 0, реальный сток иногда
    начинается с чёрного лидер-кадра). None при недоступной CLIP-модели —
    вызывающий код тогда просто не масштабирует opacity (безопасный откат,
    тот же принцип, что и у остальных CLIP-гейтов в файле)."""
    if is_video:
        tmp = path + "._particle_probe.jpg"
        try:
            r = subprocess.run(["ffmpeg", "-y", "-ss", "0.5", "-i", path, "-frames:v", "1", "-q:v", "5", tmp],
                                capture_output=True, timeout=20)
            if r.returncode != 0 or not os.path.exists(tmp):
                return None
            score = clip_relevance(tmp, PARTICLE_PROMPT)
        except Exception:
            score = None
        finally:
            if os.path.exists(tmp):
                os.remove(tmp)
        return score
    return clip_relevance(path, PARTICLE_PROMPT)


_clip_model = None
_clip_processor = None


def get_clip_model():
    global _clip_model, _clip_processor
    if _clip_model is None:
        from transformers import CLIPModel, CLIPProcessor
        name = "openai/clip-vit-base-patch32"
        _clip_model = CLIPModel.from_pretrained(name).eval()
        _clip_processor = CLIPProcessor.from_pretrained(name)
    return _clip_model, _clip_processor


# clip_relevance()/aesthetic_score() ниже читают module-level флаги
# CLIP_ENABLED/CLIP_BROKEN/AESTHETIC_ENABLED помимо своих аргументов — но
# все три МОНОТОННЫ в рамках одного прогона (CLIP_ENABLED/AESTHETIC_ENABLED
# фиксируются один раз на импорте из окружения, CLIP_BROKEN только False->
# True и никогда обратно), значит memoize_by_frame безопасен: если результат
# на (путь, текст) уже закэширован, флаги с тех пор могли только СИЛЬНЕЕ
# отключить CLIP, никогда не включить его заново — закэшированный
# "рабочий" ответ не может стать неверным из-за более позднего отказа.
@memoize_by_frame
def clip_relevance(image_path, text):
    """Косинусная близость картинки и текста ЗАПРОСА (0..1, реалистичный
    диапазон на наших фото ~0.1-0.3, не 0..1 в бытовом смысле "процент
    похожести" — это сырой косинус эмбеддингов CLIP). None при отключённой
    фиче/сбое модели — вызывающий код тогда просто не гейтит по релевантности
    (безопасный откат, тот же принцип, что PARALLAX_LIBS/PARALLAX_BROKEN)."""
    global CLIP_BROKEN
    if not CLIP_ENABLED or CLIP_BROKEN:
        return None
    try:
        import torch
        model, processor = get_clip_model()
        img = PILImage.open(image_path).convert("RGB")
        inputs = processor(text=[text], images=[img], return_tensors="pt", padding=True, truncation=True)
        with torch.no_grad():
            out = model(**inputs)
        img_e = out.image_embeds / out.image_embeds.norm(dim=-1, keepdim=True)
        txt_e = out.text_embeds / out.text_embeds.norm(dim=-1, keepdim=True)
        return float((img_e @ txt_e.T)[0][0])
    except ImportError:
        CLIP_BROKEN = True
        return None
    except Exception:
        return None


# --- Эстетическая оценка кадра (LAION aesthetic predictor v1, линейная
# голова поверх CLIP ViT-B/32) — та же модель, что уже загружена для
# clip_relevance(), никакого нового тяжёлого скачивания. Голова — всего
# 513 чисел (512-мерный вес + bias), извлечена ОДИН РАЗ из официальных
# весов (shunk031/aesthetics-predictor-v1-vit-base-patch32 на HF — это
# репаковка оригинальных LAION-AI/aesthetic-predictor sa_0_4_vit_b_32_
# linear.pth в формат HF, GitHub-источник в этой сессии недоступен по
# сетевой политике, HF открыт) и сохранена как assets/aesthetic/*.npz —
# не .pth (pickle, может исполнять код при загрузке), голый numpy-массив,
# без риска.
AESTHETIC_ENABLED = os.environ.get("AESTHETIC_SCORE", "1") != "0"
_aesthetic_head = None


def get_aesthetic_head():
    global _aesthetic_head
    if _aesthetic_head is None:
        path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
                             "assets", "aesthetic", "laion_aesthetic_vit_b_32_head.npz")
        data = np.load(path)
        _aesthetic_head = (data["weight"], float(data["bias"]))
    return _aesthetic_head


SHARPNESS_PROBE_MAX_SIDE = 720   # тот же нормализующий размер, что уже использует
                                  # visual_qc.py — Лапласиан-дисперсия растёт с
                                  # разрешением исходника, не только с реальной
                                  # резкостью; сравнивать источник и рендер нужно
                                  # в ОДНОЙ шкале.


def image_sharpness_score(image_path):
    """Дисперсия Лапласиана (тот же дешёвый blur-детектор, что уже использует
    visual_qc.py sharpness_score() — не дублируется оттуда напрямую: тот файл
    ИМПОРТИРУЕТ pipeline_smart, обратный импорт дал бы цикл). None при сбое
    чтения/декода или недоступности numpy — вызывающий код просто не гейтит
    по этой оси (тот же безопасный откат, что и у остальных опциональных
    скореров пайплайна)."""
    if np is None:
        return None
    try:
        img = PILImage.open(image_path).convert("L")
        w, h = img.size
        scale = SHARPNESS_PROBE_MAX_SIDE / max(w, h)
        if scale < 1.0:
            img = img.resize((max(1, round(w * scale)), max(1, round(h * scale))), PILImage.LANCZOS)
        arr = np.asarray(img, dtype=np.uint8)
        if PARALLAX_LIBS:   # cv2 доступен — см. import cv2 в начале файла
            return float(cv2.Laplacian(arr, cv2.CV_64F).var())
        kernel = np.array([[0.0, 1.0, 0.0], [1.0, -4.0, 1.0], [0.0, 1.0, 0.0]])
        lap = _convolve2d_same(arr.astype(np.float64), kernel)
        return float(lap.var())
    except Exception:
        return None


# Реальный, найденный вживую случай (27 августа, videos/_test20s, слот 3):
# apply_depth_of_field() размыл САМ ОБЪЕКТ, не только фон (см. коммит про
# _dof_focus_depth) — но НИЧТО в пайплайне до этого коммита не сравнивало
# резкость ГОТОВОГО РЕНДЕРА с резкостью ИСХОДНОГО фото. visual_qc.py (Шаг
# 5.5) проверяет резкость только СЫРОГО кандидата ДО рендера — у него
# физически нет доступа к тому, что Ken Burns/параллакс/ГРИП/грейд сделают
# с кадром ПОСЛЕ. Эта проверка — единственное место, которое умеет поймать
# ЛЮБОЙ будущий баг того же КЛАССА (не только сегодняшний DOF): рендер,
# который ощутимо размывает кадр относительно его же источника, независимо
# от причины (новый неудачный фильтр, регрессия в параллаксе, что угодно).
#
# Калибровка (n=4 реальных клипа этого эпизода, честно — не строгая
# статистика, а быстрая проверка на реальных данных перед тем, как
# использовать порог, см. принцип "не гадать" по всему пайплайну):
# baggy DOF (найденный баг) дал rendered/source = 245/596 = 0.41; тот же
# кадр после фикса — 639/596 = 1.07; фото с намеренным боке крупного плана
# (книга, естественное размытие фона в самом источнике) — 155/245 = 0.64;
# фото без выраженной глубины (весы) — 145/144 = 1.01. Порог 0.5 — с
# запасом ниже честного кинематографичного боке (0.64), но ловит реальный
# найденный случай (0.41). Advisory, не hard-reject (тот же принцип, что
# AESTHETIC_BORDERLINE в visual_qc.py) — рендер не останавливается, флаг
# идёт в отчёт для Шага 7.5.
RENDER_SHARPNESS_DROP_RATIO = 0.5
RENDER_QC_REPORT = []   # [{"index", "source", "rendered", "source_sharpness",
                         #   "rendered_sharpness", "ratio"}, ...] — см. main()


def render_sharpness_regression(source_photo, rendered_clip):
    """(флаг_подозрительно_размыто, ratio) — сравнивает резкость ИСХОДНОГО
    фото с резкостью кадра-пробника ИЗ ГОТОВОГО РЕНДЕРА (см.
    RENDER_SHARPNESS_DROP_RATIO выше). Пробник берётся с середины клипа
    (extract_video_probe_frame, тот же метод, что уже используют домен-гварды
    видео) — не с первого кадра, где ещё может идти вход в кенбёрнс.
    (None, None) на любом сбое (декод/недоступность numpy-CV) — безопасный
    откат, проверка просто не участвует, как и остальные опциональные оси."""
    src_sharp = image_sharpness_score(source_photo)
    if src_sharp is None or src_sharp <= 1.0:
        return None, None   # почти однотонный/вырожденный источник — не с чем сравнивать
    probe, cleanup = extract_video_probe_frame(rendered_clip, base_at=0.5)
    if probe is None:
        return None, None
    try:
        rendered_sharp = image_sharpness_score(probe)
    finally:
        if cleanup and os.path.exists(probe):
            os.remove(probe)
    if rendered_sharp is None:
        return None, None
    ratio = rendered_sharp / src_sharp
    return (ratio < RENDER_SHARPNESS_DROP_RATIO, ratio)


@memoize_by_frame
def aesthetic_score(image_path):
    """Эстетическая оценка кадра — линейная регрессия поверх L2-нормали-
    зованного CLIP image embedding (формула подтверждена по исходному коду
    модели: image_embeds /= norm(...); prediction = predictor(image_embeds)).
    Диапазон на реальных фото ~3-7 (проверено вживую на 25 кадрах эпизода —
    топ-3 по оценке визуально заметно сильнее по композиции/свету, чем
    низ; самый низкий скор корректно поймал случайно затесавшийся в кэш
    нерелевантный кадр — рюкзак/ноутбук вместо меча). None при отключённой
    фиче/сбое — вызывающий код просто не использует критерий (безопасный
    откат, тот же принцип, что CLIP_BROKEN/PARALLAX_BROKEN)."""
    global CLIP_BROKEN
    if not AESTHETIC_ENABLED or not CLIP_ENABLED or CLIP_BROKEN:
        return None
    try:
        import torch
        model, processor = get_clip_model()
        img = PILImage.open(image_path).convert("RGB")
        inputs = processor(images=[img], return_tensors="pt")
        with torch.no_grad():
            vis_out = model.vision_model(pixel_values=inputs["pixel_values"])
            feat = model.visual_projection(vis_out.pooler_output)
        e = (feat / feat.norm(dim=-1, keepdim=True))[0].numpy()
        w, b = get_aesthetic_head()
        return float(e @ w + b)
    except ImportError:
        CLIP_BROKEN = True
        return None
    except Exception:
        return None


_depth_model = None


def get_depth_model():
    global _depth_model
    if _depth_model is None:
        from transformers import pipeline as hf_pipeline
        _depth_model = hf_pipeline(task="depth-estimation",
                                    model="depth-anything/Depth-Anything-V2-Small-hf")
    return _depth_model


def estimate_depth(canvas_bgr):
    """Карта глубины (float32, 0..1, 1=близко) — строится по УЖЕ обрезанному
    холсту (canvas_bgr из fill_crop_canvas), а не по исходному фото.
    Раньше модель считала глубину по несжатому оригиналу (его родное
    соотношение сторон), а карта потом растягивалась голым cv2.resize под
    размер холста — без кропа, который применялся к цветной картинке. При
    несовпадении соотношения сторон (портретное фото под альбомный холст)
    карта глубины съезжала и тянулась не по тому же кадру, что видит
    зритель: параллакс сдвигал пиксели по чужой геометрии — отсюда
    видимое искажение/"плавание" картинки. Считая глубину прямо по canvas,
    геометрия гарантированно совпадает."""
    model = get_depth_model()
    h, w = canvas_bgr.shape[:2]
    img = PILImage.fromarray(canvas_bgr[:, :, ::-1])  # BGR -> RGB
    out = model(img)
    depth = np.array(out["predicted_depth"], dtype=np.float32)
    if depth.shape != (h, w):
        depth = cv2.resize(depth, (w, h), interpolation=cv2.INTER_LINEAR)
    d_min, d_max = float(depth.min()), float(depth.max())
    if d_max - d_min < 1e-6:
        return np.full((h, w), 0.5, dtype=np.float32)
    depth = (depth - d_min) / (d_max - d_min)
    # Depth-Anything даёт РЕЗКИЙ край на границе объекта (перепад ~0..1 за
    # 1-2px — проверено: grad p99 ~0.08, максимум >2.0 на пиксель). При
    # remap с parallax_px до ~70px это превращает границу в артефакт
    # "двойного контура"/расслоения на резких силуэтах (рукоять меча на
    # фоне боке) — то, что видно глазом как "ИИ-искажение". Настоящей
    # физически верной параллакс-окклюзии тут всё равно нет (плоская
    # картинка, не многослойная сцена), поэтому лечим не резкость карты,
    # а её крутизну: широкое гауссово размытие растягивает переход через
    # много пикселей, и remap плывёт плавно вместо "разрыва" на 1-2px —
    # тот же приём, что использует Apple/Google в 3D-Ken-Burns эффектах.
    sigma = max(3.0, min(h, w) * 0.018)
    depth = cv2.GaussianBlur(depth, (0, 0), sigmaX=sigma)
    return depth


def fill_crop_canvas(photo_path, cw, ch, anchor=None):
    """Тот же increase+crop, что и в ffmpeg-пути: заливаем холст целиком,
    обрезаем лишнее — без чёрных полос по краям (BGR для cv2). anchor —
    та же логика, что в compute_crop_offset (см. detect_face_anchor):
    None -> центр-кроп, как было всегда."""
    img = PILImage.open(photo_path).convert("RGB")
    iw, ih = img.size
    nw, nh, x0, y0 = compute_crop_offset(iw, ih, cw, ch, anchor)
    img = img.resize((nw, nh), PILImage.LANCZOS)
    img = img.crop((x0, y0, x0 + cw, y0 + ch))
    arr = np.array(img)[:, :, ::-1].copy()   # RGB -> BGR
    return arr


def apply_depth_of_field(canvas, depth, strength_gain=1.0):
    """Размывает фон холста ПРОПОРЦИОНАЛЬНО дистанции от переднего плана —
    см. DOF_* константы выше. Один Gaussian-blur прохода + линейный (по
    DOF_FALLOFF_POWER) блендинг по уже посчитанной depth-карте, без второй
    модели. strength_gain — тот же content-aware множитель, что уже
    масштабирует parallax_px/depth_zoom_strength (depth.std() / референс) —
    на плоских кадрах (студийный фон почти без глубины) эффект слабее, не
    выдаёт ложный "боке" там, где реального разделения план/фон нет."""
    if not DOF_ENABLED:
        return canvas
    h, w = canvas.shape[:2]
    sigma = DOF_SIGMA_FRAC * min(h, w) * max(0.3, min(1.5, strength_gain))
    if sigma < 1.0:
        return canvas
    blurred = cv2.GaussianBlur(canvas, (0, 0), sigmaX=sigma)
    focus_depth = _dof_focus_depth(depth, h, w)
    blur_weight = np.clip((focus_depth - depth) / focus_depth, 0.0, 1.0) ** DOF_FALLOFF_POWER
    blur_weight = blur_weight[:, :, None]
    return (canvas.astype(np.float32) * (1.0 - blur_weight)
            + blurred.astype(np.float32) * blur_weight).astype(np.uint8)


# Occlusion-aware двухслойный варп — независимая реализация общеизвестной
# техники "layered depth image" (см. "3D Ken Burns Effect from a Single
# Image", Niklaus/Mai/Yang/Liu, 2019 — та же архитектурная идея, на которую
# уже ссылается комментарий у estimate_depth() выше; код здесь свой, на
# штатном OpenCV cv2.inpaint(), ничего не заимствовано из чужих репозиториев).
#
# ПРОБЛЕМА, которую это решает: PARALLAX_MAX_STRETCH/WARP_SIGMA_FRAC выше —
# рабочий, измеренный фикс для одного-единственного плоского remap()
# (растяжение снижено с 172% до 13% на реальном кадре) — но это смягчение
# СИМПТОМА (сглаженная карта глубины растягивает разрыв на больше пикселей),
# не устранение ПРИЧИНЫ: на границе объекта remap() всё ещё сэмплит один и
# тот же холст по обе стороны разрыва, соседние выходные пиксели неизбежно
# тянут текстуру через границу. Настоящая проблема физическая: фото —
# плоское, за передним планом реально НЕТ данных о том, что там на самом
# деле (окклюзия) — плоский remap с этим ничего не может поделать
# принципиально, только маскировать растяжку размытием.
#
# РЕШЕНИЕ: разложить холст на 2 слоя по Otsu-порогу depth-карты (близко/
# далеко — порог считается автоматически по бимодальности гистограммы
# глубины, не гадание с процентилем). Область под "близким" объектом на
# ФОНОВОМ слое затягивается cv2.inpaint() ОДИН раз на фото (не на кадр —
# дорого) — правдоподобным продолжением фона, а не дырой/растяжкой.
# На каждом кадре оба слоя варпятся ТЕМ ЖЕ самым map_x/map_y, что и раньше
# (архитектура remap-цикла не меняется), и компонуются через мягкую
# (растушёванную) альфа-маску переднего плана — там, где раньше задняя
# плоскость стягивалась в мазок, теперь виден уже готовый (не рвущийся)
# инпейнт-фон.
PARALLAX_OCCLUSION_AWARE = os.environ.get("PARALLAX_OCCLUSION_AWARE", "1") != "0"
PARALLAX_INPAINT_RADIUS = 5   # px, стандартный диапазон cv2.inpaint() (3-7)


def foreground_background_layers(canvas, depth):
    """(bg_plate, fg_alpha) — фоновый слой с инпейнтом под передним планом
    и мягкая (0..1) альфа-маска "насколько этот пиксель — передний план".

    Сбой (inpaint не встал/маска пустая/вся картинка одним классом) ->
    (canvas, None) — вызывающий код на None откатывается на старый
    однослойный путь, тот же fail-open принцип, что у остального параллакса."""
    try:
        d8 = np.clip(depth * 255, 0, 255).astype(np.uint8)
        _, fg_mask = cv2.threshold(d8, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)
        # Otsu не гарантирует, какой класс какой — у нас депт=1 значит
        # "близко", проверяем и при необходимости инвертируем маску так,
        # чтобы fg_mask действительно соответствовал БЛИЖНЕМУ объекту.
        if fg_mask.mean() <= 0 or fg_mask.mean() >= 255:
            return canvas, None   # вся картинка одним классом — слоить нечего
        if float(depth[fg_mask > 0].mean()) < float(depth[fg_mask == 0].mean()):
            fg_mask = 255 - fg_mask
        k = PARALLAX_INPAINT_RADIUS * 2 + 1
        inpaint_mask = cv2.dilate(fg_mask, np.ones((k, k), np.uint8))
        bg_plate = cv2.inpaint(canvas, inpaint_mask, PARALLAX_INPAINT_RADIUS, cv2.INPAINT_TELEA)
        sigma = max(2.0, min(canvas.shape[:2]) * 0.01)
        fg_alpha = cv2.GaussianBlur(fg_mask.astype(np.float32) / 255.0, (0, 0), sigmaX=sigma)
        return bg_plate, fg_alpha
    except Exception:
        return canvas, None


def parallax_kenburns(photo, out, dur, title=None, zoom_in=None, pan_dir=None, stat=None,
                       section="", stat_variant=0, brightness_bias=0.0, energy_bias=0.0,
                       stat_delay=0.0, levels=None, wb=None, grain_scale=1.0, captions=None,
                       look_filter=None, domain=None):
    """2.5D-версия kenburns(): собственный покадровый рендер (OpenCV remap)
    вместо ffmpeg zoompan — только так можно сделать смещение, зависящее от
    глубины пикселя. При любой накладке (модель не встала, ffmpeg-пайп упал)
    возвращает False — вызывающий код откатывается на обычный kenburns()."""
    global PARALLAX_BROKEN
    if PARALLAX_BROKEN:
        return False
    proc = None
    stderr_f = None
    stderr_path = None
    try:
        frames = max(1, round(dur * FPS))
        cw, ch = round(WIDTH * PARALLAX_MARGIN), round(HEIGHT * PARALLAX_MARGIN)
        canvas = fill_crop_canvas(photo, cw, ch, anchor=resolve_crop_anchor(photo))
        try:
            depth = estimate_depth(canvas)
        except Exception as e:
            # Сбой именно тут почти всегда системный (модель не встала /
            # сеть до HF Hub отвалилась), не проблема конкретной картинки —
            # дальше пытаться на каждом из оставшихся хайлайтов бессмысленно,
            # только тратим время на повторную (медленную) загрузку модели.
            print(f"  depth-модель недоступна, параллакс выключается на остаток ролика: "
                  f"{type(e).__name__} {e}")
            PARALLAX_BROKEN = True
            return False

        h, zoom_in_default, pan_dir_default = kb_hash_choices(photo)
        if zoom_in is None:
            zoom_in = zoom_in_default
        dx, dy = pan_dir if pan_dir is not None else pan_dir_default
        rate_jit = ((h >> 5) % 1000) / 1000.0
        pan_jit = ((h >> 15) % 1000) / 1000.0
        # C6: см. kenburns() — та же логика скорости зума в такт энергии голоса.
        energy_zoom_mult = 1.0 + max(-0.5, min(0.5, energy_bias)) * 0.2
        delta = max(ZOOM_DELTA_MIN, min(ZOOM_DELTA_MAX,
                    ZOOM_RATE_BASE * dur * (0.75 + rate_jit * 0.5) * energy_zoom_mult))
        max_zoom = ZOOM_FLOOR + delta
        pan_amt_frac = PAN_SAFETY * (PAN_JITTER_MIN + pan_jit * (PAN_JITTER_MAX - PAN_JITTER_MIN))
        # Content-aware сила эффекта: раньше parallax_px был один и тот же
        # для любой картинки — эффект работает эффектно только там, где в
        # карте глубины ЕСТЬ реальный контраст (чёткое разделение объект/
        # фон); на плоских/текстурных кадрах (макро металла, ткань, ровный
        # задник) та же сила выглядит как случайное дрожание, не параллакс,
        # потому что двигать там физически нечего. depth.std() — дешёвая
        # мера контраста уже посчитанной карты (без доп. модели). Референс
        # 0.22 — медиана std по реальным фото канала (проверено: 0.18-0.31
        # на 8 кадрах), не гадание. Верхняя граница 1.4 — не разгоняем сверх
        # разумного. Нижняя граница поднята с 0.4 до 0.6 по прямой жалобе
        # пользователя (параллакс на хук-кадре с низкоконтрастным фоном
        # выглядел почти неотличимо от обычного Ken Burns) — parallax_kenburns
        # вызывается ИСКЛЮЧИТЕЛЬНО на highlight-кадрах (хук/открывашки
        # разделов/climax, см. is_parallax_highlight()), то есть именно там,
        # где эффект по замыслу должен читаться сильнее всего; 0.6 — разумная
        # правка на глаз, НЕ пересчитана заново на большой выборке фото
        # (честно, как и исходное значение 0.4 не было "гаданием", но и не
        # калибровкой в строгом смысле).
        depth_contrast = float(depth.std())
        strength_gain = max(0.6, min(1.4, depth_contrast / 0.22))
        parallax_px = PARALLAX_PX_BASE * (0.7 + rate_jit * 0.6) * strength_gain
        # Отдельная, СИЛЬНО сглаженная карта глубины именно для геометрии
        # варпа (см. PARALLAX_WARP_SIGMA_FRAC/PARALLAX_MAX_STRETCH выше).
        # Исходная `depth` остаётся резкой и дальше идёт в apply_depth_of_field()
        # и в depth_contrast — боке и оценка контраста хотят чёткий край,
        # геометрия от чёткого края рвётся.
        warp_depth = cv2.GaussianBlur(
            depth, (0, 0), sigmaX=max(3.0, min(cw, ch) * PARALLAX_WARP_SIGMA_FRAC))
        _gy, _gx = np.gradient(warp_depth)
        warp_grad = float(np.percentile(np.hypot(_gx, _gy), 99))
        # DEPTH_ZOOM_STRENGTH — насколько сильно ближние/дальние слои
        # расходятся по СКОРОСТИ ЗУМА при push/pull (не только по офсету
        # при пане, как раньше). Настоящая перспектива: у камеры, которая
        # реально приближается к сцене, ближние объекты растут в кадре
        # быстрее дальних — старая версия зумила все пиксели с одной и той
        # же скоростью независимо от глубины (это и есть "2D remap", не
        # честная 3D-репроекция). depth_zoom_strength тоже масштабируется
        # content-aware — той же логикой, что и parallax_px выше.
        depth_zoom_strength = 0.12 * strength_gain
        # Гарантия бюджета искажения (см. PARALLAX_MAX_STRETCH выше) — обе
        # ручки режутся по ИЗМЕРЕННОМУ на этом фото градиенту, а не по общей
        # константе. У depth_zoom_strength вклад в растяжение больше в
        # (min(кадра)/2) раз: он множит не смещение, а КООРДИНАТУ, то есть
        # эффект растёт с удалением от центра кадра — поэтому и потолок свой.
        if warp_grad > 1e-6:
            parallax_px = min(parallax_px, PARALLAX_MAX_STRETCH / warp_grad)
            depth_zoom_strength = min(
                depth_zoom_strength,
                PARALLAX_MAX_STRETCH / (warp_grad * (min(WIDTH, HEIGHT) / 2.0)))
        # Боке/глубина резкости (см. apply_depth_of_field()/DOF_* выше) —
        # размывает canvas ОДИН раз до начала покадрового remap-цикла, тот
        # же canvas дальше варпится по кадрам как обычно (background
        # остаётся размытым и через движение параллакса — оптически
        # корректно, размытие свойство сцены, не текущего вида камеры).
        #
        # РЕАЛЬНЫЙ, найденный вживую баг (deep-audit, videos/_test20s, слот 2
        # "видеоигры и школьные учебники", прямая жалоба пользователя на
        # размытие). strength_gain выше — ОДНА величина на geometric-
        # параллакс (parallax_px/depth_zoom_strength, клэмп 0.6..1.4) И на
        # силу DOF-боке — но это разные вещи: широкий geometric-клэмп
        # безопасен (сильнее едет параллакс на контрастной сцене — это и
        # есть цель), а тот же множитель для sigma боке на сцене с БОЛЬШИМ
        # разбросом глубины (толпа зрителей вдалеке + трава на разных
        # дистанциях + фигуры на переднем плане — depth.std()=0.288, близко
        # к потолку 1.4x) даёт sigma=29.7px при DOF_SIGMA_FRAC=0.014 — и,
        # что важнее, порог фокуса (_dof_focus_depth(), медиана ЦЕНТРАЛЬНОГО
        # патча) на такой сцене оставляет ~62% всего кадра НИЖЕ порога
        # (измерено: (depth < focus).mean() = 0.618) — то есть боке ложится
        # не только на реальный дальний план, но и на значительную часть
        # среднего плана, который в РЕАЛЬНОМ источнике был резким целиком
        # (обычное для photojournalism/массовых сцен глубокое ГРИП, не
        # мелкая диафрагма) — на готовом рендере это читается не как боке,
        # а как "фото размазано". Разделяем: geometric strength_gain остаётся
        # как был (0.6..1.4, доказанно безопасен), DOF получает СВОЙ, более
        # консервативный потолок 1.0 (нижняя граница 0.5 — тоже чуть строже
        # 0.6, тот же принцип "не разгонять на бесспорно сложной сцене").
        # На этом кадре: sigma 29.7px -> 22.7px (-24%), фракция ниже порога
        # не меняется (это управляется focus_depth/falloff, не strength_gain)
        # — не заявляю, что это полностью убирает эффект, только честно
        # снижает силу там, где content-aware сигнал (высокий depth.std())
        # сегодня трактуется как "разгоняй сильнее", а физически чаще
        # означает "тут много разных планов, потолок не должен разгонять
        # боке ТАК агрессивно, как на чистом двухслойном кадре".
        dof_strength_gain = max(0.5, min(1.0, strength_gain))
        canvas = apply_depth_of_field(canvas, depth, dof_strength_gain)
        # Occlusion-aware фоновый слой (см. foreground_background_layers()
        # выше) — считается ОДИН раз на фото, до покадрового цикла. bg_alpha
        # is None -> старый однослойный remap (fail-open, не другое
        # поведение при выключенном/сбойном PARALLAX_OCCLUSION_AWARE).
        bg_plate, fg_alpha = ((canvas, None) if not PARALLAX_OCCLUSION_AWARE
                               else foreground_background_layers(canvas, depth))
        # C2: лёгкий 3D-наклон камеры (roll) — до TILT_MAX_DEG, направление
        # по хэшу фото. Независимая от зума/пана ось движения, добавляет
        # ощущение "камера не на рельсах, а в руках", не дублирует то, что
        # уже даёт depth-параллакс (тот двигает БЛИЖНИЕ/ДАЛЬНИЕ слои с разной
        # скоростью, это вращает кадр целиком).
        TILT_MAX_DEG = 0.6
        tilt_dir = 1 if (h & 0x100) else -1
        # Не крутим кадр под цифрой-плашкой — читаемость важнее, тот же
        # принцип, что static_hold у kenburns() (параллакс своей "статичной"
        # ветки не имеет, гасим только этот один эффект).
        tilt_theta_max = 0.0 if stat else math.radians(TILT_MAX_DEG * tilt_dir)

        cx, cy = cw / 2.0, ch / 2.0
        ox_grid, oy_grid = np.meshgrid(np.arange(WIDTH, dtype=np.float32),
                                        np.arange(HEIGHT, dtype=np.float32))

        cmd = ["ffmpeg", "-y", "-f", "rawvideo", "-pix_fmt", "bgr24",
               "-s", f"{WIDTH}x{HEIGHT}", "-r", str(FPS), "-i", "-"]
        # Зерно — второй вход, ДО -frames:v (тот должен остаться однозначно
        # выходной опцией — если между ним и следующим -i ничего не стоит,
        # ffmpeg привязал бы его ко входу grain, а не к выходу).
        if GRAIN_ENABLED:
            cmd += ["-stream_loop", "-1", "-i", GRAIN_LOOP_PATH]
        vf = film_look(h, section, brightness_bias, energy_bias, levels, wb, domain)
        if look_filter:   # Reference-Guided Look Management — см. kenburns()
            vf += f",{look_filter}"
        if title or stat or captions:
            vf = add_overlays(vf, dur, title, stat, stat_variant, stat_delay, media_path=photo)
            vf = add_kinetic_captions(vf, captions)
        if GRAIN_ENABLED:
            fc = f"[0:v]{vf}[gr_in];{grain_blend_complex('gr_in', 1, 'vout', grain_scale)}"
            cmd += ["-filter_complex", fc, "-map", "[vout]"]
        else:
            cmd += ["-vf", vf]
        tmp_out = render_tmp_path(out)
        cmd += ["-frames:v", str(frames), "-c:v", "libx264", "-preset", RENDER_PRESET, "-crf", RENDER_CRF,
                "-r", str(FPS)] + CLIP_PIX_ARGS + COLOR_META_ARGS + [tmp_out]
        # РЕАЛЬНЫЙ баг, пойманный на реальном продакшн-рендере (не гипотеза):
        # stderr=subprocess.PIPE здесь НИКОГДА не вычитывался, пока родитель
        # покадрово пишет сырое видео в stdin ниже — классический subprocess
        # deadlock: если ffmpeg успевает написать в stderr больше системного
        # лимита пайпа (обычно 64КБ на Linux) ДО того, как родитель дозапишет
        # все кадры, ffmpeg блокируется на записи в свой заполненный stderr,
        # родитель блокируется на proc.stdin.write() — оба ждут друг друга
        # НАВСЕГДА. Не зависит от содержимого фото/fps/модели — только от
        # того, сколько именно диагностики ffmpeg успел написать для
        # конкретного клипа, поэтому и выглядело "случайным" (не каждый
        # клип, только те, что перешли порог буфера). Критично: это блокирует
        # proc.stdin.write() ВНУТРИ цикла ниже — proc.wait(timeout=60) дальше
        # по коду вообще не успевает сработать, до него не доходит.
        # Файл вместо пайпа — стандартный фикс: запись в файл не имеет
        # аналогичного лимита буфера, ffmpeg никогда не блокируется на нём.
        stderr_path = render_tmp_path(out) + ".stderr.log"
        stderr_f = open(stderr_path, "wb")
        proc = subprocess.Popen(cmd, stdin=subprocess.PIPE,
                                 stdout=subprocess.DEVNULL, stderr=stderr_f)

        for frame_i in range(frames):
            t = frame_i / frames
            eased = 3 * t ** 2 - 2 * t ** 3   # smoothstep — тот же профиль, что у zoompan-версии
            zoom = (ZOOM_FLOOR + delta * eased) if zoom_in else (max_zoom - delta * eased)
            pan_px = pan_amt_frac * eased * min(cw, ch) * 0.5 * ((1 - 1 / zoom))

            map_x0 = cx + (ox_grid - WIDTH / 2) / zoom + dx * pan_px
            map_y0 = cy + (oy_grid - HEIGHT / 2) / zoom + dy * pan_px
            map_x0 = np.clip(map_x0, 0, cw - 1)
            map_y0 = np.clip(map_y0, 0, ch - 1)

            # warp_depth, а НЕ depth: геометрию двигаем по сглаженной карте
            # (см. PARALLAX_WARP_SIGMA_FRAC) — резкий край карты глубины и
            # есть источник разрыва картинки на силуэтах.
            d_here = cv2.remap(warp_depth, map_x0, map_y0, interpolation=cv2.INTER_LINEAR,
                                borderMode=cv2.BORDER_REPLICATE)
            extra = (d_here - 0.5) * parallax_px * eased   # центрировано: ближе/дальше среднего
            # 3D-репроекция (не только офсет при пане, но и СКОРОСТЬ ЗУМА
            # по глубине): d_here уже известен на "базовой" (единый zoom)
            # позиции — используем его как приближение реальной глубины
            # источника (двухпроходная аппроксимация, честный mesh-warp
            # избыточен для этой задачи). zoom_gain > 1 для близких
            # пикселей (d_here -> 1) — под push-in они растут БЫСТРЕЕ
            # среднего, зеркально для дальних (d_here -> 0) — это и есть
            # разница между "камера едет" (старая версия, все пиксели
            # растут с одной скоростью) и "камера едет СКВОЗЬ сцену с
            # глубиной" (ближние слои обгоняют дальние).
            zoom_gain = 1.0 + (d_here - 0.5) * depth_zoom_strength * eased
            zoom_gain = np.clip(zoom_gain, 0.88, 1.15)
            map_x = cx + (ox_grid - WIDTH / 2) / (zoom * zoom_gain) + dx * pan_px + dx * extra
            map_y = cy + (oy_grid - HEIGHT / 2) / (zoom * zoom_gain) + dy * pan_px + dy * extra
            # Лёгкий поворот кадра (roll) — независимая от зума/пана степень
            # свободы: камера не строго на рельсах, а слегка меняет угол.
            # Амплитуда мала (умещается в запас холста PARALLAX_MARGIN=1.5,
            # проверено вживую на отсутствие смазанных краёв), направление —
            # детерминировано по хэшу фото.
            if tilt_theta_max != 0.0:
                theta = tilt_theta_max * eased
                cos_t, sin_t = np.float32(math.cos(theta)), np.float32(math.sin(theta))
                rel_x, rel_y = map_x - cx, map_y - cy
                map_x = cx + rel_x * cos_t - rel_y * sin_t
                map_y = cy + rel_y * cos_t + rel_x * sin_t
            map_x = np.clip(map_x, 0, cw - 1)
            map_y = np.clip(map_y, 0, ch - 1)

            frame = cv2.remap(canvas, map_x, map_y, interpolation=cv2.INTER_LINEAR,
                               borderMode=cv2.BORDER_REPLICATE)
            if fg_alpha is not None:
                # Тот же map_x/map_y (единая геометрия варпа не меняется) —
                # только источник для "того, что за передним планом" теперь
                # уже заполненный инпейнт-фон, а не растянутая текстура.
                frame_bg = cv2.remap(bg_plate, map_x, map_y, interpolation=cv2.INTER_LINEAR,
                                      borderMode=cv2.BORDER_REPLICATE)
                alpha = cv2.remap(fg_alpha, map_x, map_y, interpolation=cv2.INTER_LINEAR,
                                   borderMode=cv2.BORDER_REPLICATE)[:, :, None]
                frame = (frame.astype(np.float32) * alpha
                         + frame_bg.astype(np.float32) * (1.0 - alpha)).astype(np.uint8)
            proc.stdin.write(frame.tobytes())

        proc.stdin.close()
        proc.wait(timeout=60)
        stderr_f.close()
        stderr_f = None
        if proc.returncode != 0:
            with open(stderr_path, "rb") as f:
                err_tail = f.read().decode(errors="replace")[-200:]
            print(f"  параллакс-рендер не встал ({os.path.basename(out)}): {err_tail}")
            finalize_render(tmp_out, out, False)
            return False
        # Без ретрая здесь намеренно — покадровый python-цикл с depth-моделью
        # на порядок дороже по времени, чем zoompan-версия, а у вызывающего
        # кода (main()) УЖЕ есть готовый fallback на дешёвый kenburns() при
        # False. Достаточно честно вернуть False на битом файле — верификация
        # ffprobe тут заменяет ретрай, не дублирует его.
        ok, reason, _ = verify_clip(tmp_out, dur)
        if not ok:
            print(f"  параллакс-файл не прошёл проверку ({os.path.basename(out)}): {reason}")
            finalize_render(tmp_out, out, False)
            return False
        return finalize_render(tmp_out, out, True)
    except Exception as e:
        print(f"  параллакс сорвался ({os.path.basename(out)}): {type(e).__name__} {e}")
        finalize_render(render_tmp_path(out), out, False)
        return False
    finally:
        # Раньше при сбое ПОСРЕДИ покадрового цикла (BrokenPipeError на
        # stdin.write, таймаут на wait) дочерний ffmpeg не убивался вообще —
        # завис бы висячим процессом до конца сессии. Гасим его в любом
        # случае, если он ещё жив к выходу из функции.
        if proc is not None and proc.poll() is None:
            try:
                proc.kill()
                proc.wait(timeout=5)
            except Exception:
                pass
        if stderr_f is not None:
            try:
                stderr_f.close()
            except Exception:
                pass
        if stderr_path is not None:
            try:
                os.remove(stderr_path)
            except OSError:
                pass


# Не динамический ramp внутри клипа (это отдельная и намного более сложная
# задача — переменная PTS-кривая), а постоянная скорость по контексту клипа:
# хук чуть быстрее — энергичнее, финал чуть медленнее — снимает напряжение.
SPEED_BIAS = {"HOOK": 1.12, "FINAL": 0.92}


def measure_motion(vid, start, span, samples=4):
    """Дешёвая оценка реального движения в клипе (frame-diff на N мелких
    170x90-кадрах, тот же приём, что measure_luma) — speed ramp (см. ниже)
    имеет смысл только там, где в кадре РЕАЛЬНО что-то происходит (взмах,
    шаг, панорама съёмщика), а не когда объект просто лежит/стоит в кадре —
    там ускорение ничем не мотивировано и выглядит как рывок, не приём.
    0.0 при любой ошибке/отсутствии numpy — ramp тогда просто не применяется
    (безопасный откат на старое поведение, тот же принцип, что PARALLAX_LIBS)."""
    if np is None:
        return 0.0
    try:
        frames = []
        for i in range(samples):
            t = start + span * (i + 0.5) / samples
            tmp = vid + f"._motion_probe_{i}.jpg"
            r = subprocess.run(
                ["ffmpeg", "-y", "-ss", f"{t:.2f}", "-i", vid, "-frames:v", "1",
                 "-vf", "scale=160:90", tmp],
                capture_output=True, timeout=15)
            if r.returncode == 0 and os.path.exists(tmp):
                img = PILImage.open(tmp).convert("L")
                frames.append(np.asarray(img, dtype=np.float32))
                os.remove(tmp)
        if len(frames) < 2:
            return 0.0
        diffs = [float(np.abs(frames[i] - frames[i - 1]).mean()) for i in range(1, len(frames))]
        return (sum(diffs) / len(diffs)) / 255.0
    except Exception:
        return 0.0


# Slow -> fast -> normal внутри ОДНОГО клипа — подчёркивает момент реального
# действия (замах, шаг, столкновение), а не плоская постоянная скорость на
# весь план (то, что уже делает SPEED_BIAS выше на уровне целого клипа).
# Тройка (доля_длительности_на_выходе, множитель_скорости).
SPEED_RAMP_SEGMENTS = [(0.30, 0.85), (0.45, 1.20), (0.25, 1.00)]
SPEED_RAMP_MOTION_THRESHOLD = 0.02   # ниже — план статичен, ramp не гейтится сюда
# РЕАЛЬНЫЙ баг, пойманный на реальном продакшн-рендере (не гипотеза): спид-
# рамп (split -> trim/setpts -> concat) в паре с film_look() (свой отдельный
# split/gblur=sigma=14/blend для bloom-эффекта, см. film_look()) вешает
# ffmpeg на источниках с аномально высоким fps (60/1, 60000/1001) —
# воспроизведено напрямую бисекцией: голый ramp без film_look — 20с, ramp+
# деффликер — 19с, ramp+film_look — не укладывается в 90с. На обычных
# ~24-30fps источниках та же связка (156 других клипов того же эпизода)
# отрабатывает штатно — проблема именно в комбинации высокого fps с
# вложенными split/concat узлами графа, не в film_look()/ramp по отдельности.
# Порог с запасом выше стандартных 24/25/30fps стока, ниже проблемных 60fps.
# 60fps-исходники и так часто сняты specifically под готовое замедление —
# пропуск доп. спид-рампа на них не потеря приёма, разумный трейд-офф.
SPEED_RAMP_MAX_SOURCE_FPS = 40.0


def build_speed_ramp_filter(skip, dur, actual, label_in="base", label_out="ramped"):
    """[label_in] -> trim/setpts по SPEED_RAMP_SEGMENTS -> concat -> [label_out],
    как отдельный кусок filter_complex-графа (не обычный -vf, т.к. нужен
    concat нескольких setpts-кусков одного и того же входа). None, если
    исходника не хватает (safety margin) — вызывающий код тогда просто не
    применяет ramp, как есть."""
    needed = dur * sum(frac * mult for frac, mult in SPEED_RAMP_SEGMENTS)
    if actual - skip < needed + 0.05:
        return None
    n = len(SPEED_RAMP_SEGMENTS)
    # Один и тот же [label_in] нельзя подать входом сразу в 3 независимых
    # trim (ffmpeg не фанаутит именованный pad автоматически) — явный split.
    split_labels = [f"{label_out}_s{i}" for i in range(n)]
    parts = [f"[{label_in}]split={n}{''.join(f'[{s}]' for s in split_labels)}"]
    labels, pos = [], skip
    for i, (frac, mult) in enumerate(SPEED_RAMP_SEGMENTS):
        out_d = dur * frac
        src_d = out_d * mult
        lbl = f"{label_out}{i}"
        # Motion blur ТОЛЬКО на реально ускоренном (mult>1) сегменте — без
        # смаза ускорение через голый setpts выглядит цифровым рывком
        # (кадры просто чаще пропускаются), со смазом читается как
        # операторский приём. Замедленный/нормальный сегмент не трогаем —
        # там лишнее размытие только портит резкость, которую специально
        # вернули unsharp'ом (см. film_look). tmix не меняет число кадров/
        # длительность — безопасно вставлять здесь без пересчёта таймингов.
        blur = ",tmix=frames=3:weights='1 2 1'" if mult > 1.0 else ""
        parts.append(
            f"[{split_labels[i]}]trim=start={pos:.3f}:duration={src_d:.3f},"
            f"setpts=PTS-STARTPTS,setpts={1 / mult:.5f}*PTS{blur}[{lbl}]")
        labels.append(f"[{lbl}]")
        pos += src_d
    parts.append(f"{''.join(labels)}concat=n={len(labels)}:v=1:a=0[{label_out}]")
    return ";".join(parts)


def detect_scene_change_offset(vid, max_skip, scene_threshold=0.12):
    """Сцен-анализ вместо чисто произвольного хэш-пропуска (см. video_render):
    ищем РЕАЛЬНЫЙ момент смены кадра/начала движения в допустимом окне
    [0, max_skip] штатным ffmpeg-детектором сцен (select=gt(scene,THRESH) —
    честный frame-diff, не полноценный optical flow, но быстро и без новых
    зависимостей). Берём САМУЮ ПОЗДНЮЮ найденную смену в пределах окна —
    максимально используем допустимый запас, но приземляемся точно на
    реальное событие в кадре, а не на случайное место.

    Порог уверенности: сцен не найдено (статичный до самого края план,
    либо анализ не удался) -> None, вызывающий код откатывается на старый
    детерминированный хэш-пропуск — то же safety-поведение, что у
    anchor-кропа/saliency (см. resolve_crop_anchor)."""
    try:
        r = subprocess.run(
            ["ffmpeg", "-i", vid, "-t", f"{max_skip:.2f}", "-vf",
             f"select='gt(scene\\,{scene_threshold})',showinfo", "-f", "null", "-"],
            capture_output=True, text=True, timeout=30)
        times = [float(m) for m in re.findall(r"pts_time:([\d.]+)", r.stderr)]
        candidates = [t for t in times if 0.1 <= t <= max_skip]
        return max(candidates) if candidates else None
    except Exception:
        return None


def video_render(vid, out, dur, title=None, stat=None, section="", stat_variant=0,
                  brightness_bias=0.0, energy_bias=0.0, stat_delay=0.0, levels=None, wb=None,
                  grain_scale=1.0, handheld=False, captions=None, ffmpeg_threads=None):
    """Аналог kenburns(), но для стокового видео: без zoompan (движение уже
    есть в кадре), заливка кадра целиком + обрезка (не letterbox), растяжение
    по времени, если исходный ролик короче нужной длительности.

    handheld — лёгкая ручная тряска (C3): у фото уже есть film weave
    (WOBBLE_AMP_CANVAS_PX), у видео-стока движения камеры не было вообще —
    боевые сцены на стоке выглядели подозрительно гладко (будто со штатива).
    Заказывается по контенту (ACTION_WORDS в тексте блока, см. main()), не
    на каждый видео-кадр — на спокойных сюжетах тряска ничем не мотивирована.

    Speed ramp (slow->fast->normal, SPEED_RAMP_SEGMENTS) — отдельный путь
    через -filter_complex (нужен concat нескольких setpts-кусков ОДНОГО
    входа, обычный -vf так не умеет). Применяется только когда есть и запас
    исходника, и реальное движение в кадре (measure_motion) — иначе тихо
    падаем обратно на старый -vf путь ниже."""
    try:
        actual = get_media_duration(vid)
    except Exception:
        actual = dur
    # Заказ в кадрах — та же причина, что в kenburns(): точная единица вместо
    # сравнения дробных секунд (см. комментарий у -frames:v ниже).
    frames = max(1, int(round(dur * FPS)))
    h = int(hashlib.md5(vid.encode()).hexdigest()[:8], 16)
    if handheld:
        # Небольшой запас (3.5%) сверх целевого кадра под тряску — тот же
        # принцип, что PARALLAX_MARGIN у фото, просто меньше (тут не нужно
        # места под пан/зум, только под дрожание в несколько пикселей).
        ov_w, ov_h = round(WIDTH * 1.035), round(HEIGHT * 1.035)
        amp = 6.0
        ph1, ph2 = ((h >> 3) % 628) / 100.0, ((h >> 11) % 628) / 100.0
        shake_x = f"{amp:.1f}*sin(2*PI*t*0.9+{ph1:.2f})+{amp*0.6:.1f}*sin(2*PI*t*2.3+{ph2:.2f})"
        shake_y = f"{amp:.1f}*sin(2*PI*t*1.1+{ph2:.2f})+{amp*0.6:.1f}*sin(2*PI*t*2.7+{ph1:.2f})"
        scale_crop = (f"scale={ov_w}:{ov_h}:force_original_aspect_ratio=increase,"
                      f"crop={WIDTH}:{HEIGHT}:x='({ov_w}-{WIDTH})/2+{shake_x}':"
                      f"y='({ov_h}-{HEIGHT})/2+{shake_y}',setsar=1")
    else:
        scale_crop = f"scale={WIDTH}:{HEIGHT}:force_original_aspect_ratio=increase,crop={WIDTH}:{HEIGHT},setsar=1"
    if DEFLICKER_ENABLED:
        # ПОСЛЕ scale/crop (работает на целевом разрешении, не на исходнике —
        # дешевле, порядок с setpts ниже не важен: deflicker смотрит на
        # ПОСЛЕДОВАТЕЛЬНОСТЬ кадров, setpts меняет только PTS-метки, не сам
        # контент/порядок кадров), ДО film_look() — творческий грейд видит уже
        # сглаженный по яркости кадр, не сырой источник.
        scale_crop += f",{DEFLICKER_FILTER.rstrip(',')}"
    bias = next((v for k, v in SPEED_BIAS.items() if section.startswith(k)), 1.0)
    # Стоковое видео часто начинается со статичного/вялого кадра до того, как
    # начнётся реальное движение (панорама разгоняется, руки только подносят
    # предмет к камере) — первая секунда почти всегда самая скучная в клипе.
    # Пропуск возможен только если есть запас (actual заметно больше dur) —
    # иначе откусили бы от нужной длительности и пришлось бы растягивать
    # (setpts) остаток, что и так уже отдельная ветка ниже. Детерминированный
    # джиттер по хэшу файла — не одна и та же доля пропуска на каждом клипе.
    skip = 0.0
    if actual - dur > 0.6:
        max_skip = min(1.6, (actual - dur) * 0.5)
        scene_skip = detect_scene_change_offset(vid, max_skip)
        skip = scene_skip if scene_skip is not None else (
            max_skip * (0.5 + ((h >> 20) % 1000) / 1000.0 * 0.5))

    ramp_filter = None
    margin_needed = dur * sum(frac * mult for frac, mult in SPEED_RAMP_SEGMENTS)
    if actual - skip >= margin_needed + 0.05:
        src_fps = get_media_fps(vid)
        # SPEED_RAMP_MAX_SOURCE_FPS — см. докстринг константы (реальный
        # зависший рендер на 60fps-стоке, не гипотеза). src_fps=None
        # (ffprobe не смог определить) -> не гейтим, прежнее поведение.
        if src_fps is None or src_fps <= SPEED_RAMP_MAX_SOURCE_FPS:
            motion = measure_motion(vid, skip, min(dur, actual - skip))
            if motion >= SPEED_RAMP_MOTION_THRESHOLD:
                ramp_filter = build_speed_ramp_filter(skip, dur, actual)

    tmp_out = render_tmp_path(out)
    if ramp_filter:
        tail = film_look(h, section, brightness_bias, energy_bias, levels, wb)
        full_tail = tail
        if title or stat or captions:
            full_tail = add_overlays(tail, dur, title, stat, stat_variant, stat_delay)
            full_tail = add_kinetic_captions(full_tail, captions)
        cmd = ["ffmpeg", "-y", "-i", vid]
        if GRAIN_ENABLED:
            cmd += ["-stream_loop", "-1", "-i", GRAIN_LOOP_PATH]
            filter_complex = (f"[0:v]{scale_crop}[base];{ramp_filter};"
                               f"[ramped]{full_tail}[gr_in];{grain_blend_complex('gr_in', 1, 'vout', grain_scale)}")
        else:
            filter_complex = f"[0:v]{scale_crop}[base];{ramp_filter};[ramped]{full_tail}[vout]"
        cmd += ["-filter_complex", filter_complex,
               "-map", "[vout]", "-frames:v", str(frames), "-an",
               "-c:v", "libx264", "-preset", RENDER_PRESET, "-crf", RENDER_CRF,
               "-r", str(FPS)] + CLIP_PIX_ARGS + COLOR_META_ARGS
        if ffmpeg_threads:
            cmd += ["-threads", str(ffmpeg_threads)]
        cmd += [tmp_out]
        ok, reason = run_ffmpeg_with_retry(
            lambda: subprocess.run(cmd, capture_output=True, text=True, timeout=render_timeout_sec(dur)),
            tmp_out, dur, os.path.basename(out))
        if ok:
            return finalize_render(tmp_out, out, True)
        print(f"  speed ramp не встал на видео ({os.path.basename(out)}): {reason} — рисую без ramp")

    vf_base = scale_crop
    setpts_factor = None
    if actual < dur - 0.05:
        setpts_factor = dur / max(actual, 0.1)   # уже растягиваем нехватку — bias не добавляем поверх
    elif bias != 1.0 and actual >= dur * bias:
        setpts_factor = 1.0 / bias
    if setpts_factor is not None:
        vf_base += f",setpts={setpts_factor:.5f}*PTS"
    vf_base += f",{film_look(h, section, brightness_bias, energy_bias, levels, wb)}"
    vf_overlay = None
    if title or stat or captions:
        vf_overlay = add_overlays(vf_base, dur, title, stat, stat_variant, stat_delay)
        vf_overlay = add_kinetic_captions(vf_overlay, captions)

    def render(vf):
        cmd = ["ffmpeg", "-y"]
        if skip > 0.05:
            cmd += ["-ss", f"{skip:.2f}"]
        cmd += ["-i", vid]
        if GRAIN_ENABLED:
            cmd += ["-stream_loop", "-1", "-i", GRAIN_LOOP_PATH]
            fc = f"[0:v]{vf}[gr_in];{grain_blend_complex('gr_in', 1, 'vout', grain_scale)}"
            cmd += ["-filter_complex", fc, "-map", "[vout]"]
        else:
            cmd += ["-vf", vf]
        cmd += ["-frames:v", str(frames), "-an",
                "-c:v", "libx264", "-preset", RENDER_PRESET, "-crf", RENDER_CRF,
                "-r", str(FPS)] + CLIP_PIX_ARGS + COLOR_META_ARGS
        if ffmpeg_threads:
            cmd += ["-threads", str(ffmpeg_threads)]
        cmd += [tmp_out]
        return subprocess.run(cmd, capture_output=True, text=True, timeout=render_timeout_sec(dur))

    label = os.path.basename(out)
    if vf_overlay:
        ok, reason = run_ffmpeg_with_retry(lambda: render(vf_overlay), tmp_out, dur, label)
        if ok:
            return finalize_render(tmp_out, out, True)
        if not _looks_like_drawtext_failure(reason):
            # См. _looks_like_drawtext_failure — тот же принцип, что kenburns().
            print(f"  [{label}] рендер видео с подписями не удался ({reason}) — "
                  f"это не про drawtext, не откатываюсь на версию без них")
            return finalize_render(tmp_out, out, False)
        print(f"  титр/плашка не встали на видео ({label}): {reason} — рисую без них")
    ok, reason = run_ffmpeg_with_retry(lambda: render(vf_base), tmp_out, dur, label)
    if not ok:
        print(f"  [{label}] рендер видео не удался после {RENDER_RETRY_ATTEMPTS} попыток: {reason}")
    return finalize_render(tmp_out, out, ok)


VIDEO_RELEVANCE_MAX_TRIES = 3  # сколько видео-кандидатов реально СКАЧАТЬ и
                                # проверить на релевантность, прежде чем
                                # сдаться (тот же принцип, что
                                # PHOTO_DEDUP_MAX_TRIES у фото — здесь
                                # меньше, видео тяжелее по трафику/времени)
# Реальный, найденный вживую случай (27 августа, videos/_test20s, слот 7,
# ПОСЛЕ добавления video_sharpness_ok в гейт релевантности): при 8 запросах
# пула round-robin-чередование (zip_longest) даёт КАЖДОМУ запросу только
# ОДНУ попытку в пределах try_budget=8 (см. try_budget ниже: max(3,8)=8,
# min(10,8)=8) — если у ПЕРВОГО кандидата "sword blade close up" сорвался
# новый гейт резкости (частый случай — экшн-сток по мечам почти всегда с
# motion-blur, прямая проверка вживую: 4 из первых 4 кандидатов не прошли
# резкость), до второго кандидата ТОЙ ЖЕ темы перебор физически не доходит
# — и слот получает видео из СОВСЕМ ДРУГОГО запроса пула (гантель вместо
# занесённого клинка), semantically разгромно проигрывающее непроверенному
# 5-му кандидату (id=855260 в прямой проверке — резкий, sentence_relevance
# 0.118 против отданного варианта). Тот же класс проблемы, что уже была
# закрыта в этом же файле для ДРУГОГО бюджета (комментарий "РЕАЛЬНЫЙ баг,
# найденный покадровым просмотром" ниже, про кухонные весы) — гейт стал
# строже, бюджет под него не подрос. 10->30: та же ЛОГИКА компромисса, что
# уже применена к PHOTO_DEDUP_MAX_TRIES (6->20) — не буквальное число из
# внешнего аудита, обоснованный запас (round-robin из 8 запросов теперь
# реально доходит до ~3-4 попытки на запрос, а не только до первой).
VIDEO_RELEVANCE_MAX_TRIES_HARD_CAP = 30


def _video_relevance_max_tries_for(index):
    return VIDEO_RELEVANCE_MAX_TRIES if index < FAST_MODE_START_INDEX else FAST_VIDEO_RELEVANCE_MAX_TRIES


def _video_relevance_max_tries_hard_cap_for(index):
    return (VIDEO_RELEVANCE_MAX_TRIES_HARD_CAP if index < FAST_MODE_START_INDEX
            else FAST_VIDEO_RELEVANCE_MAX_TRIES_HARD_CAP)


VIDEO_MIN_LUMA_HARD = 0.06     # ниже — кадр практически чёрный, отбраковка
VIDEO_PREFER_MIN_LUMA = 0.18   # ниже — кадр читается плохо, уступает более светлому
_PEXELS_VIDEO_SEARCH_CACHE = {}


def _pexels_search_videos(api_query):
    """Видео-выдача Pexels с кэшем на процесс — та же причина и та же
    механика, что у _pexels_search_photos (см. её докстринг): без кэша сбор
    пула из всех запросов секции упёрся бы в квоту 200/час."""
    if api_query in _PEXELS_VIDEO_SEARCH_CACHE:
        return _PEXELS_VIDEO_SEARCH_CACHE[api_query]
    q = urllib.parse.quote(api_query)
    req = urllib.request.Request(
        f"https://api.pexels.com/videos/search?query={q}&per_page=80&orientation=landscape",
        headers={"Authorization": PEXELS_API_KEY, "User-Agent": UA})
    with urllib.request.urlopen(req, timeout=15) as r:
        data = json.load(r)
    videos = data.get("videos") or []
    _PEXELS_VIDEO_SEARCH_CACHE[api_query] = videos
    return videos


def pexels_video(query, index, used_ids=None, used_hashes=None, action_qualifier=None,
                  extra_queries=None, sentence_score_fn=None, text_key=None, arbiter_text=None,
                  is_opening_shot=False):
    """Раньше брала ПЕРВОЕ ещё не показанное видео из выдачи без единой
    проверки релевантности/риска (реальный, ранее не закрытый структурный
    пробел, найденный внешним аудитом + прямой проверкой на реальном
    ролике — см. коммит: фото-путь через is_relevant_candidate() уже давно
    гейтит кандидатов, видео-путь был полностью незащищён, из-за чего
    восточноазиатский клинок в видео-B-roll проходил без единой проверки).
    Теперь — тот же принцип, что pexels_photo(): перебираем выдачу
    (до VIDEO_RELEVANCE_MAX_TRIES реально скачанных кандидатов), для
    каждого извлекаем кадр-пробник (extract_video_probe_frame() — устойчив
    к чёрному лидеру/fade-in) и прогоняем через is_relevant_candidate() —
    тот же relevance/risky-margin/visual-domain-guard гейт, что у фото.
    Ни один слот не остаётся пустым: если НИ ОДИН кандидат не прошёл гейт
    (или пробник не извлёкся — тогда гейт просто не может сработать, кандидат
    считается допустимым, тот же безопасный откат, что у остальных
    опциональных CLIP-проверок), в кэш уходит первый реально скачанный —
    честная деградация, не сорванный слот. Из доступных video_files берём
    ближайшее по ширине к целевому 1920 — не тянем 4K ради 1080p-выхода.

    used_hashes — общий (на весь эпизод, тот же список, что пробрасывается в
    pexels_photo()) aHash-дедуп. Раньше видео сверялось с уже показанным
    медиа ТОЛЬКО по ID Pexels — визуальный дубль под другим ID (частый
    случай: одна и та же студийная съёмка продаётся и фотостоком, и
    клипом) проходил как новый. Пробный кадр здесь и так извлекается ради
    проверки релевантности — лишних вычислений дедуп не добавляет, только
    ahash() уже открытого файла. Кандидат, прошедший relevance, но визуально
    похожий на уже выбранное медиа, не отбрасывается — он остаётся вторым
    приоритетом (relevant_dup_fallback): дедуп не должен пустить слот
    впустую, только предпочесть менее похожий вариант, если он есть среди
    уже скачанных попыток."""
    global PEXELS_BROKEN
    cache = os.path.join(TEMP_FOLDER, "pexels_video_cache")
    os.makedirs(cache, exist_ok=True)
    # gate_sig — см. pexels_photo()/candidate_gate_signature(): без него улучшение
    # анахронизм-гварда не переоценивает уже закэшированное видео, отобранное
    # по старым правилам (реальный найденный случай — катана в кэше этого файла).
    # text_key — та же причина и та же механика, что в pexels_photo() (см. её
    # докстринг у qkey): без этого правка текста сценария может не поменять
    # ни запрос, ни ключ кэша, и видео под старую фразу тихо остаётся стоять.
    qkey = "|".join([query] + sorted(q for q in (extra_queries or []) if q and q != query)
                     + ([text_key] if text_key else []))
    qhash = hashlib.md5(qkey.encode()).hexdigest()[:8]
    gate_sig = candidate_gate_signature().split(":", 1)[-1]
    cf = os.path.join(cache, f"{index:04d}_{qhash}_{gate_sig}.mp4")
    # size>0, не просто exists — см. atomic_url_download: реальный случай,
    # пойманный вживую на этом эпизоде — 0-байтный файл от прерванной
    # закачки прошлого прогона тихо "проходил" как готовый кэш и ронял
    # блок из ролика без единой строчки в логе (ffmpeg на пустом файле не
    # печатает никакого "непредвиденного сбоя" уровня main() — падает
    # молча внутри рендер-функции).
    if os.path.exists(cf) and os.path.getsize(cf) > 0:
        return cf
    if not PEXELS_API_KEY:
        return None
    try:
        # Пул из ВСЕХ запросов секции — то же, что уже сделано для фото
        # (см. extra_queries в pexels_photo). До этого видео-слот жёстко
        # держался одного позиционно доставшегося запроса, и никакого
        # смыслового выбора у него не было вообще: на реальном рендере
        # фраза "сколько весил настоящий боевой меч" получила зал
        # кинотеатра, потому что позиции достался запрос про кино.
        pool_queries = [query] + [q for q in (extra_queries or []) if q and q != query]
        per_query = []
        for pq in pool_queries:
            # action_qualifier — движение из текста блока (см.
            # action_video_qualifier): только в строку к API, не в ключ кэша
            # и не в relevance-скоринг, как и disambiguate_search_query().
            api_q = apply_action_qualifier(disambiguate_search_query(pq), action_qualifier)
            lst = []
            for v in _pexels_search_videos(api_q):
                v = dict(v)
                v["_origin_query"] = pq
                lst.append(v)
            per_query.append(lst)
        # Чередование по запросам — см. тот же комментарий в pexels_photo():
        # перебирается лишь VIDEO_RELEVANCE_MAX_TRIES кандидатов, и при
        # склейке "подряд" все они были бы из первого запроса. Реально
        # найдено покадрово: фраза "сколько весил настоящий боевой меч"
        # получала зал кинотеатра, потому что позиции достался запрос про
        # кино и до запросов про меч перебор не доходил.
        videos = []
        seen_ids = set()
        for row in itertools.zip_longest(*per_query):
            for v in row:
                if v is None:
                    continue
                vid = v.get("id")
                if vid in seen_ids:
                    continue
                seen_ids.add(vid)
                videos.append(v)
        if not videos:
            return None
        ordered = videos
        if used_ids is not None:
            ordered = ([v for v in videos if v.get("id") not in used_ids]
                       + [v for v in videos if v.get("id") in used_ids])
        # Три уровня приоритета для кандидата, который не оказался
        # немедленным победителем: relevant+уникальный (лучший, принимается
        # сразу) > relevant, но визуальный дубль уже показанного >
        # первый вообще скачанный (старое поведение "ни один не прошёл
        # relevance" — честная деградация, не пустой слот).
        dup_fallback = None    # (путь, id, hash) — прошёл relevance, похож на уже показанное
        plain_fallback = None  # (путь, id, hash) — первый скачанный, безопасная сетка
        # Кандидаты, прошедшие все гейты, больше НЕ принимаются "первым
        # попавшимся": собираются и сравниваются по смыслу полной фразы
        # (sentence_score_fn) и читаемости кадра — так же, как у фото.
        good = []              # [(sentence_score, luma_ok, путь, id, hash)]
        tries = 0
        # РЕАЛЬНЫЙ баг, найденный покадровым просмотром готового рендера
        # (не гипотеза): VIDEO_RELEVANCE_MAX_TRIES=3 калибровалась под
        # СТАРУЮ логику "до 3 попыток на ОДИН запрос". После расширения пула
        # (см. extra_queries выше) список кандидатов чередуется по ВСЕМ
        # запросам секции — на HOOK из 8 запросов бюджет в 3 попытки
        # покрывает буквально первые 3 запроса из 8 и ни разу не доходит до
        # "warrior on horseback with sword". На реальном рендере это отдало
        # фразу "герой заносит клинок... враг падает" видео с кухонными
        # весами — единственным кандидатом, до которого хватило попыток,
        # хотя по смыслу разгромно проигрывающим не опробованному всаднику
        # с занесённым мечом. С пулом бюджет — минимум одна попытка на
        # каждый запрос пула (иначе большинство запросов не участвует в
        # сравнении вообще), с потолком против неограниченного трафика на
        # секции с большим числом авторских запросов.
        try_budget = _video_relevance_max_tries_for(index)
        if sentence_score_fn is not None:
            try_budget = min(_video_relevance_max_tries_hard_cap_for(index),
                             max(_video_relevance_max_tries_for(index), len(pool_queries)))
        for v in ordered:
            if tries >= try_budget:
                break
            files = [f for f in (v.get("video_files") or [])
                     if f.get("file_type") == "video/mp4" and f.get("width")]
            if not files:
                continue
            best = min(files, key=lambda f: abs(f["width"] - WIDTH))
            trial = cf + f".trial_{v.get('id')}.mp4"
            try:
                vid_req = urllib.request.Request(best["link"], headers={"User-Agent": UA})
                atomic_url_download(vid_req, trial, timeout=40)
            except Exception:
                continue
            tries += 1
            probe, cleanup = extract_video_probe_frame(trial)
            relevant = True
            cand_hash = None
            sent_score = 0.0
            cand_luma = None
            if probe is not None:
                try:
                    # Гейт сверяется с запросом ЭТОГО БЛОКА (`query`), не с тем,
                    # из которого кандидат приплыл в общий пул — тот же разбор и
                    # та же причина, что подробно расписаны у фото-пути в
                    # pexels_photo() (кандидат из соседнего запроса секции
                    # проходил «по своему» и попадал в чужой по смыслу блок).
                    relevant = is_relevant_candidate(probe, query)
                    if used_hashes is not None:
                        try:
                            cand_hash = ahash(probe)
                        except Exception:
                            cand_hash = None
                    try:
                        cand_luma = measure_luma(probe)
                    except Exception:
                        cand_luma = None
                    if relevant and sentence_score_fn is not None:
                        try:
                            s = sentence_score_fn(probe)
                            sent_score = float(s) if s is not None else 0.0
                        except Exception:
                            sent_score = 0.0
                        # SAME_QUERY_BONUS (см. visual_director.py) — тот же
                        # фикс, что и у фото: кандидат из ЧУЖОГО запроса пула
                        # не должен побеждать кандидата, назначенного этому
                        # слоту ПО СМЫСЛУ, только за счёт того, что общая
                        # тема эпизода перетягивает sentence_score. visual_
                        # director — модуль, не глобальная переменная этой
                        # функции (та живёт только внутри main()) — ленивый
                        # импорт, тот же fail-open паттерн, что у
                        # visual_qc_bonus() в visual_director.py.
                        if v.get("_origin_query") == query:
                            try:
                                import visual_director as _vd
                                sent_score += _vd.SAME_QUERY_BONUS
                            except Exception:
                                pass
                        # OPENING_AESTHETIC_WEIGHT (см. visual_director.py) —
                        # та же архитектурная причина, что у фото-пути:
                        # семантика почти всегда предпочитает буквальный, но
                        # скучный кандидат раньше, чем эстетика успевает
                        # сравниться — для открывающего кадра ролика решает
                        # ДАЖЕ без VLM-арбитра/Gemini. probe — реальный кадр
                        # ЭТОГО видео-кандидата, ещё не удалён (см. finally
                        # ниже) — тот же aesthetic_score(), что фото-путь.
                        if is_opening_shot:
                            try:
                                import visual_director as _vd
                                av = aesthetic_score(probe)
                                if av is not None:
                                    norm = max(0.0, min(1.5, (av - _vd.AESTHETIC_NORM_MIN) / _vd.AESTHETIC_NORM_RANGE))
                                    sent_score += norm * _vd.OPENING_AESTHETIC_WEIGHT
                            except Exception:
                                pass
                finally:
                    if cleanup and os.path.exists(probe):
                        os.remove(probe)
            # Практически чёрный кадр — отбраковываем жёстко: грейд канала
            # темнит и без того, зритель просто не увидит, что показано
            # (реальный случай на рендере — кадр с еле различимой полоской
            # клинка). Порог 0.06 намеренно НИЖЕ реально встреченных тёмных
            # кандидатов (0.113/0.118): осознанно тёмный кадр — часть стиля
            # канала и отбраковываться не должен, режем только то, где
            # разглядеть нечего физически.
            if cand_luma is not None and cand_luma < VIDEO_MIN_LUMA_HARD:
                relevant = False
            luma_ok = 1 if (cand_luma is None or cand_luma >= VIDEO_PREFER_MIN_LUMA) else 0
            # Домен-гвард (анахронизм-защита) — ДОПОЛНИТЕЛЬНО на нескольких
            # кадрах по всей длительности ролика, не только на том же одном
            # пробнике, что уже участвовал в relevant выше: is_relevant_
            # candidate() сама по себе тоже гейтит домен, но ТОЛЬКО на этом
            # первом кадре — реальный найденный случай, когда именно ПЕРВЫЙ
            # кадр был тесным кропом на рукояти без клинка/гарды и гейт
            # ничего не поймал (см. video_domain_guard_violation()). Только
            # когда relevant уже True — на явно нерелевантных candidates,
            # которые и так не пройдут, лишние кадры не тянем.
            if relevant:
                violated, _ = video_domain_guard_violation(trial, query)
                if violated:
                    relevant = False
            # video_sharpness_ok (VIDEO_SHARPNESS_REJECT) — см. её докстринг:
            # реальный найденный случай (videos/_test20s, слот 7) — видео-
            # кандидаты НИКОГДА не проверялись на резкость, только фото. Тот
            # же принцип, что домен-гвард выше: только когда relevant уже
            # True — на заведомо провальных кандидатах лишний многокадровый
            # проход не тянем. False (не None — сбой decode не должен молча
            # пропускать явно смазанное видео) блокирует так же, как домен-
            # анахронизм.
            if relevant:
                sharp_ok = video_sharpness_ok(trial)
                if sharp_ok is False:
                    relevant = False
            is_dup = (cand_hash is not None and used_hashes and
                      min((hamming(cand_hash, uh) for uh in used_hashes), default=99)
                      <= PHOTO_DEDUP_HAMMING)
            if relevant and not is_dup:
                good.append((sent_score, luma_ok, trial, v.get("id"), cand_hash, v.get("_origin_query")))
                # Без смыслового скоринга сравнивать нечего — прежнее
                # поведение "первый прошедший побеждает" (ноль регресса для
                # вызовов без sentence_score_fn). С пулом ранний обрыв по
                # фиксированному числу "хороших" кандидатов — тот же баг,
                # что try_budget выше чинит для попыток скачивания: первые
                # найденные "хорошие" почти всегда из ранних запросов пула
                # (дальние запросы просто не успевают дать кандидата). Обрыв
                # только по исчерпанию try_budget — тот уже ограничен
                # VIDEO_RELEVANCE_MAX_TRIES_HARD_CAP, второй потолок не нужен.
                if sentence_score_fn is None:
                    break
                continue
            if relevant and dup_fallback is None:
                dup_fallback = (trial, v.get("id"), cand_hash)
            elif plain_fallback is None:
                plain_fallback = (trial, v.get("id"), cand_hash)
            else:
                os.remove(trial)
        if good:
            # Читаемость кадра важнее тонкой разницы в смысловом скоре:
            # нерелевантных здесь уже нет (все прошли гейт), а невидимый
            # кадр бесполезен независимо от того, что на нём изображено.
            good.sort(key=lambda g: (g[1], g[0]), reverse=True)
            best = good[0]
            # VLM-АРБИТР (см. shot_director.arbitrate_hook_candidates и
            # _build_video_arbiter_shortlist) — тот же принцип, что уже
            # применён к pexels_photo(): реальный найденный случай (idx4,
            # videos/_test20s, 29 августа) — видео-путь раньше вообще не
            # был подключён к арбитру (только к SAME_QUERY_BONUS в
            # sent_score), и модерн-реконструкция с толпой зрителей/
            # телефонами (не ловится ни CLIP-релевантностью, ни
            # CONTENT_ALT_BLOCKLIST, если alt-текст Pexels не содержит ни
            # одного из его терминов) так и оставалась победителем.
            if (arbiter_text is not None and
                    os.environ.get("VLM_ARBITER_MODE", "off").strip().lower() == "on"):
                # Открывающий кадр — та же логика, что у pexels_photo()
                # (см. is_opening_shot там): шире шорт-лист, критерий
                # эффектности вместо буквальной точности запроса.
                if is_opening_shot:
                    shortlist = _build_opening_video_shortlist(good)
                else:
                    shortlist = _build_video_arbiter_shortlist(good, query)
                if len(shortlist) >= 2:
                    # Реальный найденный баг: shortlist здесь — пути к
                    # ВИДЕОФАЙЛАМ (.mp4), а Gemini vision принимает только
                    # статичные картинки — сырой .mp4 под mime_type=image/*
                    # дал HTTP 400 Bad Request (videos/_test20s, idx4, 29
                    # августа). Пробник уже удалён к этому моменту (см.
                    # finally у extract_video_probe_frame выше) — исходный
                    # видеофайл ещё цел, извлекаем заново ТОЛЬКО для
                    # шорт-листа (не для всего good — дёшево).
                    probes = []
                    for g in shortlist:
                        p, cleanup = extract_video_probe_frame(g[2])
                        if p is not None:
                            probes.append((g, p, cleanup))
                    arbiter_pick = None
                    if len(probes) >= 2:
                        import shot_director
                        arbiter_pick = shot_director.arbitrate_hook_candidates(
                            arbiter_text, [p for _, p, _ in probes],
                            [g[3] for g, _, _ in probes], VIDEO_FOLDER, is_opening=is_opening_shot)
                    if arbiter_pick is not None:
                        match = next((g for g, p, _ in probes if p == arbiter_pick), None)
                        if match is not None:
                            best = match
                    for _, p, cleanup in probes:
                        if cleanup and os.path.exists(p):
                            try:
                                os.remove(p)
                            except OSError:
                                pass
            for g in good:
                if g is best:
                    continue
                try:
                    os.remove(g[2])
                except OSError:
                    pass
            for fb in (dup_fallback, plain_fallback):
                if fb is not None and os.path.exists(fb[0]):
                    try:
                        os.remove(fb[0])
                    except OSError:
                        pass
            os.replace(best[2], cf)
            if used_ids is not None:
                used_ids.add(best[3])
            if used_hashes is not None and best[4] is not None:
                used_hashes.append(best[4])
            return cf
        chosen = dup_fallback or plain_fallback
        if chosen is not None:
            path, vid, cand_hash = chosen
            if chosen is plain_fallback:
                # Ни один кандидат не прошёл relevance-гейт вообще (не
                # только "похож на уже показанное", как у dup_fallback) —
                # тот же случай, что RELEVANCE_GATE_MISSES ловит у фото
                # (см. её докстринг выше). probe уже удалён к этому моменту
                # (extract_video_probe_frame чистит себя сам) — путь ещё цел
                # (это САМ видеофайл, не пробник), поэтому релевантность
                # можно честно перепосчитать один раз на итоговом кадре.
                probe2, cleanup2 = extract_video_probe_frame(path)
                rel = clip_relevance(probe2, query) if probe2 is not None else None
                if cleanup2 and probe2 and os.path.exists(probe2):
                    os.remove(probe2)
                RELEVANCE_GATE_MISSES.append({
                    "index": index, "query": query, "relevance": rel,
                    "threshold": CLIP_RELEVANCE_THRESHOLD, "kind": "video",
                })
                # STOCK_EXHAUSTED_MISSES — см. её докстринг у объявления выше.
                # Мы уже ЗДЕСЬ (chosen is plain_fallback) только когда good
                # пуст И dup_fallback пуст — то есть НИ ОДИН из tries
                # просмотренных кандидатов не прошёл relevant+sharp_ok,
                # независимо от дедупа. Ничего заново считать не нужно —
                # сам факт, что мы в этой ветке, и есть искомый сигнал.
                STOCK_EXHAUSTED_MISSES.append({
                    "index": index, "kind": "video", "query": query,
                    "n_candidates_examined": tries,
                })
            os.replace(path, cf)
            if used_ids is not None:
                used_ids.add(vid)
            if used_hashes is not None and cand_hash is not None:
                used_hashes.append(cand_hash)
            return cf
        return None
    except Exception as e:
        PEXELS_BROKEN = True
        print(f"  Pexels video [{query}]: {e}")
        return None


# Мгновенный рез после stat-плашки. Раньше 0.03с — при FPS=24 это 0.72 кадра,
# то есть физически НЕ короче обычного hardcut: ffmpeg всё равно округлял его
# до того же одного кадра. Один кадр — реальный минимум сетки, и теперь это
# написано честно (ветка в плане переходов остаётся отдельной: смысл разный,
# и при другом FPS значения снова разойдутся).
SNAP_CUT_DUR = 1 / FPS


def quantize_dur_to_frame(d):
    """Длительность -> ближайшее целое число кадров (минимум один кадр)."""
    return max(1, int(round(d * FPS))) / FPS


def quantize_durations_to_frames(durs):
    """Кадровая сетка для ВСЕХ длительностей клипов, с диффузией ошибки
    округления в следующий клип.

    Зачем (реальный, посчитанный рассинхрон, не гипотеза): длительность
    клипа физически не может быть дробной по кадрам — ffmpeg всё равно
    отдаёт целое число кадров. Раньше клипу заказывалось, например, 3.5671с,
    а на выходе получалось 86 кадров = 3.5833с, то есть в среднем +20мс на
    каждый клип В ОДНУ СТОРОНУ. На эпизоде из 400-500 кадров (после
    sub-cuts) это 8-10 секунд систематического ухода видео вперёд от
    голоса, которые потом просто отрезались финальным муксом (-t по длине
    аудио) — то есть последние кадры ролика вообще не доезжали, а картинка
    к концу отставала от текста.

    Диффузия (carry) важнее самого округления: без неё ошибки округления
    (до полукадра каждая) складывались бы случайным блужданием на сотнях
    клипов; с carry суммарная ошибка ВСЕГО таймлайна ограничена полукадром
    (~21мс при 24fps) независимо от числа клипов."""
    out, carry = [], 0.0
    for d in durs:
        target = d + carry
        q = quantize_dur_to_frame(target)
        carry = target - q
        out.append(q)
    return out


def plan_transitions(sections, blocks=None, xfade_dur=XFADE_DUR):
    """План склейки: [(тип_перехода, длительность), ...] длиной len(sections)-1,
    где элемент j описывает переход между клипами j и j+1.

    ЗАЧЕМ ОТДЕЛЬНАЯ ФУНКЦИЯ (реальный баг, а не рефакторинг ради красоты).
    Раньше тип и длительность перехода выбирались ВНУТРИ xfade_chain() по
    хэшу ПУТЕЙ ФАЙЛОВ клипов. А пути содержат params_hash, в который входит
    длительность клипа (см. main()) — то есть узнать план можно было только
    ПОСЛЕ того, как длительности уже посчитаны. Но длительности считаются
    из бюджета нахлёстов, а бюджет — это и есть сумма плана: замкнутый круг.
    Из-за него estimate_xfade_budget() был вынужден брать ВЕРХНЮЮ ГРАНИЦУ
    "обычной" пары (0.1667с) вместо факта, а факт — 85% одного кадра
    (0.0417с). Перебор ~0.12с на каждой обычной склейке; на 300+ обычных
    склейках 40-минутного эпизода это 35+ секунд, на которые видео
    оказывалось ДЛИННЕЕ аудио. Финальный мукс обрезал их по -t, то есть:
    (1) хвост ролика (несколько последних кадров) не попадал в файл вообще,
    (2) картинка накопительно отставала от голоса — к концу эпизода на
    десятки секунд, при том что весь остальной код (alignment.csv,
    section_sync, snap_hook_cuts_to_energy) борется за точность до
    десятых долей секунды.

    Хэш теперь считается от (номер склейки + имена секций) — данных,
    известных ДО выбора файлов. Разнообразие ровно то же (тот же md5, та же
    статистика), круговая зависимость исчезла, и один и тот же план
    используется и для бюджета, и для реальной склейки, и для расчёта
    визуальных стартов подписей — они физически не могут разойтись.

    Логика ветвления — ровно та, что была в xfade_chain() (переход = сигнал
    драматургии): граница секции -> заметный переход; sub-cut -> один кадр;
    сразу после stat-плашки -> snap; хук -> только жёсткие резы; остальное —
    85% hardcut / 15% короткий диссолв."""
    plan = []
    cut_hist, boundary_hist = [], []
    for i in range(1, len(sections)):
        h = int(hashlib.md5(f"xfade:{i}|{sections[i - 1]}|{sections[i]}".encode()).hexdigest()[:8], 16)
        is_boundary = sections[i] != sections[i - 1]
        b_prev = blocks[i - 1] if blocks else None
        b_cur = blocks[i] if blocks else None
        if is_boundary:
            candidate = BOUNDARY_TRANSITIONS[h % len(BOUNDARY_TRANSITIONS)]
            transition = pick_no_repeat(boundary_hist, candidate, BOUNDARY_TRANSITIONS, 1)
            this_dur = xfade_dur
        elif b_cur is not None and b_cur.get("is_subcut"):
            transition, this_dur = "fade", XFADE_DUR_HARD
        elif b_prev is not None and b_prev.get("stat"):
            transition, this_dur = "fade", SNAP_CUT_DUR
        elif b_cur is not None and sections[i].startswith("HOOK"):
            transition, this_dur = "fade", XFADE_DUR_HARD
        else:
            candidate = "hardcut" if (h % 20 >= 3) else XFADE_TRANSITIONS[(h >> 8) % len(XFADE_TRANSITIONS)]
            choice = pick_no_repeat(cut_hist, candidate, ["hardcut"] + XFADE_TRANSITIONS, max_repeat=3)
            this_dur = XFADE_DUR_HARD if choice == "hardcut" else xfade_dur * 0.4
            transition = "fade" if choice == "hardcut" else choice
        plan.append((transition, quantize_dur_to_frame(this_dur)))
    return plan


def xfade_chain(clips, durs, sections, out, xfade_dur=XFADE_DUR, blocks=None, plan=None):
    """Один проход filter_complex с цепочкой xfade между ВСЕМИ соседними
    кадрами — вместо жёсткой склейки. Переход = сигнал драматургии, не
    случайность: раньше тип перехода выбирался чисто хэшем путей файлов,
    без связи со сменой темы/функции блока — dissolve мог случайно попасть
    внутрь одной фразы, hardcut — между разделами. Теперь мотивированно
    (нужен параллельный список blocks — метаданные клипов, is_subcut/stat/
    section; без него откат на старое хэш-разнообразие для обратной
    совместимости):
    - граница секции → dissolve/fadeblack/fadewhite (смена темы)
    - sub-cut внутри одного исходного блока → только hardcut (это один кадр
      мысли, разрезанный на фазы — не повод анонсировать переход)
    - сразу после клипа со stat-плашкой → snap cut (мгновенный, короче
      обычного hardcut — цифра "впечаталась" и тут же сменилась)
    - весь хук → только hardcut (энергия, скорость, никаких dissolve)
    - остальное — 85% hardcut / 15% короткий dissolve (не полный xfade_dur)
    Возвращает (True, итоговая_длительность) или (False, 0.0), если
    что-то пошло не так (тогда main() откатывается на обычный concat -c copy)."""
    n = len(clips)
    if n < 2:
        return False, 0.0
    # План склейки (тип/длительность каждого перехода) считает plan_transitions()
    # — ОДИН источник истины и для бюджета длительностей, и для этой склейки,
    # и для visual_starts подписей (см. её докстринг про круговую зависимость).
    if plan is None:
        plan = plan_transitions(sections, blocks, xfade_dur=xfade_dur)
    parts, prev_label, cum = [], "0:v", durs[0]
    for i in range(1, n):
        transition, this_dur = plan[i - 1]
        offset = max(0.0, cum - this_dur)
        out_label = f"vx{i}" if i < n - 1 else "vout"
        # .6f, не .3f: offset к концу длинного эпизода — тысячи секунд, и
        # округление до миллисекунд может сдвинуть его на кадр относительно
        # плана (ffmpeg переводит offset в кадры). Полукадр при 24fps — 21мс,
        # запас на порядок больше миллисекунды, но печатать точно ничего не
        # стоит, а гарантия появляется.
        parts.append(f"[{prev_label}][{i}:v]xfade=transition={transition}:"
                     f"duration={this_dur:.6f}:offset={offset:.6f}[{out_label}]")
        cum = cum + durs[i] - this_dur
        prev_label = out_label
    cmd = ["ffmpeg", "-y"]
    for c in clips:
        cmd += ["-i", c]
    # Это единственный проход, который видит ВСЮ склейку сразу — то, что
    # уйдёт на YouTube (финальный мукс делает -c:v copy, второго прохода
    # уже не будет). Каждый отдельный клип и так уже CRF 17 (RENDER_CRF, см.
    # kenburns/video_render/parallax_kenburns) — если тут снова ужать до 23,
    # это второе поколение потерь поверх первого, заметное именно на тёмном
    # грейде (градиенты/дым/зерно). FINAL_PASS_PRESET/CRF — разовая цена, не
    # на каждый маленький клип.
    cmd += ["-filter_complex", ";".join(parts), "-map", "[vout]",
            "-c:v", "libx264", "-preset", FINAL_PASS_PRESET, "-crf", FINAL_PASS_CRF,
            "-pix_fmt", "yuv420p", "-r", str(FPS)] + COLOR_META_ARGS + [out]
    # РЕАЛЬНЫЙ пробел, пойманный аудитом того же класса багов, что и
    # SPEED_RAMP_MAX_SOURCE_FPS/parallax stderr-deadlock (см. их докстринги
    # выше): у этого вызова не было НИКАКОГО timeout — при зависании ffmpeg
    # (тот же класс проблем, что и задокументированный ниже "молча роняет
    # кадры и застревает") весь уже отрендеренный за часы прогон терялся бы
    # молча, без единого сигнала. cum — суммарная длительность чанка (до 35
    # клипов на FINAL_PASS_PRESET+FINAL_PASS_CRF (medium+16), тяжелее, чем
    # per-clip RENDER_PRESET+RENDER_CRF (veryfast+17) — щедрый множитель
    # (30x), это последний рубеж защиты от НАСТОЯЩЕГО зависания, не бюджет
    # под скорость.
    try:
        r = subprocess.run(cmd, capture_output=True, text=True,
                            timeout=max(180, cum * 30))
    except subprocess.TimeoutExpired:
        print(f"  xfade-склейка зависла (таймаут {max(180, cum * 30):.0f}с), откат на concat.")
        return False, 0.0
    if r.returncode != 0:
        print("  xfade-склейка не удалась, откат на concat:", r.stderr[-300:])
        return False, 0.0
    # Пойман вживую на 150 клипах (после sub-cuts): ffmpeg возвращает 0
    # (успех), но при очень длинной цепочке последовательных xfade в ОДНОМ
    # filter_complex молча "роняет" кадры (dup=0 drop=20000+ в stderr) и
    # застревает на застывшем кадре с середины ролика — итоговый файл
    # правильной длины (после -shortest/-t на муксе), но 800+ секунд из
    # них заморожены. Return-код тут не индикатор, реальная длительность —
    # индикатор. На ~90 клипах (до sub-cuts) с той же схемой такого не
    # было — это масштабная проблема ffmpeg с очень длинной цепочкой в
    # одном графе, не баг в математике offset/cum (та проверена отдельно).
    try:
        real_dur = get_media_duration(out)
    except Exception:
        real_dur = 0.0
    expected = max(cum, 0.1)
    if real_dur < expected * 0.9 - 2.0:
        print(f"  xfade-склейка вернула 0, но реальная длительность {real_dur:.1f}с "
              f"против ожидаемых {expected:.1f}с (похоже на застревание ffmpeg на "
              f"длинной цепочке xfade) — откат на concat.")
        return False, 0.0
    return True, expected


XFADE_CHUNK_SIZE = 35   # порог чанкования — см. xfade_chain_chunked


def _chunk_bounds(n, sections, chunk_size):
    """(start,end) полуинтервалы индексов клипов на чанки ~chunk_size —
    резать ТОЛЬКО на границах section (там и так планировался заметный
    dissolve/fadeblack/fadewhite, см. xfade_chain — на стыке чанков он
    станет обычным concat-cut, это читается как ещё один hardcut, не как
    потеря приёма, в отличие от разрыва ПОСЕРЕДИНЕ фразы). Защита от
    вырожденного случая (вся секция длиннее 2×chunk_size — например,
    гигантский BODY без внутренних BLOCK) — режем принудительно, не гоняясь
    за границей до бесконечности: маленькая потеря одного перехода лучше
    риска снова упереться в ту же ffmpeg-багу на длинной цепочке."""
    if n <= chunk_size:
        return [(0, n)]
    bounds, pos = [0], 0
    while pos < n:
        target = min(pos + chunk_size, n)
        if target >= n:
            bounds.append(n)
            break
        j = target
        hard_cap = min(pos + chunk_size * 2, n)
        while j < hard_cap and sections[j] == sections[j - 1]:
            j += 1
        bounds.append(j)
        pos = j
    bounds = sorted(set(bounds))
    chunks = list(zip(bounds[:-1], bounds[1:]))
    # xfade_chain() требует минимум 2 клипа (n<2 -> (False, 0.0) сразу) —
    # де-фрагментируем случайный "хвостик" в 1 клип (получается, если
    # граница секции легла ровно на предпоследний индекс) слиянием с
    # соседним чанком, а не оставляем orphan-чанк, гарантированно
    # роняющий всю сборку в откат на concat.
    fixed = []
    for a, b in chunks:
        if b - a < 2 and fixed:
            pa, _ = fixed[-1]
            fixed[-1] = (pa, b)
        else:
            fixed.append((a, b))
    if len(fixed) > 1 and fixed[0][1] - fixed[0][0] < 2:
        (a0, _), (_, b1) = fixed[0], fixed[1]
        fixed[0] = (a0, b1)
        del fixed[1]
    return fixed


def xfade_chain_chunked(clips, durs, sections, out, temp_dir, xfade_dur=XFADE_DUR, blocks=None,
                         chunk_size=XFADE_CHUNK_SIZE):
    """Обёртка над xfade_chain(): на длинной цепочке (150+ клипов после
    sub-cuts) один filter_complex со всеми xfade сразу ловит документированный
    в xfade_chain() баг ffmpeg — молча роняет кадры и застревает на
    застывшем кадре с середины ролика, при том что return-код 0. Раньше
    единственным ответом был полный откат на голый concat — ролик собирался,
    но терял ВСЕ переходы разом. Вместо этого режем на чанки по chunk_size
    (см. _chunk_bounds — только по границам section), каждый чанк — свой
    независимый xfade_chain() (короткая цепочка, баг не всплывает), чанки
    склеиваются -c copy (без потерь, все чанки — один и тот же кодек/
    параметры). Если ХОТЯ БЫ один чанк не собрался — честный откат на
    concat всего ролика, как раньше (лучше без переходов, чем сорванная
    сборка)."""
    n = len(clips)
    bounds = _chunk_bounds(n, sections, chunk_size)
    # Один общий план на весь ролик, чанкам отдаются его СРЕЗЫ: элемент
    # plan[j] описывает переход между глобальными клипами j и j+1, значит
    # внутри чанка [a, b) работают переходы plan[a:b-1] (переход на самом
    # входе чанка не делается вообще — чанки склеиваются concat -c copy,
    # именно это учитывает estimate_xfade_budget()).
    plan = plan_transitions(sections, blocks, xfade_dur=xfade_dur)
    if len(bounds) <= 1:
        return xfade_chain(clips, durs, sections, out, xfade_dur=xfade_dur, blocks=blocks, plan=plan)
    chunk_files, chunk_total = [], 0.0
    for ci, (a, b) in enumerate(bounds):
        cblocks = blocks[a:b] if blocks else None
        cout = os.path.join(temp_dir, f"_xchunk_{ci:03d}.mp4")
        ok, cdur = xfade_chain(clips[a:b], durs[a:b], sections[a:b], cout,
                                xfade_dur=xfade_dur, blocks=cblocks, plan=plan[a:b - 1])
        if not ok:
            print(f"  чанк {ci} ({b - a} клипов) xfade не собрался — вся склейка откатывается на concat")
            return False, 0.0
        chunk_files.append(cout)
        chunk_total += cdur
    concat_list = os.path.join(temp_dir, "_xchunk_concat.txt")
    open(concat_list, "w", encoding="utf-8").write(
        "".join(f"file '{os.path.abspath(c)}'\n" for c in chunk_files))
    r = subprocess.run(["ffmpeg", "-y", "-f", "concat", "-safe", "0",
                        "-i", concat_list, "-c", "copy", out], capture_output=True, text=True)
    if r.returncode != 0:
        print("  склейка чанков xfade не удалась, откат на concat:", r.stderr[-300:])
        return False, 0.0
    # Чанки скопированы в out побайтово (-c copy) — дальше они не нужны
    # никому: xfade_chain() выше не кэширует их между прогонами (cout
    # каждый раз перезаписывается заново), а весь код ниже по пайплайну
    # (pad_to_length/финальный мукс) работает только с out. Раньше чанки
    # (~столько же места, сколько сам out) оставались лежать мёртвым
    # грузом до konца прогона — на реальном 165-клипном эпизоде это было
    # ~2.9 ГБ пиковой нехватки диска, буквально то место, где сборка
    # несколько раз падала на "No space left on device" при последующем
    # финальном муксе. Удаление — не оптимизация с компромиссом: это
    # чистая уборка уже скопированных временных файлов, out от неё не
    # зависит и не меняется. Сбой удаления (permissions и т.п.) не должен
    # рушить уже УСПЕШНУЮ склейку — не критично, просто предупреждение.
    for cf in chunk_files:
        try:
            os.remove(cf)
        except OSError as e:
            print(f"  предупреждение: не удалось удалить временный чанк {cf}: {e}")
    return True, chunk_total


def estimate_xfade_budget(blocks, chunk_size=XFADE_CHUNK_SIZE):
    """Сколько склейка суммарно "съест" нахлёстами — теперь ТОЧНО, а не
    оценкой сверху: это буквально сумма того самого плана, по которому
    xfade_chain() потом и режет (см. plan_transitions() — там же история
    бага с круговой зависимостью и цена перебора: 35+ секунд ухода видео
    от аудио на 40-минутном эпизоде).

    Учитывается и чанкование: xfade_chain_chunked() склеивает чанки через
    concat -c copy, то есть переход НА ВХОДЕ каждого чанка не делается и
    нахлёста не потребляет — раньше эти ~0.4с на каждый чанк (13-14 чанков
    на длинном эпизоде) тоже уходили в перебор."""
    sections = [b["section"] for b in blocks]
    plan = plan_transitions(sections, blocks)
    if not plan:
        return 0.0
    dropped = {a for a, _b in _chunk_bounds(len(blocks), sections, chunk_size) if a > 0}
    return sum(d for i, (_t, d) in enumerate(plan, start=1) if i not in dropped)


def pad_to_length(video, target, temp_dir):
    """Достраивает видео до нужной длины заморозкой последнего кадра — нужно
    после xfade_chain(), если реальный итог всё же короче target (несмотря
    на estimate_xfade_budget с запасом сверху — редкий остаточный случай,
    не обычный путь). Возвращает (путь, gap) — gap > 0 означает, что
    заморозка реально сработала, main() отражает это в QC."""
    cur = get_media_duration(video)
    gap = target - cur
    if gap <= 0.05:
        return video, 0.0
    lastframe = os.path.join(temp_dir, "_lastframe.jpg")
    padclip = os.path.join(temp_dir, "_pad.mp4")
    padded = os.path.join(temp_dir, "_padded.mp4")
    subprocess.run(["ffmpeg", "-y", "-sseof", "-0.3", "-i", video,
                    "-vframes", "1", lastframe], capture_output=True)
    r = subprocess.run(["ffmpeg", "-y", "-loop", "1", "-i", lastframe, "-t", f"{gap:.3f}",
                        "-c:v", "libx264", "-preset", FINAL_PASS_PRESET, "-crf", FINAL_PASS_CRF,
                        "-pix_fmt", "yuv420p", "-r", str(FPS)] + COLOR_META_ARGS + [padclip],
                       capture_output=True, text=True)
    if r.returncode != 0:
        return video, gap
    lst = os.path.join(temp_dir, "_pad_concat.txt")
    open(lst, "w", encoding="utf-8").write(
        f"file '{os.path.abspath(video)}'\nfile '{os.path.abspath(padclip)}'\n")
    r = subprocess.run(["ffmpeg", "-y", "-f", "concat", "-safe", "0",
                        "-i", lst, "-c", "copy", padded], capture_output=True, text=True)
    return (padded, gap) if r.returncode == 0 else (video, gap)


def get_media_duration(path):
    r = subprocess.run(["ffprobe", "-v", "quiet", "-print_format", "json",
                        "-show_format", path], capture_output=True, text=True, check=True)
    return float(json.loads(r.stdout)["format"]["duration"])


def get_media_fps(path):
    """r_frame_rate первого видеопотока (см. SPEED_RAMP_MAX_SOURCE_FPS) —
    None при любой ошибке/отсутствии видеопотока (fail-open, тот же принцип,
    что get_media_duration/measure_motion): вызывающий код тогда не гейтит
    спид-рамп по fps вообще, прежнее поведение."""
    try:
        r = subprocess.run(["ffprobe", "-v", "quiet", "-print_format", "json",
                            "-select_streams", "v:0", "-show_entries", "stream=r_frame_rate",
                            path], capture_output=True, text=True, check=True)
        rate = json.loads(r.stdout)["streams"][0]["r_frame_rate"]
        num, _, den = rate.partition("/")
        return float(num) / float(den or 1)
    except Exception:
        return None


def audio_qc(path):
    """Технический QC дорожки ДО сборки — тот же принцип, что qc_report() для
    картинок: не блокирует, только честно докладывает брак, который иначе
    заметили бы только на слух постфактум (клиппинг, слишком тихо/громко,
    длинные участки мёртвой тишины помимо самих [pause] — забытый обрыв
    записи). Бесплатно — штатные ffmpeg-фильтры astats/silencedetect,
    никакого нового API."""
    try:
        r = subprocess.run(
            ["ffmpeg", "-nostats", "-i", path, "-af",
             "astats=reset=0,silencedetect=noise=-40dB:d=1.5", "-f", "null", "-"],
            capture_output=True, text=True, timeout=120)
        err = r.stderr
    except Exception as e:
        print(f"  Audio QC: не удалось проверить ({e})")
        return
    warns = []
    m = re.search(r"Peak level dB:\s*(-?[\d.]+)", err)
    if m and float(m.group(1)) > -0.1:
        warns.append(f"пик {m.group(1)} dBFS — на грани клиппинга")
    m = re.search(r"RMS level dB:\s*(-?[\d.]+)", err)
    rms = float(m.group(1)) if m else None
    if rms is not None and rms < -35:
        warns.append(f"RMS {rms:.1f} dBFS — очень тихо")
    elif rms is not None and rms > -12:
        warns.append(f"RMS {rms:.1f} dBFS — очень громко/пережато")
    silences = [float(x) for x in re.findall(r"silence_duration:\s*([\d.]+)", err)]
    if silences:
        try:
            dur = get_media_duration(path)
            ratio = sum(silences) / dur
            if ratio > 0.15:
                warns.append(f"{ratio*100:.0f}% дорожки — тишина длиннее 1.5с (мёртвый воздух?)")
        except Exception:
            pass
    print(f"Audio QC: {'; '.join(warns)}" if warns else "Audio QC: клиппинга/аномальной громкости не найдено")


@memoize_by_frame
def ahash(photo_path, size=8):
    """Средний хэш (average hash) картинки — 64-битная строка, дешёвая
    замена imagehash-библиотеке (Pillow уже обязательная зависимость, лишний
    пакет не нужен). Похожие по контенту кадры дают близкий хэш даже если
    это разные файлы с разных источников."""
    img = PILImage.open(photo_path).convert("L").resize((size, size), PILImage.LANCZOS)
    pixels = list(img.getdata())
    avg = sum(pixels) / len(pixels)
    return "".join("1" if p > avg else "0" for p in pixels)


def hamming(a, b):
    return sum(c1 != c2 for c1, c2 in zip(a, b))


def qc_report(media_log):
    """Не блокирует сборку — просто честно докладывает, если несколько
    кадров ролика визуально почти одинаковые (Pexels ID разные, а по факту
    похожий кроп/пересъёмка того же сюжета — то, что ловится глазом, но не
    ловится дедупом по ID). Порог 6 бит из 64 — эмпирически "заметно похоже".
    Возвращает список дублей — раньше это тонуло в середине лога, а ГОТОВО
    выглядело как чистый успех; теперь main() отражает находку в итоговой
    строке и коде возврата (не блокирует сборку — только честно не молчит:
    тот же принцип, что уже применён к пропущенным блокам)."""
    if len(media_log) < 2:
        return []
    hashes = []
    for i, path in media_log:
        try:
            hashes.append((i, ahash(path)))
        except Exception:
            pass
    dupes = []
    for a in range(len(hashes)):
        for bb in range(a + 1, len(hashes)):
            i1, h1 = hashes[a]
            i2, h2 = hashes[bb]
            d = hamming(h1, h2)
            if d <= 6:
                dupes.append((i1 + 1, i2 + 1, d))
    if dupes:
        print(f"QC: похожие кадры (проверь глазами) — {dupes}")
    else:
        print("QC: явных повторов по картинке не найдено")
    return dupes


def apply_section_boundary_shift(blocks, durs):
    """Лёгкая версия J/L-cut. Классический приём (звук следующей сцены
    начинается раньше её картинки) тут физически не из чего собрать — вся
    озвучка это один сплошной файл на весь ролик, а не отдельная дорожка
    на клип. Но можно сдвинуть саму ТОЧКУ ВИДЕО-РЕЗА относительно границы
    фразы на 250-400мс раньше или позже вместо ровно момента паузы —
    зритель считывает лёгкую рассинхронность видео/смыслового реза как
    признак ручного монтажа, а не нарезки строго по паузам. Сумма
    длительностей не меняется — время просто перетекает между соседними
    блоками ДО и ПОСЛЕ границы секции.

    2.7 (доразбор второго продакшн-документа, п.3.2 "J/L-cuts — главный
    приём, по которому документалка ощущается срежиссированной"): раньше
    сдвиг применялся ТОЛЬКО на границах секций (HOOK->BLOCK1 и т.п.) — то
    есть буквально на паре резов за весь ролик, а не на "каждой смене
    сцены", как советует источник. Подавляющее большинство резов (внутри
    одной секции) резались РОВНО по границе фразы — без единой микро-
    рассинхронности. apply_within_cut_shift() ниже — тот же механизм,
    меньшая амплитуда (клипы внутри секции короче — большой сдвиг съел бы
    заметную долю короткого кадра), применяется отдельным проходом сразу
    после этой функции."""
    d = list(durs)
    for i in range(1, len(blocks)):
        if blocks[i]["section"] == blocks[i - 1]["section"]:
            continue
        h = int(hashlib.md5(blocks[i]["text"][:40].encode()).hexdigest()[:8], 16)
        mag = 0.25 + (h % 150) / 1000.0   # 0.25-0.40с, детерминировано по тексту
        give = mag if (h & 1) else -mag
        floor_prev = hook_floor_for(blocks, i - 1)
        floor_cur = hook_floor_for(blocks, i)
        if d[i - 1] - give >= floor_prev and d[i] + give >= floor_cur:
            d[i - 1] -= give
            d[i] += give
    return d


def apply_within_cut_shift(blocks, durs):
    """J/L-cut для резов ВНУТРИ секции — см. докстринг apply_section_boundary_shift
    (2.7): та же идея (точка видео-реза чуть раньше/позже границы фразы,
    сумма длительностей сохраняется), но НЕ на границах секций (там уже
    отработала apply_section_boundary_shift своей, более крупной амплитудой)
    и с меньшим сдвигом — иначе на 3-4-секундном кадре сдвиг в 300мс это уже
    десятая часть его собственной длины, заметно искажает темп.

    Пропускаем два случая, где сдвиг СЕМАНТИЧЕСКИ неверен, не просто
    "не нужен": sub-cut внутри одного исходного блока (это одна и та же
    мысль, разрезанная на фазы показа — граница между её кусками не несёт
    "смены сцены", J/L-cut тут нечего анонсировать) и рез сразу после
    stat-плашки (snap cut — намеренно МГНОВЕННЫЙ, цифра "впечаталась" и тут
    же сменился кадр; сдвигать его — противоречить собственному замыслу
    snap cut, не улучшать его)."""
    d = list(durs)
    for i in range(1, len(blocks)):
        if blocks[i]["section"] != blocks[i - 1]["section"]:
            continue   # уже сдвинуто apply_section_boundary_shift
        if blocks[i].get("is_subcut") or blocks[i - 1].get("stat"):
            continue
        h = int(hashlib.md5((blocks[i - 1]["text"][-30:] + blocks[i]["text"][:30]).encode()).hexdigest()[:8], 16)
        mag = 0.08 + (h % 100) / 1000.0   # 0.08-0.18с — заметно меньше, чем на границе секции
        give = mag if (h & 1) else -mag
        floor_prev = hook_floor_for(blocks, i - 1)
        floor_cur = hook_floor_for(blocks, i)
        if d[i - 1] - give >= floor_prev and d[i] + give >= floor_cur:
            d[i - 1] -= give
            d[i] += give
    return d


def apply_human_jitter(blocks, durs, magnitude=0.3):
    """Механическая регулярность длительностей — узнаваемый штамп автослайдшоу:
    даже с real-alignment таймингом (см. load_alignment_weights) сетка
    остаётся слишком "правильной". Живой монтаж имеет микронеровности:
    иногда кадр обрывается на 2.3с раньше расчётного, иногда держится
    дольше. Джиттер — детерминированный (hashlib.md5 текста, не встроенный
    hash() — тот рандомизирован между запусками и сломал бы кэш), сумма
    длительностей сохраняется РОВНО (вычитаем среднее смещение из всех
    дельт вместо пропорционального масштабирования — иначе масштаб просто
    съедает большую часть эффекта на длинном ролике)."""
    deltas = []
    for b in blocks:
        h = int(hashlib.md5((b["section"] + b["text"][:40]).encode()).hexdigest()[:8], 16)
        frac = (h % 1000) / 1000.0
        deltas.append((frac - 0.5) * 2 * magnitude)
    mean_delta = sum(deltas) / len(deltas)
    deltas = [x - mean_delta for x in deltas]
    # Свой пол для хука (hook_floor_for — с учётом ещё более низкого пола на
    # первые резы) — иначе джиттер молча утаскивал бы уже нарочно короткие
    # хук-кадры обратно к общему MIN_CLIP, сводя на нет весь смысл отдельного,
    # более быстрого пола (см. block_durations).
    out = [max(hook_floor_for(blocks, i), d + delta)
           for i, (d, delta) in enumerate(zip(durs, deltas))]
    scale = sum(durs) / sum(out)
    return [x * scale for x in out]


SUBCUT_MIN_SOURCE_DUR = 8.0   # блок короче этого не режем вообще
SUBCUT_MIN_PART_DUR = 3.0     # ни один получившийся под-кадр не короче этого
SUBCUT_CONTRAST_WORDS = {"но", "однако", "зато", "хотя", "просто", "ведь",
                          "потому", "поэтому", "притом", "притом,"}
# Раньше здесь стоял отдельный, более агрессивный набор порогов
# (SUBCUT_HOOK_MIN_SOURCE_DUR=2.0/SUBCUT_HOOK_MIN_PART_DUR=0.9/
# SUBCUT_HOOK_MIN_WORDS=4) для первых HOOK_OPENING_CUTS блоков хука — резал
# короткие фразы открытия на ещё более мелкие куски (вплоть до ~1с).
# Убрано целиком вместе с HOOK_OPENING_MIN_CLIP/HOOK_OPENING_CUTS (см.
# HOOK_MIN_CLIP выше) по прямому требованию пользователя: хук теперь режется
# теми же порогами (SUBCUT_MIN_SOURCE_DUR/SUBCUT_MIN_PART_DUR), что и тело
# ролика — единственное, что остаётся хук-специфичным, это сам пол
# длительности готового клипа (HOOK_MIN_CLIP=2.2 через hook_floor_for).

_PURE_NUMBER_RE = re.compile(r'^\d+$')   # "1240" из "1240." — год/номер, не конец предложения


def _internal_sentence_boundaries(words):
    """Индексы слов (резать ПОСЛЕ этого индекса), где внутри блока заканчивается
    ЗАКОНЧЕННОЕ предложение (.!?) — реальный, найденный вживую класс бага (27
    августа, videos/_test20s, финальный блок хука "Готов спорить, что да.
    Герой на экране заносит клинок..."): один физический блок сценария может
    содержать НЕСКОЛЬКО риторически независимых предложений, если автор не
    поставил между ними [pause]/[short pause] (границы блока и так уже
    задаются тегами — по построению ВНУТРИ уже распарсенного блока такого
    тега нет, значит любая точка/! /? внутри текста блока — это ровно тот
    случай, когда автор ЗАБЫЛ явно разметить границу, не намеренно оставил
    monolith). Раньше split_long_blocks() решал резать ТОЛЬКО по длительности
    (est < SUBCUT_MIN_SOURCE_DUR) — короткий по времени, но составной по
    смыслу блок (три предложения, произнесённые быстро) не резался вовсе,
    и все они получали ОДИН общий кадр — зритель видит "не тот" кадр в
    момент смены смысла внутри блока. Последнее слово блока не считается
    внутренней границей (это и так конец блока). Число с точкой на конце
    ("1240.") не считается концом предложения — почти всегда десятичная
    точка/номер, не разрыв смысла."""
    bounds = []
    for i, word in enumerate(words[:-1]):
        core = word.rstrip('»"\')')
        if core and core[-1] in ".!?" and not _PURE_NUMBER_RE.match(core[:-1]):
            bounds.append(i + 1)
    return bounds


def split_long_blocks(blocks, real_weights):
    """Один блок = один клип 4-20 сек — механическая сетка "одна мысль = одна
    картинка". Профессиональный монтаж на одну длинную фразу даёт 2-3
    визуальных решения. Режем блок, если он длиннее SUBCUT_MIN_SOURCE_DUR
    (по реальному alignment-весу, при его отсутствии — грубая оценка по
    словам) — ЛИБО, независимо от длительности, если внутри блока несколько
    ЗАКОНЧЕННЫХ предложений без явного [pause]/[short pause] между ними (см.
    _internal_sentence_boundaries — реальный найденный случай, короткий по
    времени, но составной по смыслу блок раньше не резался вовсе). Внутри —
    по смысловым триггерам: сами границы предложений (приоритет), иначе
    контраст-союзы ("но"/"однако"/...) или первое число за пределами первой
    четверти блока. Без триггеров, но всё равно длинный — режем ровно посередине по словам.
    Реальный вес блока делится между кусками ПРОПОРЦИОНАЛЬНО их доле слов —
    сумма сохраняется, ничего не выдумываем сверху. Запрос к стоку для
    под-кадров остаётся тем же самым блоком (resolve_queries считается уже
    ПОСЛЕ split, на новом расширенном списке — если у куска нет своего
    ключевого слова, он унаследует запрос соседнего куска той же секции,
    та же логика, что уже работает для обычных блоков), картинка другая —
    засчёт дедупа по used_photo_ids на большем пуле Pexels (per_page=40)."""
    new_blocks, new_weights = [], []
    for b, w in zip(blocks, real_weights or [None] * len(blocks)):
        min_source = SUBCUT_MIN_SOURCE_DUR
        min_part = SUBCUT_MIN_PART_DUR
        min_words = 8
        est = w if w is not None else b["words"] / 2.08
        words = b["text"].split()
        # sentence_bounds — см. _internal_sentence_boundaries(): несколько
        # ЗАКОНЧЕННЫХ (.!?) предложений в одном блоке — сигнал сильнее и
        # надёжнее, чем длительность est. Проверяем ДО обоих ранних выходов
        # (по длительности/по числу слов) — реальный найденный случай был
        # именно коротким по времени (4.1с — заведомо младше SUBCUT_MIN_
        # SOURCE_DUR=8.0), но составным по смыслу (3 предложения). Без этого
        # условия оба ранних выхода отсекли бы ровно тот блок, который и
        # нужно резать.
        sentence_bounds = _internal_sentence_boundaries(words)
        if est < min_source and not sentence_bounds:
            new_blocks.append(b)
            new_weights.append(w)
            continue
        if len(words) < min_words and not sentence_bounds:
            new_blocks.append(b)
            new_weights.append(w)
            continue
        split_at = list(sentence_bounds)
        if not split_at:
            for i, word in enumerate(words):
                wl = word.strip(",.!?—–:;»«").lower()
                if wl in SUBCUT_CONTRAST_WORDS and 2 <= i <= len(words) - 3:
                    split_at.append(i)
            for i, word in enumerate(words):
                if re.search(r'\d', word) and i > len(words) // 4:
                    split_at.append(i)
                    break
        if not split_at:
            # Без смыслового триггера резать РОВНО посередине по счёту слов
            # означало иногда рвать словосочетание внутри одной фразы ("в
            # тысячу" | "раз" — тайминг не привязан к речи). Ищем ближайшую к
            # середине пунктуационную границу (конец клаузы: , . ! ? — ; :) —
            # рез попадает на естественную паузу произношения. Не нашли ни
            # одной в разумном радиусе — старое поведение (ровно посередине).
            mid = len(words) // 2
            found = None
            for radius in range(0, len(words) // 2 + 1):
                for cand in (mid - radius, mid + radius):
                    if 2 <= cand <= len(words) - 3 and words[cand - 1].rstrip()[-1:] in ",.!?—;:":
                        found = cand
                        break
                if found is not None:
                    break
            split_at = [found if found is not None else mid]
        bounds = sorted(set([0] + split_at + [len(words)]))
        chunks = [(a, c) for a, c in zip(bounds, bounds[1:]) if c > a]
        # Склеиваем куски короче SUBCUT_MIN_PART_DUR (по доле слов от est)
        # с предыдущим — не даём под-кадру уйти ниже комфортной длины.
        total_w = len(words)
        merged = []
        for a, c in chunks:
            frac = (c - a) / total_w
            if merged and est * frac < min_part:
                pa, _ = merged[-1]
                merged[-1] = (pa, c)
            else:
                merged.append((a, c))
        if len(merged) < 2:
            new_blocks.append(b)
            new_weights.append(w)
            continue
        # Плашка раньше ВСЕГДА доставалась первому куску (k==0) независимо от
        # того, где в исходном блоке реально стоял [stat:...] — если рез
        # приходился ДО фразы с числом, цифра на экране показывалась на
        # куске, где она ещё не произнесена, а реальный кусок с числом
        # оставался без плашки вовсе. stat_word_pos (см. parse_blocks) —
        # позиция тега в словах исходного блока; находим, в какой ИМЕННО
        # кусок она попадает, и пересчитываем позицию относительно НАЧАЛА
        # этого куска (nb-локально), чтобы дальше по конвейеру плашку можно
        # было синхронизировать с моментом озвучки, а не с началом клипа.
        stat_pos = b.get("stat_word_pos")
        for k, (a, c) in enumerate(merged):
            nb = dict(b)
            nb["text"] = " ".join(words[a:c])
            nb["words"] = c - a
            has_stat = b["stat"] is not None and stat_pos is not None and (
                (a < stat_pos <= c) or (stat_pos <= 0 and k == 0))
            nb["stat"] = b["stat"] if has_stat else None
            nb["stat_word_pos"] = max(0, stat_pos - a) if has_stat else None
            nb["pause_after"] = b["pause_after"] if k == len(merged) - 1 else 0.0
            nb["is_subcut"] = k > 0   # для choose_motion_mode() (1.4) — деталь, не главный кадр фразы
            # is_climax (2.8) — та же логика, что и у плашки: тег стоит перед
            # НАЧАЛОМ исходного блока, значит момент, к которому привязана
            # тишина-акцент, попадает в ПЕРВЫЙ получившийся под-кадр, не во
            # все (dict(b) выше скопировал бы флаг во все k без явного сброса).
            nb["is_climax"] = b.get("is_climax", False) if k == 0 else False
            new_blocks.append(nb)
            new_weights.append((w * (c - a) / total_w) if w is not None else None)
    return new_blocks, new_weights


def render_recipe_signature():
    """Отпечаток САМОГО РЕЦЕПТА картинки (исходный код функций рендера +
    ключевые константы) — входит в params_hash кэша temp_smart/ (см. main()).

    Закрывает класс бага, который в этом файле был честно описан как
    "ЗАМЕТКА НА БУДУЩЕЕ" у _warm_mult(), но не закрыт: params_hash хэшировал
    только РАНТАЙМ-параметры блока (текст/длительность/запрос/подписи), а не
    версию рецепта. Любая правка грейда (film_look/_scene_bias/_warm_mult),
    зерна, движения камеры или оформления плашек молча переживала уже
    отрендеренные клипы: на следующем прогоне часть эпизода оставалась в
    старом рецепте, часть — в новом, причём разница видна на глаз только
    при сравнении кадров, а в логе не сказано ничего. Ровно эта ловушка
    уже требовала ручной чистки temp_smart/ "не забыть перед правкой".

    Теперь смена рецепта инвалидирует кэш САМА. Инвалидация грубая (любая
    правка перечисленных функций — даже строчки лога — считается сменой
    рецепта): это осознанно консервативная сторона, лишний перерендер
    дешевле молча смешанного грейда в одном ролике.

    Сбой inspect (нестандартная упаковка, .pyc без исходника) -> стабильная
    заглушка: поведение как раньше, без падения."""
    try:
        import inspect
        parts = [inspect.getsource(f) for f in (
            film_look, _scene_bias, _warm_mult, grain_blend_complex,
            add_overlays, add_kinetic_captions, kenburns, video_render,
            parallax_kenburns, choose_motion_mode, piecewise_ease_expr,
            # is_parallax_highlight — ТОЖЕ часть рецепта, не рантайм-параметр:
            # правка её условий (например, что считать highlight-моментом)
            # меняет, КАКОЙ путь рендера (parallax_kenburns vs обычный
            # kenburns) получит уже закэшированный клип, при том что ни один
            # из перечисленных выше рантайм-параметров params_hash при этом
            # не меняется — без неё такая правка молча не инвалидировала бы
            # старый кэш (тот же класс бага, что и у остальных функций здесь).
            is_parallax_highlight,
            # foreground_background_layers — ТОЖЕ часть рецепта: вызывается
            # ИЗНУТРИ parallax_kenburns() (по имени, не инлайн-кодом), поэтому
            # правка её собственного тела не меняет исходник parallax_kenburns
            # и молча не инвалидировала бы старый кэш — тот же класс пробела,
            # что и у is_parallax_highlight выше.
            foreground_background_layers,
            # apply_depth_of_field/_dof_focus_depth — тот же класс пробела,
            # что foreground_background_layers выше: вызываются ИЗНУТРИ
            # parallax_kenburns() по имени, правка их тела (например, замена
            # DOF_FOCUS_DEPTH на адаптивный порог, 27 августа) не меняет
            # исходник parallax_kenburns и молча не инвалидировала бы старый
            # кэш без явного перечисления здесь.
            apply_depth_of_field, _dof_focus_depth,
            # Найдено самоаудитом 03.09 (Explore-агент, тот же принцип, что
            # уже применён к is_parallax_highlight/foreground_background_
            # layers/apply_depth_of_field выше): все функции ниже вызываются
            # ПО ИМЕНИ изнутри уже перечисленных film_look/kenburns/
            # parallax_kenburns/video_render, реально влияют на итоговую
            # картинку и НЕ мемоизированы между прогонами процесса (в
            # отличие от кандидатов ниже, у @memoize_by_frame — она
            # ВНУТРИПРОЦЕССНАЯ, не защищает от staleness МЕЖДУ прогонами,
            # см. её докстринг) — правка их тела молча не инвалидировала бы
            # старый temp_smart/clip_*.mp4, тот же класс бага, что и у уже
            # перечисленных функций.
            #
            # auto_levels_params/auto_wb_params — из film_look(): дают
            # contrast/brightness/colorchannelmixer техническую нормировку
            # ДО творческого грейда, идут прямо в возвращаемую строку
            # фильтра.
            auto_levels_params, auto_wb_params,
            # kb_hash_choices — из kenburns()/parallax_kenburns(): даёт
            # zoom_in/pan_dir по умолчанию, которые входят в z=/x=/y=
            # выражение zoompan.
            kb_hash_choices,
            # estimate_busyness — из kenburns(): напрямую масштабирует силу
            # зума (delta *= 0.7 при busy > 0.6).
            estimate_busyness,
            # resolve_crop_anchor/compute_crop_offset — из kenburns()/
            # parallax_kenburns(): решают, какая часть фото попадёт в
            # crop=.
            resolve_crop_anchor, compute_crop_offset,
            # pick_stat_variant — из add_overlays(): выбирает между 4
            # визуально разными оформлениями stat-плашки.
            pick_stat_variant,
            # detect_scene_change_offset — из video_render(): решает, с
            # какого момента исходного видео стартует клип (-ss).
            detect_scene_change_offset,
            # measure_motion/build_speed_ramp_filter — из video_render():
            # решают, применяется ли speed-ramp вообще, и строят сам
            # filter_complex-граф эффекта.
            measure_motion, build_speed_ramp_filter,
            # estimate_depth/fill_crop_canvas — из parallax_kenburns():
            # единственный источник карты глубины, от которой зависят
            # parallax_px/depth_zoom_strength И уже перечисленные выше
            # apply_depth_of_field/foreground_background_layers — их более
            # фундаментальный апстрим-источник данных, ранее в список не
            # попавший.
            estimate_depth, fill_crop_canvas,
        )]
        parts.append(repr((
            sorted(MOOD_GRADE.items()), sorted(DOMAIN_WARM_PUSH_SCALE.items()),
            GRAIN_ENABLED, GRAIN_OPACITY, DEFLICKER_ENABLED, DOF_ENABLED,
            DOF_FOCUS_DEPTH, DOF_FOCUS_DEPTH_FLOOR, DOF_FOCUS_CENTER_Y, DOF_FOCUS_CENTER_X,
            FPS, WIDTH, HEIGHT, ZOOM_FLOOR, ZOOM_RATE_BASE,
            ZOOM_DELTA_MIN, ZOOM_DELTA_MAX, PAN_SAFETY,
            PARALLAX_ENABLED, PARALLAX_WARP_SIGMA_FRAC, PARALLAX_MAX_STRETCH,
            PARALLAX_OCCLUSION_AWARE, PARALLAX_INPAINT_RADIUS,
            HOOK_KINETIC_CAPTIONS_ENABLED,
            CLIP_PIX_ARGS, COLOR_META_ARGS,
        )))
    except Exception:
        return "recipe:unknown"
    return "recipe:" + hashlib.md5("".join(parts).encode()).hexdigest()[:10]


RENDER_RECIPE_SIG = None   # считается один раз в main() (см. render_recipe_signature)


def check_jobs_in_order(pending_jobs):
    """pending_jobs обязан идти строго по ВОЗРАСТАНИЮ индекса блока — этого
    (и только этого) требует xfade-склейка ниже: кадры должны попасть в
    цепочку в том же порядке, в каком идут блоки сценария.

    РЕАЛЬНЫЙ БАГ, который здесь жил (падение всего прогона, не порча
    порядка): проверка была `assert job["i"] == k` — то есть требовала,
    чтобы индекс блока СОВПАДАЛ с позицией в списке. Но блок, для которого
    не нашлось ни фото, ни видео (кончилась квота Pexels, пустая выдача по
    запросу, нет ключа), в pending_jobs НЕ добавляется вообще — это штатный
    путь `continue` с записью в missing/render_manifest. После первого же
    такого блока все последующие позиции сдвигались на единицу, и ровно эта
    "защитная" проверка роняла весь рендер сырым AssertionError с
    трейсбеком — вместо аккуратного отчёта "СТОП: N клип(ов) не приняты"
    (RENDER_STRICT_GATE, ниже) или сборки без пропущенных кадров. То есть
    страховка от гипотетического бага сама создавала гарантированное
    падение на самом обычном сценарии.

    Возрастание (а не равенство позиции) — это и есть настоящий инвариант:
    он держится при любом числе пропусков и ловит именно то, от чего
    страховка ставилась (переставленные/дублированные задания)."""
    prev = -1
    for pos, job in enumerate(pending_jobs):
        if job["i"] <= prev:
            raise AssertionError(
                f"pending_jobs не по порядку: позиция {pos} содержит блок {job['i']} "
                f"после блока {prev} — склейка получила бы кадры не в том порядке "
                f"(см. комментарий у append в main())")
        prev = job["i"]
    return True


def print_plan_summary(blocks, durs, queries, total, xfade_budget, n_blocks_before_subcuts):
    """Свод для --plan-only (см. PLAN_ONLY): показывает то же самое, что
    иначе можно узнать только по факту рендера — часы CPU спустя. Ни ffmpeg,
    ни сетевых вызовов к Pexels/CLIP-моделям здесь нет: только уже
    посчитанные blocks/durs/queries.

    Побочные файлы (shot_manifest.json/subtitles.srt/chapters.txt) к этому
    моменту уже записаны вызывающим кодом (main()) — это чистая печать
    свода поверх них, не отдельный проход."""
    n_sections = len({b["section"] for b in blocks})
    n_subcuts = sum(1 for b in blocks if b.get("is_subcut"))
    n_generic = sum(1 for q in queries if q in GENERIC_FALLBACKS)
    total_dur = sum(durs)
    predicted_final = total_dur - xfade_budget

    print("\n=== PLAN-ONLY: сборка НЕ запускалась (ни одного вызова ffmpeg) ===")
    print(f"Блоков: {len(blocks)} (до sub-cuts: {n_blocks_before_subcuts}, "
          f"sub-cuts: {n_subcuts}) в {n_sections} секци(ях)")
    print(f"Средний кадр: {total_dur / max(1, len(blocks)):.2f}с")
    by_section = {}
    for b, d in zip(blocks, durs):
        by_section.setdefault(b["section"], []).append(d)
    for name, ds in by_section.items():
        print(f"  {name}: {len(ds)} кадр(ов), средний {sum(ds) / len(ds):.2f}с, "
              f"сумма {sum(ds):.1f}с")
    print(f"Аудио: {total:.2f}с | сумма длительностей кадров: {total_dur:.2f}с | "
          f"бюджет склейки: {xfade_budget:.2f}с")
    drift_ms = abs(predicted_final - total) * 1000
    half_frame_ms = 500.0 / FPS
    drift_note = ("в пределах полукадра — тайминг сойдётся без заморозки в хвосте"
                  if drift_ms <= half_frame_ms else
                  "БОЛЬШЕ полукадра — при реальном рендере жди либо заморозку в хвосте "
                  "(pad_to_length), либо перебор, обрезаемый муксом; стоит перепроверить "
                  "block_durations()/estimate_xfade_budget() на этом сценарии")
    print(f"Прогноз длины смонтированного видео (сумма - бюджет): {predicted_final:.2f}с "
          f"(расхождение с аудио: {drift_ms:.0f} мс — {drift_note})")
    if n_generic:
        print(f"  ВНИМАНИЕ: {n_generic} слот(ов) без тематического запроса — ушли в "
              f"GENERIC_FALLBACKS (см. resolve_queries). Стоит расширить themes.json "
              f"ДО того, как тратить кредиты Pexels/AI-картинок на угадывание.")
    print("Файлы для проверки: media_plan/shot_manifest.json, subtitles.srt, chapters.txt")
    print("Готово (план). Для реальной сборки — запусти без --plan-only.")


def _timed_render(render_fn, clip_idx, *args, **kwargs):
    """Замер времени рендера ОДНОГО клипа.

    Обёртка СНАРУЖИ kenburns()/video_render()/parallax_kenburns(), а не
    таймер внутри них — сознательно: их исходный код хэшируется
    render_recipe_signature(), и правка тела (даже добавление строки
    замера) сменила бы params_hash и молча инвалидировала весь кэш
    temp_smart/ на 165 клипов. Реальный случай 01.09: monkeypatch
    choose_motion_mode ровно так и запустил незапланированный полный
    перерендер.

    Функция верхнего уровня, а не lambda/closure: ProcessPoolExecutor
    пикклит вызываемое, замыкание не пикклится. При STAGE_TIMER=0 —
    прозрачный проброс, поведение байт-в-байт прежнее."""
    with stage_timer.stage("clip_render", clip_idx=clip_idx, fn=render_fn.__name__):
        return render_fn(*args, **kwargs)


def main():
    if not os.path.exists(AUDIO_FILE):
        print(f"Аудио не найдено: {AUDIO_FILE}")
        return 1
    total = get_audio_duration()
    print(f"Аудио: {total:.1f}с ({total/60:.1f} мин)")
    audio_qc(AUDIO_FILE)
    os.makedirs(TEMP_FOLDER, exist_ok=True)
    # Замер стадий — только при STAGE_TIMER=1, иначе путь не выставляется
    # и stage() остаётся пустым (см. scripts/stage_timer.py).
    if stage_timer.STAGE_TIMER_ENABLED:
        stage_timer.set_output_path(
            os.path.join(VIDEO_FOLDER, "media_plan", "stage_timings.jsonl"))
        print("  Замер стадий включён (STAGE_TIMER=1) -> media_plan/stage_timings.jsonl")
    # Огрызки .partial.mp4 от предыдущего прогона, убитого посреди рендера
    # клипа (SIGKILL/OOM/обрыв — см. render_tmp_path/finalize_render) —
    # безопасно чистить на старте: раз файл лежит под .partial.mp4, а не
    # под финальным именем, значит тот рендер так и не завершился успехом,
    # доедать его нечем, только место занимает.
    for stale in glob.glob(os.path.join(TEMP_FOLDER, "clip_*.mp4.partial.mp4")):
        try:
            os.remove(stale)
        except OSError:
            pass
    # Тот же огрызок, но от финального мукса (см. render_tmp_path(OUTPUT_FILE)
    # в конце main()) — лежит не в TEMP_FOLDER, а рядом с самим final.mp4.
    stale_final = render_tmp_path(OUTPUT_FILE)
    if os.path.exists(stale_final):
        try:
            os.remove(stale_final)
        except OSError:
            pass
    blocks = parse_blocks(SCRIPT_FILE) if os.path.exists(SCRIPT_FILE) else []
    if not blocks:
        print("Сценарий не найден/пуст")
        return 1
    # Реальный тайминг считаем ДО sub-cuts — alignment.csv записан 1:1 на
    # исходные блоки (по [pause]/[short pause]), split_long_blocks() потом
    # честно делит вес пропорционально словам между получившимися кусками.
    real_weights = load_alignment_weights(blocks)
    if real_weights:
        known = sum(1 for w in real_weights if w is not None)
        print(f"Реальный тайминг (alignment.csv): {known}/{len(blocks)} блоков")
    n_before = len(blocks)
    blocks, real_weights = split_long_blocks(blocks, real_weights)
    if len(blocks) != n_before:
        print(f"Sub-cuts: {n_before} -> {len(blocks)} блоков")
    # См. merge_short_phrase_locked_blocks() — PHRASE LOCK ветка строит
    # длительность строго по реальным онсетам речи, без единого пола, поэтому
    # сам HOOK_MIN_CLIP/MIN_CLIP её не защищает; здесь заранее сливаем
    # блоки, чья реальная фраза короче пола, чтобы КАЖДЫЙ уцелевший рез
    # (и в PHRASE LOCK, и в обычной ветке — обе читают уже этот blocks)
    # гарантированно не давал клип короче пола.
    n_before_merge = len(blocks)
    blocks, real_weights = merge_short_phrase_locked_blocks(blocks, real_weights, total)
    if len(blocks) != n_before_merge:
        print(f"Phrase-lock merge (клипы короче пола): {n_before_merge} -> {len(blocks)} блоков")
    # Кроссфейд между КАЖДОЙ парой кадров суммарно "съедает" какую-то часть
    # длительности — закладываем это в целевую длительность заранее, чтобы
    # после склейки общая длина видео снова совпала с аудио (без этого хвост
    # ролика проигрывался бы без картинки под конец аудиодорожки). Считаем
    # ПОСЛЕ split — sub-cuts добавляют новые склейки, бюджет должен их
    # учитывать. estimate_xfade_budget() — точная оценка по категориям
    # перехода (2.4), не плоская (n-1)*XFADE_DUR.
    xfade_budget = estimate_xfade_budget(blocks)
    target = total + xfade_budget
    durs = block_durations(blocks, target, real_weights=real_weights)

    # === PHRASE LOCK — рез строго на начале фразы =========================
    # Реальная, измеренная причина жалобы «кадр показывается не под озвучку»
    # (28 августа): ниже по коду длительность проходила через СЕМЬ
    # преобразований (floor/cap-клэмп и rescale внутри block_durations,
    # energy_mults, apply_section_boundary_shift ±250-400мс,
    # apply_within_cut_shift ±80-180мс, apply_human_jitter ±300мс,
    # snap_hook_cuts_to_energy, поштучное quantize_durations_to_frames).
    # Каждое двигает границу кадра ОТНОСИТЕЛЬНО фразы, и ошибки СКЛАДЫВАЮТСЯ
    # по накоплению — к концу хука рез уезжает от своей фразы на доли секунды
    # и больше, то есть кадр «принадлежит» уже не той фразе.
    #
    # Обоснование, почему это чистое улучшение, а не размен:
    # эти преобразования вводились как «оживление» механически ровной сетки —
    # но сетка перестала быть механической ровно тогда, когда появился
    # реальный alignment: длительности фраз и так неравномерны от природы
    # речи (в этом эпизоде 1.25с .. 4.58с). То есть джиттер добавляет
    # неравномерность, которая УЖЕ есть, и платит за это единственным, что
    # тут по-настоящему важно — совпадением кадра с произносимой фразой.
    # J/L-cut (apply_*_shift) в этой архитектуре тоже недостижим и честно
    # признан таковым в собственном докстринге («классический приём тут
    # физически не из чего собрать» — одна сплошная дорожка озвучки на весь
    # ролик): сдвиг видео-реза с границы фразы не создаёт J/L-cut, он
    # создаёт ровно тот рассинхрон, на который жалуется зритель.
    onsets = load_alignment_onsets(blocks) if PHRASE_LOCK else None
    phrase_locked = None
    if onsets:
        phrase_locked = phrase_locked_durations(
            onsets, total, plan_transitions([b["section"] for b in blocks], blocks))
    curve = audio_energy_curve(AUDIO_FILE)
    energy_lvls = [1.0] * len(blocks)

    if phrase_locked:
        durs = phrase_locked
        # Шкала аудио для субтитров/глав — те же самые онсеты, а не отдельная
        # оценка: раньше субтитры считались по block_durations() (оценка с
        # клэмпом и rescale), из-за чего они закономерно «не успевали за
        # озвучкой» — та же корневая причина, что и у картинки.
        sub_starts = [0.0] + [onsets[i] for i in range(1, len(onsets))]
        sub_baseline = [(sub_starts[i + 1] if i + 1 < len(sub_starts) else total) - sub_starts[i]
                        for i in range(len(sub_starts))]
        if curve:
            # Громкость больше НЕ двигает резы (это ломало бы привязку), но
            # по-прежнему даёт лёгкую пульсацию грейда — там она безвредна.
            energy_lvls = energy_levels(curve, sub_starts, sub_baseline)
        print(f"Тайминг: рез привязан к началу фразы по alignment "
              f"({len(onsets)}/{len(blocks)} блоков, точность ±полкадра)")
    else:
        # Прежнее поведение целиком — эпизод без alignment (или с текстом,
        # правленным после записи): точной шкалы фраз не существует, и
        # «оживление» ровной оценки остаётся осмысленным.
        if curve:
            baseline = block_durations(blocks, total, real_weights=real_weights)
            starts, acc = [], 0.0
            for d in baseline:
                starts.append(acc)
                acc += d
            mults = energy_pace_multipliers(curve, starts, baseline)
            durs = block_durations(blocks, target, energy_mults=mults, real_weights=real_weights)
            energy_lvls = energy_levels(curve, starts, baseline)
            print("Ритм по громкости: включён")
        durs = apply_section_boundary_shift(blocks, durs)
        durs = apply_within_cut_shift(blocks, durs)
        durs = apply_human_jitter(blocks, durs)
        sub_baseline = block_durations(blocks, total, real_weights=real_weights)
        sub_starts, sub_acc = [], 0.0
        for d in sub_baseline:
            sub_starts.append(sub_acc)
            sub_acc += d
        durs = snap_hook_cuts_to_energy(blocks, durs, sub_starts, AUDIO_FILE)
        durs = quantize_durations_to_frames(durs)
    print(f"Средний кадр: {sum(durs)/len(durs):.1f}с")

    write_subtitles(VIDEO_FOLDER, blocks, sub_starts, sub_baseline, real_weights=real_weights)
    write_chapters(VIDEO_FOLDER, blocks, sub_starts)

    # visual_starts — РЕАЛЬНЫЕ старты клипов на шкале визуального монтажа,
    # ПОСЛЕ всех "очеловечивающих" сдвигов durs выше (apply_section_boundary_shift/
    # apply_within_cut_shift/apply_human_jitter/snap_hook_cuts_to_energy) И
    # после xfade-нахлёста (см. hook_visual_starts). Нужны ТОЛЬКО для
    # rescale_hook_words_to_visual_time() ниже (P0-3) — sub_starts/sub_baseline
    # остаются аудио-шкалой для write_subtitles/write_chapters (это и должно
    # быть привязано к голосу, не к монтажу).
    visual_starts = hook_visual_starts(blocks, durs)

    # media_plan/phrase_timeline.json — ПРОВЕРЯЕМЫЙ аудит привязки кадра к
    # фразе. Пишется ВСЕГДА (даже когда привязки нет — тогда честно
    # locked=false), потому что «показалось ли вовремя» до этого нельзя было
    # проверить ничем, кроме просмотра глазами. Дрейф считается не по
    # намерению, а по РЕАЛЬНОЙ визуальной шкале монтажа (hook_visual_starts —
    # она уже учитывает сжатие таймлайна кроссфейдом), то есть отражает то,
    # что зритель действительно увидит.
    phrase_timeline = {"locked": bool(phrase_locked), "fps": FPS,
                       "audio_total_sec": total, "blocks": []}
    worst_drift = 0.0
    for i, b in enumerate(blocks):
        want = (0.0 if i == 0 else onsets[i]) if onsets else None
        drift = (visual_starts[i] - want) if want is not None else None
        if drift is not None:
            worst_drift = max(worst_drift, abs(drift))
        phrase_timeline["blocks"].append({
            "index": i, "section": b["section"], "text": b["text"][:120],
            "speech_onset_sec": want, "visual_start_sec": visual_starts[i],
            "duration_sec": durs[i], "drift_sec": drift,
        })
    phrase_timeline["worst_drift_sec"] = worst_drift if onsets else None
    phrase_timeline["max_allowed_drift_sec"] = 0.5 / FPS
    pt_path = os.path.join(VIDEO_FOLDER, "media_plan", "phrase_timeline.json")
    os.makedirs(os.path.dirname(pt_path), exist_ok=True)
    with open(pt_path + ".tmp", "w", encoding="utf-8") as f:
        json.dump(phrase_timeline, f, ensure_ascii=False, indent=2)
    os.replace(pt_path + ".tmp", pt_path)
    if phrase_locked:
        print(f"  Привязка кадра к фразе: худший дрейф {worst_drift * 1000:.0f}мс "
              f"(предел полкадра = {500 / FPS:.0f}мс) — media_plan/phrase_timeline.json")
    else:
        print("  ВНИМАНИЕ: точной привязки кадра к фразе НЕТ (нет alignment или текст "
              "правился после записи) — тайминг оценочный, см. media_plan/phrase_timeline.json")

    clips, clip_durs, clip_sections, clip_blocks = [], [], [], []
    missing = []   # индексы блоков, для которых не нашлось ни фото, ни видео
    media_log = []   # (индекс, путь_к_фото) — для QC-проверки на похожие кадры в конце
    render_manifest = {}   # индекс -> статус (ok/failed/skipped-no-media), для резюме/диагностики
    zoom_hist, pan_hist = [], []
    # Пул на kenburns()/video_render() — НЕ на parallax_kenburns() (та
    # остаётся последовательной в этом же процессе, см. комментарий у
    # RENDER_POOL_ENABLED выше). Решение "что рендерить" (выбор фото/видео,
    # anti-repeat) остаётся ПОЛНОСТЬЮ последовательным, как и раньше —
    # параллелится только сам вызов ffmpeg, уже после того, как всё решено.
    # РЕАЛЬНЫЙ найденный вживую OOM (31 авг, полный рендер 01_ves-mecha,
    # dmesg): cgroup OOM-killer убил pid 1405 (anon-rss 8.66GB) и следом ещё
    # 3 форкнутых воркера пула — КАЖДЫЙ с тем же anon-rss ~8.66GB. kenburns()/
    # video_render() (единственное, что реально уходит в этот пул) сами по
    # себе не грузят ни одну ML-модель — им передаются уже готовые
    # wb/levels/look_filter/domain, посчитанные ДО submit(). Причина —
    # порядок вызовов: pexels_photo()/sentence_relevance() (SigLIP2-so400m +
    # Jina, лениво загружаются в главном процессе при первом обращении к
    # кандидату) отрабатывают РАНЬШЕ первого render_pool.submit() внутри
    # того же блока — то есть к моменту первого форка пул уже приходится
    # форкать процесс, в котором эти модели УЖЕ загружены. fork() на Linux
    # делит память через COW, но refcounting трогает заголовок почти
    # каждого объекта, которого касается воркер (в т.ч. периодическая
    # cyclic GC) — COW расходится, и воркер фактически получает свою копию
    # уже загруженного веса моделей, которые ему не нужны. mp_context=spawn
    # даёт форкнутому процессу чистый интерпретер (torch/onnxruntime/
    # transformers импортируются только ВНУТРИ get_clip_model()/
    # get_depth_model()/sentence_relevance(), не на уровне модуля — см.
    # `import` в этих функциях) — воркер, вызывающий только kenburns()/
    # video_render(), никогда их не касается и не тянет ни байта моделей.
    render_pool = (concurrent.futures.ProcessPoolExecutor(
                       max_workers=RENDER_POOL_WORKERS,
                       mp_context=multiprocessing.get_context("spawn"))
                   if RENDER_POOL_ENABLED else None)
    pending_jobs = []   # [{i, out, d, section, block, video, photo, future|None, ok}], в порядке блоков
    log_render_diagnostics("render_start")
    # Версия рецепта картинки — часть ключа кэша клипов (см.
    # render_recipe_signature): правка грейда/движения/оформления больше не
    # переживает молча уже отрендеренные клипы.
    global RENDER_RECIPE_SIG
    RENDER_RECIPE_SIG = recipe_sig = render_recipe_signature()
    use_local = os.path.isdir(MEDIA_FOLDER) and bool(local_photo(0))
    use_pexels = bool(PEXELS_API_KEY)
    # === PEXELS QUERIES === написан вручную по протоколу (CLAUDE.md ЧАСТЬ 13,
    # Шаг 3), но до этой строки НИКОГДА не читался пайплайном — см. докстринг
    # resolve_queries()/authored_queries. {} у эпизодов без этой секции
    # (напр. тестовые скрипты) -> ноль влияния, прежнее поведение.
    authored_queries = parse_pexels_queries(SCRIPT_FILE)
    if authored_queries:
        print(f"  Авторские PEXELS QUERIES: {sum(len(v) for v in authored_queries.values())} "
              f"запрос(ов) на {len(authored_queries)} секци(й)")
    queries = resolve_queries(blocks, authored_queries=authored_queries)
    # Пул запросов СЕКЦИИ на каждый блок (см. extra_queries в pexels_photo).
    # Раньше авторские запросы раздавались блокам ПОЗИЦИОННО ПО КРУГУ
    # (pool[idx % len(pool)]) — на секции из 16 блоков и 3 запросов это
    # означало, что блок про заточку клинка получал запрос "medieval castle
    # hall" просто потому, что выпал третьим по счёту. Реально измерено на
    # videos/01_ves-mecha: совпадало по смыслу примерно 1 из 3, остальное —
    # шум раздачи. Теперь позиция задаёт лишь ОСНОВНОЙ запрос (кэш/гейт), а
    # кандидаты собираются из всех запросов секции, и победителя выбирает
    # сопоставление ПОЛНОЙ ФРАЗЫ блока с картинкой (Semantic Visual Director,
    # sentence_relevance) — то, для чего эта модель и обучена, в отличие от
    # сравнения текста с текстом (проверено: на text-vs-text та же модель
    # ошибалась 3 раза из 4, поэтому этот путь сознательно не используется).
    section_query_pool = {}
    if authored_queries:
        for b in blocks:
            key = _normalize_section_key(b["section"])
            if key and key in authored_queries:
                section_query_pool[b["section"]] = authored_queries[key]

    # LLM-режиссёр, атмосферное обогащение ХУКА (SHOT_DIRECTOR_MODE=on) —
    # РЕАЛЬНЫЙ, найденный вживую пробел, отдельный от direct_query() выше
    # (тот покрывает только блоки БЕЗ запроса вообще). Прямая жалоба
    # пользователя: у "Пятнадцать килограммов" уже ЕСТЬ технически
    # релевантный авторский запрос ("weighing scale metal object"), но он
    # взят слишком буквально — реальный монтажёр связал бы число с темой
    # ролика (меч), не с бытовым предметом. enrich_atmospheric_queries()
    # даёт 2-3 альтернативных запроса на КАЖДЫЙ блок хука (не заменяет
    # own_query — добавляет в тот же extra_queries-пул, что уже кросс-
    # опыляет кандидатов внутри секции, см. комментарий выше). Отбор кадра
    # (relevance-гейт + Semantic Visual Director реранк по РЕАЛЬНОЙ фразе)
    # не меняется — слот физически не может стать хуже, только получить
    # более богатый пул на выбор. Только ХУК (не всё тело эпизода) — тот же
    # принцип, что и у всех остальных HOOK-специфичных решений пайплайна
    # (короче клипы, только hardcut, параллакс на всю секцию): это
    # "самый крутой обрыв на кривой удержания" (ЧАСТЬ 9 CLAUDE.md),
    # оправдывает трату бюджета Gemini именно здесь, а не размазывание по
    # всему эпизоду. Бюджет — тот же SHOT_DIRECTOR_MAX_CALLS_PER_RUN/кэш,
    # что у direct_query() (единый счётчик _calls_made в shot_director.py).
    if (os.environ.get("SHOT_DIRECTOR_MODE", "off").strip().lower() == "on"
            and "HOOK" in section_query_pool):
        import shot_director
        atmo_extra = []
        for i, b in enumerate(blocks):
            if not b["section"].startswith("HOOK"):
                continue
            own_query = queries[i]
            if not own_query:
                continue
            context = section_query_pool.get(b["section"], [])
            alt = shot_director.enrich_atmospheric_queries(b["text"], own_query, context, VIDEO_FOLDER)
            if alt:
                atmo_extra.extend(alt)
        if atmo_extra:
            pool = list(section_query_pool.get("HOOK", []))
            base_len = len(pool)
            for q in atmo_extra:
                if q not in pool:
                    pool.append(q)
            section_query_pool["HOOK"] = pool
            print(f"  Атмосферное обогащение хука: +{len(pool) - base_len} "
                  f"запрос(ов) от LLM-режиссёра (media_plan/shot_director_cache/atmo_*.json)")

    write_shot_manifest(VIDEO_FOLDER, blocks, durs, queries)

    if PLAN_ONLY:
        print_plan_summary(blocks, durs, queries, total, xfade_budget, n_before)
        return 0

    # Reference-Guided Look Management (scripts/look_reference.py) — ленивый импорт
    # (см. clip_relevance()/torch выше — тот же принцип: не тянуть модель/CLIP в
    # процесс, если режим off) — только для shadow/assist; look_ref остаётся
    # None иначе — весь блок ниже, использующий look_ref, безопасно
    # пропускается (look_filter=None на каждый клип, ноль влияния на рендер).
    # ДО look_cache_sig — тот вызывает look_ref.cache_signature(), которая
    # должна быть уже импортирована.
    look_ref = None
    if os.environ.get("LOOK_MANAGEMENT_MODE", "off").strip().lower() in ("shadow", "assist"):
        import look_reference as look_ref  # noqa: F401
    look_cache_sig = _look_management_cache_signature(look_ref)
    # Semantic Visual Director (scripts/visual_director.py) — тот же ленивый
    # импорт по режиму, что look_ref выше (не тянуть CLIP-модель в процесс,
    # если режим off). visual_director сам импортирует pipeline_smart (см.
    # докстринг модуля) — это НЕ циклический импорт с точки зрения Python
    # (мы импортируем visual_director уже ВНУТРИ выполнения main(), после
    # того как pipeline_smart полностью загружен), тот же паттерн уже
    # использует look_reference.py.
    visual_director = None
    if os.environ.get("VISUAL_DIRECTOR_MODE", "off").strip().lower() in ("shadow", "assist"):
        import visual_director as visual_director  # noqa: F401
    director_cache_sig = _visual_director_cache_signature(visual_director)
    # П.4: доменная модуляция warm_mult (DOMAIN_WARM_PUSH_SCALE, film_look())
    # — НЕЗАВИСИМА от Look Management/Visual Director (свой режим, свой
    # дефолт), но переиспользует ту же classify_domain(), если look_ref уже
    # импортирован для Look Management — повторный import того же модуля
    # дёшев (sys.modules), только тогда, когда оба включены одновременно
    # реально считается CLIP дважды на кадр (Look Management сегодня off по
    # умолчанию у этого канала — для него domain_ref это единственный вызов).
    # Дефолт "on" (не "off", как у shadow/assist-систем выше) — сознательно:
    # эффект узкий (сегодня только домен snow, см. DOMAIN_WARM_PUSH_SCALE),
    # переиспользует уже проверенный код (не новый эксперимент), правится по
    # прямой жалобе на конкретный кадр, визуально сверен Шагом 7.5 перед тем
    # как считаться готовым.
    # РЕАЛЬНЫЙ БАГ, пойманный при разборе (найден и исправлен в этом же
    # коммите, до первого реального использования): `domain_ref = look_ref`
    # раньше стояло БЕЗ проверки DOMAIN_GRADE_MODE — если Look Management уже
    # включён (LOOK_MANAGEMENT_MODE=shadow/assist), домен-модуляция включалась
    # молча, даже когда DOMAIN_GRADE_MODE=off явно просил её выключить. Флаг
    # теперь проверяется ОДИН РАЗ и решает, участвует ли domain_ref вообще,
    # независимо от того, откуда берётся сам модуль (переиспользуется look_ref
    # или импортируется отдельно).
    domain_ref = None
    if os.environ.get("DOMAIN_GRADE_MODE", "on").strip().lower() != "off":
        domain_ref = look_ref
        if domain_ref is None:
            import look_reference as domain_ref  # noqa: F401
    domain_cache_sig = _domain_grade_cache_signature(domain_ref)
    # Arc-stage awareness — см. _load_arc_stage_by_index() выше. Передаётся
    # НИЖЕ в look_ref.look_correction_filter()/director_score_fn, чтобы Look
    # Management/Visual Director реагировали на драматургическую стадию
    # текущего блока, а не только на содержимое кадра в изоляции (тот же
    # принцип, по которому проф. колорист/монтажёр держит цвет/крупность
    # плана ПОДЧИНЁННЫМИ сюжету, не одинаковыми по всему ролику). Загружаем
    # ОДИН РАЗ, только если хотя бы один потребитель реально активен —
    # иначе это чтение файла впустую.
    arc_stage_by_index = (_load_arc_stage_by_index(VIDEO_FOLDER)
                           if (look_ref is not None or visual_director is not None) else {})
    # РЕАЛЬНЫЙ, найденный вживую пробел (deep-audit, videos/_test20s, слот 0
    # "Пятнадцать килограммов", прямая жалоба пользователя на атмосферность
    # отбора). domain_match_bonus() уже существует и уже подключён к
    # compute_extra_score() — но text_domain_hint(sem_text) считается ТОЛЬКО
    # по локальному тексту 1-2 соседних блоков, а короткие "числовые"/связочные
    # фразы ("Пятнадцать килограммов.") физически не содержат ни одного
    # домен-слова (battle/museum/snow/...) — сигнал молча нулевой, и бонус
    # никогда не срабатывает именно там, где короткая фраза больше всего
    # нуждается в подсказке "к какой теме она принадлежит". Живая проверка:
    # domain_match_bonus для этого блока был 0.0 на КАЖДОМ кандидате
    # (candidate_domain неважен — text_domain уже None). section_domain_hint
    # — тот же text_domain_hint(), но по ОБЪЕДИНЁННОМУ тексту всех авторских
    # (+ атмосферно обогащённых, см. атмосферное обогащение хука выше)
    # запросов секции — считается РОВНО ОДИН раз на секцию (не на кандидата
    # и не на блок), copейки по стоимости. Используется ТОЛЬКО как fallback,
    # когда у КОНКРЕТНОГО блока свой сигнал отсутствует — блок с явным
    # локальным доменом ("зал кинотеатра" -> urban/night) им не переопределяется.
    #
    # РЕАЛЬНЫЙ, найденный вживую баг в ПЕРВОЙ версии этого фикса (тот же
    # заход, до коммита): join(pool) склеивал 20-30+ запросов в одну строку
    # ДЛИННЕЕ, чем текстовый энкодер CLIP умеет принять целиком — truncation
    # обрезает её до первых ~77 токенов, и КАКОЙ ИМЕННО домен выживает после
    # обрезки зависит от порядка запросов в пуле почти случайно. Живая
    # проверка на РЕАЛЬНОМ пуле этого эпизода (26-34 запроса, три чуть
    # разных состава пула между прогонами): join-версия дала три РАЗНЫХ
    # ответа — "battle", "archive_bw", None — на семантически одном и том же
    # пуле, где явное большинство (10 из 16 классифицированных запросов)
    # реально "battle". Голосование по домену КАЖДОГО запроса ПООТДЕЛЬНОСТИ
    # (короткие строки, никогда не обрезаются) и выбор самого частого —
    # устойчиво к порядку и к 1-2 отсутствующим/новым запросам, та же
    # проверка дала "battle" стабильно на всех трёх составах пула.
    section_domain_hint = {}
    if visual_director is not None:
        for sec, pool in section_query_pool.items():
            votes = {}
            for q in pool:
                d, _ = visual_director.lr.text_domain_hint(q)
                if d:
                    votes[d] = votes.get(d, 0) + 1
            if votes:
                section_domain_hint[sec] = max(votes.items(), key=lambda kv: kv[1])[0]
    used_photo_ids = set()   # общий на весь ролик — не даём одной фотке всплыть дважды
    used_video_ids = set()   # то же самое, отдельно для видео (разные ID-пространства)
    used_photo_hashes = []   # aHash уже отобранных фото — ловит визуальные дубли под РАЗНЫМИ ID (см. pexels_photo)
    recent_shot_sizes = []   # скользящее окно масштаба плана (wide/medium/close/detail) — см. estimate_shot_size
    recent_media_types = []   # скользящее окно фото/видео — content-aware чередование, см. main() ниже
    recent_semantic_tags = []   # скользящее окно (domain, role) уже выбранных фото — см. visual_director.repetition_penalty
    stat_count = 0   # 2.2: номер плашки по счёту в ролике -> вариант оформления (chередуются по кругу)
    luma_ema = None   # для сглаживания скачков экспозиции между соседними склейками (см. measure_luma())
    look_report = {}   # индекс -> запись решения Look Management (каждый индекс, не только там, где сработало)
    look_state = None   # аналог luma_ema — {"delta","domain","reference_id"} между клипами (см. look_reference.EMPTY_STATE)
    director_report = {}   # индекс -> {"base_winner","director_winner","diverged"} (см. visual_director_report.json)

    def mark_reports_skipped(i, reason):
        """Единая точка записи "этот индекс пропущен" сразу в ОБА отчёта
        (look_report/director_report) — раньше каждая РАННЯЯ ветка цикла
        (continue до реального рендера кадра) дублировала обе строки по
        отдельности, и реальный баг уже случался: одну из веток добавили,
        забыв продублировать вторую запись (см. коммент у cache-hit ниже) —
        индекс тихо выпадал из visual_director_report.json. Полный путь
        (реальный рендер кадра, дальше по циклу) сюда не относится: там обе
        записи разной формы и без continue между ними, дублировать нечего."""
        look_report[i] = {"decision": reason}
        director_report[i] = {"decision": reason}

    typewriter_click_times = []   # D4: абсолютные секунды щелчков клавиатуры на весь ролик
    # HOOK_KINETIC_CAPTIONS_ENABLED=False (см. его комментарий выше) -> hook_words
    # остаётся [] на весь эпизод, ни один клип хука не получит captions — тот
    # же честный откат, что и при отсутствии alignment.csv (D2).
    hook_words = (load_hook_word_timings(blocks, sub_starts, sub_baseline, real_weights)
                  if HOOK_KINETIC_CAPTIONS_ENABLED else [])
    # P0-3: слова с аудио-шкалы (sub_starts/sub_baseline) переносятся на
    # шкалу реально показанного кадра (visual_starts/durs) — см. докстринг
    # rescale_hook_words_to_visual_time().
    hook_words = rescale_hook_words_to_visual_time(hook_words, blocks, sub_starts, sub_baseline,
                                                     visual_starts, durs)
    for i, (b, d) in enumerate(zip(blocks, durs)):
        # Титр темы — только на ПЕРВОМ кадре новой секции (BLOCK N: Название).
        is_section_start = i == 0 or blocks[i]["section"] != blocks[i - 1]["section"]
        title = section_title(b["section"]) if is_section_start else None
        stat = b.get("stat")
        if not ON_SCREEN_TEXT_ENABLED:
            title, stat = None, None
        stat_variant = stat_count
        # D2: кинетические подписи — только ХУК, только если alignment.csv
        # реально дал слова на эту секцию. hook_words уже пересчитаны в
        # ВИЗУАЛЬНУЮ шкалу (rescale_hook_words_to_visual_time, P0-3) —
        # поэтому здесь тоже visual_starts[i]/d (реальный старт/длительность
        # ЭТОГО клипа на шкале монтажа), а не sub_starts/sub_baseline
        # (аудио-шкала — она бы совпала с визуальной только без "очелове-
        # чивающих" сдвигов durs, см. apply_within_cut_shift и соседей).
        captions = (hook_captions_for_block(hook_words, visual_starts[i], d)
                    if (hook_words and b["section"].startswith("HOOK")) else None)
        if stat:
            stat_count += 1
        # Момент внутри клипа, когда число уже произнесено (см. stat_word_pos
        # в parse_blocks/split_long_blocks) — доля слов ДО тега [stat:...] от
        # общего числа слов В ЭТОМ куске, умноженная на его финальную
        # длительность. Та же word-count-пропорция, что уже используется как
        # честный фоллбэк тайминга по всему пайплайну (не выдумываем более
        # точную модель специально под этот случай).
        stat_word_pos = b.get("stat_word_pos")
        stat_delay = (stat_word_pos / max(1, b["words"]) * d) if (stat and stat_word_pos) else 0.0
        # D4: печатная машинка — только на 5-м варианте плашки (см. add_overlays).
        # Таймкоды щелчков считаем на РЕАЛЬНОЙ (не xfade-раздутой) шкале —
        # sub_starts/sub_baseline уже посчитаны выше по тексту, та же шкала,
        # что уже используется для субтитров (см. комментарий у sub_baseline).
        if stat and stat_variant % 5 == 4:
            real_dur = sub_baseline[i]
            real_delay = max(0.0, min(stat_delay, real_dur - 1.2))
            click_text = stat.upper() if FONT_IS_DISPLAY else stat
            _, click_cd = typewriter_reveal_timing(len(click_text), real_delay, real_dur)
            typewriter_click_times.extend(
                sub_starts[i] + real_delay + k * click_cd for k in range(len(click_text)))
        # Хэш параметров рендера в имени — иначе правка script.txt (текст,
        # тайминг, плашка) без ручной чистки temp_smart/ молча оставляла
        # старый клип под новые данные (тот же класс бага, что уже правили
        # для pexels_cache). Запрос (queries[i]) обязателен в хэше отдельно —
        # без него правка channel_themes.json/media_plan/themes.json при
        # совпавшей длительности тихо оставляла старый (уже нерелевантный)
        # клип под новым запросом — поймано QC-сверкой вживую: клип с новым
        # запросом "medieval sword close up" продолжал показывать старую
        # киноплёнку, потому что длительность/заголовок/плашка/секция не
        # изменились, а запрос в хэш не входил.
        # captions в хэше — D2, чтобы правка/пересчёт alignment.csv не
        # оставляла старые (без подписей или с другим текстом/таймингом)
        # закэшированные клипы висеть под тем же именем.
        # look_cache_sig — Reference-Guided Look Management (см.
        # _look_management_cache_signature()) — грубая, но безопасная
        # инвалидация всех клипов разом при смене lookbook.json/флага.
        # domain_cache_sig — та же грубая инвалидация для DOMAIN_GRADE_MODE/
        # DOMAIN_WARM_PUSH_SCALE (см. _domain_grade_cache_signature(), П.4) —
        # отдельная от Look Management модуляция, отдельная сигнатура.
        # director_cache_sig — РЕАЛЬНЫЙ баг, найден внешним форензик-аудитом
        # (P1-4): раньше params_hash не содержал НИЧЕГО про
        # VISUAL_DIRECTOR_MODE, поэтому off -> assist на уже отрендеренном
        # эпизоде не инвалидировал кэш — см. _visual_director_cache_signature().
        # arc_stage этого КОНКРЕТНОГО блока — тот же класс бага, если его не
        # включить: сгенерировать/пересчитать speech_plan.json ПОСЛЕ первого
        # рендера (или наоборот, удалить его) молча оставило бы старые
        # кэшированные клипы под именем, которое больше не отражает реальный
        # arc_stage, использованный при их рендере (Look Management/Visual
        # Director получили бы другую силу/бонус на пересчёте, а кэш этого
        # бы не заметил).
        params_hash = hashlib.md5(
            f"{d:.3f}|{title}|{stat}|{stat_variant}|{b['section']}|{queries[i]}|{stat_delay:.3f}|"
            f"{captions}|{look_cache_sig}|{domain_cache_sig}|{director_cache_sig}|"
            f"{arc_stage_by_index.get(i)}|{recipe_sig}".encode()).hexdigest()[:8]
        out = os.path.join(TEMP_FOLDER, f"clip_{i:04d}_{params_hash}.mp4")
        if os.path.exists(out) and not verify_clip(out, d)[0]:
            # Кэш раньше доверял голому os.path.exists() — обрезанный/битый
            # клип от прошлого убитого прогона (SIGKILL/OOM ровно так уже
            # падал многочасовой рендер, см. render_tmp_path()) молча
            # принимался бы за готовый на следующем запуске. Теперь огрызок
            # чистится и падает в обычный (не кэш-хит) путь ниже — само-
            # исцеляется повторным рендером вместо того, чтобы либо портить
            # ролик, либо требовать ручной чистки temp_smart/.
            print(f"  [{i+1}] кэш битый (не прошёл verify_clip), перерендерю")
            try:
                os.remove(out)
            except OSError:
                pass
        if os.path.exists(out):
            # РЕАЛЬНЫЙ баг, пойманный вживую: раньше кэш-хит уходил в clips
            # СРАЗУ здесь, по ходу цикла, а промах кэша (ниже) — только В
            # pending_jobs, с append в clips ОТДЕЛЬНЫМ проходом ПОСЛЕ конца
            # всего цикла. Пока хэш параметров у блока не меняется — разницы
            # не видно, но стоило хэшу измениться у ОДНОЙ группы блоков
            # (здесь — у всего ХУКА разом, после правки D2-таймингов) — их
            # кэш-хиты соседних секций уходили в clips ПЕРВЫМИ по ходу цикла,
            # а сам хук (сплошь кэш-промахи) — единым блоком В КОНЕЦ, уже
            # после resolve-прохода. Итог на реальном ролике: хук отрендерился
            # верно, но склейка voed поставила его в самый хвост ролика, а
            # титр BLOCK 1 оказался в первых секундах. Фикс: кэш-хит идёт
            # ТЕМ ЖЕ путём (pending_jobs, future=None, ok сразу True) — единый
            # проход ниже строит clips строго по порядку индекса блока
            # независимо от того, кэш это или свежий рендер.
            pending_jobs.append({"i": i, "out": out, "d": d, "section": b["section"], "block": b,
                                  "video": False, "photo": None, "future": None, "ok": True})
            # Look Management/Semantic Visual Director не могут проанализировать
            # кэш-хит — нет сохранённого пути к исходному фото/свежих levels/wb
            # на этот прогон (см. ЗАМЕТКУ про shadow в look_reference.py).
            # Честная запись в ОБА отчёта (см. mark_reports_skipped() выше —
            # именно на этой ветке однажды реально забыли продублировать
            # вторую запись), не тишина — иначе shadow/director-отчёт на уже
            # отрендеренном эпизоде выглядел бы полным, хотя ничего не
            # проанализировано.
            mark_reports_skipped(i, "skipped_cache_hit")
            continue
        photo = local_photo(i) if use_local else None
        video = None
        # Semantic Visual Director — role/text_domain/director_score_fn
        # существуют для этой итерации независимо от того, каким путём в
        # итоге получено медиа (используются ниже при записи director_report),
        # но САМИ СЧИТАЮТСЯ (text_domain_hint — CLIP-вызов) ТОЛЬКО когда
        # реально есть шанс дойти до pexels_photo() — местный photo уже
        # решённый блок (use_local) сюда вообще не заходит, счёт впустую не
        # тратим (см. докстринг visual_director.py про cost-tradeoff).
        director_role = None
        director_text_domain = None
        director_score_fn = None
        director_entry = None
        director_assist = visual_director is not None and visual_director.VISUAL_DIRECTOR_MODE == "assist"
        # is_opening — САМЫЙ ПЕРВЫЙ блок всего эпизода (i==0, HOOK по
        # построению сценария) — см. OPENING_AESTHETIC_WEIGHT в
        # visual_director.py и is_opening в arbitrate_hook_candidates.
        # Реальная жалоба пользователя (/goal, 29 августа): "самое
        # начало... нужно самый красивый впечатляющий кадр для наивысшего
        # удержания" — работает ДАЖЕ без VLM-арбитра/Gemini (см. её
        # блок-комментарий), т.к. решает сам base/director выбор.
        is_opening_shot = (i == 0)
        if not photo and use_pexels:
            # Смысловая оценка кадра-пробника ВИДЕО против полной фразы —
            # раньше видео-путь такой оценки не имел вообще (только фото),
            # и видео-слот молча оставался на позиционно доставшемся
            # запросе: на реальном рендере фраза "сколько весил настоящий
            # боевой меч" получила зал кинотеатра. Та же модель и та же
            # функция, что уже используются для фото.
            sem_text = semantic_context_text(blocks, i)
            video_sentence_fn = None
            if visual_director is not None:
                video_sentence_fn = functools.partial(
                    visual_director.sentence_relevance, block_text=sem_text)
            if visual_director is not None:
                director_role = visual_director.functional_role(b, is_section_start)
                director_text_domain, _ = visual_director.lr.text_domain_hint(sem_text)
                if director_text_domain is None:
                    director_text_domain = section_domain_hint.get(b["section"])
                director_score_fn = functools.partial(
                    visual_director.compute_extra_score, role=director_role, block_text=sem_text,
                    text_domain=director_text_domain, recent_semantic_tags=recent_semantic_tags,
                    arc_stage=arc_stage_by_index.get(i), own_query=queries[i], is_opening=is_opening_shot)
                director_entry = {}
            # Content-aware чередование вместо механического i%2 (ЧАСТЬ 14
            # раньше просто нечётные->фото/чётные->видео) — зритель
            # подсознательно считывает такую периодичность. Видео заказываем,
            # когда текст блока реально описывает действие/движение
            # (ACTION_WORDS — "штурм"/"погоня"/"удар" и т.п., там сток-видео
            # осмысленно показывает движение), плюс детерминированный хэш
            # текста как база для обычного визуального разнообразия (иначе
            # почти весь ролик без экшн-лексики ушёл бы в чистое фото).
            # Никогда видео под цифру-плашку — движущийся фон мешает читать
            # число (см. static_hold в choose_motion_mode — тот же принцип
            # для фото, но video_render своей motion_mode-ветки не имеет).
            # Не встык 2 видео подряд (видео — акцент, не фон) и не больше
            # 3 фото подряд (иначе монотонно) — то же разнообразие, что уже
            # держат zoom_hist/pan_hist через pick_no_repeat, но асимметрично
            # (видео реже, чем фото, по самой природе приёма).
            h_text = int(hashlib.md5(b["text"][:40].encode()).hexdigest()[:8], 16)
            want_video = (has_action_word(b["text"]) or h_text % 2 == 1) and not stat
            if want_video and recent_media_types[-1:] == ["video"]:
                want_video = False
            if (not want_video and not stat and len(recent_media_types) >= 3
                    and all(t == "photo" for t in recent_media_types[-3:])):
                want_video = True
            prefer_video = want_video and d >= MIN_CLIP + 1.0
            act_qual = action_video_qualifier(b["text"])
            # VLM-арбитр — ТОЛЬКО хук (см. shot_director.arbitrate_hook_
            # candidates, HOOK-only-скоуп объявлен пользователю явно, не
            # скрытый компромисс: свободный тариф Gemini не выдержал бы
            # арбитраж на весь эпизод, см. её блок-комментарий). Реальный,
            # НЕ дополненный соседями текст блока (в отличие от sem_text) —
            # VLM понимает короткую фразу саму по себе.
            hook_arbiter_text = b["text"] if b["section"].startswith("HOOK") else None
            if prefer_video:
                video = pexels_video(queries[i], i, used_ids=used_video_ids, used_hashes=used_photo_hashes,
                                     action_qualifier=act_qual,
                                     extra_queries=section_query_pool.get(b["section"]),
                                     sentence_score_fn=video_sentence_fn, text_key=sem_text,
                                     arbiter_text=hook_arbiter_text, is_opening_shot=is_opening_shot)
                if not video:
                    photo = pexels_photo(queries[i], i, used_ids=used_photo_ids, used_hashes=used_photo_hashes,
                                      recent_sizes=recent_shot_sizes, target_luma=luma_ema,
                                      director_score_fn=director_score_fn, director_assist=director_assist,
                                      director_report=director_entry,
                                      extra_queries=section_query_pool.get(b["section"]), text_key=sem_text,
                                      arbiter_text=hook_arbiter_text, is_opening_shot=is_opening_shot)
            else:
                photo = pexels_photo(queries[i], i, used_ids=used_photo_ids, used_hashes=used_photo_hashes,
                                      recent_sizes=recent_shot_sizes, target_luma=luma_ema,
                                      director_score_fn=director_score_fn, director_assist=director_assist,
                                      director_report=director_entry,
                                      extra_queries=section_query_pool.get(b["section"]), text_key=sem_text,
                                      arbiter_text=hook_arbiter_text, is_opening_shot=is_opening_shot)
                if not photo and d >= MIN_CLIP + 1.0:
                    video = pexels_video(queries[i], i, used_ids=used_video_ids, used_hashes=used_photo_hashes,
                                         action_qualifier=act_qual,
                                         extra_queries=section_query_pool.get(b["section"]),
                                         sentence_score_fn=video_sentence_fn, text_key=sem_text,
                                         arbiter_text=hook_arbiter_text, is_opening_shot=is_opening_shot)
            # Раньше Pexels отключался навсегда после ЛЮБОГО промаха, включая
            # обычную пустую выдачу по одному неудачному запросу. Гасим источник
            # только если API реально отвалился.
            if not photo and not video and PEXELS_BROKEN:
                use_pexels = False
        if not photo and not video:
            # Последняя попытка: локальная папка ПО КРУГУ. Повтор картинки
            # хуже свежего кадра, но несравнимо лучше пропущенного блока
            # (тот при RENDER_STRICT_GATE=1 останавливает всю сборку).
            photo = local_photo(i, allow_cycle=True)
        if not photo and not video:
            print(f"  [{i+1}] нет медиа")
            missing.append(i + 1)
            render_manifest[i] = {"index": i, "status": "failed",
                                   "reason": "нет медиа (ни фото, ни видео)", "section": b["section"]}
            mark_reports_skipped(i, "skipped_no_media")
            continue
        recent_media_types.append("video" if video else "photo")
        del recent_media_types[:-6]
        # Semantic Visual Director — аудит-трейл + скользящее окно
        # (domain, role) для repetition_penalty. director_entry.get(
        # "base_winner") — надёжный маркер того, что pexels_photo() реально
        # дошёл до цикла скачивания/ранжирования (не кэш-хит, не local_photo,
        # не video) — см. комментарий про director_entry=None по умолчанию
        # выше. Домен победившего кадра считается ЗАНОВО, отдельным вызовом
        # candidate_domain_for() на уже выбранном файле (не переносится из
        # pexels_photo через report) — так pexels_photo остаётся семантически
        # "не знающим", что такое домен, только считает extra_score.
        if visual_director is None:
            director_report[i] = {"decision": "skipped_disabled"}
        elif video:
            director_report[i] = {"decision": "skipped_video"}
            # DIRECTOR_RELEVANCE_MISSES для ВИДЕО — реальный, найденный вживую
            # пробел (27 августа, videos/_test20s, слот 7): фото-путь получил
            # свой пол релевантности выше, видео-путь — нет (эта ветка раньше
            # заканчивалась одной строкой "skipped_video"). На практике сам
            # гейт резкости кандидата (video_sharpness_ok в pexels_video())
            # может отсеять ВСЕ кандидаты правильной по смыслу темы (сток
            # "мужчина заносит клинок" почти всегда с motion-blur) и оставить
            # победителем видео из ДРУГОГО запроса общего пула секции (общая
            # гантель для текста про занесённый клинок) — семантически
            # проверить и это тоже, тем же порогом и тем же методом, что и
            # фото (кадр-пробник + sentence_relevance), а не молчать.
            probe, cleanup = extract_video_probe_frame(video)
            if probe is not None:
                try:
                    director_rel = visual_director.sentence_relevance(probe, sem_text)
                finally:
                    if cleanup and os.path.exists(probe):
                        os.remove(probe)
                if director_rel is not None and director_rel < visual_director.DIRECTOR_RELEVANCE_FLOOR:
                    DIRECTOR_RELEVANCE_MISSES.append({
                        "index": i, "text": sem_text, "photo": video, "kind": "video",
                        "relevance": director_rel, "threshold": visual_director.DIRECTOR_RELEVANCE_FLOOR,
                    })
        elif director_entry is None or director_entry.get("base_winner") is None:
            director_report[i] = {"decision": "skipped_not_scored"}
        else:
            director_entry["decision"] = "scored"
            director_entry["role"] = director_role
            director_entry["text_domain"] = director_text_domain
            director_report[i] = director_entry
            candidate_domain = visual_director.candidate_domain_for(photo)
            recent_semantic_tags.append((candidate_domain, director_role))
            del recent_semantic_tags[:-visual_director.REPETITION_WINDOW]
            # DIRECTOR_RELEVANCE_MISSES — тот же принцип, что RELEVANCE_GATE_
            # MISSES (см. её докстринг): is_relevant в кортеже _score_and_pick
            # гейтит только по ORIGIN QUERY (английский запрос-посредник),
            # НЕ по реальному тексту блока — Директор (compute_extra_score)
            # добавляет sentence_relevance() как доп. ранжирующий сигнал, но
            # у НЕГО САМОГО не было пола: победитель мог оказаться семантически
            # слабым по смыслу фразы и всё равно выиграть, если он лучший
            # (не идеальный) среди прошедших origin-query гейт. Реальный
            # найденный случай (27 августа, videos/_test20s, слот 1):
            # sentence_relevance("Так говорят кино, видеоигры и школьные
            # учебники...", фото весов) = 0.041 — фото победило, потому что
            # было лучшим доступным, а не потому что подходило по смыслу.
            # DIRECTOR_RELEVANCE_FLOOR откалиброван на 8 реальных парах этого
            # же эпизода (visual_director.py, см. её докстринг у константы) —
            # только отчёт, победителя не меняет (иначе пришлось бы решать,
            # ЧЕМ его заменить, когда весь пул одинаково слаб).
            director_rel = visual_director.sentence_relevance(photo, sem_text)
            if director_rel is not None and director_rel < visual_director.DIRECTOR_RELEVANCE_FLOOR:
                DIRECTOR_RELEVANCE_MISSES.append({
                    "index": i, "text": sem_text, "photo": photo, "kind": "photo",
                    "relevance": director_rel, "threshold": visual_director.DIRECTOR_RELEVANCE_FLOOR,
                })
        # Непрерывность экспозиции: измеряем яркость ИМЕННО этого кадра,
        # сравниваем со скользящим средним последних клипов — если скачок
        # большой (сток из разных источников редко совпадает по свету),
        # подмешиваем небольшую компенсацию в brightness, а не выравниваем
        # целиком (иначе пропала бы естественная вариативность вообще).
        luma = measure_luma(photo, is_video=False) if photo else measure_luma(video, is_video=True)
        if luma is not None:
            brightness_bias = 0.0 if luma_ema is None else max(-0.035, min(0.035, (luma_ema - luma) * 0.35))
            luma_ema = luma if luma_ema is None else luma_ema * 0.6 + luma * 0.4
        else:
            brightness_bias = 0.0
        # Адаптивная ТЕХНИЧЕСКАЯ нормализация экспозиции ЭТОГО кадра (auto-
        # levels по перцентилям, см. measure_levels()/auto_levels_params()) —
        # решает другую задачу, чем brightness_bias выше (тот сглаживает
        # скачок МЕЖДУ соседними кадрами, это подтягивает разброс ВНУТРИ
        # одного кадра к общей базе), применяется в film_look() ПЕРЕД
        # неизменным творческим грейдом, не вместо него.
        levels, wb = (measure_levels(photo, is_video=False, want_wb=True) if photo
                      else measure_levels(video, is_video=True, want_wb=True))
        # П.2 (аудит "зерно vs частицы в мире"): частицастость ИСХОДНИКА —
        # снижает GRAIN_OPACITY для этого клипа при финальном блендинге,
        # см. measure_particle_score()/PARTICLE_SCORE_THRESHOLD (калибровано
        # на реальных кадрах, не на глаз).
        particle_score = (measure_particle_score(photo, is_video=False) if photo
                           else measure_particle_score(video, is_video=True))
        grain_scale = (PARTICLE_GRAIN_SCALE if (particle_score is not None
                        and particle_score >= PARTICLE_SCORE_THRESHOLD) else 1.0)
        energy_bias = max(-0.5, min(0.5, energy_lvls[i] - 1.0))
        # Reference-Guided Look Management (см. scripts/look_reference.py) —
        # ТОЛЬКО для фото (video-клипы не входят в эту версию системы, см.
        # докстринг модуля). Каждый индекс блока получает запись в
        # look_report — даже когда фича выключена или это video-клип — тот
        # же принцип полноты аудита, что уже применяет render_manifest
        # (пользователь указал на этот пробел явно). has_face — свой,
        # отдельный вызов detect_face_anchor() (та же функция, что уже
        # использует resolve_crop_anchor() внутри kenburns()/
        # parallax_kenburns() для кропа, второй недорогой вызов здесь — не
        # переиспользование внутреннего состояния тех функций, т.к. решение
        # о коррекции нужно ДО диспетчеризации рендера). scene_boundary —
        # is_section_start уже посчитан выше в этой же итерации, сигнал для
        # сброса EMA-сглаживания на границе секции сценария (см.
        # look_correction_filter()).
        look_filter = None
        if not photo:
            look_report[i] = {"decision": "skipped_video" if video else "skipped_no_media"}
        elif look_ref is None:
            look_report[i] = {"decision": "skipped_disabled"}
        else:
            has_face = detect_face_anchor(photo) is not None
            look_filter, look_entry, look_state = look_ref.look_correction_filter(
                photo, levels, wb, has_face, scene_boundary=is_section_start,
                section=b["section"], prev_state=look_state, arc_stage=arc_stage_by_index.get(i))
            look_report[i] = look_entry
        # П.4: домен кадра для DOMAIN_WARM_PUSH_SCALE (film_look()) — только
        # фото (видео не участвует, тот же скоуп, что Look Management выше),
        # свой независимый вызов classify_domain() (не переиспользует
        # look_entry — та не гарантирует поле "domain" на всех ветках
        # решения Look Management, см. look_correction_filter()).
        domain = None
        if photo and domain_ref is not None:
            try:
                domain, _domain_margin = domain_ref.classify_domain(photo)
            except Exception:
                domain = None
        # Один непойманный сбой в рендере ОДНОГО кадра (редкий edge case —
        # битый файл, неожиданный тип данных и т.п.) раньше падал наружу и
        # убивал весь многочасовой прогон main() целиком, теряя ВСЮ уже
        # проделанную работу. kenburns()/video_render() и так возвращают
        # False на предсказуемые сбои (ffmpeg не встал и т.п.) — это перехват
        # именно НЕПРЕДВИДЕННОГО исключения, кадр просто уходит в missing
        # (как и любой другой honest-failure), рендер продолжается дальше.
        future = None
        try:
            if video:
                if render_pool:
                    future = render_pool.submit(
                        _timed_render, video_render, i, video, out, d, title=title, stat=stat, section=b["section"],
                        stat_variant=stat_variant, brightness_bias=brightness_bias,
                        energy_bias=energy_bias, stat_delay=stat_delay, levels=levels, wb=wb, grain_scale=grain_scale,
                        handheld=has_action_word(b["text"]), captions=captions,
                        ffmpeg_threads=RENDER_FFMPEG_THREADS)
                    ok = None
                else:
                    ok = _timed_render(video_render, i, video, out, d, title=title, stat=stat, section=b["section"],
                                       stat_variant=stat_variant, brightness_bias=brightness_bias,
                                       energy_bias=energy_bias, stat_delay=stat_delay, levels=levels, wb=wb, grain_scale=grain_scale,
                                       handheld=has_action_word(b["text"]), captions=captions)
            else:
                # anti-repetition: хэш сам по себе не мешает 3 зумам подряд случайно
                # совпасть — держим окно последних решений и форсируем смену при повторе.
                _, zi_cand, pd_cand = kb_hash_choices(photo)
                zoom_in = pick_no_repeat(zoom_hist, zi_cand, [True, False], max_repeat=2)
                pan_dir = pick_no_repeat(pan_hist, pd_cand, PAN_DIRECTIONS, max_repeat=2)
                # Параллакс — только на самые заметные точки ролика (хук целиком +
                # первый кадр каждого раздела + момент [climax]), не на все фото:
                # покадровый рендер с depth-моделью в разы дороже по времени
                # zoompan-версии, на 40+ кадрах это лишние десятки минут ради
                # эффекта, который большую часть ролика зритель всё равно не
                # разглядывает так пристально, как хук/открывашки/разоблачение.
                # По прямому запросу пользователя (17-28-минутные ролики,
                # "в отдельных местах уже нельзя сделать отдельно параллакс,
                # например когда что-то важное") — [climax] добавлен третьим
                # условием: та же разметка, что уже используют reveal_hold в
                # speech_planner.py и climax dip в музыке (CLIMAX_DIP_LEAD_SEC),
                # не новый сигнал, тот же самый "момент разоблачения", который
                # сценарист и так помечает тегом. Кадр НЕ дублируется — climax
                # даёт максимум 1 доп. слот на секцию (см. is_climax присвоение
                # выше, k==0). Всегда ПОСЛЕДОВАТЕЛЬНО в главном процессе (см.
                # RENDER_POOL_ENABLED выше) — только тут живёт depth-модель.
                is_highlight = is_parallax_highlight(b, is_section_start)
                ok = False
                if PARALLAX_ENABLED and is_highlight:
                    # Параллакс (2.5D depth remap) — своя, уже отдельно проверенная
                    # зум/пан-математика, motion_mode на него не распространяем:
                    # это отдельный, более дорогой визуальный приём для самых
                    # заметных точек ролика, не нуждается в дополнительной
                    # категоризации поверх собственной.
                    ok = _timed_render(parallax_kenburns, i, photo, out, d, title=title, zoom_in=zoom_in,
                                            pan_dir=pan_dir, stat=stat, section=b["section"],
                                            stat_variant=stat_variant, brightness_bias=brightness_bias,
                                            energy_bias=energy_bias, stat_delay=stat_delay, levels=levels, wb=wb, grain_scale=grain_scale,
                                            captions=captions, look_filter=look_filter, domain=domain)
                if not ok:
                    photo_hash, _, _ = kb_hash_choices(photo)
                    cur_shot_size = recent_shot_sizes[-1] if recent_shot_sizes else None
                    motion_mode = choose_motion_mode(b, is_section_start, photo_hash, shot_size=cur_shot_size)
                    if render_pool:
                        future = render_pool.submit(
                            _timed_render, kenburns, i, photo, out, d, title=title, zoom_in=zoom_in, pan_dir=pan_dir,
                            stat=stat, section=b["section"], motion_mode=motion_mode,
                            brightness_bias=brightness_bias, energy_bias=energy_bias,
                            stat_variant=stat_variant, stat_delay=stat_delay, levels=levels, wb=wb, grain_scale=grain_scale,
                            captions=captions, look_filter=look_filter, ffmpeg_threads=RENDER_FFMPEG_THREADS, domain=domain)
                        ok = None
                    else:
                        ok = _timed_render(kenburns, i, photo, out, d, title=title, zoom_in=zoom_in, pan_dir=pan_dir,
                                      stat=stat, section=b["section"], motion_mode=motion_mode,
                                      brightness_bias=brightness_bias, energy_bias=energy_bias,
                                      stat_variant=stat_variant, stat_delay=stat_delay, levels=levels, wb=wb, grain_scale=grain_scale,
                                      captions=captions, look_filter=look_filter, domain=domain)
        except Exception as e:
            print(f"  [{i+1}] непредвиденный сбой рендера, пропускаю кадр: {type(e).__name__} {e}")
            ok, future = False, None
        pending_jobs.append({"i": i, "out": out, "d": d, "section": b["section"], "block": b,
                              "video": bool(video), "photo": photo, "future": future, "ok": ok})
        if i % 20 == 0 or i < 3:
            print(f"  [{i+1}/{len(blocks)}] {d:.1f}с {b['words']} слов ({'видео' if video else 'фото'}, "
                  f"{'в очереди' if future is not None else 'готово' if ok else 'пропуск'})")
        if i % 10 == 9:
            log_render_diagnostics(f"block_{i+1}/{len(blocks)}")
        if use_pexels and not use_local and i % 10 == 9:
            time.sleep(0.4)

    # Резолвим отложенные (в пуле) рендеры — future.result() блокирует, только
    # если этот конкретный клип ещё не доехал, к этому моменту у воркеров уже
    # было всё время работы цикла выше, чтобы прогрызть очередь. Порядок —
    # строго по индексу блока (pending_jobs собран в порядке цикла), не по
    # порядку завершения — xfade-склейка ниже требует правильную последовательность.
    check_jobs_in_order(pending_jobs)
    for job in pending_jobs:
        if job["future"] is not None:
            try:
                job["ok"] = job["future"].result()
            except Exception as e:
                print(f"  [{job['i']+1}] непредвиденный сбой рендера в пуле, пропускаю кадр: "
                      f"{type(e).__name__} {e}")
                job["ok"] = False
        if job["ok"]:
            clips.append(job["out"])
            clip_durs.append(job["d"])
            clip_sections.append(job["section"])
            clip_blocks.append(job["block"])
            if not job["video"] and job["photo"]:
                media_log.append((job["i"], job["photo"]))
                # Пост-рендер QC (RENDER_SHARPNESS_DROP_RATIO выше) — единственная
                # проверка в пайплайне, которая смотрит на ГОТОВЫЙ кадр, а не на
                # исходное фото ДО Ken Burns/параллакса/ГРИП/грейда. Дёшево (Лапла-
                # сиан на уже скачанном исходнике + один кадр-пробник уже готового
                # клипа, без новой модели/сети) — считается синхронно здесь же, не
                # в пуле, лишние доли секунды на клип не стоят отдельного воркера.
                flagged, ratio = render_sharpness_regression(job["photo"], job["out"])
                if flagged:
                    RENDER_QC_REPORT.append({
                        "index": job["i"], "source": job["photo"], "rendered": job["out"],
                        "ratio": ratio, "threshold": RENDER_SHARPNESS_DROP_RATIO,
                    })
            elif job["video"]:
                # Второй, независимый предохранитель поверх селекционного
                # гейта (video_sharpness_ok в pexels_video()): если ВЕСЬ пул
                # кандидатов был смазан (fallback всё равно не оставляет слот
                # пустым, см. философию ЧАСТИ 13), это честно всплывает здесь
                # на ГОТОВОМ клипе — та же логика, что render_sharpness_
                # regression() даёт фото, но для видео нет "источника"
                # отдельно от рендера (клип и есть исходник, без Ken Burns/
                # ГРИП поверх), поэтому проверяем абсолютную резкость, не
                # отношение.
                v_sharp_ok = video_sharpness_ok(job["out"])
                if v_sharp_ok is False:
                    RENDER_QC_REPORT.append({
                        "index": job["i"], "source": None, "rendered": job["out"],
                        "ratio": None, "threshold": VIDEO_SHARPNESS_REJECT,
                        "reason": "video_median_sharpness_below_threshold",
                    })
            render_manifest[job["i"]] = {"index": job["i"], "status": "ok", "path": job["out"],
                                          "section": job["section"], "duration": job["d"],
                                          "kind": "video" if job["video"] else "photo"}
        else:
            missing.append(job["i"] + 1)
            render_manifest[job["i"]] = {"index": job["i"], "status": "failed",
                                          "reason": "см. консольный лог выше (run_ffmpeg_with_retry) — "
                                                    f"после {RENDER_RETRY_ATTEMPTS} попыток",
                                          "section": job["section"], "duration": job["d"]}
    if render_pool:
        render_pool.shutdown(wait=True)
    log_render_diagnostics("render_done")
    print(f"  Рендер завершён: {len(clips)}/{len(blocks)} клипов")

    manifest_path = os.path.join(VIDEO_FOLDER, "media_plan", "render_manifest.json")
    os.makedirs(os.path.dirname(manifest_path), exist_ok=True)
    manifest_tmp = manifest_path + ".tmp"
    with open(manifest_tmp, "w", encoding="utf-8") as f:
        json.dump({"total_blocks": len(blocks), "ok": len(clips), "missing": missing,
                    "clips": [render_manifest[i] for i in sorted(render_manifest)]},
                   f, ensure_ascii=False, indent=2)
    os.replace(manifest_tmp, manifest_path)

    # RELEVANCE_GATE_MISSES — см. её докстринг у объявления выше: слоты, где
    # ВЕСЬ просмотренный пул кандидатов провалил relevance-гейт, но слот всё
    # равно не остался пустым (философия ЧАСТИ 13). Тот же принцип честной
    # записи, что уже применяет look_manifest.json чуть ниже — пишем ВСЕГДА
    # (даже пустой список), не пропускаем файл молча.
    relevance_report_path = os.path.join(VIDEO_FOLDER, "media_plan", "relevance_gate_report.json")
    relevance_report_tmp = relevance_report_path + ".tmp"
    with open(relevance_report_tmp, "w", encoding="utf-8") as f:
        json.dump({"misses": RELEVANCE_GATE_MISSES}, f, ensure_ascii=False, indent=2)
    os.replace(relevance_report_tmp, relevance_report_path)
    if RELEVANCE_GATE_MISSES:
        # Формулировка "весь пул провалил гейт" здесь исторически неточна —
        # см. докстринг STOCK_EXHAUSTED_MISSES выше: на деле проверяется
        # только ПОБЕДИТЕЛЬ, а лексикографический кортеж _score_and_pick()
        # может предпочесть нерелевантного, но уникального кандидата
        # релевантному дублю — победитель нерелевантен, а пул при этом не
        # обязательно исчерпан. Честная пул-вайд проверка — ниже.
        print(f"  ВНИМАНИЕ: {len(RELEVANCE_GATE_MISSES)} слот(ов) получили кандидата НИЖЕ порога "
              f"relevance — см. media_plan/relevance_gate_report.json, сверить глазами на Шаге 7.5.")

    # STOCK_EXHAUSTED_MISSES — см. её докстринг у объявления выше: строго
    # более сильный сигнал, чем RELEVANCE_GATE_MISSES — не "победитель не
    # идеален", а "ни один кандидат из ВСЕГО просмотренного пула не прошёл
    # ни relevance, ни резкость одновременно" (независимо от дедупа). На
    # это стоит реагировать иначе, чем на обычный промах: не "сверить
    # глазами", а "стоку тут физически нечего предложить — см. Шаг 5,
    # AI-картинка/видео вместо стока для этого слота".
    stock_exhausted_path = os.path.join(VIDEO_FOLDER, "media_plan", "stock_exhausted_report.json")
    stock_exhausted_tmp = stock_exhausted_path + ".tmp"
    with open(stock_exhausted_tmp, "w", encoding="utf-8") as f:
        json.dump({"misses": STOCK_EXHAUSTED_MISSES}, f, ensure_ascii=False, indent=2)
    os.replace(stock_exhausted_tmp, stock_exhausted_path)
    if STOCK_EXHAUSTED_MISSES:
        idxs = [m["index"] for m in STOCK_EXHAUSTED_MISSES]
        print(f"  ВНИМАНИЕ: {len(STOCK_EXHAUSTED_MISSES)} слот(ов) {idxs} — сток не дал НИ ОДНОГО "
              f"кандидата, прошедшего и relevance, и резкость (весь просмотренный пул честно "
              f"исчерпан) — см. media_plan/stock_exhausted_report.json. Для этих слотов сток — "
              f"тупик, не проверка глазами: нужна AI-картинка/видео (Шаг 5) вместо стока.")

    # RENDER_QC_REPORT — см. render_sharpness_regression()/RENDER_SHARPNESS_
    # DROP_RATIO выше: клипы, где ГОТОВЫЙ рендер ощутимо размытее своего же
    # источника (реальный найденный случай — DOF-баг 27 августа). Advisory,
    # не hard-reject — тот же принцип честной записи, что и у остальных
    # отчётов здесь.
    render_qc_path = os.path.join(VIDEO_FOLDER, "media_plan", "render_qc_report.json")
    render_qc_tmp = render_qc_path + ".tmp"
    with open(render_qc_tmp, "w", encoding="utf-8") as f:
        json.dump({"flagged": RENDER_QC_REPORT}, f, ensure_ascii=False, indent=2)
    os.replace(render_qc_tmp, render_qc_path)
    if RENDER_QC_REPORT:
        print(f"  ВНИМАНИЕ: {len(RENDER_QC_REPORT)} клип(ов) заметно размытее своего исходника "
              f"(rendered/source < {RENDER_SHARPNESS_DROP_RATIO}) — см. media_plan/render_qc_report.json, "
              f"сверить глазами на Шаге 7.5.")

    # DIRECTOR_RELEVANCE_MISSES — см. её докстринг у объявления выше и
    # DIRECTOR_RELEVANCE_FLOOR в visual_director.py: победитель Директора
    # семантически слаб по РЕАЛЬНОМУ тексту блока (не по origin query).
    # Пустой список, если VISUAL_DIRECTOR_MODE не assist (условие "scored"
    # выше просто никогда не срабатывает) — пишем файл всё равно, тот же
    # принцип честной записи "нечего сообщить", что и у остальных отчётов.
    director_rel_path = os.path.join(VIDEO_FOLDER, "media_plan", "director_relevance_report.json")
    director_rel_tmp = director_rel_path + ".tmp"
    with open(director_rel_tmp, "w", encoding="utf-8") as f:
        json.dump({"misses": DIRECTOR_RELEVANCE_MISSES}, f, ensure_ascii=False, indent=2)
    os.replace(director_rel_tmp, director_rel_path)
    if DIRECTOR_RELEVANCE_MISSES:
        print(f"  ВНИМАНИЕ: {len(DIRECTOR_RELEVANCE_MISSES)} слот(ов) — выбранный кадр семантически "
              f"слаб по РЕАЛЬНОМУ тексту блока (не по запросу) — см. "
              f"media_plan/director_relevance_report.json, сверить глазами на Шаге 7.5.")

    # Reference-Guided Look Management — аудит-трейл (см. scripts/
    # look_reference.py). look_report пуст, если фича выключена/lookbook
    # пуст (реальный случай сегодня — см. LOOKBOOK_JSON_PATH) — тогда пишем
    # пустой отчёт с enabled=False, не пропускаем файл молча (тот же принцип
    # честной записи "нечего сообщить", что уже применяет speech_validator.py
    # к media_plan/pause_decisions.json).
    look_manifest_path = os.path.join(VIDEO_FOLDER, "media_plan", "look_manifest.json")
    look_manifest_tmp = look_manifest_path + ".tmp"
    cache_hits_skipped_analysis = sum(1 for e in look_report.values() if e.get("decision") == "skipped_cache_hit")
    with open(look_manifest_tmp, "w", encoding="utf-8") as f:
        json.dump({"enabled": look_ref is not None,
                    "cache_hits_skipped_analysis": cache_hits_skipped_analysis,
                    "clips": [look_report[i] for i in sorted(look_report)]},
                   f, ensure_ascii=False, indent=2)
    os.replace(look_manifest_tmp, look_manifest_path)
    # Честное предупреждение: shadow/assist на уже отрендеренном эпизоде
    # (temp_smart/ содержит кэш из прошлого прогона) не анализирует
    # кэш-хиты — у них физически нет сохранённого пути к исходному фото на
    # этот прогон (см. докстринг look_reference.py). Отчёт в этом случае
    # НЕ полная симуляция assist — печатаем это явно, не оставляем
    # оператора гадать, почему клипов в look_manifest.json меньше, чем
    # блоков в эпизоде.
    if look_ref is not None and cache_hits_skipped_analysis:
        print(f"  Look Management: {cache_hits_skipped_analysis} клип(ов) пропущено анализом "
              f"(кэш из прошлого прогона) — для честного shadow/assist-прогона на этом эпизоде "
              f"очисти temp_smart/ и перезапусти.")

    # Semantic Visual Director — аудит-трейл (см. scripts/visual_director.py).
    # Тот же принцип, что look_manifest.json чуть выше: пустой/enabled=False
    # отчёт при выключенной фиче — не тишина, честная запись "нечего сообщить".
    director_manifest_path = os.path.join(VIDEO_FOLDER, "media_plan", "visual_director_report.json")
    director_manifest_tmp = director_manifest_path + ".tmp"
    director_scored = sum(1 for e in director_report.values() if e.get("decision") == "scored")
    director_diverged = sum(1 for e in director_report.values() if e.get("diverged"))
    director_cache_hits_skipped = sum(1 for e in director_report.values() if e.get("decision") == "skipped_cache_hit")
    with open(director_manifest_tmp, "w", encoding="utf-8") as f:
        json.dump({"enabled": visual_director is not None,
                    "mode": visual_director.VISUAL_DIRECTOR_MODE if visual_director is not None else "off",
                    "scored": director_scored,
                    "diverged_from_base": director_diverged,
                    "cache_hits_skipped_analysis": director_cache_hits_skipped,
                    "clips": [director_report[i] for i in sorted(director_report)]},
                   f, ensure_ascii=False, indent=2)
    os.replace(director_manifest_tmp, director_manifest_path)
    # То же честное предупреждение, что уже есть у Look Management чуть выше
    # (см. cache_hits_skipped_analysis там) — тот же класс "shadow/assist на
    # уже отрендеренном эпизоде не полная симуляция".
    if visual_director is not None and director_cache_hits_skipped:
        print(f"  Visual Director: {director_cache_hits_skipped} клип(ов) пропущено анализом "
              f"(кэш из прошлого прогона) — для честного shadow/assist-прогона на этом эпизоде "
              f"очисти temp_smart/ и перезапусти.")

    # Жёсткий финальный гейт: цель не "никогда не упасть" (нечестное
    # обещание — сеть/диск/память могут отказать всегда), а чтобы одиночный
    # сбой не портил ГОТОВЫЙ ролик молча. Раньше пропущенный клип просто
    # уходил в missing, а final.mp4 всё равно собирался с меньшим числом
    # клипов и растянутым freeze-кадром на месте пропуска (см.
    # pad_to_length ниже) — ненулевой код возврата был единственным
    # признаком проблемы, и его легко не заметить в конце многочасового
    # лога. RENDER_STRICT_GATE=0 возвращает старое поведение для тех, кому
    # осознанно нужна частичная сборка (ручная досборка позже).
    if missing and RENDER_STRICT_GATE:
        print(f"\nСТОП: {len(missing)} клип(ов) не приняты — final.mp4 НЕ собран "
              f"(RENDER_STRICT_GATE=1). Причины — {manifest_path}:")
        for i in missing:
            entry = render_manifest.get(i - 1, {})
            print(f"  [{i}] {entry.get('reason', 'причина не зафиксирована')}")
        print("Перезапусти прогон — уже готовые клипы (atomic-кэш) переиспользуются, "
              "перерендерятся только пропущенные.")
        return 1

    if not clips:
        print("Нет клипов")
        return 1
    merged = os.path.join(TEMP_FOLDER, "merged.mp4")
    with stage_timer.stage("assembly_xfade", n_clips=len(clips)):
        ok, xfade_total = xfade_chain_chunked(clips, clip_durs, clip_sections, merged, TEMP_FOLDER,
                                               blocks=clip_blocks)
    if not ok:
        concat = os.path.join(TEMP_FOLDER, "concat.txt")
        # Пути ТОЛЬКО абсолютные: concat-демуксер ffmpeg резолвит относительные
        # пути от папки самого concat.txt, а не от cwd — иначе сборка падает.
        open(concat, "w", encoding="utf-8").write(
            "".join(f"file '{os.path.abspath(c)}'\n" for c in clips))
        # Тот же пробел, что у xfade_chain()/финального мукса выше — fallback-
        # путь на concat не должен быть НЕЗАЩИЩЁННЕЕ пути, с которого он
        # откатывается. -c copy — тоже быстрый ремукс, щедрый множитель
        # достаточен как последний рубеж против настоящего зависания.
        try:
            r = subprocess.run(["ffmpeg", "-y", "-f", "concat", "-safe", "0",
                                "-i", concat, "-c", "copy", merged], capture_output=True, text=True,
                               timeout=max(180, total))
        except subprocess.TimeoutExpired:
            print(f"Склейка (concat) зависла (таймаут {max(180, total):.0f}с).")
            return 1
        if r.returncode != 0:
            print("Склейка:", r.stderr[-300:])
            return 1
    merged, pad_gap = pad_to_length(merged, total, TEMP_FOLDER)
    # Симметричный контроль расхождения. Гейт по pad_gap ниже ловит только
    # СЛИШКОМ КОРОТКОЕ видео (заморозка в хвосте). Обратная сторона —
    # видео ДЛИННЕЕ аудио — раньше не диагностировалась вообще: финальный
    # мукс просто обрезал лишнее по -t, и это выглядело как штатная
    # сборка, хотя означало, что картинка накопительно отстаёт от голоса
    # (ровно тот баг, который лечат plan_transitions/
    # quantize_durations_to_frames). Теперь перебор виден в логе числом.
    try:
        merged_dur = get_media_duration(merged)
        overshoot = merged_dur - total
        if overshoot > 0.5:
            print(f"  ВНИМАНИЕ: смонтированное видео на {overshoot:.2f}с длиннее аудио "
                  f"({merged_dur:.2f}с против {total:.2f}с) — финальный мукс обрежет хвост "
                  f"по -t, но это значит, что картинка к концу отстаёт от голоса на эту "
                  f"же величину. Ожидаемое расхождение после кадровой сетки — доли "
                  f"секунды; больше — повод смотреть на бюджет склейки "
                  f"(estimate_xfade_budget/plan_transitions) или на пропущенные клипы.")
    except Exception:
        pass
    # Freeze-padding существует ТОЛЬКО чтобы закрыть маленький остаточный
    # зазор от xfade-округления (обычно доли секунды) — не как приёмный
    # механизм для реально пропущенного клипа. Раньше большой pad_gap
    # (например, вся длительность потерянного кадра) просто ронял код
    # возврата в конце main(), но final.mp4 всё равно ЗАПИСЫВАЛСЯ с
    # замороженным хвостом — ненулевой exit code легко потерять в конце
    # многочасового лога, а файл выглядит "готовым". Это ПРОВЕРКА ЦЕЛОСТНОСТИ:
    # ловит ЛЮБОЕ необъяснённое расхождение длительности (включая
    # гипотетическую ошибку расчёта xfade-бюджета), не только missing —
    # но именно НЕОБЪЯСНЁННОЕ. Если missing уже непустой и мы вообще
    # добрались сюда, значит RENDER_STRICT_GATE=0 (иначе гейт выше уже
    # вернул бы 1) — пользователь осознанно попросил старое поведение
    # "частичная сборка вместо срыва", и pad_gap тут ПОЛНОСТЬЮ объясняется
    # длительностью уже залогированных пропущенных клипов, а не скрытым
    # багом бюджета xfade. Дважды наказывать за один и тот же осознанный
    # пропуск (сначала пометить missing, потом всё равно не собрать файл)
    # значит не давать lenient-режиму вообще ничего лениться.
    if pad_gap > PAD_GAP_HARD_CAP_SEC and not (missing and not RENDER_STRICT_GATE):
        print(f"\nСТОП: заморозка в хвосте {pad_gap:.1f}с превышает допуск "
              f"{PAD_GAP_HARD_CAP_SEC:.1f}с — final.mp4 НЕ собран (расчёт длительностей "
              f"разошёлся сильнее, чем можно списать на округление xfade).")
        return 1

    # -shortest САМ ПО СЕБЕ недостаточен с -c:v copy: копирование пакетов
    # режет только по границам GOP исходного клипа, а не по факту конца
    # аудио — на реальном 17-минутном ролике это давало +6с видео без
    # звука сверху (проверено вживую). Явный -t с точной длительностью
    # аудио режет ровно там, где надо, независимо от размера GOP.
    # A1: атмосферная подложка + сайдчейн-дакинг под голосом (build_music_mix,
    # безопасный откат на чистый голос, если ассет отсутствует/выключен).
    # A7: loudnorm теперь считается на ГОТОВОМ миксе голос+музыка, а не на
    # одном голосе — иначе музыка добавляла бы громкость ПОСЛЕ калибровки
    # под цель (LOUDNORM_TARGET_I) и сводила бы её к нулю (та же ошибка,
    # что "нормализовать трек, потом наложить ещё один трек поверх без
    # пересчёта").
    # A2: границы HOOK/FINAL по реальным длительностям отрендеренных клипов
    # (не по словам сценария — клипы уже учитывают все реальные подрезки/
    # sub-cuts) — секции идут по порядку HOOK -> BLOCK* -> FINAL, так что
    # достаточно суммы длительностей внутри каждой без отдельного поиска границ.
    hook_end = sum(d for sec, d in zip(clip_sections, clip_durs) if sec.startswith("HOOK"))
    final_start = sum(d for sec, d in zip(clip_sections, clip_durs) if not sec.startswith("FINAL"))
    # A6: обработка голоса (highpass/EQ/деэссер/компрессия) ДО подмешивания
    # музыки — тот же порядок, что в реальном пост-продакшене: сначала
    # приводишь дорожку диктора в порядок, потом кладёшь её в микс.
    voice_processed = os.path.join(TEMP_FOLDER, "voice_processed.wav")
    voice_processed = process_voice(AUDIO_FILE, voice_processed)
    premix = os.path.join(TEMP_FOLDER, "premix.wav")
    # 2.8: [climax] в script.txt -> реальный момент на той же шкале, что уже
    # использует sub_starts (real, не xfade-раздутая — см. комментарий у неё).
    climax_times = [sub_starts[i] for i, b in enumerate(blocks) if b.get("is_climax")]
    # P1-15: осознанно длинные паузы (см. load_pause_windows/PAUSE_SWELL_MIN_KEEP_SEC)
    # в РЕАЛЬНОМ (после обрезки) времени — та же raw_to_real_time, что уже
    # даёт точную шкалу подписям хука, здесь даёт точную шкалу музыке.
    _pw_cuts = load_pause_cuts()
    pause_windows_real = [(raw_to_real_time(ws, _pw_cuts), keep)
                           for ws, keep in load_pause_windows() if keep >= PAUSE_SWELL_MIN_KEEP_SEC]
    # P0 (нейрокогнитивная критика): не накладывать swell поверх climax dip
    # на одном и том же участке трека — см. _exclude_climax_overlapping_windows().
    pause_windows_real = _exclude_climax_overlapping_windows(pause_windows_real, climax_times)
    premix = build_music_mix(voice_processed, total, premix, hook_end=hook_end, final_start=final_start,
                              climax_times=climax_times, pause_windows_real=pause_windows_real)
    # D4: щелчки клавиатуры поверх готового микса — ПОСЛЕ музыки/дакинга
    # (иначе сайдчейн реагировал бы и на сами щелчки), ДО финального loudnorm
    # (клики тоже участвуют в мастеринге громкости целиком, не бесплатный
    # довесок сверху уже откалиброванного микса).
    if typewriter_click_times:
        premix_clicks = os.path.join(TEMP_FOLDER, "premix_clicks.wav")
        premix = add_typewriter_clicks(premix, typewriter_click_times, total, premix_clicks)
    # loudnorm — целевая громкость YouTube (-14 LUFS integrated, -1.5dB
    # true peak потолок, LRA 11) вместо "как есть от TTS". Было -16: на
    # этой платформе тише целевой означает, что ролик звучит глуше соседних
    # в ленте (платформа поднимает громкость только ГРОМКИХ роликов, тихие
    # не подтягивает). ЧЕТЫРЕ места обязаны совпадать — дефолт target_i у
    # measure_loudnorm_stats() и три литерала ниже: первый проход меряет
    # под одну цель, второй применяет под другую, и рассинхрон дал бы
    # смещение громкости, которого нет ни в одном логе. Разные
    # заказы озвучки/движки иначе дают заметно разную громкость от эпизода
    # к эпизоду — не проф. уровень, если зритель тянется к громкости между
    # роликами одного канала. Двухпроходный (measure -> linear=true) вместо
    # однопроходного динамического — тот подстраивает усиление на лету и
    # даёт неровную громкость внутри самого ролика. afade — раньше ролик
    # начинался и обрывался всухую (щелчок на монтажный лад, не финал).
    loud_stats = measure_loudnorm_stats(premix)
    fade_out_st = max(0.0, total - 2.0)
    if loud_stats:
        af = (f"loudnorm=I={LOUDNORM_TARGET_I}:TP={LOUDNORM_TARGET_TP}:LRA={LOUDNORM_TARGET_LRA}:linear=true:"
              f"measured_I={loud_stats['input_i']}:measured_TP={loud_stats['input_tp']}:"
              f"measured_LRA={loud_stats['input_lra']}:measured_thresh={loud_stats['input_thresh']}:"
              f"offset={loud_stats['target_offset']},"
              f"afade=t=in:st=0:d=0.4,afade=t=out:st={fade_out_st:.3f}:d=2")
    else:
        af = (f"loudnorm=I={LOUDNORM_TARGET_I}:TP={LOUDNORM_TARGET_TP}:LRA={LOUDNORM_TARGET_LRA},"
              f"afade=t=in:st=0:d=0.4,afade=t=out:st={fade_out_st:.3f}:d=2")
    # Атомарная запись — тот же принцип, что render_tmp_path()/finalize_render()
    # у отдельных клипов (см. коммент там): final.mp4 — то, что пользователь
    # ФАКТИЧЕСКИ проверяет как "готово или нет". Обрыв ровно на этом финальном
    # проходе (пусть и короткий по времени — это -c:v copy, не перекодирование)
    # раньше оставлял бы обрезанный final.mp4 под финальным именем, что
    # выглядело бы как "готовый, но битый" файл, а не как "рендер не доехал".
    output_tmp = render_tmp_path(OUTPUT_FILE)
    # РЕАЛЬНЫЙ пробел, пойманный аудитом того же класса багов, что и
    # SPEED_RAMP_MAX_SOURCE_FPS/parallax stderr-deadlock/xfade_chain выше —
    # у ПОСЛЕДНЕГО шага перед final.mp4 (после часов рендера всех клипов)
    # не было никакого timeout вообще. Зависание здесь молча теряло бы весь
    # уже сделанный прогон. -c:v copy — быстрый ремукс, не перекодирование,
    # поэтому щедрого множителя достаточно (сама операция обычно на порядок
    # быстрее total, это именно последний рубеж против настоящего
    # зависания, не бюджет под скорость).
    #
    # РЕАЛЬНЫЙ, измеренный вживую баг (deep-audit, videos/_test20s, 28 августа):
    # "-t {total} ... -c:v copy ... -shortest" резало ВИДЕО не там, где нужно.
    # merged.mp4 (прямой выход xfade_chain_chunked/pad_to_length) на этом
    # эпизоде — ровно 575 кадров/23.958333с (совпадает с планом
    # phrase_locked_durations байт-в-байт), total (аудио) — 23.955354с, то
    # есть видео ДЛИННЕЕ аудио всего на ~3мс — меньше кадра. Ожидаемая обрезка
    # -t/-shortest — доля кадра. РЕАЛЬНАЯ, измеренная на этом же merged.mp4 +
    # premix.wav (тем же ffmpeg, теми же байтами) — 572 кадра/23.833333с,
    # то есть ЦЕЛЫХ 3 КАДРА (125мс) видео потеряны молча. Причина —
    # PTS-based "-t"/"-shortest" при "-c:v copy" режет по границе, которую
    # диктует B-frame/GOP reordering контейнера, а не точный счётчик кадров:
    # "лишних" кадров на выходе НЕ бывает (аудио и так не длиннее видео), то
    # есть -t/-shortest здесь вообще не нужны видео-потоку — их работу
    # (не дать видео убежать от аудио) полностью покрывает pad_to_length()
    # выше по коду, который уже гарантирует merged >= total. Живая проверка
    # (тот же merged.mp4+premix.wav, только "-vframes {N} -c:v copy" без
    # "-t"/"-shortest" на видео): 575/23.958333с — точное совпадение с
    # merged.mp4, ни одного потерянного кадра. Худший случай — хвост
    # ПОСЛЕДНЕГО клипа эпизода (для этого рендера это как раз клип, теряющий
    # 3 кадра из финальной фразы хука) укорачивается молча на до ~4 кадров
    # ПОСЛЕ того, как весь остальной пайплайн (alignment.csv,
    # phrase_locked_durations, кадровая сетка) уже добился точности до
    # полукадра — единственное место, где вся эта точность бы терялась.
    # Аудио по-прежнему явно триммится "-t" (оно перекодируется в AAC —
    # PTS-обрезка там точна, тот же принцип, что и раньше).
    video_frames_target = min(round(total * FPS), round(get_media_duration(merged) * FPS))
    _mux_t0 = time.perf_counter()
    try:
        r = subprocess.run(["ffmpeg", "-y", "-i", merged, "-i", premix,
                            "-t", f"{total:.3f}",
                            "-af", af,
                            # -ar 48000 обязателен именно ЗДЕСЬ (поймано вживую на
                            # реальном рендере): loudnorm с TP (true peak, для
                            # inter-sample пиков по ITU-R BS.1770 нужен передискрет)
                            # сам меняет частоту потока на выходе фильтра — без
                            # явного -ar это утекает прямо в AAC-энкодер (поймано:
                            # 96000Hz на итоговом final.mp4 при всём остальном
                            # звуке 48000Hz — единственное место в файле, где
                            # -ar не был проставлен явно, все остальные 11
                            # вызовов это уже получили в P2-17).
                            "-c:v", "copy", "-vframes", str(video_frames_target),
                            "-c:a", "aac", "-b:a", "192k", "-ar", "48000",
                            "-movflags", "+faststart",
                            output_tmp], capture_output=True, text=True,
                           timeout=max(180, total))
    except subprocess.TimeoutExpired:
        stage_timer.record("final_mux", time.perf_counter() - _mux_t0, ok=False)
        print(f"Финальный мукс завис (таймаут {max(180, total):.0f}с) — final.mp4 не собран.")
        finalize_render(output_tmp, OUTPUT_FILE, False)
        return 1
    stage_timer.record("final_mux", time.perf_counter() - _mux_t0)
    if r.returncode != 0:
        print("Аудио:", r.stderr[-300:])
        finalize_render(output_tmp, OUTPUT_FILE, False)
        return 1
    finalize_render(output_tmp, OUTPUT_FILE, True)
    # Честная цифра вместо "надеемся" — измеряем итоговую громкость ГОТОВОГО
    # файла (не входного audio.mp3): если разошлось с целью (см. loudnorm=I=
    # в финальном миксе выше, сейчас -14) больше, чем на децибел, это видно
    # в отчёте, а не тонет молча. РЕАЛЬНЫЙ найденный баг (02.09): при смене
    # цели -16 -> -14 эта проверка осталась зашита на -16.0 отдельно от
    # четырёх точек loudnorm= — честный рендер на -14.3 (в пределах цели)
    # печатал ложную тревогу "разошлось с целью -16". Вынесено в константу
    # рядом с самим loudnorm=, а не восьмым магическим числом.
    final_lufs = None
    try:
        fr = subprocess.run(["ffmpeg", "-i", OUTPUT_FILE, "-af",
                              f"loudnorm=I={LOUDNORM_TARGET_I}:TP={LOUDNORM_TARGET_TP}:"
                              f"LRA={LOUDNORM_TARGET_LRA}:print_format=json",
                              "-f", "null", "-"], capture_output=True, text=True, timeout=60)
        fs, fe = fr.stderr.rindex("{"), fr.stderr.rindex("}") + 1
        final_lufs = float(json.loads(fr.stderr[fs:fe])["input_i"])
    except Exception:
        pass
    mb = os.path.getsize(OUTPUT_FILE) / (1024 * 1024)
    # Пропущенные кадры и раньше не останавливали сборку (стратегия
    # "лучше меньше клипов, чем сорванный рендер") — но раньше это тонуло
    # в середине лога, а ГОТОВО выглядело как чистый успех. Теперь пропуски
    # видны в итоговой строке, и код возврата честно отражает, что не всё
    # доехало (не 0, если что-то пропущено).
    dupes = qc_report(media_log)
    status = f" | ПРОПУЩЕНО {len(missing)} блоков: {missing}" if missing else ""
    if final_lufs is not None:
        status += f" | Громкость: {final_lufs:.1f} LUFS" + (
            "" if abs(final_lufs - LOUDNORM_TARGET_I) <= 1.0
            else f" (!!! разошлось с целью {LOUDNORM_TARGET_I:.0f})")
    # Дубли по фото — та же логика: не блокируем сборку (видео уже готово
    # и в целом смотрибельно), но не даём находке потеряться в середине
    # лога и не даём коду возврата соврать, что всё чисто.
    status += f" | QC: {len(dupes)} похожих пар кадров — проверь глазами" if dupes else ""
    # Freeze-padding (2.4) — estimate_xfade_budget() должен был свести его
    # к нулю почти всегда; заметный (>PAD_GAP_HARD_CAP_SEC) случай уже
    # остановил бы сборку выше (см. проверку сразу после pad_to_length) —
    # если мы вообще добрались сюда, pad_gap заведомо <= допуска, но мелкий
    # ненулевой остаток всё ещё стоит показать честно, не молчать про него.
    status += f" | заморозка в хвосте: {pad_gap:.2f}с (в пределах допуска)" if pad_gap > 0.1 else ""
    print(f"\nГОТОВО: {OUTPUT_FILE} ({mb:.0f} MB, {total/60:.1f} мин, {len(clips)} кадров){status}")
    return 1 if (missing or dupes) else 0


if __name__ == "__main__":
    sys.exit(main())
